window.DRUG_DATA = [{"topic": "cardio", "generic": "Ramipril", "pronunciation": "ra-MIH-pril", "brand": ["Altace"], "class": "ACE inhibitor", "moa": "Inhibits angiotensin-converting enzyme, blocking conversion of angiotensin I to angiotensin II, reducing vasoconstriction and aldosterone release.", "indication": "Hypertension; HFrEF; post-MI; cardiovascular risk reduction; diabetic nephropathy.", "dosage": "2.5–10 mg PO daily (start 1.25–2.5 mg in HF/renal impairment); max 10 mg/day", "examPoints": ["Contraindicated in pregnancy (category D/X) — fetotoxic in 2nd/3rd trimester", "Do NOT combine with ARB or direct renin inhibitor (aliskiren) — risk of hyperkalemia/renal failure", "Dry non-productive cough (bradykinin-mediated) — switch to ARB if intolerable", "Risk of angioedema — more common in Black patients; if occurs, do not rechallenge with any ACEI", "Check SCr and K+ within 1-2 weeks of starting/titrating; hold if K+ >5.5 or SCr rises >30%"], "counselling": ["May cause dizziness, especially after the first dose — rise slowly from sitting/lying", "Report persistent dry cough, swelling of face/lips/tongue, or difficulty breathing immediately", "Avoid potassium supplements and salt substitutes (often contain KCl) unless directed", "Stay hydrated but don't over-restrict fluids; avoid NSAIDs which blunt effect and harm kidneys", "Takes several weeks for full blood pressure effect"], "sideEffects": ["Dry cough", "Hyperkalemia", "Hypotension (first-dose)", "Headache", "Angioedema (rare, serious)", "Acute kidney injury"]}, {"topic": "cardio", "generic": "Candesartan", "pronunciation": "kan-deh-SAR-tan", "brand": ["Atacand"], "class": "Angiotensin II receptor blocker (ARB)", "moa": "Selectively blocks the AT1 receptor, preventing angiotensin II-mediated vasoconstriction and aldosterone secretion without affecting bradykinin.", "indication": "Hypertension; HFrEF (alternative to ACEI); diabetic nephropathy.", "dosage": "8–32 mg PO daily (start 4–8 mg in HF/renal impairment); max 32 mg/day", "examPoints": ["No dry cough (bradykinin not affected) — preferred if ACEI-induced cough", "Still contraindicated in pregnancy and with aliskiren in diabetics", "Angioedema risk lower than ACEI but still present; caution if prior ACEI angioedema", "Monitor K+ and SCr similarly to ACE inhibitors", "First-line alternative for ACEI-intolerant patients, not typically added on top of ACEI"], "counselling": ["Take at the same time each day, with or without food", "Rise slowly to avoid dizziness, especially when starting", "Avoid potassium supplements/salt substitutes unless told otherwise", "Report facial/tongue swelling or trouble breathing immediately", "Use effective contraception; stop and inform prescriber if pregnancy suspected"], "sideEffects": ["Dizziness", "Hyperkalemia", "Hypotension", "Headache", "Angioedema (rare)", "Renal impairment"]}, {"topic": "cardio", "generic": "Metoprolol succinate", "pronunciation": "meh-TOE-proh-lol SUK-sih-nayt", "brand": ["Lopresor SR", "Betaloc CR"], "class": "Beta-1 selective blocker (extended-release)", "moa": "Selectively blocks beta-1 adrenergic receptors, reducing heart rate, contractility, and myocardial oxygen demand.", "indication": "Hypertension; HFrEF (evidence-based extended-release formulation only); angina; rate control in AFib.", "dosage": "25–200 mg PO daily (extended-release); start 12.5–25 mg/day in HF, titrate slowly q2wk", "examPoints": ["Only the extended-release (succinate) formulation has HFrEF mortality benefit — NOT the immediate-release tartrate salt", "Avoid abrupt discontinuation — taper to prevent rebound tachycardia/hypertension", "Caution/avoid in decompensated HF, severe bradycardia, high-grade AV block, severe asthma", "Can mask hypoglycemia symptoms (tachycardia) in diabetics — sweating still occurs", "Beta-1 selectivity is dose-dependent — lost at higher doses"], "counselling": ["Take at the same time each day, do not crush/chew the extended-release tablet", "Do not stop suddenly even if you feel fine", "Check your pulse periodically; report resting HR <50-55 bpm or dizziness", "May take a few weeks to see full effect on heart failure symptoms", "Report worsening shortness of breath or swelling"], "sideEffects": ["Fatigue", "Bradycardia", "Cold extremities", "Dizziness/hypotension", "Masking of hypoglycemia symptoms in diabetics", "Bronchospasm (high doses)"]}, {"topic": "cardio", "generic": "Amlodipine", "pronunciation": "am-LOH-dih-peen", "brand": ["Norvasc"], "class": "Dihydropyridine calcium channel blocker", "moa": "Blocks L-type calcium channels in vascular smooth muscle causing peripheral vasodilation; minimal direct cardiac effect at therapeutic doses.", "indication": "Hypertension; chronic stable angina; vasospastic (Prinzmetal) angina.", "dosage": "2.5–10 mg PO daily; start 2.5 mg in elderly/hepatic impairment; max 10 mg/day", "examPoints": ["Classic dose-dependent side effect: peripheral edema (not fluid overload — does not respond well to diuretics)", "Safe in HFrEF from a mortality standpoint (unlike non-DHP CCBs) but does not improve HF outcomes", "No significant AV node effect — can be combined with beta-blockers (unlike verapamil/diltiazem)", "Long half-life (~30-50h) allows once-daily dosing and smooth BP control", "Reflex tachycardia less common than with short-acting DHPs due to gradual onset"], "counselling": ["Take once daily at the same time; can be taken with or without food", "Ankle/leg swelling is common and dose-related — report if bothersome, but don't self-treat with a diuretic", "Rise slowly to avoid dizziness when starting", "Avoid grapefruit juice in large quantities", "May take 1-2 weeks for full blood pressure effect"], "sideEffects": ["Peripheral edema", "Flushing", "Headache", "Dizziness", "Gingival hyperplasia (rare)", "Reflex tachycardia"]}, {"topic": "cardio", "generic": "Atorvastatin", "pronunciation": "uh-TOR-vuh-STAT-in", "brand": ["Lipitor"], "class": "HMG-CoA reductase inhibitor (statin)", "moa": "Competitively inhibits HMG-CoA reductase, the rate-limiting enzyme in hepatic cholesterol synthesis, upregulating LDL receptor expression and lowering LDL-C.", "indication": "Primary and secondary prevention of atherosclerotic cardiovascular disease; hyperlipidemia.", "dosage": "10–80 mg PO once daily (any time of day); high-intensity dosing 40–80 mg/day", "examPoints": ["High-intensity statin (atorvastatin 40-80mg, rosuvastatin 20-40mg) lowers LDL by ≥50%", "Contraindicated in pregnancy/breastfeeding and active liver disease", "Major interaction: strong CYP3A4 inhibitors (clarithromycin, itraconazole, protease inhibitors) increase myopathy/rhabdomyolysis risk", "Baseline LFTs recommended; routine periodic LFT monitoring generally not required unless symptomatic", "Statin-associated muscle symptoms (SAMS) — check CK if myopathy suspected; rhabdomyolysis is rare but serious"], "counselling": ["Can be taken any time of day, with or without food (atorvastatin has long half-life, unlike simvastatin)", "Report unexplained muscle pain, tenderness, or weakness, especially with fever/dark urine", "Avoid large quantities of grapefruit juice", "Continue taking even if cholesterol normalizes — it's a long-term therapy", "Inform prescriber before starting if pregnant or planning pregnancy"], "sideEffects": ["Myalgia", "Headache", "GI upset", "Elevated LFTs", "Myopathy/rhabdomyolysis (rare, serious)", "New-onset diabetes (slight increase)"]}, {"topic": "cardio", "generic": "Apixaban", "pronunciation": "uh-PIKS-uh-ban", "brand": ["Eliquis"], "class": "Direct oral anticoagulant (Factor Xa inhibitor)", "moa": "Directly and selectively inhibits free and clot-bound Factor Xa, preventing thrombin generation and clot formation, without requiring antithrombin.", "indication": "Stroke prevention in non-valvular AFib; treatment/prevention of VTE (DVT/PE); post-orthopedic surgery VTE prophylaxis.", "dosage": "5 mg PO BID; reduce to 2.5 mg BID if ≥2 of: age ≥80, weight ≤60 kg, SCr ≥133 µmol/L; VTE prophylaxis 2.5 mg BID", "examPoints": ["Dose reduction (2.5mg BID) criteria: at least 2 of — age ≥80, weight ≤60kg, SCr ≥133 µmol/L", "No routine coagulation monitoring needed; preferred over warfarin for most non-valvular AFib", "Avoid in mechanical heart valves and moderate-severe mitral stenosis — use warfarin instead", "Reversal agent: andexanet alfa; hold before elective surgery per renal function/bleed risk", "Contraindicated with strong dual CYP3A4/P-gp inhibitors or inducers (e.g., avoid with strong azole antifungals + ritonavir)"], "counselling": ["Take exactly as prescribed, twice daily, do not skip doses — short half-life means missed doses reduce protection quickly", "No routine blood test monitoring needed (unlike warfarin)", "Report unusual bleeding/bruising, blood in urine/stool, or black tarry stools", "Tell every healthcare provider and dentist you're on this before any procedure", "Do not stop abruptly without talking to your prescriber — increases clot/stroke risk"], "sideEffects": ["Bleeding/bruising", "GI bleeding", "Anemia", "Nausea", "Intracranial hemorrhage (rare, serious)"]}, {"topic": "cardio", "generic": "Warfarin", "pronunciation": "WOR-fuh-rin", "brand": ["Coumadin"], "class": "Vitamin K antagonist (anticoagulant)", "moa": "Inhibits vitamin K epoxide reductase, blocking synthesis of clotting factors II, VII, IX, X and proteins C and S.", "indication": "Mechanical heart valves; AFib with valvular disease/mitral stenosis; VTE treatment; antiphospholipid syndrome.", "dosage": "Individualized to target INR (usually 2–3); typical start 5 mg PO daily, adjust per INR (lower start 2–5 mg in elderly)", "examPoints": ["Target INR usually 2-3 (2.5-3.5 for mechanical mitral valves)", "Numerous food/drug interactions: vitamin K-rich foods (leafy greens) lower INR; many antibiotics, amiodarone, antifungals raise INR", "Protein C/S have short half-lives — transient hypercoagulable state at initiation; bridge with heparin/LMWH in high-risk VTE", "Reversal: vitamin K (oral/IV) ± prothrombin complex concentrate (PCC) for major bleeding", "Teratogenic — contraindicated in pregnancy (warfarin embryopathy)"], "counselling": ["Keep vitamin K intake consistent day-to-day rather than avoiding it entirely", "Regular INR blood tests are required — do not skip appointments", "Report any unusual bruising/bleeding, blood in urine or stool", "Tell your pharmacist about any new prescription, OTC, or herbal product before starting it", "Take at the same time each day, consistently"], "sideEffects": ["Bleeding", "Bruising", "Skin necrosis (rare, protein C deficiency)", "Purple toe syndrome (rare)", "Hair loss"]}, {"topic": "cardio", "generic": "Clopidogrel", "pronunciation": "kloh-PID-oh-grel", "brand": ["Plavix"], "class": "P2Y12 platelet inhibitor (antiplatelet)", "moa": "Irreversibly blocks the P2Y12 ADP receptor on platelets, preventing ADP-mediated platelet activation and aggregation; is a prodrug requiring CYP2C19 activation.", "indication": "ACS (with ASA — dual antiplatelet therapy); post-PCI/stent; secondary stroke/PVD prevention; ASA-intolerant patients.", "dosage": "75 mg PO daily; loading dose 300–600 mg for ACS/PCI", "examPoints": ["CYP2C19 poor metabolizers have reduced efficacy — genetic testing sometimes considered", "DAPT duration post-DES typically 6-12 months (per guidelines/bleeding risk), shorter in high bleeding risk", "Interaction: omeprazole/esomeprazole (strong CYP2C19 inhibitors) may reduce activation — pantoprazole preferred if PPI needed", "Hold 5-7 days before elective surgery when possible", "Irreversible antiplatelet effect lasts the lifespan of the platelet (~7-10 days)"], "counselling": ["Take once daily, with or without food", "Do not stop without talking to your cardiologist, especially soon after a stent — stopping early risks stent thrombosis", "Report unusual bruising/bleeding, black stools", "Tell your dentist/surgeon you're on this before any procedure", "May be taken with low-dose ASA as directed — don't add other NSAIDs without asking"], "sideEffects": ["Bleeding", "Bruising", "GI upset", "Rash", "Thrombotic thrombocytopenic purpura (TTP, rare)"]}, {"topic": "cardio", "generic": "Furosemide", "pronunciation": "fyoor-OH-seh-myd", "brand": ["Lasix"], "class": "Loop diuretic", "moa": "Inhibits the Na-K-2Cl cotransporter in the thick ascending limb of the loop of Henle, causing significant natriuresis and diuresis.", "indication": "Fluid overload in HF, hepatic/renal edema; hypertension (adjunct); hyperkalemia management.", "dosage": "20–80 mg PO/IV daily–BID, titrate to effect; max up to 600 mg/day in refractory edema", "examPoints": ["Sulfa moiety — use caution/consider alternatives (ethacrynic acid) in true sulfonamide allergy", "Causes hypokalemia, hypomagnesemia, hyponatremia — monitor electrolytes; contrast with K-sparing diuretics", "Ototoxicity risk with rapid IV administration or high doses, especially with other ototoxic drugs (aminoglycosides)", "Ceiling diuretic — effect increases with dose up to a max (unlike thiazides)", "IV to PO conversion is roughly 1:2 (bioavailability ~50%)"], "counselling": ["Take in the morning (or morning + early afternoon if twice daily) to avoid nighttime urination", "Weigh yourself daily at the same time; report rapid weight gain (>2kg in a few days)", "Rise slowly to avoid dizziness from low blood pressure", "Report muscle cramps, weakness, or irregular heartbeat (signs of low potassium)", "May increase urination significantly within 30-60 minutes of a dose"], "sideEffects": ["Hypokalemia", "Hypotension", "Dehydration", "Hyponatremia", "Ototoxicity (high dose/IV)", "Hyperuricemia/gout flare"]}, {"topic": "cardio", "generic": "Spironolactone", "pronunciation": "spy-roh-noh-LAK-tohn", "brand": ["Aldactone"], "class": "Aldosterone antagonist / potassium-sparing diuretic (MRA)", "moa": "Competitively blocks mineralocorticoid (aldosterone) receptors in the distal nephron, reducing sodium/water retention and potassium excretion.", "indication": "HFrEF (NYHA II-IV, mortality benefit); resistant hypertension; primary hyperaldosteronism; ascites/cirrhosis.", "dosage": "12.5–25 mg PO daily for HFrEF, titrate to 50 mg/day max; up to 100 mg/day for ascites/hyperaldosteronism", "examPoints": ["Major risk: hyperkalemia, especially combined with ACEI/ARB — monitor K+ and SCr closely", "Contraindicated if K+ >5.0, significant renal impairment (per RALES/EMPHASIS-HF criteria)", "Anti-androgenic effects: gynecomastia, menstrual irregularities (less common with eplerenone, a selective MRA)", "One of the 'four pillars' of HFrEF therapy (with ACEI/ARB/ARNI, beta-blocker, SGLT2i)", "Avoid potassium supplements and salt substitutes while on therapy"], "counselling": ["Take with food to reduce stomach upset", "Avoid potassium supplements and salt substitutes unless told otherwise by your prescriber", "Report muscle weakness, irregular heartbeat, or tingling (possible high potassium)", "Men: report breast tenderness/enlargement; women: report menstrual changes", "Routine blood tests for potassium and kidney function are needed"], "sideEffects": ["Hyperkalemia", "Gynecomastia (men)", "Menstrual irregularities (women)", "GI upset", "Dizziness", "Severe hyperkalemia/arrhythmia (rare, serious)"]}, {"topic": "cardio", "generic": "Sacubitril/valsartan", "pronunciation": "suh-KYOO-bih-tril / val-SAR-tan", "brand": ["Entresto"], "class": "Angiotensin receptor-neprilysin inhibitor (ARNI)", "moa": "Sacubitril inhibits neprilysin (increasing natriuretic peptides for vasodilation/natriuresis) while valsartan blocks the AT1 receptor; combined effect superior to ACEI alone in HFrEF (PARADIGM-HF).", "indication": "HFrEF (replaces ACEI/ARB as preferred first-line RAAS agent in guideline-directed therapy).", "dosage": "Start 49/51 mg PO BID (24/26 mg BID if ACEI/ARB-naïve or renal/hepatic impairment), titrate to target 97/103 mg BID over 2–4 weeks", "examPoints": ["Must washout ACE inhibitor for 36 hours before starting (both increase bradykinin) — high angioedema risk if overlapped", "Never combine with an ACEI or another ARB", "Contraindicated in pregnancy and history of ACEI/ARB-related angioedema", "Monitor blood pressure, renal function, and potassium as with ACEI/ARB", "One of the four pillars of HFrEF GDMT along with beta-blocker, MRA, SGLT2i"], "counselling": ["Do not take within 36 hours of your last ACE inhibitor dose when switching", "Take twice daily, with or without food", "Rise slowly to prevent dizziness, especially early in treatment", "Report facial/tongue swelling or difficulty breathing immediately (angioedema)", "Continue other heart failure medications as directed — this is usually used in combination"], "sideEffects": ["Hypotension", "Hyperkalemia", "Cough (less than ACEI)", "Dizziness", "Renal impairment", "Angioedema (rare, serious)"]}, {"topic": "cardio", "generic": "Amiodarone", "pronunciation": "uh-MEE-oh-duh-rohn", "brand": ["Cordarone"], "class": "Class III antiarrhythmic (multi-channel blocker)", "moa": "Blocks potassium channels (prolonging repolarization/QT) plus sodium, calcium channel, and beta-blocking properties, broadening its antiarrhythmic action across atrial and ventricular tissue.", "indication": "Ventricular tachyarrhythmias; refractory AFib rhythm/rate control; cardiac arrest (VF/pulseless VT per ACLS).", "dosage": "Loading 800–1600 mg/day PO in divided doses x1–3 weeks, then taper to maintenance 100–400 mg/day; IV loading per ACLS protocol", "examPoints": ["Extremely long half-life (weeks) — effects and interactions persist long after stopping", "Classic toxicities: pulmonary fibrosis, thyroid dysfunction (both hypo- and hyperthyroidism, due to iodine content), hepatotoxicity, blue-grey skin discoloration, corneal microdeposits", "Baseline and periodic monitoring: TFTs, LFTs, chest X-ray/PFTs, ophthalmologic exam", "Major interaction: potentiates warfarin (reduce warfarin dose ~30-50%) and digoxin (reduce digoxin dose) — both CYP/P-gp mediated", "Photosensitivity — advise sun protection"], "counselling": ["Wear sunscreen and protective clothing — skin can burn easily or turn blue-grey with long-term use", "Report new shortness of breath or persistent cough (possible lung toxicity)", "Regular blood tests for thyroid and liver function are required", "May affect other medications significantly — inform every prescriber that you take this", "Report vision changes; routine eye exams may be recommended"], "sideEffects": ["Thyroid dysfunction", "Pulmonary fibrosis", "Hepatotoxicity", "Photosensitivity/blue-grey skin", "Corneal microdeposits", "QT prolongation/torsades (rare)"]}, {"topic": "cardio", "generic": "Digoxin", "pronunciation": "dih-JOKS-in", "brand": ["Toloxin"], "class": "Cardiac glycoside", "moa": "Inhibits the Na+/K+-ATPase pump, increasing intracellular sodium and calcium (positive inotrope); also increases vagal tone, slowing AV nodal conduction (rate control).", "indication": "HFrEF symptom control (no mortality benefit); rate control in AFib (especially with concurrent HF).", "dosage": "0.125–0.25 mg PO daily (lower in renal impairment/elderly); target trough level 0.5–0.9 ng/mL for HF", "examPoints": ["Narrow therapeutic index — target trough level typically 0.5-0.9 ng/mL for HF (lower end targeted now)", "Toxicity risk increased by hypokalemia, hypomagnesemia, hypercalcemia, renal impairment", "Signs of toxicity: nausea/vomiting, visual disturbances (yellow-green halos), arrhythmias (classically bidirectional VT)", "Major interactions: amiodarone, verapamil, clarithromycin increase digoxin levels (reduce dose ~50%)", "Antidote for severe toxicity: digoxin immune Fab (DigiFab)"], "counselling": ["Take at the same time every day", "Report nausea, vomiting, loss of appetite, visual changes (seeing yellow/green halos), or irregular heartbeat", "Do not double up if you miss a dose — contact your pharmacist/prescriber", "Regular blood tests to check digoxin level and kidney function/electrolytes are important", "Tell your pharmacist about all new medications due to many interactions"], "sideEffects": ["Nausea/vomiting", "Visual disturbances (yellow-green halos)", "Arrhythmias", "Fatigue", "Digoxin toxicity (serious, narrow therapeutic index)"]}, {"topic": "cardio", "generic": "Hydrochlorothiazide", "pronunciation": "hy-droh-klor-oh-THY-uh-zyd", "brand": ["Apo-Hydro"], "class": "Thiazide diuretic", "moa": "Inhibits the Na-Cl cotransporter in the distal convoluted tubule, promoting natriuresis; also causes some vasodilation contributing to antihypertensive effect.", "indication": "Hypertension (first-line); mild edema.", "dosage": "12.5–25 mg PO daily; max 50 mg/day (limited added benefit above 25 mg)", "examPoints": ["Less effective diuretic than loop diuretics but better long-term BP control at low doses", "Causes hypokalemia, hyponatremia, hyperuricemia (can precipitate gout), hyperglycemia, hypercalcemia (opposite of loop diuretics)", "Ineffective when CrCl <30 mL/min (loop diuretics preferred in significant renal impairment)", "Sulfonamide-derived — caution in sulfa allergy", "Often combined with ACEI/ARB in single-pill combinations for hypertension"], "counselling": ["Take in the morning to avoid nighttime urination", "Report muscle cramps or weakness (possible low potassium)", "Stay adequately hydrated; use sun protection (photosensitivity possible)", "Routine blood tests to monitor electrolytes, kidney function, blood sugar, and uric acid", "Report joint pain/swelling (possible gout flare)"], "sideEffects": ["Hypokalemia", "Hyponatremia", "Hyperuricemia/gout", "Hyperglycemia", "Photosensitivity", "Hypercalcemia"]}, {"topic": "cardio", "generic": "Rosuvastatin", "pronunciation": "roh-SOO-vuh-STAT-in", "brand": ["Crestor"], "class": "HMG-CoA reductase inhibitor (statin)", "moa": "Inhibits hepatic HMG-CoA reductase, the rate-limiting step in cholesterol synthesis, upregulating LDL receptors and increasing LDL clearance from plasma.", "indication": "Hyperlipidemia; primary/secondary ASCVD prevention.", "dosage": "5–20 mg PO once daily (high-intensity 20–40 mg/day); max 40 mg/day; start 5–10 mg in Asian patients", "examPoints": ["High-intensity at 20-40mg (lowers LDL ≥50%); more potent per mg than atorvastatin", "Less CYP3A4 metabolism than atorvastatin/simvastatin (mainly CYP2C9) — fewer interactions with azoles/macrolides, but still caution with cyclosporine, gemfibrozil", "Reduce starting dose in Asian patients (higher plasma levels observed) and in severe renal impairment", "Same myopathy/rhabdomyolysis and hepatotoxicity class warnings as other statins", "Contraindicated in pregnancy/breastfeeding"], "counselling": ["Can be taken any time of day, with or without food", "Report unexplained muscle pain/weakness, especially with fever or dark urine", "Continue taking long term even once cholesterol is controlled", "Inform prescriber if pregnant, planning pregnancy, or breastfeeding", "Limit alcohol intake; liver function may be monitored"], "sideEffects": ["Myalgia", "Headache", "GI upset", "Elevated LFTs", "Myopathy/rhabdomyolysis (rare)", "New-onset diabetes (slight increase)"]}, {"topic": "endo", "generic": "Metformin", "pronunciation": "met-FOR-min", "brand": ["Glucophage", "Glumetza"], "class": "Biguanide", "moa": "Decreases hepatic gluconeogenesis and increases peripheral insulin sensitivity/glucose uptake; does not stimulate insulin secretion.", "indication": "First-line therapy for type 2 diabetes mellitus.", "dosage": "500 mg PO BID with meals, titrate weekly to 2000 mg/day (max 2550 mg/day); hold if eGFR <30 mL/min", "examPoints": ["First-line agent for T2DM per Diabetes Canada guidelines regardless of baseline A1C (unless contraindicated)", "Contraindicated/caution in eGFR <30 mL/min/1.73m2 (dose-reduce 30-45); hold before/after IV contrast if renal risk", "Rare but serious: lactic acidosis, risk increased in renal/hepatic impairment, sepsis, dehydration, heavy alcohol use", "Does NOT cause hypoglycemia when used alone (weight-neutral/mild weight loss)", "Can cause vitamin B12 deficiency with long-term use — periodic monitoring recommended"], "counselling": ["Take with meals to reduce GI upset; extended-release usually taken once daily with dinner", "Start low and go slow — GI side effects (diarrhea, nausea) often improve over 1-2 weeks", "Hold before procedures requiring IV contrast dye as directed by your care team, resume after checking kidney function", "Does not typically cause low blood sugar on its own", "Report unusual muscle pain, trouble breathing, or extreme tiredness (rare lactic acidosis signs)"], "sideEffects": ["Diarrhea", "Nausea/GI upset", "Metallic taste", "Vitamin B12 deficiency (long-term)", "Lactic acidosis (rare, serious)"]}, {"topic": "endo", "generic": "Gliclazide", "pronunciation": "GLY-kluh-zyd", "brand": ["Diamicron", "Diamicron MR"], "class": "Sulfonylurea", "moa": "Stimulates insulin release from pancreatic beta cells by binding to SUR1 receptors and closing ATP-sensitive K+ channels, causing depolarization and calcium influx.", "indication": "Type 2 diabetes mellitus, typically add-on to metformin.", "dosage": "40–80 mg PO daily with breakfast, titrate to max 320 mg/day (or 30–120 mg/day for MR formulation)", "examPoints": ["Main risk: hypoglycemia (higher than newer agents) — caution in elderly, renal impairment, irregular meals", "Causes weight gain (unlike metformin, SGLT2i, GLP-1 agonists)", "Gliclazide preferred over glyburide in Canada due to lower hypoglycemia risk and better renal safety profile", "Take with breakfast — skipping meals after dosing risks hypoglycemia", "Avoid/use caution in significant renal or hepatic impairment"], "counselling": ["Take with breakfast; do not skip meals after taking this medication", "Carry a fast-acting sugar source (glucose tablets, juice) in case of low blood sugar", "Know signs of hypoglycemia: shakiness, sweating, confusion, rapid heartbeat", "Limit alcohol — increases hypoglycemia risk", "Do not double the dose if a dose is missed"], "sideEffects": ["Hypoglycemia", "Weight gain", "GI upset", "Headache", "Rare: hyponatremia, hepatotoxicity"]}, {"topic": "endo", "generic": "Empagliflozin", "pronunciation": "em-pag-lih-FLOH-zin", "brand": ["Jardiance"], "class": "SGLT2 inhibitor", "moa": "Inhibits sodium-glucose cotransporter 2 in the proximal renal tubule, reducing glucose reabsorption and promoting glucosuria; also has diuretic/natriuretic effects.", "indication": "Type 2 diabetes; HFrEF and HFpEF (regardless of diabetes status); chronic kidney disease (renal protection).", "dosage": "10 mg PO once daily in morning; may increase to 25 mg/day; avoid if eGFR <20–30 mL/min/1.73m²", "examPoints": ["Proven cardiovascular and renal benefit independent of glycemic effect (EMPA-REG, EMPEROR trials) — now a pillar of HFrEF therapy", "Risk of euglycemic diabetic ketoacidosis — can occur with normal/near-normal glucose; hold during acute illness, surgery, prolonged fasting ('sick day rules')", "Increased risk of genital mycotic infections (yeast infections) due to glucosuria", "Rare but serious: Fournier's gangrene (necrotizing fasciitis of perineum)", "Causes modest weight loss and blood pressure reduction"], "counselling": ["Take once daily in the morning, with or without food", "Practice good genital hygiene to reduce yeast infection risk; report itching, discharge, or discomfort", "Follow 'sick day' instructions — hold this medication if vomiting, unable to eat/drink, or seriously ill, and contact your care team", "Report unusual severe pain, swelling, or redness in the genital/perineal area right away (rare but serious infection)", "May cause increased urination — stay well hydrated"], "sideEffects": ["Genital mycotic infections", "Urinary tract infections", "Volume depletion/hypotension", "Euglycemic DKA (rare, serious)", "Fournier's gangrene (very rare)"]}, {"topic": "endo", "generic": "Semaglutide", "pronunciation": "sem-uh-GLOO-tyd", "brand": ["Ozempic", "Rybelsus", "Wegovy"], "class": "GLP-1 receptor agonist", "moa": "Mimics glucagon-like peptide-1, enhancing glucose-dependent insulin secretion, suppressing glucagon, slowing gastric emptying, and promoting satiety.", "indication": "Type 2 diabetes (Ozempic/Rybelsus); chronic weight management (Wegovy); established ASCVD risk reduction.", "dosage": "Oral: start 3 mg daily x30 days, then 7 mg, may increase to 14 mg daily. SC (Ozempic): start 0.25 mg once weekly, titrate to 0.5–2 mg weekly", "examPoints": ["Proven cardiovascular benefit in patients with T2DM and established ASCVD (SUSTAIN-6)", "Contraindicated in personal/family history of medullary thyroid carcinoma or MEN2 syndrome (black box warning, from rodent C-cell tumor data)", "Injectable (Ozempic, once weekly subcutaneous) vs oral (Rybelsus, once daily on empty stomach with minimal water)", "Significant weight loss effect; GI side effects (nausea, vomiting) most common reason for discontinuation, usually improve with slow titration", "Caution with concurrent insulin/sulfonylurea — increased hypoglycemia risk, may need dose reduction of those agents"], "counselling": ["Injectable form: inject once weekly, same day each week, rotating injection sites (abdomen, thigh, upper arm)", "Oral form (Rybelsus): take first thing in the morning on an empty stomach with no more than 4 oz plain water, wait 30 minutes before eating/drinking/other meds", "Nausea is common when starting or increasing dose — eating smaller, lower-fat meals can help", "Report persistent severe abdominal pain (possible pancreatitis) or signs of gallbladder problems", "Report a lump/swelling in the neck or hoarseness (rare thyroid tumor concern)"], "sideEffects": ["Nausea", "Vomiting", "Diarrhea/constipation", "Decreased appetite", "Pancreatitis (rare)", "Gallbladder disease"]}, {"topic": "endo", "generic": "Insulin glargine", "pronunciation": "IN-suh-lin GLAR-jeen", "brand": ["Lantus", "Basaglar", "Toujeo"], "class": "Long-acting basal insulin analog", "moa": "Forms a precipitate at the subcutaneous injection site (neutral pH) that slowly dissolves, providing a relatively flat, prolonged insulin release over ~24 hours.", "indication": "Basal insulin coverage in type 1 and type 2 diabetes.", "dosage": "Individualized; typically start 10 units (or 0.1–0.2 units/kg) SC once daily, titrate to fasting glucose target", "examPoints": ["Relatively peakless profile — lower nocturnal hypoglycemia risk vs NPH insulin", "Cannot be mixed in the same syringe with other insulins (unlike NPH)", "Onset ~1-2h, duration ~20-24h; typically dosed once daily (Toujeo/U300 has flatter, longer profile than U100 glargine)", "Insulin is high-alert medication — dosing errors (units vs mL, pen vs vial) are a classic exam safety topic", "Dose individualized/titrated to fasting blood glucose targets"], "counselling": ["Inject at the same time each day, subcutaneously (abdomen, thigh, or upper arm), rotate injection sites", "Do not mix with other insulins in the same syringe", "Know the signs of hypoglycemia and how to treat it (fast-acting sugar, 15-15 rule)", "Store unopened pens/vials in the fridge; in-use pen can be kept at room temperature per product labeling (~28 days) and away from direct heat/light", "Never share insulin pens/needles between people, even with a new needle"], "sideEffects": ["Hypoglycemia", "Weight gain", "Injection site reactions", "Lipodystrophy (with repeated same-site injection)", "Severe hypoglycemia (serious)"]}, {"topic": "endo", "generic": "Insulin aspart", "pronunciation": "IN-suh-lin AS-part", "brand": ["NovoRapid", "Fiasp"], "class": "Rapid-acting insulin analog", "moa": "Modified insulin analog with faster subcutaneous absorption than regular human insulin, providing rapid onset and shorter duration to mimic prandial (meal-time) insulin release.", "indication": "Prandial/bolus glycemic control in type 1 and type 2 diabetes; insulin pump use.", "dosage": "Individualized; typically 0.1–0.15 units/kg SC with meals or per carb ratio/correction scale, given immediately before meals", "examPoints": ["Onset ~10-15 min, peak ~1-2h, duration ~3-5h — dosed just before or with meals (unlike regular insulin, given 30 min before)", "Fiasp (faster-acting formulation) can be dosed at the start of a meal or within 20 minutes after starting", "Used in basal-bolus regimens and insulin pumps for mealtime coverage and correction doses", "Risk of hypoglycemia increases if injected but meal is skipped/delayed or underestimated in carb counting", "Insulin remains a leading cause of medication error/hospitalization — always double-check units and insulin type"], "counselling": ["Inject shortly before eating (or per product-specific timing) — do not inject and then skip the meal", "Match your dose to the carbohydrate content of your meal as taught by your diabetes team (carb counting)", "Recognize and treat hypoglycemia promptly with fast-acting sugar", "Rotate injection sites to prevent lipodystrophy", "Store as directed; check the insulin looks clear (not cloudy) before injecting"], "sideEffects": ["Hypoglycemia", "Weight gain", "Injection site reactions", "Lipodystrophy", "Severe hypoglycemia (serious)"]}, {"topic": "endo", "generic": "Levothyroxine", "pronunciation": "lee-voh-thy-ROKS-een", "brand": ["Synthroid", "Eltroxin"], "class": "Thyroid hormone replacement (T4)", "moa": "Synthetic thyroxine (T4) that is peripherally converted to active T3, replacing endogenous thyroid hormone and restoring normal metabolic regulation via feedback on TSH.", "indication": "Hypothyroidism; TSH suppression in thyroid cancer.", "dosage": "Individualized by TSH/weight; typical start 1.6 mcg/kg/day PO (lower start 25–50 mcg/day in elderly/cardiac disease), on empty stomach", "examPoints": ["Narrow therapeutic index — check TSH ~6-8 weeks after any dose change", "Take on an empty stomach, 30-60 min before breakfast (or at bedtime, ≥3h after last meal) for consistent absorption", "Numerous absorption interactions: calcium, iron, antacids, PPIs — separate by ≥4 hours", "Lower starting dose in elderly and those with cardiac disease (risk of angina/arrhythmia if titrated too fast)", "Increased dose requirements often needed in pregnancy (~25-30% increase, checked each trimester)"], "counselling": ["Take on an empty stomach at the same time each day, consistently, at least 30-60 minutes before food or other medications", "Separate from calcium, iron supplements, and antacids by at least 4 hours", "Stick with the same brand/formulation when possible — switching can affect levels", "Regular blood tests (TSH) are needed to fine-tune your dose, especially after any change", "Report chest pain, palpitations, or heat intolerance/tremor (possible signs of too high a dose)"], "sideEffects": ["Palpitations", "Insomnia", "Weight loss", "Heat intolerance/sweating", "Tremor", "Arrhythmia/angina (if over-replaced, especially elderly)"]}, {"topic": "endo", "generic": "Alendronate", "pronunciation": "uh-LEN-droh-nayt", "brand": ["Fosamax"], "class": "Bisphosphonate", "moa": "Binds to hydroxyapatite in bone and inhibits osteoclast-mediated bone resorption, increasing bone mineral density over time.", "indication": "Osteoporosis treatment and prevention (postmenopausal and glucocorticoid-induced).", "dosage": "70 mg PO once weekly (or 10 mg daily); take on empty stomach with full glass of water, remain upright ≥30 min", "examPoints": ["Must be taken first thing in the morning, on an empty stomach, with a full glass of plain water, then remain upright (sitting/standing) for 30-60 minutes and not eat/drink anything else", "Contraindicated in esophageal abnormalities (strictures, achalasia) and inability to stand/sit upright for 30 min", "Rare but serious: osteonecrosis of the jaw and atypical femur fractures with long-term use — dental work ideally completed before starting", "Ensure adequate calcium and vitamin D intake concurrently", "'Drug holiday' often considered after 3-5 years in lower-risk patients"], "counselling": ["Take first thing in the morning on an empty stomach with a full glass of plain water (not mineral water, juice, coffee)", "Stay upright (sitting or standing) for at least 30-60 minutes after taking it and do not lie down", "Wait at least 30-60 minutes before eating, drinking anything else, or taking other medications", "Report difficulty/pain swallowing, chest pain, or severe heartburn", "Tell your dentist you're on this medication before any dental extractions or implants"], "sideEffects": ["Esophageal irritation/heartburn", "GI upset", "Musculoskeletal pain", "Osteonecrosis of the jaw (rare)", "Atypical femur fracture (rare)"]}, {"topic": "endo", "generic": "Sitagliptin", "pronunciation": "sit-uh-GLIP-tin", "brand": ["Januvia"], "class": "DPP-4 inhibitor", "moa": "Inhibits dipeptidyl peptidase-4, the enzyme that degrades endogenous GLP-1 and GIP, prolonging incretin activity and enhancing glucose-dependent insulin secretion.", "indication": "Type 2 diabetes, add-on or combination therapy.", "dosage": "100 mg PO once daily; reduce to 50 mg (eGFR 30–45) or 25 mg (eGFR <30)", "examPoints": ["Weight-neutral and low hypoglycemia risk when used alone (unlike sulfonylureas)", "Generally well-tolerated but modest A1C-lowering effect compared to SGLT2i/GLP-1 agonists", "Rare risk of acute pancreatitis — discontinue if suspected", "Renal dose adjustment required as eGFR declines (unlike linagliptin, which is not renally cleared)", "No proven cardiovascular benefit (contrast with SGLT2i/GLP-1 agonists) — not preferred in patients with established ASCVD/HF"], "counselling": ["Take once daily, with or without food", "Report persistent severe abdominal pain (possible pancreatitis)", "Low risk of hypoglycemia on its own, but higher if combined with insulin or a sulfonylurea", "Report joint pain — rare but reported side effect", "Continue diet and exercise measures as advised by your care team"], "sideEffects": ["Headache", "Nasopharyngitis", "GI upset", "Joint pain", "Pancreatitis (rare)", "Hypersensitivity/angioedema (rare)"]}, {"topic": "endo", "generic": "Prednisone", "pronunciation": "PRED-nih-sohn", "brand": ["Winpred"], "class": "Systemic corticosteroid (glucocorticoid)", "moa": "Binds intracellular glucocorticoid receptors, modulating gene transcription to suppress inflammatory and immune responses; also has significant metabolic (gluconeogenic) effects.", "indication": "Adrenal insufficiency replacement; anti-inflammatory/immunosuppressive use in many conditions (asthma exacerbation, autoimmune disease, etc.).", "dosage": "Highly variable by indication; typical 5–60 mg PO daily, taper gradually if used >2–3 weeks or high dose", "examPoints": ["Causes hyperglycemia/steroid-induced diabetes — a classic cause of new/worsened hyperglycemia to screen for on exams", "Long-term use requires tapering, not abrupt discontinuation, to avoid adrenal crisis (HPA axis suppression)", "Increases risk of osteoporosis with chronic use — consider calcium/vitamin D ± bisphosphonate prophylaxis", "Take in the morning with food to mimic natural cortisol rhythm and reduce GI upset", "Chronic use: monitor blood glucose, blood pressure, bone density, and for infection risk (immunosuppression)"], "counselling": ["Take in the morning with food to reduce stomach upset and match your body's natural rhythm", "Do not stop abruptly if you've been on it for more than a couple of weeks — must be tapered as directed", "Monitor blood sugar more closely if you have diabetes — this drug raises blood glucose", "Report signs of infection promptly, as this drug can mask or increase infection risk", "Carry a steroid alert card/wallet card if on long-term therapy"], "sideEffects": ["Hyperglycemia", "Weight gain/increased appetite", "Mood changes/insomnia", "Increased infection risk", "Osteoporosis (long-term)", "Adrenal suppression/adrenal crisis if stopped abruptly"]}, {"topic": "endo", "generic": "Liraglutide", "pronunciation": "lir-uh-GLOO-tyd", "brand": ["Victoza", "Saxenda"], "class": "GLP-1 receptor agonist", "moa": "Activates GLP-1 receptors to enhance glucose-dependent insulin secretion, suppress glucagon, slow gastric emptying, and increase satiety.", "indication": "Type 2 diabetes (Victoza); chronic weight management (Saxenda).", "dosage": "Diabetes: start 0.6 mg SC daily x1 week, increase to 1.2 mg, max 1.8 mg/day. Weight management (Saxenda): titrate to 3 mg/day", "examPoints": ["Once-daily subcutaneous injection (contrast with once-weekly semaglutide/dulaglutide)", "Contraindicated in personal/family history of medullary thyroid carcinoma or MEN2 (black box warning)", "Proven cardiovascular benefit in T2DM with established ASCVD (LEADER trial)", "Dose titrated slowly (weekly increases) to minimize GI side effects", "Saxenda (weight management) dosed higher than Victoza (diabetes) — different max doses, do not interchange"], "counselling": ["Inject once daily, any time of day, with or without food, same time each day preferred", "Rotate injection sites (abdomen, thigh, upper arm)", "Nausea is common initially — often improves as your body adjusts; eat smaller meals", "Report severe persistent abdominal pain (possible pancreatitis) or neck lump/hoarseness", "Do not share pens between people, even with a new needle"], "sideEffects": ["Nausea", "Vomiting", "Diarrhea", "Decreased appetite", "Pancreatitis (rare)", "Injection site reactions"]}, {"topic": "endo", "generic": "Methimazole", "pronunciation": "meh-THIM-uh-zohl", "brand": ["Tapazole"], "class": "Thionamide antithyroid agent", "moa": "Inhibits thyroid peroxidase, blocking iodination of tyrosine residues on thyroglobulin and thus reducing synthesis of T3/T4.", "indication": "Hyperthyroidism (Graves' disease, toxic nodular goiter); pre-treatment before radioactive iodine or thyroidectomy.", "dosage": "Start 10–30 mg/day PO (divided or once daily) based on severity, titrate to maintenance 5–15 mg/day", "examPoints": ["Preferred over propylthiouracil (PTU) except in first trimester of pregnancy or thyroid storm (PTU preferred in those situations due to teratogenicity of methimazole/faster PTU onset in storm)", "Rare but serious: agranulocytosis — counsel to report sore throat/fever immediately, get CBC checked", "Also rare: hepatotoxicity (more with PTU) — monitor LFTs if symptomatic", "Does not affect existing stored hormone — clinical effect delayed until stores are depleted (weeks)", "Teratogenic — associated with aplasia cutis and choanal/esophageal atresia if used in first trimester"], "counselling": ["Take as directed, consistently, at the same time each day", "Report sore throat, fever, or mouth ulcers immediately — could indicate a serious drop in white blood cells", "Report yellowing of skin/eyes, dark urine, or severe fatigue (possible liver involvement)", "Inform your prescriber right away if you are or could become pregnant", "Effects on thyroid levels take some weeks to become apparent — regular thyroid blood tests will guide dose"], "sideEffects": ["Rash", "GI upset", "Agranulocytosis (rare, serious)", "Hepatotoxicity (rare, serious)", "Arthralgia"]}, {"topic": "endo", "generic": "Pioglitazone", "pronunciation": "py-oh-GLIT-uh-zohn", "brand": ["Actos"], "class": "Thiazolidinedione (TZD)", "moa": "Activates PPAR-gamma nuclear receptors in adipose, muscle, and liver, improving peripheral insulin sensitivity and glucose uptake.", "indication": "Type 2 diabetes, second/third-line add-on therapy.", "dosage": "15–30 mg PO once daily, may increase to max 45 mg/day", "examPoints": ["Contraindicated in heart failure (NYHA III-IV) — causes fluid retention/edema and can precipitate/worsen HF", "Associated with weight gain and increased fracture risk (especially in women)", "Possible association with bladder cancer — caution with active or prior bladder cancer", "Onset of full glycemic effect is slow (weeks to months)", "Low hypoglycemia risk when used alone"], "counselling": ["Take once daily, with or without food", "Report swelling in the legs/ankles or sudden shortness of breath (fluid retention/heart failure risk)", "Report blood in urine or new urinary symptoms", "Weight gain and mild swelling are common — discuss with your care team if bothersome", "May take several weeks to see full blood sugar-lowering effect"], "sideEffects": ["Weight gain", "Peripheral edema", "Fracture risk (increased)", "Heart failure exacerbation", "Bladder cancer (possible association, rare)"]}, {"topic": "endo", "generic": "Desmopressin", "pronunciation": "dez-moh-PRES-in", "brand": ["DDAVP", "Octostim"], "class": "Synthetic vasopressin (ADH) analog", "moa": "Selectively activates renal V2 receptors, increasing water reabsorption in the collecting duct (antidiuretic effect) with minimal V1 (vasopressor) activity.", "indication": "Central diabetes insipidus; nocturnal enuresis; mild hemophilia A/von Willebrand disease (V1a-mediated factor release, different use).", "dosage": "Diabetes insipidus: 0.1–0.4 mg PO daily in divided doses, or 10–40 mcg intranasal daily; nocturia 25–50 mcg intranasal or 0.1–0.4 mg PO at bedtime", "examPoints": ["Major risk: hyponatremia/water intoxication if fluid intake not restricted appropriately, especially in elderly and young children", "Available in intranasal, oral, and injectable forms — bioavailability differs greatly between routes, not interchangeable dose-for-dose", "Monitor serum sodium, urine output/osmolality when initiating or adjusting dose for DI", "Distinguishes central (responds to desmopressin) from nephrogenic diabetes insipidus (does not respond)", "Restrict fluid intake around dosing time to reduce hyponatremia risk"], "counselling": ["Take/use exactly as directed — do not increase dose or frequency on your own", "Limit fluid intake as instructed, especially in the hour before and after dosing, to avoid water retention", "Report headache, nausea, confusion, or unusual weight gain (possible signs of low sodium/water overload)", "If using the nasal spray, learn the proper technique from your pharmacist", "Keep track of urine output/thirst as discussed with your prescriber to monitor effectiveness"], "sideEffects": ["Headache", "Nasal congestion (intranasal)", "Nausea", "Hyponatremia/water intoxication (serious)", "Fluid retention"]}, {"topic": "endo", "generic": "Hydrocortisone", "pronunciation": "hy-droh-KOR-tih-zohn", "brand": ["Cortef"], "class": "Glucocorticoid (physiologic replacement)", "moa": "Replaces endogenous cortisol at physiologic doses, restoring normal glucose, protein, and fat metabolism and stress response; has both glucocorticoid and mild mineralocorticoid activity.", "indication": "Primary and secondary adrenal insufficiency (Addison's disease); adrenal crisis management; congenital adrenal hyperplasia.", "dosage": "Physiologic replacement 15–25 mg/day PO in 2–3 divided doses (higher AM dose); stress dosing 2–3x usual dose during illness", "examPoints": ["Physiologic replacement dosing mimics diurnal cortisol rhythm — larger dose in morning, smaller in afternoon (unlike anti-inflammatory prednisone dosing)", "'Sick day rules' — patients must double/triple their dose during illness, fever, vomiting, trauma, or surgery to avoid adrenal crisis", "Adrenal crisis is a medical emergency: hypotension, shock, hypoglycemia, hyponatremia/hyperkalemia — treated with IV hydrocortisone and fluids", "Patients must never stop abruptly and should carry a medical alert bracelet/card and an emergency injectable hydrocortisone kit", "Distinct from prednisone's anti-inflammatory use — this is life-sustaining replacement therapy, not optional"], "counselling": ["Take exactly as scheduled — typically a larger dose in the morning, smaller dose in the afternoon, to mimic your body's natural rhythm", "Never stop this medication abruptly, even if you feel unwell — your body depends on it", "Double or triple your dose during illness, fever, injury, or before surgery as taught by your care team ('sick day rules'), and seek help if you can't keep the dose down", "Wear a medical alert bracelet and carry an emergency injection kit if prescribed", "Seek emergency care for severe vomiting, fainting, or if you cannot take your oral dose — you may need an emergency injection"], "sideEffects": ["Weight gain (supraphysiologic doses)", "Insomnia", "Mood changes", "GI upset", "Adrenal crisis (if under-dosed during illness, serious)", "Osteoporosis (long-term supraphysiologic use)"]}, {"topic": "resp", "generic": "Salbutamol", "pronunciation": "sal-BYOO-tuh-mol", "brand": ["Ventolin", "Airomir"], "class": "Short-acting beta2-agonist (SABA)", "moa": "Selectively stimulates beta2-adrenergic receptors on bronchial smooth muscle, activating adenylyl cyclase to increase cAMP and produce bronchodilation. Onset within 5 min, duration 4-6h.", "indication": "Rescue/reliever therapy for acute bronchospasm in asthma and COPD; pre-exercise prophylaxis.", "dosage": "MDI: 100–200 mcg (1–2 puffs) q4–6h PRN, max per acute episode higher under supervision; nebulized 2.5–5 mg q4–6h PRN", "examPoints": ["Rescue inhaler of choice — used PRN, not scheduled; overuse (>2 canisters/yr or >1 canister/month) signals poor control and increased mortality risk", "Increasing SABA use is a red flag requiring step-up in controller therapy per Canadian Asthma Guidelines", "Beta2 selectivity is not absolute — can cause tachycardia, tremor, hypokalemia especially at high doses", "Onset ~5 min, peak 30-60 min, duration 4-6h — distinguishes from LABA", "Available as MDI, diskus, and nebule; spacer improves lung deposition with MDI"], "counselling": ["Use only as needed for sudden shortness of breath or wheeze, or 15 min before exercise", "Shake MDI well, use a spacer if possible, rinse mouth not required (no steroid)", "Carry it with you at all times as a rescue medication", "If you're using it more than 2-3 times a week, tell your pharmacist/doctor — your asthma control needs review", "Expect a fast-acting effect within minutes; tremor and fast heartbeat can occur but usually improve"], "sideEffects": ["Tremor", "Tachycardia/palpitations", "Headache", "Nervousness", "Hypokalemia (high doses)", "Paradoxical bronchospasm (rare)"]}, {"topic": "resp", "generic": "Salmeterol", "pronunciation": "sal-MEE-ter-ol", "brand": ["Serevent"], "class": "Long-acting beta2-agonist (LABA)", "moa": "Selective beta2-agonist with a long lipophilic side chain anchoring it near the receptor, giving sustained bronchodilation over ~12 hours; slower onset than salbutamol.", "indication": "Maintenance bronchodilation in asthma (always with ICS) and COPD; not for acute relief.", "dosage": "50 mcg (1 inhalation) BID via Diskus; not for acute rescue; always with ICS in asthma", "examPoints": ["Black box warning: LABA monotherapy in asthma increases risk of severe exacerbation and asthma-related death — must always be combined with ICS", "Slower onset (~30-48 min) than formoterol — NOT for acute rescue use", "In COPD, LABA can be used without ICS (unlike asthma)", "Duration ~12h, given BID", "Combination products (e.g., fluticasone/salmeterol = Advair) improve adherence and mitigate the monotherapy risk"], "counselling": ["This is a maintenance/controller medication — take it on a regular schedule, not for sudden symptoms", "Do not stop your inhaled corticosteroid or use this inhaler alone without steroid", "Keep your fast-acting rescue inhaler (salbutamol) with you for sudden symptoms", "Effects take longer to start than a rescue inhaler — do not use this for an acute attack", "Report worsening asthma symptoms despite using this medication"], "sideEffects": ["Tremor", "Headache", "Tachycardia/palpitations", "Muscle cramps", "Increased asthma-related death risk if used without ICS (rare, black box)"]}, {"topic": "resp", "generic": "Tiotropium", "pronunciation": "ty-oh-TROH-pee-um", "brand": ["Spiriva"], "class": "Long-acting muscarinic antagonist (LAMA)", "moa": "Blocks M3 muscarinic receptors on airway smooth muscle, preventing acetylcholine-mediated bronchoconstriction; kinetic selectivity gives once-daily dosing (slow dissociation from M3 vs M2).", "indication": "Maintenance treatment of COPD (first-line); add-on in severe asthma.", "dosage": "18 mcg (1 capsule via HandiHaler) once daily, or 2 puffs (2.5 mcg/puff) once daily via Respimat", "examPoints": ["First-line maintenance option in COPD per GOLD/Canadian guidelines, alone or combined with LABA", "Once-daily dosing via HandiHaler (capsule, do not swallow) or Respimat (soft mist)", "Caution/relative contraindication: narrow-angle glaucoma and BPH/urinary retention due to anticholinergic effects", "Distinguish from ipratropium (SAMA, short-acting) used for acute exacerbations", "Not for acute symptom relief — onset is gradual"], "counselling": ["Take once daily at the same time each day for long-term control, not for sudden breathlessness", "HandiHaler capsules are for inhalation only — never swallow them", "Rinse mouth after use to reduce dry mouth", "Report eye pain, blurred vision, or difficulty urinating right away", "Effect builds over days-weeks; keep using even if you don't feel an immediate difference"], "sideEffects": ["Dry mouth", "Constipation", "Urinary retention (esp. BPH)", "Blurred vision if sprayed in eyes", "Increased cardiovascular events (debated)", "Angle-closure glaucoma precipitation (rare)"]}, {"topic": "resp", "generic": "Fluticasone propionate", "pronunciation": "floo-TIK-uh-zohn PROH-pee-oh-nayt", "brand": ["Flovent"], "class": "Inhaled corticosteroid (ICS)", "moa": "Binds glucocorticoid receptors, suppressing inflammatory gene transcription (cytokines, chemokines) and reducing airway hyperresponsiveness and mucosal edema.", "indication": "Maintenance/controller therapy for persistent asthma; reduces exacerbation frequency.", "dosage": "Inhaled: 100–500 mcg BID depending on severity/device (max ~1000 mcg BID for severe asthma)", "examPoints": ["Cornerstone of asthma controller therapy at every step above mild intermittent — reduces airway inflammation, not bronchodilator", "Oral candidiasis (thrush) and dysphonia are the classic local side effects — prevented by rinsing mouth and spacer use", "High-dose long-term use associated with adrenal suppression, growth suppression in children, osteoporosis, cataracts", "Not for acute symptom relief — has no bronchodilator effect", "GINA 2023 preferred approach: as-needed low-dose ICS-formoterol even in mild asthma (SMART strategy) rather than SABA alone"], "counselling": ["Use every day as prescribed even when feeling well — it prevents inflammation, it doesn't relieve sudden symptoms", "Rinse your mouth and spit after each use to prevent oral thrush and hoarse voice", "Use a spacer with the MDI to improve delivery and reduce throat side effects", "It can take 1-2 weeks to see full benefit", "In children, growth may be monitored periodically by the physician"], "sideEffects": ["Oral candidiasis (thrush)", "Dysphonia/hoarseness", "Sore throat", "Adrenal suppression (high dose/long-term)", "Growth suppression in children", "Cataracts/osteoporosis (long-term high dose)"]}, {"topic": "resp", "generic": "Budesonide/Formoterol", "pronunciation": "byoo-DES-oh-nyd / for-MOH-ter-ol", "brand": ["Symbicort"], "class": "ICS-LABA combination", "moa": "Budesonide (ICS) reduces airway inflammation while formoterol (fast-onset LABA) provides rapid and sustained bronchodilation via beta2-agonism.", "indication": "Asthma maintenance-and-reliever therapy (SMART/MART); COPD maintenance.", "dosage": "1–2 inhalations BID (maintenance); may be used as maintenance-and-reliever therapy (SMART) up to 8 inhalations/day max", "examPoints": ["Formoterol has a fast onset (~1-3 min) unlike salmeterol — this is what enables the SMART/MART single-inhaler strategy", "SMART approach: same inhaler used both daily as controller AND as-needed for symptoms, reducing total steroid exposure and exacerbations", "GINA preferred track 1 for asthma steps 1-2: as-needed low-dose ICS-formoterol replaces SABA-only reliever", "Maximum recommended total formoterol dose per day should not be exceeded (check product-specific max, e.g., 8 inhalations/day for Symbicort SMART in adults)", "Not interchangeable with salmeterol-containing combos for the reliever role due to onset difference"], "counselling": ["If prescribed for MART/SMART, use it both as your daily controller AND for symptom relief as directed — follow your specific plan", "Rinse your mouth after each use to prevent thrush", "Do not exceed the maximum number of puffs per day your doctor specified", "Carry it with you since it may double as your reliever", "Seek urgent care if you need increasing extra doses and aren't improving"], "sideEffects": ["Oral thrush", "Tremor", "Palpitations", "Headache", "Hoarseness", "Adrenal suppression (long-term high dose)"]}, {"topic": "resp", "generic": "Tiotropium/Olodaterol", "pronunciation": "ty-oh-TROH-pee-um / oh-loh-DA-ter-ol", "brand": ["Inspiolto Respimat"], "class": "LAMA-LABA combination", "moa": "Combines M3 muscarinic antagonism (tiotropium) with beta2-agonism (olodaterol) for complementary bronchodilation via two distinct pathways.", "indication": "Maintenance treatment of COPD (not indicated for asthma).", "dosage": "5 mcg/5 mcg (2 inhalations) once daily via Respimat", "examPoints": ["Dual bronchodilator (LAMA+LABA) is a guideline option for COPD patients with persistent breathlessness on monotherapy", "No ICS component — appropriate for COPD patients without frequent exacerbations/eosinophilia where ICS isn't indicated", "Once-daily via Respimat soft-mist inhaler", "Same cautions as individual components: glaucoma, BPH/urinary retention, cardiovascular disease", "Not for acute rescue use"], "counselling": ["Take once daily, same time each day, as a long-term maintenance treatment for COPD", "This is not a rescue inhaler — keep a fast-acting bronchodilator for sudden symptoms", "Learn the Respimat priming and inhalation technique carefully — it differs from standard MDIs", "Report eye pain, vision changes, or trouble urinating", "Effects build over time; don't stop without talking to your doctor"], "sideEffects": ["Dry mouth", "Nasopharyngitis", "Cough", "Dizziness", "Urinary retention", "Tachycardia/palpitations"]}, {"topic": "resp", "generic": "Montelukast", "pronunciation": "mon-teh-LOO-kast", "brand": ["Singulair"], "class": "Leukotriene receptor antagonist (LTRA)", "moa": "Blocks cysteinyl leukotriene type-1 (CysLT1) receptors, inhibiting leukotriene-mediated bronchoconstriction, mucus secretion, and airway edema.", "indication": "Add-on maintenance therapy for asthma; allergic rhinitis; exercise-induced bronchoconstriction prophylaxis.", "dosage": "10 mg PO once daily in the evening (5 mg for ages 6–14, 4 mg for ages 2–5)", "examPoints": ["Health Canada boxed warning for neuropsychiatric effects: agitation, aggression, nightmares, depression, suicidal thoughts — must counsel patients/caregivers", "Taken once daily in the evening for asthma/allergic rhinitis regardless of symptoms", "Less effective than ICS as monotherapy — used as add-on or alternative in mild cases/aspirin-exacerbated respiratory disease", "Useful in aspirin-exacerbated respiratory disease (AERD) and exercise-induced bronchoconstriction", "Not a rescue medication and has no immediate bronchodilator effect"], "counselling": ["Take once daily in the evening, with or without food, even when you feel well", "Watch for and report mood or behaviour changes — agitation, nightmares, suicidal thoughts — especially in children/teens", "This is not a rescue medication for sudden breathing problems", "Continue other asthma medications unless told to stop", "May help with seasonal allergy symptoms as well as asthma"], "sideEffects": ["Headache", "Abdominal pain", "Neuropsychiatric effects (agitation, nightmares, depression — boxed warning)", "Upper respiratory infection symptoms", "Churg-Strauss syndrome (rare, esp. with steroid tapering)"]}, {"topic": "resp", "generic": "Cetirizine", "pronunciation": "seh-TEER-ih-zeen", "brand": ["Reactine"], "class": "Second-generation H1-antihistamine", "moa": "Selectively blocks peripheral H1-histamine receptors, reducing allergic symptoms (itching, sneezing, rhinorrhea) with minimal CNS penetration compared to first-generation agents.", "indication": "Allergic rhinitis, chronic urticaria, allergic conjunctivitis.", "dosage": "10 mg PO once daily (5 mg if mild renal/hepatic impairment or elderly); max 10 mg/day", "examPoints": ["Second-generation = much less sedating and fewer anticholinergic effects than diphenhydramine (crosses blood-brain barrier less)", "Still mildly sedating in some patients compared to fexofenadine/loratadine — the least sedating options", "Onset within 1 hour, duration ~24h allowing once-daily dosing", "Renal dose adjustment needed in renal impairment", "Preferred first-line for allergic rhinitis/urticaria over first-generation antihistamines due to safety profile"], "counselling": ["Take once daily; can be taken any time but consistent timing helps", "May cause mild drowsiness in some people — use caution driving until you know how it affects you", "Avoid or limit alcohol as it can increase drowsiness", "Effects typically last 24 hours", "Contact your pharmacist if symptoms don't improve or worsen"], "sideEffects": ["Mild drowsiness", "Dry mouth", "Headache", "Fatigue", "Rarely: paradoxical CNS stimulation in children"]}, {"topic": "resp", "generic": "Diphenhydramine", "pronunciation": "dy-fen-HY-druh-meen", "brand": ["Benadryl"], "class": "First-generation H1-antihistamine", "moa": "Nonselective H1-receptor antagonist that crosses the blood-brain barrier readily, producing marked sedation and anticholinergic effects in addition to antihistamine action.", "indication": "Allergic reactions/urticaria, insomnia (short-term OTC use), motion sickness, antitussive.", "dosage": "25–50 mg PO q4–6h PRN; max 300 mg/day (25–50 mg IV/IM for acute allergic reactions)", "examPoints": ["Significant anticholinergic burden — avoid/use caution in elderly (Beers Criteria: high fall/cognitive risk), BPH, narrow-angle glaucoma", "Highly sedating — do not combine with alcohol or other CNS depressants; caution with driving", "Not recommended for chronic daily use for allergies — second-generation agents preferred", "Common ingredient in OTC sleep aids and multi-symptom cold products — risk of therapeutic duplication/anticholinergic toxicity", "Anticholinergic toxidrome: 'red as a beet, dry as a bone, blind as a bat, mad as a hatter, hot as a hare'"], "counselling": ["Causes drowsiness — avoid driving or operating machinery after taking it", "Avoid alcohol and other sedating medications while taking this", "Check other OTC products (cold/flu, sleep aids) for duplicate antihistamine ingredients before combining", "Older adults should generally avoid this medication due to confusion and fall risk — ask your pharmacist for alternatives", "May cause dry mouth, blurred vision, and constipation"], "sideEffects": ["Sedation/drowsiness", "Dry mouth", "Blurred vision", "Constipation/urinary retention", "Confusion (especially elderly)", "Paradoxical excitation in children"]}, {"topic": "resp", "generic": "Pseudoephedrine", "pronunciation": "soo-doh-eh-FED-rin", "brand": ["Sudafed"], "class": "Oral decongestant (sympathomimetic)", "moa": "Indirect-acting sympathomimetic that stimulates alpha-adrenergic receptors on nasal mucosa vasculature, causing vasoconstriction and reduced nasal congestion.", "indication": "Symptomatic relief of nasal/sinus congestion.", "dosage": "60 mg PO q4–6h PRN, or 120 mg extended-release q12h; max 240 mg/day", "examPoints": ["Kept behind-the-counter in Canada due to methamphetamine precursor potential — purchase quantities/ID may be tracked", "Contraindicated/caution in uncontrolled hypertension, cardiovascular disease, and with MAOIs (hypertensive crisis risk)", "Can cause insomnia — advise avoiding evening doses", "Distinguish from topical decongestants (oxymetazoline) which risk rhinitis medicamentosa with >3 days use; oral pseudoephedrine does not cause rebound congestion the same way", "Caution in BPH (urinary retention) and hyperthyroidism"], "counselling": ["Take during the day, not close to bedtime, as it can cause trouble sleeping", "Avoid if you have uncontrolled high blood pressure or heart disease — check with your pharmacist first", "Do not use with MAOI antidepressants", "You may need to show ID and sign a log to purchase this due to regulations", "Stop and seek care if you develop chest pain, severe headache, or irregular heartbeat"], "sideEffects": ["Insomnia", "Nervousness/jitteriness", "Increased heart rate", "Increased blood pressure", "Urinary retention (BPH)", "Hypertensive crisis with MAOIs (rare, serious)"]}, {"topic": "resp", "generic": "Oxymetazoline", "pronunciation": "oks-ee-meh-TAZ-oh-leen", "brand": ["Dristan", "Otrivin"], "class": "Topical nasal decongestant (alpha-adrenergic agonist)", "moa": "Direct alpha1-adrenergic agonist causing local vasoconstriction of nasal mucosa vessels, rapidly reducing congestion.", "indication": "Short-term relief of nasal congestion.", "dosage": "2–3 sprays per nostril BID PRN; limit to ≤3 consecutive days to avoid rebound congestion (rhinitis medicamentosa)", "examPoints": ["Classic exam trap: limit use to a MAXIMUM of 3 consecutive days to avoid rhinitis medicamentosa (rebound congestion)", "Rhinitis medicamentosa is caused by receptor downregulation with chronic use, leading to worsening congestion cycle", "Treatment of rebound congestion is discontinuation (may need gradual taper/one nostril at a time), not more spray", "Systemic absorption can occur, so same cardiovascular cautions as oral decongestants apply, though risk is lower", "Nasal sprays should not be shared between individuals (infection risk)"], "counselling": ["Do not use for more than 3 days in a row — longer use can make congestion worse (rebound effect)", "Tilt head slightly forward when spraying and avoid touching the tip to your nose", "Do not share your nasal spray bottle with others", "If congestion persists beyond 3 days, switch to a saline rinse or see a pharmacist/doctor rather than continuing", "Blow your nose gently before use for best effect"], "sideEffects": ["Local burning/stinging", "Dryness of nasal mucosa", "Sneezing", "Rebound congestion (rhinitis medicamentosa) with prolonged use", "Systemic sympathomimetic effects (rare)"]}, {"topic": "resp", "generic": "Varenicline", "pronunciation": "vuh-REN-ih-kleen", "brand": ["Champix"], "class": "Smoking cessation agent — nicotinic receptor partial agonist", "moa": "Partial agonist at alpha4-beta2 nicotinic acetylcholine receptors — provides mild dopamine release to reduce cravings/withdrawal while blocking nicotine from binding fully, reducing smoking reward.", "indication": "Smoking cessation aid.", "dosage": "Start 0.5 mg PO daily x3 days, then 0.5 mg BID x4 days, then 1 mg BID; begin 1 week before quit date, continue 12 weeks", "examPoints": ["Most effective single pharmacotherapy for smoking cessation in head-to-head trials, more effective than bupropion or single-form NRT", "Standard regimen: start 1 week before quit date, titrate dose over first week, continue 12 weeks (can extend another 12 for relapse prevention)", "Original boxed warning for neuropsychiatric effects was removed after EAGLES trial reassurance, but still monitor for mood/behaviour changes", "Dose adjustment needed in severe renal impairment", "Can be combined with counselling for best quit rates"], "counselling": ["Start this about 1 week before your planned quit date; you can keep smoking during the first week of titration", "Take after eating with a full glass of water to reduce nausea", "Typical course is 12 weeks; your doctor may extend it if helpful", "Report any unusual mood changes, agitation, or thoughts of self-harm to your doctor immediately", "Nausea is common early on and often improves with continued use"], "sideEffects": ["Nausea (most common)", "Insomnia", "Abnormal/vivid dreams", "Headache", "Mood changes/depression (monitor)", "Rare: seizures, cardiovascular events"]}, {"topic": "resp", "generic": "Bupropion", "pronunciation": "byoo-PROH-pee-on", "brand": ["Zyban", "Wellbutrin"], "class": "Smoking cessation agent — atypical antidepressant (NDRI)", "moa": "Norepinephrine-dopamine reuptake inhibitor; exact mechanism for smoking cessation unclear but thought to reduce nicotine craving/withdrawal via dopaminergic effects and act as a mild nicotinic receptor antagonist.", "indication": "Smoking cessation (Zyban brand); major depressive disorder (Wellbutrin brand) — same molecule, different indications/brands.", "dosage": "Smoking cessation: 150 mg PO daily x3 days, then 150 mg BID (SR); start 1–2 weeks before quit date", "examPoints": ["Lowers seizure threshold — contraindicated in seizure disorders, eating disorders (bulimia/anorexia — electrolyte disturbance risk), and abrupt alcohol/benzo withdrawal", "Start 1-2 weeks before quit date, similar to varenicline", "Same active ingredient as the antidepressant Wellbutrin — watch for therapeutic duplication if patient is on both brands", "Does not cause the sedation/weight gain typical of other antidepressants; can be activating (may help with fatigue)", "Avoid in patients with uncontrolled hypertension (can raise BP) and use caution with MAOIs"], "counselling": ["Start about 1-2 weeks before your quit date while still smoking initially", "Take doses at least 8 hours apart if on twice-daily dosing to reduce seizure risk", "Avoid alcohol, especially don't stop drinking abruptly while on this medication", "Do not take if you have a seizure disorder or history of eating disorder", "May cause insomnia — avoid taking your last dose too close to bedtime"], "sideEffects": ["Insomnia", "Dry mouth", "Headache", "Agitation/anxiety", "Seizures (dose-dependent, rare)", "Increased blood pressure"]}, {"topic": "resp", "generic": "Nicotine replacement therapy (patch/gum/lozenge)", "pronunciation": "NIK-oh-teen ree-PLAYS-ment THAIR-uh-pee", "brand": ["Nicoderm", "Nicorette"], "class": "Smoking cessation agent — nicotine replacement therapy (NRT)", "moa": "Delivers controlled doses of nicotine without tobacco combustion products, reducing withdrawal symptoms and cravings while allowing gradual dose tapering.", "indication": "Smoking cessation aid, as monotherapy or combination therapy.", "dosage": "Patch: 21 mg/24h x4–6wk, taper to 14 mg then 7 mg. Gum/lozenge: 2–4 mg q1–2h PRN (up to 24 pieces/day), based on time to first cigarette", "examPoints": ["Combination NRT (patch + fast-acting form like gum/lozenge) is more effective than any single form alone", "Patch provides steady-state nicotine (apply in morning, remove per product — 16h or 24h wear); gum/lozenge/inhaler for breakthrough cravings", "Dosing based on cigarettes/day smoked — heavier smokers start at higher patch dose", "Safe in cardiovascular disease (safer than continued smoking) — a classic exam trap, NRT is NOT contraindicated post-MI", "Local irritation with patch (rotate sites); jaw soreness with gum (chew-and-park technique)"], "counselling": ["Apply the patch to a clean, dry, hairless area each morning and rotate sites to avoid skin irritation", "Use gum with the 'chew and park' technique — chew briefly until tingling, then park between cheek and gum", "Avoid acidic drinks like coffee or juice for 15 minutes before/during use of gum or lozenge, as they reduce nicotine absorption", "Combining a patch with an as-needed form (gum/lozenge) works better than either alone", "It's safe to use even if you have heart disease — it's far safer than continuing to smoke"], "sideEffects": ["Skin irritation (patch)", "Mouth/throat irritation (gum, lozenge)", "Hiccups", "Nausea", "Insomnia/vivid dreams (patch, if worn overnight)", "Palpitations (rare)"]}, {"topic": "resp", "generic": "Roflumilast", "pronunciation": "roh-FLOO-mih-last", "brand": ["Daxas"], "class": "Phosphodiesterase-4 (PDE4) inhibitor", "moa": "Selectively inhibits PDE4, increasing intracellular cAMP in inflammatory cells, reducing lung inflammation associated with severe COPD; not a bronchodilator.", "indication": "Add-on maintenance treatment for severe COPD with chronic bronchitis phenotype and history of frequent exacerbations.", "dosage": "500 mcg PO once daily, for severe COPD with chronic bronchitis/frequent exacerbations", "examPoints": ["Reserved for severe COPD (FEV1 <50%) with chronic bronchitis and recurrent exacerbations despite bronchodilator therapy — add-on, not first-line", "Significant weight loss and GI side effects (diarrhea, nausea) are common — monitor weight, avoid in underweight patients", "Psychiatric effects: insomnia, anxiety, and depression including suicidal ideation reported — caution in psychiatric history", "Not a bronchodilator and has no role in acute exacerbations", "Avoid in hepatic impairment (moderate-severe)"], "counselling": ["This is an add-on tablet for severe COPD, taken once daily, not a rescue treatment", "Weight loss is common — your weight should be monitored regularly while on this medication", "Report new or worsening mood changes, anxiety, or thoughts of self-harm", "Diarrhea and nausea are common, especially when starting — tell your pharmacist if severe or persistent", "Continue your other COPD inhalers as prescribed"], "sideEffects": ["Diarrhea", "Nausea", "Weight loss", "Headache", "Insomnia", "Depression/psychiatric effects (monitor)"]}, {"topic": "cns", "generic": "Sertraline", "pronunciation": "SER-truh-leen", "brand": ["Zoloft"], "class": "Selective serotonin reuptake inhibitor (SSRI)", "moa": "Selectively inhibits presynaptic serotonin (5-HT) reuptake transporter, increasing synaptic serotonin availability; downstream receptor adaptation over weeks underlies delayed clinical effect.", "indication": "Major depressive disorder, panic disorder, OCD, PTSD, social anxiety disorder.", "dosage": "Start 50 mg PO daily, titrate by 50 mg increments q1wk+ as tolerated; usual range 50–200 mg/day", "examPoints": ["Full antidepressant effect takes 4-6 weeks; anxiety/GI side effects often appear first and improve over 1-2 weeks", "Black box warning: increased suicidality risk in children/adolescents/young adults (<25) especially in first weeks/dose changes", "Serotonin syndrome risk when combined with other serotonergic drugs (MAOIs, triptans, tramadol, other SSRIs/SNRIs) — never combine with MAOIs (14-day washout)", "Abrupt discontinuation causes discontinuation syndrome — taper needed (though sertraline's longer half-life makes this somewhat less severe than paroxetine)", "Considered relatively safe in pregnancy/breastfeeding among SSRIs; preferred post-MI for depression given cardiac safety data"], "counselling": ["Take at the same time each day, with food to reduce nausea", "It can take 4-6 weeks to feel the full benefit — keep taking it even if you don't notice a difference right away", "Do not stop suddenly — your dose needs to be tapered down under medical supervision", "Report any worsening mood, agitation, or thoughts of self-harm right away, especially in the first few weeks", "Avoid combining with other serotonergic supplements/medications (e.g., St. John's Wort) without checking first"], "sideEffects": ["Nausea", "GI upset/diarrhea", "Sexual dysfunction", "Insomnia or somnolence", "Headache", "Serotonin syndrome (rare, serious)", "Hyponatremia (esp. elderly)"]}, {"topic": "cns", "generic": "Venlafaxine", "pronunciation": "ven-luh-FAKS-een", "brand": ["Effexor XR"], "class": "Serotonin-norepinephrine reuptake inhibitor (SNRI)", "moa": "Inhibits reuptake of both serotonin and norepinephrine (serotonergic at low doses, noradrenergic effect increasing at higher doses), increasing synaptic availability of both neurotransmitters.", "indication": "Major depressive disorder, generalized anxiety disorder, social anxiety disorder, panic disorder.", "dosage": "Start 37.5–75 mg PO daily (XR), titrate q4–7 days; usual range 75–225 mg/day, max 375 mg/day", "examPoints": ["Dose-dependent blood pressure elevation — monitor BP, especially at higher doses (>150mg/day)", "Notorious for a severe discontinuation syndrome (dizziness, 'brain zaps', irritability) due to short half-life — requires slow taper", "Same suicidality boxed warning as other antidepressants in young people", "Serotonin syndrome risk with other serotonergic agents; avoid with MAOIs", "XR formulation allows once-daily dosing and reduces nausea vs immediate-release"], "counselling": ["Take the extended-release capsule at the same time each day, swallowed whole with food", "Your blood pressure may need periodic checks, especially if your dose is increased", "Do not stop abruptly — this medication requires a gradual taper to avoid withdrawal symptoms like dizziness or 'brain zaps'", "Full benefit may take several weeks", "Tell your doctor about all other medications, including migraine treatments and other antidepressants, to avoid interactions"], "sideEffects": ["Nausea", "Dry mouth", "Increased blood pressure (dose-dependent)", "Insomnia", "Sexual dysfunction", "Discontinuation syndrome (notable)", "Serotonin syndrome (rare)"]}, {"topic": "cns", "generic": "Quetiapine", "pronunciation": "kweh-TY-uh-peen", "brand": ["Seroquel"], "class": "Atypical (second-generation) antipsychotic", "moa": "Antagonizes dopamine D2 and serotonin 5-HT2A receptors, along with histamine H1 and alpha1-adrenergic receptors, contributing to antipsychotic effect and sedative/hypotensive properties.", "indication": "Schizophrenia, bipolar disorder (mania, depression, maintenance), adjunct for MDD; off-label low-dose for insomnia/anxiety.", "dosage": "Psychiatric dosing varies widely by indication; schizophrenia typically titrated to 300–800 mg/day; low doses (25–100 mg) used for sleep/adjunct (off-label)", "examPoints": ["Strong H1-antihistamine and alpha1-blocking activity explains prominent sedation and orthostatic hypotension, especially at low doses", "Metabolic syndrome risk: weight gain, dyslipidemia, hyperglycemia — requires baseline and periodic metabolic monitoring (weight, waist circumference, lipids, glucose/A1c)", "Lower extrapyramidal symptom (EPS) risk than typical antipsychotics due to rapid D2 dissociation, but not zero at high doses", "QT prolongation risk — caution with other QT-prolonging drugs", "Boxed warning: increased mortality in elderly patients with dementia-related psychosis (class effect for atypicals)"], "counselling": ["Take as directed; if taken for sleep it's usually given in the evening due to sedation", "Rise slowly from sitting/lying down to reduce dizziness from low blood pressure", "Regular monitoring of weight, blood sugar, and cholesterol is needed while on this medication", "Do not stop abruptly without medical advice", "Report fever, muscle stiffness, or confusion right away (rare but serious reaction)"], "sideEffects": ["Sedation/drowsiness", "Weight gain", "Orthostatic hypotension", "Dry mouth", "Metabolic syndrome (dyslipidemia, hyperglycemia)", "Neuroleptic malignant syndrome (rare, serious)", "QT prolongation"]}, {"topic": "cns", "generic": "Risperidone", "pronunciation": "ris-PER-ih-dohn", "brand": ["Risperdal"], "class": "Atypical (second-generation) antipsychotic", "moa": "Antagonizes D2 and 5-HT2A receptors; at higher doses D2 blockade predominates, increasing EPS risk relative to other atypicals; also blocks alpha1-adrenergic receptors.", "indication": "Schizophrenia, bipolar mania, irritability associated with autism, off-label behavioural disturbances in dementia (short-term).", "dosage": "Start 1–2 mg PO daily, titrate to usual range 2–6 mg/day (max 16 mg/day); lower start (0.5 mg) in elderly", "examPoints": ["Most likely of the atypicals to cause EPS and hyperprolactinemia at typical doses because of higher D2 affinity — dose-dependent", "Hyperprolactinemia can cause galactorrhea, gynecomastia, menstrual irregularities, sexual dysfunction — classic exam association", "Available as long-acting injectable (Risperdal Consta) for adherence in schizophrenia", "Boxed warning: increased mortality in elderly dementia patients (class effect)", "Lower sedation/metabolic burden than olanzapine/quetiapine but not negligible"], "counselling": ["Take consistently, with or without food, as directed", "Report unusual muscle stiffness, tremor, or restlessness — these may need a dose adjustment", "Tell your doctor about any breast changes, unexpected milk production, or menstrual changes", "Rise slowly to avoid dizziness from blood pressure drops", "If on the long-acting injection, keep your scheduled injection appointments"], "sideEffects": ["Extrapyramidal symptoms (dose-dependent)", "Hyperprolactinemia", "Weight gain", "Sedation", "Orthostatic hypotension", "Neuroleptic malignant syndrome (rare)"]}, {"topic": "cns", "generic": "Haloperidol", "pronunciation": "hal-oh-PER-ih-dol", "brand": ["Haldol"], "class": "Typical (first-generation) antipsychotic (high-potency)", "moa": "Potent antagonism of D2 dopamine receptors in mesolimbic pathway (antipsychotic effect) and nigrostriatal pathway (source of EPS); minimal anticholinergic/antihistaminic activity.", "indication": "Schizophrenia, acute agitation/psychosis, Tourette syndrome, delirium (off-label, short-term).", "dosage": "PO: 0.5–5 mg BID–TID, titrate to effect; IM (acute agitation) 2–5 mg q4–8h PRN; max varies by indication", "examPoints": ["High-potency typical = high EPS risk (dystonia, akathisia, parkinsonism) but low sedation/anticholinergic/hypotensive effects — contrast with low-potency agents like chlorpromazine", "Risk of tardive dyskinesia with long-term use — irreversible in some cases, monitor with AIMS scale", "Neuroleptic malignant syndrome (NMS): fever, rigidity, autonomic instability, altered mental status — medical emergency", "IM/IV formulation used for acute agitation; QT prolongation risk especially IV route — ECG monitoring recommended", "Acute dystonia treated with anticholinergic (benztropine) or antihistamine (diphenhydramine)"], "counselling": ["Take exactly as prescribed; do not adjust dose without talking to your prescriber", "Report muscle stiffness, tremor, restlessness, or abnormal movements promptly", "Report high fever, severe muscle rigidity, or confusion immediately — this can be a medical emergency", "Avoid alcohol while taking this medication", "Regular check-ins are needed to monitor for movement side effects over time"], "sideEffects": ["Extrapyramidal symptoms (dystonia, akathisia, parkinsonism)", "Tardive dyskinesia (long-term)", "Sedation (mild)", "QT prolongation", "Neuroleptic malignant syndrome (rare, serious)", "Hyperprolactinemia"]}, {"topic": "cns", "generic": "Lithium carbonate", "pronunciation": "LITH-ee-um KAR-boh-nayt", "brand": ["Carbolith", "Lithane"], "class": "Mood stabilizer", "moa": "Exact mechanism unclear; modulates neurotransmitter release and second-messenger signaling (inositol depletion, GSK-3 inhibition).", "indication": "Bipolar disorder — acute mania and long-term maintenance/relapse prevention.", "dosage": "Start 300 mg PO BID–TID, titrate to serum level 0.6–1.2 mmol/L (0.8–1.2 for acute mania); check levels 12h post-dose", "examPoints": ["Narrow therapeutic index — target trough level typically 0.6-1.2 mmol/L (levels drawn 12h post-dose)", "NSAIDs, ACE inhibitors/ARBs, and thiazides all raise lithium levels — key interaction to catch", "Toxicity signs: coarse tremor, ataxia, confusion, GI upset progressing to seizures/coma", "Monitor renal function and TSH at baseline and periodically (nephrogenic diabetes insipidus, hypothyroidism risk)"], "counselling": ["Take consistently with food to reduce GI upset", "Maintain steady fluid and salt intake — dehydration or low-sodium diets raise lithium levels", "Report fine tremor, vomiting, diarrhea, or confusion right away", "Blood levels need regular monitoring, especially after dose changes"], "sideEffects": ["Fine hand tremor", "Polyuria/polydipsia", "Weight gain", "GI upset", "Hypothyroidism (long-term)", "Toxicity: coarse tremor, confusion, seizures (rare but serious)"]}, {"topic": "cns", "generic": "Valproic acid / Divalproex sodium", "pronunciation": "val-PROH-ik AS-id / dy-VAL-proh-eks SOH-dee-um", "brand": ["Depakene", "Epival"], "class": "Mood stabilizer / anticonvulsant", "moa": "Increases GABA availability (inhibits GABA transaminase) and blocks voltage-gated sodium channels, stabilizing neuronal excitability; broad-spectrum antiepileptic activity.", "indication": "Bipolar disorder (acute mania), epilepsy (broad-spectrum, including absence seizures), migraine prophylaxis.", "dosage": "Start 10–15 mg/kg/day PO in divided doses, titrate to target serum level 350–700 µmol/L; max ~60 mg/kg/day", "examPoints": ["Boxed warning: teratogenic (neural tube defects) — highly effective contraception required in women of childbearing potential; avoid in pregnancy if possible", "Boxed warning: hepatotoxicity risk, especially in first 6 months and in children <2 years — monitor LFTs", "Boxed warning: pancreatitis risk (can occur at any time during treatment)", "Therapeutic drug monitoring: target trough level typically 350-700 micromol/L (50-100 mcg/mL)", "Thrombocytopenia and hyperammonemia are also monitored — check CBC and consider ammonia if altered mental status"], "counselling": ["Reliable contraception is essential while taking this medication due to birth defect risk — discuss family planning with your doctor", "Report yellowing of skin/eyes, severe abdominal pain, or unusual bruising/bleeding immediately", "Take with food to reduce stomach upset; do not chew or crush enteric-coated tablets", "Regular blood tests (liver function, blood counts, drug levels) are required", "Do not stop abruptly if being used for seizures — this can trigger seizures"], "sideEffects": ["Nausea/GI upset", "Weight gain", "Tremor", "Hair thinning", "Hepatotoxicity (boxed warning)", "Pancreatitis (boxed warning)", "Teratogenicity (boxed warning)", "Thrombocytopenia"]}, {"topic": "cns", "generic": "Lamotrigine", "pronunciation": "luh-MOH-trih-jeen", "brand": ["Lamictal"], "class": "Anticonvulsant / mood stabilizer", "moa": "Blocks voltage-gated sodium channels, stabilizing neuronal membranes and inhibiting release of excitatory neurotransmitters (glutamate).", "indication": "Bipolar disorder maintenance (especially depressive episode prevention), epilepsy (partial and generalized seizures).", "dosage": "Slow titration per protocol to minimize rash risk: start 25 mg/day (25 mg every other day if on valproate), increase q2wk to target 100–400 mg/day", "examPoints": ["Classic exam trap: requires slow dose titration over weeks to minimize risk of serious rash including Stevens-Johnson syndrome/TEN", "Rash risk is significantly increased when titrated too quickly or combined with valproate (which inhibits lamotrigine metabolism, requiring a lower/slower titration)", "Valproate roughly doubles lamotrigine levels; carbamazepine (enzyme inducer) lowers lamotrigine levels — dose adjustments needed", "More effective for bipolar depression/relapse prevention than for acute mania", "Hormonal contraceptives (estrogen) can lower lamotrigine levels; conversely, lamotrigine levels may fall during pregnancy requiring monitoring"], "counselling": ["Follow the slow dose-increase schedule exactly as prescribed — do not speed it up", "Stop the medication and seek immediate medical attention if you develop a rash, especially with fever, blistering, or mouth sores", "Tell your doctor about all other medications, especially valproate or hormonal birth control, as doses may need adjusting", "If you miss several days of doses, contact your doctor before restarting — you may need to re-titrate from a lower dose", "Do not stop abruptly if taken for seizures"], "sideEffects": ["Rash (can be serious — SJS/TEN)", "Headache", "Dizziness", "Diplopia/blurred vision", "Nausea", "Aseptic meningitis (rare)"]}, {"topic": "cns", "generic": "Donepezil", "pronunciation": "doh-NEP-eh-zil", "brand": ["Aricept"], "class": "Cholinesterase inhibitor", "moa": "Reversibly inhibits acetylcholinesterase, increasing synaptic acetylcholine levels in the CNS to partially compensate for cholinergic neuron loss in Alzheimer's disease.", "indication": "Mild to moderate (and moderate-severe) Alzheimer's disease dementia.", "dosage": "Start 5 mg PO daily at bedtime, may increase to 10 mg after 4–6 weeks; max 23 mg/day (severe AD)", "examPoints": ["Disease-modifying it is NOT — provides modest symptomatic benefit only, does not halt underlying neurodegeneration", "GI side effects (nausea, diarrhea, vomiting) are dose-related and most common on initiation/titration — start low, go slow", "Cholinergic excess can cause bradycardia — caution/avoid in sick sinus syndrome or conduction abnormalities without pacemaker", "Avoid concurrent use with anticholinergic drugs (opposing/counteracting mechanisms) — common prescribing cascade error to catch", "Once-daily dosing, typically taken at bedtime"], "counselling": ["Take once daily, usually at bedtime, with or without food", "Nausea or diarrhea are common when starting or increasing the dose and often improve with time", "Effects are modest — this may slow symptom progression but will not cure or reverse the disease", "Report a slow or irregular heartbeat, fainting, or dizziness", "Avoid other medications with strong anticholinergic effects (some OTC sleep aids, certain antihistamines) as they work against this drug"], "sideEffects": ["Nausea", "Diarrhea", "Vomiting", "Insomnia/vivid dreams", "Muscle cramps", "Bradycardia (caution)", "Weight loss"]}, {"topic": "cns", "generic": "Levodopa/Carbidopa", "pronunciation": "lee-voh-DOH-puh / kar-bih-DOH-puh", "brand": ["Sinemet"], "class": "Dopaminergic agent (Parkinson's disease)", "moa": "Levodopa is converted to dopamine in the CNS to replace deficient striatal dopamine; carbidopa is a peripheral decarboxylase inhibitor that prevents peripheral conversion, reducing peripheral side effects and increasing CNS delivery.", "indication": "Parkinson's disease — most effective symptomatic therapy for motor symptoms.", "dosage": "Start 100/25 mg PO TID, titrate based on response; usual range 300–800 mg levodopa/day in divided doses", "examPoints": ["Gold standard/most effective agent for Parkinson's motor symptoms, but long-term use associated with motor fluctuations ('wearing-off') and dyskinesias", "High-protein meals can reduce levodopa absorption/efficacy — timing around meals matters, especially with advancing disease", "Non-selective MAOIs are contraindicated (hypertensive crisis) — must washout before starting", "Abrupt discontinuation can precipitate a parkinsonism-hyperpyrexia crisis resembling NMS — never stop abruptly", "Carbidopa component prevents peripheral dopamine conversion, reducing nausea/vomiting and cardiovascular side effects versus levodopa alone"], "counselling": ["Take on a consistent schedule; high-protein meals may reduce how well it works, so timing around meals can help — ask your care team about the best approach for you", "Do not stop this medication suddenly, even temporarily, without medical guidance", "You may notice the medication becomes less effective closer to the next dose ('wearing off') — report this pattern to your doctor", "Some involuntary movements (dyskinesias) can develop over time with long-term use — report new or worsening movements", "Rise slowly from sitting or lying to reduce dizziness"], "sideEffects": ["Nausea", "Dyskinesias (long-term)", "Motor fluctuations/'wearing off'", "Orthostatic hypotension", "Hallucinations/confusion", "Impulse control disorders"]}, {"topic": "cns", "generic": "Pramipexole", "pronunciation": "pram-ih-PEKS-ohl", "brand": ["Mirapex"], "class": "Dopamine agonist (Parkinson's disease)", "moa": "Directly stimulates postsynaptic dopamine D2/D3 receptors, mimicking dopamine action without requiring conversion from a precursor.", "indication": "Parkinson's disease (monotherapy in early disease or adjunct to levodopa); restless legs syndrome.", "dosage": "Start 0.125 mg PO TID, titrate q5–7 days to usual range 0.5–1.5 mg TID; reduce for renal impairment", "examPoints": ["Associated with impulse control disorders — pathological gambling, hypersexuality, compulsive shopping/eating — important counselling point often tested", "Causes more sedation/somnolence than levodopa, including sudden 'sleep attacks' — caution with driving", "Often used in younger patients to delay starting levodopa (delays motor fluctuation onset) though less potent than levodopa", "Renal dose adjustment required (renally eliminated, unlike levodopa)", "Abrupt discontinuation can cause dopamine agonist withdrawal syndrome"], "counselling": ["Report any new compulsive behaviours — gambling, shopping, hypersexuality, binge eating — to your doctor right away, as this drug can cause these", "This medication can cause sudden sleepiness, even while driving — use caution until you know how it affects you", "Rise slowly from sitting or lying to reduce dizziness", "Do not stop abruptly without medical guidance", "Take with food if it upsets your stomach"], "sideEffects": ["Somnolence/sedation ('sleep attacks')", "Nausea", "Orthostatic hypotension", "Impulse control disorders", "Hallucinations", "Peripheral edema"]}, {"topic": "cns", "generic": "Lorazepam", "pronunciation": "lor-AZ-eh-pam", "brand": ["Ativan"], "class": "Benzodiazepine", "moa": "Enhances GABA-A receptor activity by increasing chloride channel opening frequency, potentiating inhibitory GABAergic neurotransmission, producing anxiolytic, sedative, and anticonvulsant effects.", "indication": "Anxiety disorders (short-term), acute agitation, status epilepticus, alcohol withdrawal, procedural sedation.", "dosage": "0.5–2 mg PO/SL/IV q6–8h PRN (anxiety); max 4 mg/dose IV for status epilepticus", "examPoints": ["Intermediate half-life and no active metabolites — preferred in hepatic impairment and elderly ('LOT' drugs: Lorazepam, Oxazepam, Temazepam undergo only glucuronidation)", "Risk of physical dependence/withdrawal with regular use beyond 2-4 weeks — taper required, never stop abruptly (seizure risk)", "Combined use with opioids carries a boxed warning for fatal respiratory depression", "Paradoxical disinhibition/agitation can occur, especially in elderly or children", "First-line benzodiazepine for status epilepticus and alcohol withdrawal (CIWA protocol) given rapid onset and reliable IV kinetics"], "counselling": ["Use only as directed — this is generally intended for short-term use due to dependence risk", "Do not stop suddenly after regular use — your dose needs to be tapered gradually", "Avoid alcohol and other sedating medications, especially opioids — the combination can be fatal", "May cause drowsiness and impaired coordination — avoid driving until you know how it affects you", "Elderly patients should use with extra caution due to fall and confusion risk"], "sideEffects": ["Sedation/drowsiness", "Dizziness", "Ataxia/impaired coordination", "Memory impairment", "Dependence/withdrawal with prolonged use", "Respiratory depression (esp. with opioids)"]}, {"topic": "cns", "generic": "Zopiclone", "pronunciation": "ZOH-pih-klohn", "brand": ["Imovane"], "class": "Z-drug (nonbenzodiazepine hypnotic)", "moa": "Binds selectively to the benzodiazepine site on GABA-A receptors (different binding subunit profile than benzodiazepines), enhancing GABAergic inhibition with relatively selective hypnotic effect.", "indication": "Short-term treatment of insomnia.", "dosage": "5–7.5 mg PO at bedtime (start 3.75 mg in elderly); short-term use only, max 7.5 mg/day", "examPoints": ["Recommended for short-term use only (typically 7-10 days, up to a few weeks) due to tolerance and dependence risk, similar concerns as benzodiazepines", "Classic side effect: persistent bitter/metallic taste the next day", "Beers Criteria: avoid in elderly due to fall risk, cognitive impairment, similar risk profile to benzodiazepines despite being 'non-benzo'", "Next-day residual sedation/psychomotor impairment possible — caution with driving in the morning after use", "Should not be combined with alcohol or other CNS depressants (respiratory depression risk)"], "counselling": ["Take immediately before bedtime when you can get a full night's sleep (7-8 hours)", "This is intended for short-term use only — talk to your doctor if you feel you need it for more than a couple of weeks", "A bitter or metallic taste afterward is common and expected", "Avoid alcohol while taking this medication", "You may feel drowsy the next morning — avoid driving until you feel fully alert"], "sideEffects": ["Bitter/metallic taste", "Daytime drowsiness", "Dizziness", "Dry mouth", "Dependence with prolonged use", "Complex sleep behaviours (rare, e.g., sleep-walking)"]}, {"topic": "cns", "generic": "Sumatriptan", "pronunciation": "soo-muh-TRIP-tan", "brand": ["Imitrex"], "class": "Triptan (5-HT1B/1D agonist)", "moa": "Selective agonist at serotonin 5-HT1B/1D receptors, causing cranial vasoconstriction and inhibiting release of vasoactive neuropeptides (CGRP), aborting the migraine cascade.", "indication": "Acute treatment of migraine (with or without aura) and cluster headache.", "dosage": "50–100 mg PO at onset of migraine, may repeat once after 2h (max 200 mg/day); SC 6 mg (max 12 mg/day); nasal 20 mg", "examPoints": ["Contraindicated in patients with cardiovascular disease, uncontrolled hypertension, and history of stroke/TIA due to vasoconstrictive effects — key screening point", "Contraindicated within 24 hours of another triptan or ergot-containing medication (additive vasoconstriction)", "Serotonin syndrome risk when combined with SSRIs/SNRIs/MAOIs — caution, though absolute risk is debated; still requires counselling", "Best efficacy when taken early in the migraine attack, at onset of pain (not during aura only)", "Overuse (>10 days/month) can cause medication-overuse headache — a classic exam trap"], "counselling": ["Take as soon as migraine symptoms/pain begin for best effect — don't wait until the headache is severe", "Do not use if you have heart disease, uncontrolled high blood pressure, or a history of stroke — confirm with your doctor first", "Do not combine with another triptan or ergotamine-type medication within 24 hours", "Limit use to no more than 9-10 days per month to avoid rebound/medication-overuse headache", "Report chest tightness, jaw/throat tightness after a dose — a known but usually benign effect, though should be discussed with your doctor"], "sideEffects": ["Chest/jaw/throat tightness (usually benign)", "Tingling/paresthesia", "Dizziness", "Fatigue", "Flushing", "Coronary vasospasm (rare, serious)", "Serotonin syndrome (rare, with serotonergic combos)"]}, {"topic": "cns", "generic": "Carbamazepine", "pronunciation": "kar-buh-MAZ-eh-peen", "brand": ["Tegretol"], "class": "Anticonvulsant / mood stabilizer", "moa": "Blocks voltage-gated sodium channels, stabilizing hyperexcitable neuronal membranes and reducing repetitive neuronal firing; also a potent inducer of hepatic CYP3A4 and its own metabolism (autoinduction).", "indication": "Bipolar disorder (mania), epilepsy (partial and generalized tonic-clonic seizures), trigeminal neuralgia.", "dosage": "Start 100–200 mg PO BID, titrate slowly to usual range 800–1200 mg/day (max 1600–2000 mg/day); target level 17–50 µmol/L", "examPoints": ["Boxed warning: serious dermatologic reactions (SJS/TEN) strongly associated with HLA-B*1502 allele — screening recommended in patients of Asian ancestry before starting", "Boxed warning: aplastic anemia and agranulocytosis — baseline and periodic CBC monitoring required", "Potent CYP3A4 inducer causing many drug interactions, including reducing efficacy of hormonal contraceptives and warfarin", "Autoinduction of its own metabolism means levels/doses often need upward adjustment a few weeks after starting", "Therapeutic drug monitoring target range typically 17-51 micromol/L (4-12 mcg/mL); hyponatremia (SIADH) is another key monitoring point"], "counselling": ["Report any rash immediately and stop the medication until assessed — this can signal a serious reaction, especially in the first weeks", "Report fever, sore throat, unusual bruising or bleeding — signs of a rare but serious blood problem requiring blood tests", "This medication can make hormonal birth control less effective — discuss alternative or backup contraception", "Regular blood tests (drug level, blood counts, sodium) are required, especially early in treatment", "Do not stop abruptly if taken for seizures — this can trigger seizures"], "sideEffects": ["Dizziness", "Drowsiness", "Diplopia/blurred vision", "Nausea", "Hyponatremia (SIADH)", "Aplastic anemia/agranulocytosis (rare, boxed warning)", "Stevens-Johnson syndrome/TEN (rare, boxed warning)"]}, {"topic": "infd", "generic": "Amoxicillin", "pronunciation": "uh-mok-sih-SIL-in", "brand": ["Amoxil"], "class": "Aminopenicillin (beta-lactam)", "moa": "Binds penicillin-binding proteins (PBPs) to inhibit bacterial cell wall synthesis, causing cell lysis; extended spectrum vs. natural penicillins to cover some gram-negatives.", "indication": "Otitis media, sinusitis, community-acquired pneumonia, strep pharyngitis, H. pylori eradication (triple/quad therapy).", "dosage": "250–500 mg PO q8h or 500–875 mg q12h; high-dose 1 g TID for resistant AOM/sinusitis; pediatric 25–90 mg/kg/day divided", "examPoints": ["Cross-reactivity with penicillin allergy ~1-2%; avoid in true IgE-mediated penicillin allergy", "High-dose (80-90 mg/kg/day in children) used for AOM to overcome resistant S. pneumoniae", "Ampicillin-class rash (non-allergic, maculopapular) common with concurrent mononucleosis/EBV — do not label as true allergy", "Renal dose adjustment needed in CrCl <30 mL/min"], "counselling": ["Complete the full course even if feeling better", "Take with or without food", "May cause diarrhea — report if severe/bloody (C. diff risk)", "Report rash, hives, or swelling immediately"], "sideEffects": ["Diarrhea", "Nausea", "Rash", "Candidiasis (oral/vaginal)", "Anaphylaxis (rare)", "C. difficile colitis (rare)"]}, {"topic": "infd", "generic": "Amoxicillin-Clavulanate", "pronunciation": "uh-mok-sih-SIL-in KLAV-yoo-lan-ayt", "brand": ["Clavulin"], "class": "Aminopenicillin + beta-lactamase inhibitor", "moa": "Amoxicillin inhibits cell wall synthesis; clavulanate irreversibly inhibits bacterial beta-lactamases, restoring amoxicillin activity against beta-lactamase-producing organisms (e.g., H. influenzae, S. aureus, some E. coli).", "indication": "Recurrent/resistant otitis media, sinusitis, animal/human bite wounds, diabetic foot infections.", "dosage": "500/125 mg PO q8h or 875/125 mg q12h; high-dose formulation for resistant infections", "examPoints": ["Clavulanate component increases diarrhea risk substantially vs. amoxicillin alone", "First-line for animal/human bite wounds (covers Pasteurella and anaerobes)", "Higher clavulanate ratio (e.g., 875/125) preferred to reduce GI upset vs. older 500/125 dosed more frequently", "Renal dose adjustment required at CrCl <30 mL/min"], "counselling": ["Take with food to reduce GI upset", "Complete full course", "Report severe diarrhea (possible C. diff)", "Report signs of liver toxicity (rare) — dark urine, jaundice"], "sideEffects": ["Diarrhea (more than amoxicillin alone)", "Nausea", "Rash", "Cholestatic hepatitis (rare, more common in elderly/prolonged use)", "C. difficile colitis"]}, {"topic": "infd", "generic": "Cephalexin", "pronunciation": "sef-uh-LEKS-in", "brand": ["Keflex"], "class": "First-generation cephalosporin", "moa": "Binds PBPs to inhibit bacterial cell wall synthesis; primarily active against gram-positive organisms (staph, strep) with modest gram-negative coverage.", "indication": "Skin and soft tissue infections (cellulitis), uncomplicated UTI, strep pharyngitis.", "dosage": "250–500 mg PO q6h (or 500 mg q12h for uncomplicated cystitis); max 4 g/day", "examPoints": ["Cross-reactivity with penicillin allergy is low (~1-2%) but avoid if history of severe/anaphylactic penicillin reaction", "Does NOT cover MRSA or Pseudomonas", "Renal dose adjustment needed in renal impairment", "Good first-line for uncomplicated cellulitis without MRSA risk factors"], "counselling": ["Take on an empty stomach for best absorption, but may take with food if GI upset occurs", "Complete the full course", "Space doses evenly through the day", "Report rash or difficulty breathing"], "sideEffects": ["Diarrhea", "Nausea/vomiting", "Rash", "Vaginal candidiasis", "C. difficile colitis (rare)"]}, {"topic": "infd", "generic": "Ceftriaxone", "pronunciation": "sef-try-AKS-ohn", "brand": ["Rocephin"], "class": "Third-generation cephalosporin", "moa": "Inhibits bacterial cell wall synthesis via PBP binding; broad gram-negative coverage with CNS penetration, stable against many beta-lactamases.", "indication": "Community-acquired pneumonia, meningitis, gonorrhea, pyelonephritis, sepsis (empiric).", "dosage": "1–2 g IV/IM once daily; up to 2 g q12h for meningitis; gonorrhea 500 mg–1 g IM single dose", "examPoints": ["Do NOT co-administer with IV calcium-containing solutions in neonates — risk of fatal calcium-ceftriaxone precipitate in lungs/kidneys", "No renal dose adjustment needed (primarily biliary excretion) — key differentiator from most other cephalosporins", "Single 500 mg-1g IM dose is first-line for uncomplicated gonorrhea", "Can cause biliary sludging/pseudolithiasis with prolonged use"], "counselling": ["This is given by injection (IM or IV) — administered in clinic/hospital", "Report abdominal pain (possible gallbladder sludging)", "Report diarrhea, especially if severe or bloody", "Complete full course as prescribed by provider"], "sideEffects": ["Diarrhea", "Injection site pain/induration", "Biliary sludging/pseudolithiasis", "Rash", "C. difficile colitis", "Hemolytic anemia (rare)"]}, {"topic": "infd", "generic": "Ciprofloxacin", "pronunciation": "SIP-roh-FLOKS-uh-sin", "brand": ["Cipro"], "class": "Fluoroquinolone", "moa": "Inhibits bacterial DNA gyrase and topoisomerase IV, preventing DNA replication and transcription; broad gram-negative coverage including Pseudomonas.", "indication": "Complicated UTI/pyelonephritis, some GI infections, Pseudomonas coverage.", "dosage": "250–750 mg PO q12h depending on indication; 400 mg IV q8–12h; avoid with dairy/antacids (chelation)", "examPoints": ["Health Canada boxed warning: tendon rupture/tendinitis risk, increased in elderly, corticosteroid use, transplant patients", "Chelates with divalent/trivalent cations (Ca, Mg, Fe, Al, Zn) — separate from antacids/dairy/multivitamins by 2-6 hours", "QT prolongation risk — caution with other QT-prolonging drugs", "Avoid as first-line for uncomplicated cystitis due to resistance/safety concerns (reserve for complicated cases)", "Risk of aortic aneurysm/dissection, CNS effects (confusion, seizures), and peripheral neuropathy"], "counselling": ["Do not take with dairy products, calcium-fortified juice, or antacids at the same time — separate by several hours", "Report tendon pain, swelling, or sudden difficulty moving a joint — stop drug and seek care", "Avoid excess sun exposure (photosensitivity)", "Report new confusion, tingling, or numbness", "Stay well hydrated"], "sideEffects": ["Nausea", "Diarrhea", "Headache", "Tendinitis/tendon rupture (rare but serious)", "QT prolongation", "Peripheral neuropathy", "CNS effects (dizziness, confusion, seizures)"]}, {"topic": "infd", "generic": "Azithromycin", "pronunciation": "uh-ZITH-roh-MY-sin", "brand": ["Zithromax"], "class": "Macrolide", "moa": "Binds the 50S ribosomal subunit to inhibit bacterial protein synthesis; bacteriostatic with atypical pathogen coverage (Chlamydia, Mycoplasma, Legionella).", "indication": "Community-acquired pneumonia (atypical coverage), chlamydia, pertussis, COPD exacerbation.", "dosage": "500 mg PO once on day 1, then 250 mg daily days 2–5 (Z-pack); or 500 mg daily x3 days; STI 1 g single dose", "examPoints": ["QT prolongation risk — caution with other QT-prolonging drugs and in patients with known long QT", "Long half-life allows short courses (e.g., 5-day or single-dose 1g for chlamydia)", "Fewer CYP3A4 interactions than erythromycin/clarithromycin, making it preferred macrolide in polypharmacy patients", "Not reliable for empiric CAP monotherapy in areas with high macrolide-resistant S. pneumoniae"], "counselling": ["May take with or without food (food may reduce GI upset)", "Complete the full course even if symptoms improve", "Report palpitations, fainting, or irregular heartbeat", "Space from antacids containing aluminum/magnesium"], "sideEffects": ["GI upset (nausea, diarrhea, abdominal pain)", "QT prolongation", "Hepatotoxicity (rare)", "Hearing loss (reversible, high-dose/prolonged use)", "Allergic reactions"]}, {"topic": "infd", "generic": "Clarithromycin", "pronunciation": "kluh-RITH-roh-MY-sin", "brand": ["Biaxin"], "class": "Macrolide", "moa": "Binds 50S ribosomal subunit inhibiting bacterial protein synthesis; also used as component of H. pylori eradication regimens.", "indication": "H. pylori eradication (triple therapy), respiratory tract infections, atypical mycobacterial infections.", "dosage": "250–500 mg PO q12h x7–14 days; extended-release 1000 mg once daily", "examPoints": ["Strong CYP3A4 inhibitor — significant interaction potential (statins, warfarin, colchicine, benzodiazepines)", "Contraindicated with colchicine in renal/hepatic impairment — risk of fatal colchicine toxicity", "QT prolongation risk", "Avoid combining with simvastatin/lovastatin (rhabdomyolysis risk) — hold statin or switch"], "counselling": ["May cause a metallic/bitter taste", "Take with food if GI upset occurs", "Report muscle pain/weakness if on a statin", "Report palpitations or irregular heartbeat"], "sideEffects": ["Metallic taste", "GI upset", "QT prolongation", "Hepatotoxicity", "Drug interactions (CYP3A4)", "C. difficile colitis"]}, {"topic": "infd", "generic": "Nitrofurantoin", "pronunciation": "ny-troh-fyoor-AN-toyn", "brand": ["Macrobid", "Macrodantin"], "class": "Nitrofuran antibiotic", "moa": "Damages bacterial DNA/ribosomal proteins after activation by bacterial nitroreductases; concentrates in urine.", "indication": "Uncomplicated cystitis (UTI) in patients with normal renal function.", "dosage": "100 mg PO BID x5 days (uncomplicated cystitis); avoid if CrCl <30 mL/min", "examPoints": ["Contraindicated/ineffective at CrCl <30 mL/min — fails to reach adequate urinary concentration and raises systemic toxicity risk", "Avoid near term in pregnancy (38-42 weeks) — risk of neonatal hemolytic anemia", "Not effective for pyelonephritis/upper tract or systemic infection — urine-only concentration", "Macrobid (SR) dosed BID; Macrodantin (immediate release) dosed QID"], "counselling": ["Take with food to reduce nausea", "Complete the full course even if symptoms improve", "May turn urine brown — this is harmless", "Report new cough or shortness of breath (rare pulmonary toxicity with long-term use)"], "sideEffects": ["Nausea", "Headache", "Brown urine discoloration", "Pulmonary toxicity (long-term use, rare)", "Peripheral neuropathy (rare)", "Hemolytic anemia in G6PD deficiency"]}, {"topic": "infd", "generic": "Metronidazole", "pronunciation": "meh-troh-NY-duh-zohl", "brand": ["Flagyl"], "class": "Nitroimidazole antibiotic/antiprotozoal", "moa": "Reduced intracellularly by anaerobic organisms to form reactive intermediates that damage bacterial/protozoal DNA.", "indication": "Anaerobic infections, C. difficile infection (alternative), bacterial vaginosis, trichomoniasis, H. pylori regimens.", "dosage": "500 mg PO/IV q8–12h depending on indication (BV: 500 mg BID x7 days; C. diff: 500 mg TID); avoid alcohol (disulfiram-like reaction)", "examPoints": ["Strict alcohol avoidance — disulfiram-like reaction (flushing, nausea, tachycardia); avoid during and for 48-72h after therapy", "Significant CYP2C9 interaction with warfarin — increases INR, requires monitoring", "Metallic taste is classic and near-universal", "Peripheral neuropathy risk with prolonged/high cumulative doses"], "counselling": ["Avoid alcohol during treatment and for 48-72 hours after the last dose", "Expect a metallic taste — this is expected and harmless", "Take with food to reduce nausea", "Report tingling/numbness in hands or feet if on a long course"], "sideEffects": ["Metallic taste", "Nausea", "Disulfiram-like reaction with alcohol", "Peripheral neuropathy (prolonged use)", "Dark/reddish-brown urine", "Headache"]}, {"topic": "infd", "generic": "Vancomycin", "pronunciation": "van-koh-MY-sin", "brand": ["Vancocin"], "class": "Glycopeptide antibiotic", "moa": "Inhibits bacterial cell wall synthesis by binding D-Ala-D-Ala terminus of peptidoglycan precursors, preventing transpeptidation/transglycosylation; active against gram-positives including MRSA.", "indication": "MRSA infections (IV), severe C. difficile infection (oral, non-absorbed formulation).", "dosage": "IV: 15–20 mg/kg q8–12h, dosed/monitored by trough or AUC; oral (C. diff): 125 mg q6h x10 days (poorly absorbed, gut-only effect)", "examPoints": ["IV vancomycin requires trough/AUC-guided monitoring — nephrotoxic, especially with other nephrotoxins (aminoglycosides, contrast)", "'Vancomycin flushing syndrome' (formerly red man syndrome) from rapid infusion — histamine-mediated, not a true allergy; slow infusion rate to manage", "Oral vancomycin is NOT absorbed systemically — only useful for C. difficile colitis, not systemic infections", "AUC/MIC-based dosing now preferred over trough-only monitoring per updated guidelines"], "counselling": ["IV infusion must be given slowly to reduce flushing/reaction risk", "Report ringing in ears or hearing changes (ototoxicity)", "Blood tests will monitor kidney function and drug levels regularly", "Oral form (for C. diff) stays in the gut and won't treat infections elsewhere in the body"], "sideEffects": ["Nephrotoxicity", "Vancomycin flushing syndrome ('red man syndrome')", "Ototoxicity (rare)", "Thrombophlebitis at IV site", "DRESS syndrome (rare, severe)"]}, {"topic": "infd", "generic": "Trimethoprim-Sulfamethoxazole", "pronunciation": "try-METH-oh-prim SUL-fuh-meth-OKS-uh-zohl", "brand": ["Septra", "Bactrim"], "class": "Folate synthesis inhibitor combination (sulfonamide + diaminopyrimidine)", "moa": "Sequentially blocks two steps of bacterial folate synthesis (dihydropteroate synthase and dihydrofolate reductase), producing synergistic bactericidal effect.", "indication": "Uncomplicated UTI, PJP prophylaxis/treatment, some skin/soft tissue infections (MRSA coverage).", "dosage": "1 DS tablet (160/800 mg) PO q12h for most infections; UTI x3 days, other infections x7–14 days", "examPoints": ["Contraindicated in sulfa allergy and in pregnancy near term (kernicterus risk) / avoid in first trimester (neural tube defect risk with trimethoprim, a folate antagonist)", "Increases INR with warfarin (CYP2C9 inhibition) — significant interaction", "Can cause hyperkalemia, especially with ACEi/ARB or in renal impairment — trimethoprim acts like a potassium-sparing diuretic on the distal nephron", "Renal dose adjustment required; avoid in severe renal impairment"], "counselling": ["Take with a full glass of water", "Complete the full course", "Avoid excess sun exposure (photosensitivity)", "Report rash, especially with fever or mucosal involvement (Stevens-Johnson risk)"], "sideEffects": ["Nausea", "Rash", "Hyperkalemia", "Photosensitivity", "Stevens-Johnson syndrome (rare, serious)", "Bone marrow suppression (rare)"]}, {"topic": "infd", "generic": "Doxycycline", "pronunciation": "doks-ee-SY-kleen", "brand": ["Vibramycin", "Doxycin"], "class": "Tetracycline antibiotic", "moa": "Binds 30S ribosomal subunit, blocking aminoacyl-tRNA attachment and inhibiting bacterial protein synthesis.", "indication": "Atypical pneumonia, Lyme disease, chlamydia, acne, malaria prophylaxis, tick-borne illnesses.", "dosage": "100 mg PO q12h (or 100–200 mg daily); take with food/fluid and remain upright to avoid esophageal irritation; avoid in pregnancy/children <8yr", "examPoints": ["Contraindicated in pregnancy and children <8 years — permanent tooth discoloration and inhibited bone growth", "Chelates with divalent/trivalent cations (dairy, antacids, iron) — separate administration by 2-3 hours", "First-line for Lyme disease and Rocky Mountain spotted fever", "Photosensitivity is prominent — sun protection counselling essential"], "counselling": ["Take with a full glass of water and remain upright for 30 minutes (esophageal irritation risk)", "Avoid dairy, antacids, or iron supplements within a few hours of dosing", "Use sunscreen and protective clothing — significant sun sensitivity", "Do not use if pregnant or breastfeeding"], "sideEffects": ["GI upset", "Esophageal irritation/ulceration", "Photosensitivity", "Tooth discoloration (children/in utero)", "Intracranial hypertension (rare)"]}, {"topic": "infd", "generic": "Fluconazole", "pronunciation": "floo-KOH-nuh-zohl", "brand": ["Diflucan"], "class": "Triazole antifungal", "moa": "Inhibits fungal cytochrome P450 enzyme (lanosterol 14-alpha-demethylase), blocking ergosterol synthesis and disrupting fungal cell membrane integrity.", "indication": "Vaginal candidiasis (single dose), oropharyngeal/esophageal candidiasis, cryptococcal meningitis (with amphotericin), candidemia.", "dosage": "150 mg PO single dose for vaginal candidiasis; 100–400 mg daily for other candidal/systemic infections depending on severity", "examPoints": ["Significant CYP3A4/CYP2C9 inhibitor — increases levels of warfarin, statins, phenytoin, sulfonylureas", "QT prolongation risk at higher doses", "Single 150 mg oral dose is standard for uncomplicated vaginal candidiasis", "Renal dose adjustment needed for CrCl <50 mL/min (except single-dose use)"], "counselling": ["Single-dose treatment for vaginal yeast infection may take a few days for symptoms to fully resolve", "Report increased bleeding/bruising if on warfarin", "Report muscle pain if on a statin", "Take with or without food"], "sideEffects": ["Headache", "Nausea", "Abdominal pain", "QT prolongation (dose-related)", "Hepatotoxicity (rare)", "Rash"]}, {"topic": "infd", "generic": "Oseltamivir", "pronunciation": "oh-sel-TAM-ih-veer", "brand": ["Tamiflu"], "class": "Neuraminidase inhibitor (antiviral)", "moa": "Inhibits influenza viral neuraminidase, preventing release of new virions from infected cells and limiting viral spread within the respiratory tract.", "indication": "Treatment and post-exposure prophylaxis of influenza A and B.", "dosage": "75 mg PO BID x5 days, started within 48h of symptom onset; renal dose adjustment required", "examPoints": ["Most effective when started within 48 hours of symptom onset", "Renal dose adjustment required for CrCl <60 mL/min", "Not a substitute for annual influenza vaccination", "Prophylactic dosing (once daily) differs from treatment dosing (twice daily)"], "counselling": ["Start as soon as possible after symptoms begin, ideally within 48 hours", "Take with food to reduce nausea", "Complete the full 5-day course for treatment", "Continue standard flu precautions (hand hygiene, mask) while contagious"], "sideEffects": ["Nausea", "Vomiting", "Headache", "Neuropsychiatric events (rare, more reported in children/adolescents)", "Rash (rare)"]}, {"topic": "infd", "generic": "Valacyclovir", "pronunciation": "val-ay-SY-kloh-veer", "brand": ["Valtrex"], "class": "Nucleoside analog antiviral (prodrug of acyclovir)", "moa": "Converted to acyclovir, which is phosphorylated by viral thymidine kinase and incorporated into viral DNA, terminating chain elongation and inhibiting viral DNA polymerase.", "indication": "Herpes simplex (genital/oral), herpes zoster (shingles), suppressive therapy for recurrent HSV.", "dosage": "Genital herpes: 1 g PO BID x7–10 days (initial) or 500 mg BID x3 days (recurrent); zoster 1 g TID x7 days", "examPoints": ["Improved oral bioavailability vs. acyclovir allows less frequent dosing", "Renal dose adjustment required — reduce dose/frequency in renal impairment", "Best efficacy for zoster when started within 72 hours of rash onset", "Adequate hydration needed to reduce crystalline nephropathy risk, especially at high doses"], "counselling": ["Start treatment as early as possible after symptom onset (tingling/prodrome for HSV, rash onset for zoster)", "Drink plenty of water while taking this medication", "Can reduce but does not eliminate risk of transmitting herpes to partners", "Complete the full course as prescribed"], "sideEffects": ["Headache", "Nausea", "Dizziness", "Nephrotoxicity (especially with dehydration/high doses)", "Neurotoxicity/confusion (mainly in renal impairment/elderly)"]}, {"topic": "renal", "generic": "Furosemide", "pronunciation": "fyoor-OH-seh-myd", "brand": ["Lasix"], "class": "Loop diuretic", "moa": "Inhibits the Na-K-2Cl cotransporter (NKCC2) in the thick ascending limb of the loop of Henle, blocking sodium/chloride reabsorption and producing potent diuresis.", "indication": "Volume overload in heart failure, CKD, cirrhosis; hypertension (less common first-line); hyperkalemia adjunct.", "dosage": "20–80 mg PO/IV daily–BID, titrate to effect; higher doses often needed in CKD", "examPoints": ["Effective even at low GFR (unlike thiazides) — preferred diuretic in advanced CKD/renal impairment", "Causes hypokalemia, hypomagnesemia, hyponatremia, and metabolic alkalosis — monitor electrolytes", "Ototoxicity risk with rapid IV administration or high doses, especially combined with aminoglycosides", "Sulfonamide structure — caution (not absolute contraindication) in sulfa allergy"], "counselling": ["Take in the morning (or early afternoon for a second dose) to avoid nighttime urination", "Rise slowly from sitting/lying to avoid dizziness from low blood pressure", "Report muscle cramps, weakness, or irregular heartbeat (signs of low potassium)", "Weigh yourself daily and report rapid weight gain or swelling"], "sideEffects": ["Hypokalemia", "Dehydration/hypotension", "Hyponatremia", "Ototoxicity (high-dose/rapid IV)", "Hyperuricemia/gout flares", "Hypomagnesemia"]}, {"topic": "renal", "generic": "Hydrochlorothiazide", "pronunciation": "hy-droh-klor-oh-THY-uh-zyd", "brand": ["HydroDiuril"], "class": "Thiazide diuretic", "moa": "Inhibits the Na-Cl cotransporter (NCC) in the distal convoluted tubule, reducing sodium reabsorption; also promotes calcium retention.", "indication": "Hypertension (first-line), mild edema, nephrolithiasis prevention (hypercalciuria).", "dosage": "12.5–25 mg PO daily; less effective when eGFR <30 mL/min", "examPoints": ["Loses efficacy at eGFR <30 mL/min/1.73m2 — switch to loop diuretic in advanced CKD", "Causes hypokalemia, hyponatremia, hypercalcemia (opposite of loops), hyperuricemia, hyperglycemia, hyperlipidemia", "Useful adjunct to reduce urinary calcium excretion in recurrent calcium stone formers", "Additive hyponatremia risk with SSRIs and in elderly patients"], "counselling": ["Take in the morning to avoid nighttime urination", "Report muscle cramps or weakness (possible low potassium)", "Use sun protection (photosensitivity possible)", "Monitor blood sugar if diabetic — may raise glucose slightly"], "sideEffects": ["Hypokalemia", "Hyponatremia", "Hyperuricemia", "Hyperglycemia", "Hypercalcemia", "Photosensitivity"]}, {"topic": "renal", "generic": "Spironolactone", "pronunciation": "spy-roh-noh-LAK-tohn", "brand": ["Aldactone"], "class": "Potassium-sparing diuretic (aldosterone antagonist)", "moa": "Competitively blocks mineralocorticoid (aldosterone) receptors in the distal nephron, reducing sodium reabsorption and potassium/hydrogen excretion.", "indication": "Heart failure with reduced ejection fraction (mortality benefit), resistant hypertension, ascites/cirrhosis, primary hyperaldosteronism.", "dosage": "12.5–25 mg PO daily, titrate to max 50 mg/day (HF) or higher for ascites; monitor K+ closely in CKD", "examPoints": ["Major hyperkalemia risk — avoid or use with caution combined with ACEi/ARB, potassium supplements, or in renal impairment; monitor potassium and renal function", "Antiandrogenic effects cause gynecomastia and menstrual irregularities — eplerenone is a selective alternative without this effect", "Contraindicated in significant renal impairment (typically avoid if eGFR <30) and in hyperkalemia", "Mortality benefit in HFrEF demonstrated in RALES trial — part of guideline-directed medical therapy (GDMT)"], "counselling": ["Avoid salt substitutes containing potassium chloride", "Report muscle weakness, irregular heartbeat, or tingling (signs of high potassium)", "Men may notice breast tenderness/enlargement — report if bothersome", "Regular blood tests needed to monitor potassium and kidney function"], "sideEffects": ["Hyperkalemia", "Gynecomastia (men)", "Menstrual irregularities (women)", "GI upset", "Dizziness/hypotension"]}, {"topic": "renal", "generic": "Sevelamer", "pronunciation": "seh-VEL-uh-mer", "brand": ["Renagel", "Renvela"], "class": "Non-calcium phosphate binder", "moa": "Binds dietary phosphate in the GI tract via ion exchange, forming a non-absorbable complex excreted in feces, reducing serum phosphate absorption.", "indication": "Hyperphosphatemia in CKD, particularly dialysis patients (avoids calcium/aluminum load).", "dosage": "800–1600 mg PO TID with meals, titrated to serum phosphate target", "examPoints": ["Must be taken WITH meals — ineffective if taken away from food since it binds phosphate from the diet", "Preferred over calcium-based binders in patients at risk of vascular calcification or with hypercalcemia", "Also lowers LDL cholesterol as a secondary effect (binds bile acids)", "Can bind and reduce absorption of some oral medications — space administration"], "counselling": ["Take with every meal or snack, not on an empty stomach", "Swallow tablets whole, do not crush or chew (or follow specific product instructions for powder)", "Take other medications 1 hour before or 3 hours after if instructed by your pharmacist", "Report severe constipation or abdominal pain"], "sideEffects": ["GI upset (nausea, bloating)", "Constipation", "Diarrhea", "Abdominal pain"]}, {"topic": "renal", "generic": "Calcium Carbonate", "pronunciation": "KAL-see-um KAR-boh-nayt", "brand": ["Tums", "Calsan"], "class": "Calcium-based phosphate binder", "moa": "Calcium ions bind dietary phosphate in the gut forming insoluble calcium phosphate, reducing phosphate absorption; also provides supplemental calcium.", "indication": "Hyperphosphatemia in CKD (with caution), calcium supplementation.", "dosage": "500–1500 mg elemental calcium PO with meals as phosphate binder, titrated to phosphate level", "examPoints": ["Total elemental calcium intake (diet + binder) should typically stay under ~1500 mg/day in CKD patients to avoid vascular calcification/hypercalcemia", "Must be taken WITH meals to bind dietary phosphate effectively", "Avoid in patients with hypercalcemia or adynamic bone disease", "Less preferred than non-calcium binders (e.g., sevelamer) when vascular calcification risk is high"], "counselling": ["Take with meals for phosphate binding (different from taking on empty stomach for calcium supplementation alone)", "Do not exceed the recommended dose — excess calcium can be harmful in kidney disease", "Report symptoms of high calcium: constipation, confusion, muscle weakness, excessive thirst", "Chew tablets well or as directed"], "sideEffects": ["Constipation", "Hypercalcemia", "Vascular/soft tissue calcification (long-term excess)", "Bloating/gas"]}, {"topic": "renal", "generic": "Sodium Bicarbonate", "pronunciation": "SOH-dee-um by-KAR-boh-nayt", "brand": ["Neut (injectable)", "generic oral tablets"], "class": "Alkalinizing agent", "moa": "Provides bicarbonate ion to buffer excess hydrogen ions, correcting metabolic acidosis and raising serum pH/bicarbonate levels.", "indication": "Metabolic acidosis of CKD (slows CKD progression per KDIGO), urine alkalinization, treatment of hyperkalemia (adjunct, acidosis-related).", "dosage": "Individualized; typically 650 mg–1300 mg PO BID–TID to correct metabolic acidosis, target serum bicarb ≥22 mmol/L", "examPoints": ["KDIGO guidelines recommend oral bicarbonate supplementation in CKD when serum bicarbonate is persistently <22 mmol/L to slow progression", "High sodium load can worsen volume overload/hypertension/heart failure — monitor fluid status", "Used in hyperkalemia management as an adjunct if acidosis is present (shifts K+ intracellularly), not a primary treatment", "Can raise urine pH — relevant for uric acid/cystine stone management or certain drug toxicities (e.g., salicylate)"], "counselling": ["Take exactly as prescribed — dose is individualized based on blood bicarbonate levels", "Report swelling, weight gain, or shortness of breath (may indicate fluid retention)", "Take with food if stomach upset occurs", "Regular blood tests will monitor your bicarbonate and electrolyte levels"], "sideEffects": ["Fluid retention/edema", "Hypertension exacerbation", "Metabolic alkalosis (if overcorrected)", "Belching/gas", "Milk-alkali syndrome (rare, high doses with calcium)"]}, {"topic": "renal", "generic": "Patiromer", "pronunciation": "puh-TIH-roh-mer", "brand": ["Veltassa"], "class": "Potassium binder (non-absorbed polymer)", "moa": "Exchanges calcium for potassium in the GI lumen, binding potassium and increasing its fecal excretion, lowering serum potassium.", "indication": "Chronic hyperkalemia management, especially to enable continuation of RAAS inhibitor therapy (ACEi/ARB/spironolactone) in CKD/HF.", "dosage": "Start 8.4 g PO once daily, titrate q1wk in 8.4 g increments to max 25.2 g/day, based on serum K+", "examPoints": ["Onset of action is ~7 hours — NOT for acute/emergent hyperkalemia (use insulin/glucose, calcium gluconate, etc. for acute management)", "Must be separated from other oral medications by at least 3 hours (binds many drugs, reducing their absorption)", "Allows patients to stay on cardio/renal-protective RAAS inhibitors despite hyperkalemia risk", "Can cause hypomagnesemia — monitor magnesium levels"], "counselling": ["Mix the powder with water and take once daily with food", "Take other oral medications at least 3 hours before or after this drug", "This is for chronic potassium control, not for emergency treatment of high potassium", "Report muscle cramps or weakness (possible low magnesium)"], "sideEffects": ["Constipation", "Hypomagnesemia", "Diarrhea", "Abdominal discomfort", "Hypokalemia (if overcorrected)"]}, {"topic": "renal", "generic": "Sodium Zirconium Cyclosilicate", "pronunciation": "SOH-dee-um zer-KOH-nee-um sy-kloh-SIL-ih-kayt", "brand": ["Lokelma"], "class": "Potassium binder (non-absorbed selective cation exchanger)", "moa": "Selectively traps potassium ions throughout the GI tract in exchange for sodium and hydrogen, increasing fecal potassium excretion.", "indication": "Chronic hyperkalemia management; faster onset than patiromer, sometimes used in semi-acute settings under supervision.", "dosage": "Acute: 10 g PO TID x48h; maintenance 5–10 g PO once daily, titrated to serum K+", "examPoints": ["Faster onset (~1 hour) compared to patiromer (~7 hours), though still not for true life-threatening emergent hyperkalemia without other measures", "Contains sodium — caution in heart failure/fluid overload due to sodium load", "Separate from other oral medications by at least 2 hours", "Maintenance dosing individualized to keep serum potassium in target range"], "counselling": ["Mix powder with water and take as directed, can be taken with or without food", "Take other oral medications at least 2 hours before or after this drug", "Report swelling or weight gain (sodium content may cause fluid retention)", "This helps control potassium long-term; continue other prescribed heart/kidney medications unless told otherwise"], "sideEffects": ["Edema (sodium-related)", "Hypokalemia (if overcorrected)", "GI upset", "Hypertension (fluid retention)"]}, {"topic": "renal", "generic": "Epoetin alfa", "pronunciation": "eh-POH-eh-tin AL-fuh", "brand": ["Eprex"], "class": "Erythropoiesis-stimulating agent (ESA)", "moa": "Recombinant human erythropoietin that stimulates erythroid progenitor cells in bone marrow to increase red blood cell production.", "indication": "Anemia of chronic kidney disease (dialysis and non-dialysis).", "dosage": "Start 50–100 units/kg SC/IV 3x/week, titrated to target Hgb 100–115 g/L", "examPoints": ["Boxed warning: increased risk of death, MI, stroke, and venous thromboembolism when hemoglobin targets exceed ~110-115 g/L — use lowest dose to avoid transfusion", "Ensure adequate iron stores (ferritin, TSAT) before/during therapy — iron deficiency blunts ESA response", "Uncontrolled hypertension is a contraindication until BP is controlled", "Target Hgb typically 100-115 g/L per guidelines; avoid normalizing to >130 g/L"], "counselling": ["This is given by injection (subcutaneous or IV), typically in clinic or self-administered as trained", "Regular blood tests will monitor your hemoglobin and iron levels", "Report severe headache, chest pain, leg swelling, or shortness of breath", "Blood pressure will be monitored regularly during treatment"], "sideEffects": ["Hypertension", "Injection site reactions", "Thromboembolic events (DVT/PE)", "Headache", "Increased cardiovascular risk (MI/stroke) if overcorrected", "Pure red cell aplasia (rare, antibody-mediated)"]}, {"topic": "renal", "generic": "Darbepoetin alfa", "pronunciation": "dar-beh-poh-EE-tin AL-fuh", "brand": ["Aranesp"], "class": "Erythropoiesis-stimulating agent (ESA), long-acting", "moa": "Hyperglycosylated erythropoietin analog with longer half-life than epoetin alfa, stimulating erythroid progenitor cell proliferation and differentiation.", "indication": "Anemia of chronic kidney disease — allows less frequent dosing (weekly to monthly) vs. epoetin alfa.", "dosage": "Start 0.45 mcg/kg SC/IV once weekly (or 0.75 mcg/kg q2wk), titrated to target Hgb 100–115 g/L", "examPoints": ["Same boxed warning as epoetin alfa: increased cardiovascular/thromboembolic risk at higher hemoglobin targets", "Longer half-life allows every 2-4 week dosing, improving convenience/adherence over epoetin's 2-3x weekly dosing", "Iron studies must be optimized before and during therapy for adequate response", "Target Hgb 100-115 g/L; avoid rapid rate of rise (>10 g/L over 2 weeks) which increases cardiovascular risk"], "counselling": ["Given by injection, less frequently than some other ESAs (ask your care team about your schedule)", "Regular blood work will check hemoglobin and iron status", "Report chest pain, leg swelling/pain, severe headache, or shortness of breath", "Take iron supplements as prescribed to support response to this medication"], "sideEffects": ["Hypertension", "Thromboembolic events", "Injection site reactions", "Headache", "Increased cardiovascular risk if overcorrected"]}, {"topic": "renal", "generic": "Digoxin", "pronunciation": "dih-JOKS-in", "brand": ["Toloxin"], "class": "Cardiac glycoside (renally-adjusted drug example)", "moa": "Inhibits Na-K-ATPase pump, increasing intracellular sodium and calcium via the Na-Ca exchanger, enhancing myocardial contractility; also increases vagal tone slowing AV conduction.", "indication": "Heart failure with reduced ejection fraction (symptom control), rate control in atrial fibrillation.", "dosage": "0.0625–0.125 mg PO daily in renal impairment (reduced from standard dosing); monitor trough levels closely", "examPoints": ["Renally cleared — requires significant dose reduction in CKD; toxicity risk increases markedly as renal function declines", "Narrow therapeutic index (target trough 0.5-0.9 ng/mL for HF) — toxicity risk with hypokalemia, hypomagnesemia, hypercalcemia", "Hypokalemia potentiates digoxin toxicity (increased binding to Na-K-ATPase) — critical interaction with diuretics", "Classic toxicity signs: nausea, visual disturbances (yellow-green halos), arrhythmias (any new arrhythmia in patient on digoxin = suspect toxicity)"], "counselling": ["Take at the same time each day", "Check your pulse as instructed and report if very slow or irregular", "Report nausea, vomiting, vision changes (halos/yellow-green vision), or confusion", "Keep all appointments for blood level and kidney function monitoring"], "sideEffects": ["Nausea/vomiting", "Visual disturbances (yellow-green halos)", "Arrhythmias", "Confusion (especially elderly)", "Digoxin toxicity (narrow therapeutic index)"]}, {"topic": "renal", "generic": "Enoxaparin", "pronunciation": "ee-noks-AP-uh-rin", "brand": ["Lovenox"], "class": "Low molecular weight heparin (renally-adjusted drug example)", "moa": "Enhances antithrombin activity, preferentially inhibiting Factor Xa (and to a lesser extent thrombin/IIa), preventing clot formation/propagation.", "indication": "VTE prophylaxis/treatment, ACS management.", "dosage": "1 mg/kg SC q12h (treatment) or 40 mg SC daily (prophylaxis); reduce to 1 mg/kg SC once daily if CrCl <30 mL/min", "examPoints": ["Requires dose reduction in CrCl <30 mL/min — accumulates and raises bleeding risk in renal impairment; anti-Xa monitoring may be used", "Not readily reversible (partial reversal with protamine) — caution in high bleeding risk with renal impairment", "Risk of heparin-induced thrombocytopenia (HIT), lower than unfractionated heparin but still present", "Avoid or use extreme caution with epidural/spinal anesthesia (spinal hematoma risk) — timing rules around procedures"], "counselling": ["Given by subcutaneous injection, rotate injection sites (abdomen typically)", "Report unusual bruising, bleeding gums, blood in urine/stool, or black tarry stools", "Do not massage the injection site after administration", "Keep all lab appointments if platelet or kidney monitoring is ordered"], "sideEffects": ["Bleeding/bruising", "Injection site hematoma", "Thrombocytopenia (including HIT, rare)", "Elevated liver enzymes (transient)"]}, {"topic": "renal", "generic": "Gabapentin", "pronunciation": "GA-buh-PEN-tin", "brand": ["Neurontin"], "class": "Anticonvulsant/neuropathic pain agent (renally-adjusted drug example)", "moa": "Binds the alpha-2-delta subunit of voltage-gated calcium channels, reducing neurotransmitter release; exact mechanism in pain/seizure control not fully defined.", "indication": "Neuropathic pain, uremic pruritus in dialysis patients, restless legs syndrome, adjunct seizure therapy.", "dosage": "Renal-adjusted: reduce dose/frequency substantially (e.g., 100–300 mg once daily to TID) based on CrCl; standard dosing up to 3600 mg/day if normal renal function", "examPoints": ["Renally cleared unchanged — requires substantial dose reduction as CrCl declines; accumulation causes sedation/toxicity in CKD/dialysis", "Overdose/accumulation in renal failure can cause myoclonus, encephalopathy, and altered mental status — often under-recognized in dialysis patients", "Used off-label for uremic pruritus, typically dosed post-dialysis in ESRD patients", "Additive CNS depression with opioids/benzodiazepines — increased respiratory depression risk"], "counselling": ["Take exactly as prescribed — your kidney function determines your dose", "Report excessive drowsiness, confusion, or difficulty walking", "Do not stop abruptly — taper as directed to avoid withdrawal/seizure risk", "Avoid alcohol and use caution with other sedating medications"], "sideEffects": ["Drowsiness/sedation", "Dizziness", "Peripheral edema", "Ataxia", "Myoclonus/encephalopathy (accumulation in renal failure)"]}, {"topic": "renal", "generic": "Calcitriol", "pronunciation": "kal-SIH-tree-ol", "brand": ["Rocaltrol"], "class": "Active vitamin D analog", "moa": "Active (1,25-dihydroxy) form of vitamin D that does not require renal 1-alpha-hydroxylation; increases intestinal calcium/phosphate absorption and suppresses parathyroid hormone secretion.", "indication": "Secondary hyperparathyroidism and hypocalcemia in CKD/dialysis (failing kidneys cannot activate native vitamin D).", "dosage": "0.25–0.5 mcg PO once daily (or 3x/week for dialysis patients), titrated to PTH/calcium levels", "examPoints": ["Used because CKD kidneys lose 1-alpha-hydroxylase activity, so native vitamin D (cholecalciferol) cannot be adequately activated", "Major risk is hypercalcemia and hyperphosphatemia — monitor calcium, phosphate, and PTH regularly", "Overtreatment risk of adynamic bone disease if PTH suppressed too low", "Often used with phosphate binders to control phosphate given increased GI phosphate absorption"], "counselling": ["Take as directed, often taken with or adjusted around dialysis sessions", "Report symptoms of high calcium: constipation, nausea, confusion, excessive thirst/urination", "Attend all scheduled lab monitoring appointments", "Do not take extra over-the-counter vitamin D without discussing with your care team"], "sideEffects": ["Hypercalcemia", "Hyperphosphatemia", "Nausea/constipation", "Adynamic bone disease (over-suppression of PTH, long-term)"]}, {"topic": "renal", "generic": "Cinacalcet", "pronunciation": "SIN-uh-KAL-set", "brand": ["Sensipar"], "class": "Calcimimetic", "moa": "Increases the sensitivity of the calcium-sensing receptor (CaSR) on parathyroid chief cells to extracellular calcium, reducing PTH secretion.", "indication": "Secondary hyperparathyroidism in dialysis patients; hypercalcemia in parathyroid carcinoma.", "dosage": "Start 30 mg PO once daily, titrate q2–4wk to max 180 mg/day, based on PTH and calcium", "examPoints": ["Unlike vitamin D analogs, cinacalcet LOWERS serum calcium (useful when hyperparathyroidism coexists with hypercalcemia/hyperphosphatemia)", "Main risk is hypocalcemia — monitor calcium closely, especially at treatment initiation and dose changes", "Take with food to improve absorption and reduce nausea", "Not used in non-dialysis CKD due to hypocalcemia risk without offsetting benefit demonstrated"], "counselling": ["Take with food or shortly after a meal", "Report symptoms of low calcium: muscle cramps/spasms, numbness/tingling around mouth or fingers, seizures (rare)", "Do not stop or change dose without checking with your care team — requires lab monitoring", "Attend all scheduled blood tests for calcium and PTH"], "sideEffects": ["Hypocalcemia", "Nausea/vomiting", "Diarrhea", "Myalgia", "QT prolongation (secondary to hypocalcemia)"]}, {"topic": "gi", "generic": "Omeprazole", "pronunciation": "oh-MEP-ruh-zohl", "brand": ["Losec", "Olex"], "class": "Proton pump inhibitor (PPI)", "moa": "Irreversibly inhibits the H+/K+-ATPase (proton pump) on gastric parietal cells, blocking the final step of acid secretion.", "indication": "GERD, peptic ulcer disease, H. pylori eradication (combo), NSAID-induced ulcer prophylaxis, Zollinger-Ellison syndrome.", "dosage": "20–40 mg PO once daily before breakfast; up to 40 mg BID for severe GERD/H. pylori regimens", "examPoints": ["Take 30-60 min before first meal for maximal efficacy (needs active pumps to bind)", "Long-term use linked to B12/Mg2+ deficiency, increased fracture risk, C. difficile risk, and possible rebound acid hypersecretion on discontinuation", "Reduces absorption of drugs needing acid (e.g., ketoconazole, atazanavir); increases INR risk with warfarin (CYP2C19)", "Clopidogrel interaction: avoid omeprazole/esomeprazole (CYP2C19 inhibition reduces clopidogrel activation) — pantoprazole preferred if PPI needed"], "counselling": ["Take on an empty stomach, 30-60 minutes before breakfast", "Do not crush/chew delayed-release capsules; may open and sprinkle on soft food if needed", "Long-term use may need periodic review — lowest effective dose for shortest duration", "Report signs of low magnesium (muscle cramps, irregular heartbeat, seizures)"], "sideEffects": ["Headache", "Diarrhea/constipation", "Abdominal pain", "Hypomagnesemia (long-term)", "Increased fracture risk (long-term)", "C. difficile-associated diarrhea"]}, {"topic": "gi", "generic": "Ranitidine (historical) / Famotidine", "pronunciation": "ruh-NIT-ih-deen / fuh-MOH-tih-deen", "brand": ["Pepcid"], "class": "H2-receptor antagonist (H2RA)", "moa": "Competitively blocks histamine H2 receptors on gastric parietal cells, reducing basal and stimulated acid secretion.", "indication": "GERD, peptic ulcer disease, heartburn/dyspepsia (OTC low-dose).", "dosage": "Ranitidine withdrawn from market (NDMA contamination); Famotidine 20–40 mg PO daily–BID (OTC 10 mg PRN)", "examPoints": ["Ranitidine was withdrawn from Canadian market (2020) due to NDMA contamination — famotidine is the H2RA now used/tested", "Less effective than PPIs for erosive esophagitis and severe GERD", "Renal dose adjustment required (renally eliminated)", "Tolerance can develop with chronic use (tachyphylaxis)"], "counselling": ["Can be taken with or without food", "OTC use limited to short-term symptom relief (~2 weeks); see a doctor if symptoms persist", "Take 30-60 min before trigger foods/events for prevention", "Space apart from antacids if taking both"], "sideEffects": ["Headache", "Dizziness", "Constipation/diarrhea", "Confusion (esp. elderly, renal impairment)"]}, {"topic": "gi", "generic": "Ondansetron", "pronunciation": "on-DAN-seh-tron", "brand": ["Zofran"], "class": "5-HT3 receptor antagonist (antiemetic)", "moa": "Blocks serotonin (5-HT3) receptors centrally (chemoreceptor trigger zone) and peripherally (vagal afferents in GI tract) to prevent nausea/vomiting.", "indication": "Chemotherapy/radiation-induced nausea and vomiting (CINV/RINV), postoperative nausea and vomiting (PONV).", "dosage": "4–8 mg PO/IV q8h PRN for nausea/vomiting; max 16 mg single oral dose (QT prolongation risk at higher doses)", "examPoints": ["QT prolongation risk — caution with other QT-prolonging drugs, electrolyte abnormalities, congenital long QT", "Dose-related constipation is common and can be significant", "Not first-line for simple gastroenteritis-related nausea in adults per some guidelines but widely used off-label", "ODT (orally disintegrating tablet) formulation available for patients with vomiting/swallowing difficulty"], "counselling": ["Can be taken with or without food", "ODT dissolves on tongue — do not need water", "Report palpitations, fainting, or irregular heartbeat", "Constipation is common — increase fluids/fibre if appropriate"], "sideEffects": ["Headache", "Constipation", "Fatigue", "QT prolongation (dose-dependent)", "Serotonin syndrome risk (rare, with other serotonergic drugs)"]}, {"topic": "gi", "generic": "Metoclopramide", "pronunciation": "met-oh-KLOH-pruh-myd", "brand": ["Reglan (generic common)"], "class": "Dopamine (D2) antagonist / prokinetic antiemetic", "moa": "Blocks D2 receptors in the CTZ (antiemetic effect) and enhances upper GI motility via cholinergic sensitization, increasing gastric emptying and lower esophageal sphincter tone.", "indication": "Diabetic gastroparesis, GERD (short-term), nausea/vomiting, prevention of chemotherapy-induced nausea.", "dosage": "5–10 mg PO/IV TID–QID before meals and at bedtime; max 30 mg/day; limit to ≤12 weeks (tardive dyskinesia risk)", "examPoints": ["Health Canada boxed warning: extrapyramidal symptoms (EPS) and tardive dyskinesia — limit use to <12 weeks", "Contraindicated in Parkinson's disease and GI obstruction/perforation", "Can cause acute dystonic reactions especially in young women/children — treat with diphenhydramine or benztropine", "Crosses BBB unlike domperidone — higher CNS/EPS risk"], "counselling": ["Take 30 minutes before meals and at bedtime as directed", "Report any unusual muscle movements, stiffness, or restlessness immediately", "Do not use for longer than the prescribed short course", "Avoid alcohol and other sedating drugs"], "sideEffects": ["Drowsiness/fatigue", "Restlessness (akathisia)", "Extrapyramidal symptoms", "Tardive dyskinesia (long-term use)", "Hyperprolactinemia"]}, {"topic": "gi", "generic": "Domperidone", "pronunciation": "dom-PER-ih-dohn", "brand": ["Domperidone (generic)"], "class": "Peripheral dopamine (D2) antagonist / prokinetic", "moa": "Blocks D2 receptors in the GI tract and CTZ; does not readily cross the blood-brain barrier, giving prokinetic/antiemetic effect with lower EPS risk than metoclopramide.", "indication": "Nausea/vomiting, gastroparesis symptoms, off-label galactagogue (not approved indication).", "dosage": "10 mg PO TID before meals; max 30 mg/day (QT prolongation risk at higher doses)", "examPoints": ["Health Canada warning: dose-dependent QT prolongation and sudden cardiac death risk — max recommended dose lowered, avoid in patients >60y or with cardiac risk factors when possible", "Contraindicated with concurrent strong CYP3A4 inhibitors (increases levels/QT risk) and in significant cardiac disease", "Lower EPS risk than metoclopramide since it doesn't cross BBB significantly", "Not FDA-approved in the US but available in Canada"], "counselling": ["Take 15-30 minutes before meals", "Report palpitations, dizziness, or fainting", "Avoid combining with other QT-prolonging medications unless directed", "Use the lowest effective dose for the shortest time"], "sideEffects": ["Dry mouth", "Headache", "Abdominal cramps", "QT prolongation/arrhythmia (serious)", "Hyperprolactinemia (galactorrhea, gynecomastia)"]}, {"topic": "gi", "generic": "Dimenhydrinate", "pronunciation": "dy-men-HY-drih-nayt", "brand": ["Gravol"], "class": "Antihistamine (H1 antagonist) / anticholinergic antiemetic", "moa": "Blocks H1 histamine receptors and has anticholinergic activity in the vestibular system and CTZ, suppressing nausea/vomiting particularly of motion-sickness origin.", "indication": "Motion sickness, nausea/vomiting (general, post-op), vertigo.", "dosage": "50–100 mg PO/IV/IM q4–6h PRN; max 400 mg/day", "examPoints": ["Significant sedation — caution with driving/machinery, additive CNS depression with alcohol/opioids/benzodiazepines", "Anticholinergic effects — caution in elderly (falls, confusion), BPH, narrow-angle glaucoma", "For motion sickness prevention, take 30-60 min before travel", "Available OTC in multiple formulations (tabs, chewable, suppository, injectable)"], "counselling": ["Take 30-60 minutes before travel for motion sickness prevention", "May cause drowsiness — avoid driving until you know how it affects you", "Avoid alcohol", "Can cause dry mouth, blurred vision — report urinary retention or confusion (esp. in elderly)"], "sideEffects": ["Drowsiness/sedation", "Dry mouth", "Blurred vision", "Urinary retention", "Confusion (elderly)", "Paradoxical excitation (children)"]}, {"topic": "gi", "generic": "Polyethylene glycol 3350", "pronunciation": "pol-ee-ETH-ih-leen GLY-kol", "brand": ["RestoraLAX", "PegLyte (bowel prep, combined)"], "class": "Osmotic laxative", "moa": "Non-absorbable osmotic agent that retains water in the colon, softening stool and increasing stool volume to stimulate peristalsis.", "indication": "Chronic constipation, bowel preparation for colonoscopy (higher-dose formulations).", "dosage": "17 g (1 capful) dissolved in liquid PO once daily PRN for constipation", "examPoints": ["Considered first-line for chronic constipation given efficacy/tolerability profile — minimal cramping vs. stimulants", "Onset typically 1-3 days for standard constipation dosing", "Bowel prep formulations (large volume, electrolytes) are distinct products/doses from daily maintenance use", "Safe for long-term use unlike stimulant laxatives"], "counselling": ["Dissolve powder completely in water/beverage before drinking", "May take 1-3 days to produce a bowel movement", "Ensure adequate fluid intake throughout the day", "Bowel prep instructions must be followed exactly as prescribed (timing relative to procedure)"], "sideEffects": ["Bloating", "Abdominal cramping", "Nausea", "Diarrhea (if overdosed)", "Electrolyte imbalance (large-volume bowel prep, esp. renal/cardiac patients)"]}, {"topic": "gi", "generic": "Docusate sodium", "pronunciation": "DOK-yoo-sayt SOH-dee-um", "brand": ["Colace", "Soflax"], "class": "Stool softener (surfactant laxative)", "moa": "Lowers surface tension of stool, allowing water and lipids to penetrate and soften the fecal mass, easing passage.", "indication": "Prevention of constipation/straining (e.g., post-surgery, postpartum, opioid-induced constipation adjunct), not effective for treating established constipation alone.", "dosage": "100–200 mg PO once–BID daily as stool softener", "examPoints": ["Weak evidence for efficacy as monotherapy for established constipation — best used prophylactically or combined with a stimulant", "Commonly paired with senna for opioid-induced constipation prevention", "Onset 1-3 days", "Not a substitute for osmotic/stimulant laxatives in moderate-severe constipation"], "counselling": ["Take with a full glass of water", "Best used to prevent straining, not to treat existing hard, impacted stool", "May take 1-3 days for effect", "Increase fluid and fibre intake if possible"], "sideEffects": ["Mild abdominal cramping", "Diarrhea", "Throat irritation (liquid form)", "Rash (rare)"]}, {"topic": "gi", "generic": "Senna", "pronunciation": "SEN-uh", "brand": ["Senokot"], "class": "Stimulant laxative", "moa": "Anthraquinone glycoside metabolized by colonic bacteria to active compounds that stimulate colonic motility and reduce water/electrolyte absorption from the colon.", "indication": "Constipation (short-term/occasional use), opioid-induced constipation (with docusate or alone), bowel prep adjunct.", "dosage": "1–2 tablets (8.6 mg sennosides) PO once–BID, max 4 tablets BID", "examPoints": ["Onset 6-12 hours — often dosed at bedtime for a morning effect", "Classic first-line prophylactic agent for opioid-induced constipation (stimulant, since opioids slow motility — osmotic/softener alone often insufficient)", "Chronic overuse historically associated with 'cathartic colon'/melanosis coli (pigmentation, largely benign) — avoid prolonged unsupervised use", "Avoid in suspected bowel obstruction"], "counselling": ["Usually taken at bedtime; effect expected in 6-12 hours", "For short-term use — see a doctor if constipation persists beyond one week", "May cause abdominal cramping", "Do not use if you have unexplained abdominal pain, nausea, or vomiting"], "sideEffects": ["Abdominal cramping", "Diarrhea", "Electrolyte imbalance (overuse)", "Melanosis coli (chronic use, benign)", "Dependence/laxative tolerance (chronic misuse)"]}, {"topic": "gi", "generic": "Lactulose", "pronunciation": "LAK-tyoo-lohs", "brand": ["Lactulose (generic)"], "class": "Osmotic laxative (disaccharide)", "moa": "Non-absorbable synthetic disaccharide metabolized by colonic bacteria to organic acids, drawing water into the colon osmotically; in hepatic encephalopathy, acidifies colon to trap ammonia (NH4+) for excretion.", "indication": "Constipation; hepatic encephalopathy (reduces ammonia absorption).", "dosage": "15–30 mL PO once–BID, titrated to 2–3 soft stools/day; hepatic encephalopathy up to 30–45 mL TID–QID", "examPoints": ["Dual exam-relevant use: constipation AND hepatic encephalopathy (titrate to 2-3 soft stools/day in HE)", "Onset can take 24-48 hours for constipation indication", "Causes significant flatulence/bloating due to bacterial fermentation — counsel patients to expect this", "Caution in galactosemia (contains galactose) and diabetics (contains sugars)"], "counselling": ["May take 1-2 days to work for constipation", "Expect gas/bloating initially — this often improves", "In hepatic encephalopathy, dose is adjusted to achieve 2-3 soft bowel movements per day — do not stop without direction", "Take with juice or water to improve taste if needed"], "sideEffects": ["Flatulence", "Bloating/abdominal cramping", "Nausea", "Diarrhea/electrolyte imbalance (if overdosed)"]}, {"topic": "gi", "generic": "Loperamide", "pronunciation": "loh-PER-uh-myd", "brand": ["Imodium"], "class": "Antidiarrheal (peripheral opioid mu-receptor agonist)", "moa": "Acts on opioid mu-receptors in the intestinal wall to slow peristalsis and increase transit time; minimal CNS penetration at normal doses due to P-glycoprotein efflux.", "indication": "Acute nondysenteric diarrhea, chronic diarrhea (e.g., IBS-D), traveler's diarrhea symptom control.", "dosage": "4 mg PO after first loose stool, then 2 mg after each subsequent stool; max 16 mg/day (OTC max 8 mg/day)", "examPoints": ["Avoid in bloody diarrhea/high fever (suspected invasive bacterial infection, e.g., C. diff, Shigella) — risk of toxic megacolon", "High-dose misuse/abuse can cause serious cardiac arrhythmias (QT prolongation, torsades) — Health Canada/FDA warnings on supratherapeutic doses", "Not for use in children under 2 (some guidance under 12 with caution) due to risk of CNS depression/paralytic ileus", "P-glycoprotein inhibitors (e.g., quinidine) can increase CNS penetration and toxicity risk"], "counselling": ["Do not exceed the recommended dose — taking more does not work faster and can be dangerous to the heart", "Stop and seek care if diarrhea contains blood, or if fever develops", "Not for chronic use without medical evaluation of the underlying cause", "Stay hydrated with oral rehydration if diarrhea is significant"], "sideEffects": ["Constipation", "Abdominal cramping/bloating", "Dizziness", "Dry mouth", "Serious cardiac arrhythmia (overdose/misuse)"]}, {"topic": "gi", "generic": "Mesalamine (5-ASA)", "pronunciation": "meh-SAL-uh-meen", "brand": ["Asacol", "Mezavant", "Salofalk", "Pentasa"], "class": "Aminosalicylate (5-ASA anti-inflammatory)", "moa": "Locally acts on colonic/intestinal mucosa to inhibit prostaglandin and leukotriene synthesis and scavenge reactive oxygen species, reducing mucosal inflammation.", "indication": "Mild-moderate ulcerative colitis (induction and maintenance); some formulations for Crohn's.", "dosage": "Oral: 2.4–4.8 g/day in divided doses or once daily; rectal (suppository/enema) 500 mg–1 g daily–BID depending on disease extent", "examPoints": ["Different formulations release at different GI sites (pH-dependent, time-dependent, or combined) — formulation choice matters for disease location (e.g., proctitis = suppository/enema; pancolitis = oral +/- rectal)", "Rare but important: mesalamine-induced nephrotoxicity — baseline and periodic renal function monitoring recommended", "Sulfasalazine (related, contains sulfa+5-ASA) causes more side effects due to the sulfapyridine moiety and requires folic acid supplementation", "Combination oral + rectal therapy often more effective than oral alone for distal disease"], "counselling": ["Take consistently as directed — do not crush/chew enteric-coated or delayed-release forms", "Complete the full course even if feeling better — this is a maintenance therapy for UC", "Suppository/enema forms: use at bedtime and try to retain as long as possible", "Report unusual bruising, blood in urine, or decreased urination (renal effects)"], "sideEffects": ["Headache", "Nausea/abdominal pain", "Diarrhea", "Rash", "Nephrotoxicity (rare)", "Pancreatitis (rare)"]}, {"topic": "gi", "generic": "Clarithromycin (H. pylori component)", "pronunciation": "kluh-RITH-roh-MY-sin", "brand": ["Biaxin"], "class": "Macrolide antibiotic", "moa": "Binds the 50S ribosomal subunit, inhibiting bacterial protein synthesis; active against H. pylori as part of combination eradication therapy.", "indication": "H. pylori eradication (triple/quadruple therapy component), respiratory and other bacterial infections.", "dosage": "500 mg PO BID x14 days as part of triple/quadruple H. pylori eradication therapy", "examPoints": ["Classic PPI triple therapy: PPI + clarithromycin + amoxicillin (or metronidazole if penicillin-allergic) for 7-14 days", "Rising clarithromycin resistance is a major reason quadruple therapy (PPI + bismuth + metronidazole + tetracycline) is now often preferred first-line in many regions", "Strong CYP3A4 inhibitor — major interaction potential (statins, colchicine — can be fatal, warfarin)", "QT prolongation risk, especially combined with other QT-prolonging drugs"], "counselling": ["Complete the full course exactly as prescribed even if symptoms improve, to reduce resistance and ensure eradication", "Take with or without food as directed by product", "Report severe diarrhea (C. diff), palpitations, or signs of liver problems", "Tell your pharmacist about all other medications due to significant interaction potential"], "sideEffects": ["GI upset (nausea, diarrhea, metallic taste)", "Headache", "QT prolongation", "Hepatotoxicity (rare)", "C. difficile-associated diarrhea"]}, {"topic": "gi", "generic": "Bismuth subsalicylate", "pronunciation": "BIZ-muth sub-suh-LIS-ih-layt", "brand": ["Pepto-Bismol"], "class": "Antidiarrheal / mild antimicrobial-antisecretory agent", "moa": "Provides antisecretory, anti-inflammatory, and direct antimicrobial (against H. pylori and enterotoxigenic bacteria) effects in the GI tract; also used as a component of quadruple H. pylori therapy.", "indication": "Traveler's diarrhea, dyspepsia/upset stomach, component of bismuth quadruple H. pylori therapy.", "dosage": "524 mg (2 tabs or 30 mL) PO q30–60min PRN, max 8 doses/day", "examPoints": ["Contains salicylate — avoid in children/teens with viral illness (Reye's syndrome risk), and caution in ASA allergy or those on anticoagulants/other salicylates", "Causes harmless black/dark stools and can darken the tongue — important counselling point to avoid alarming patients", "Component of bismuth quadruple therapy: bismuth + PPI + metronidazole + tetracycline for H. pylori (especially with clarithromycin resistance concerns)", "Can interfere with absorption of tetracyclines if not properly timed/formulated together in combo product"], "counselling": ["May turn stool and/or tongue black/dark — this is harmless and temporary", "Avoid if allergic to aspirin/salicylates or if taking other salicylate products", "Do not give to children or teenagers with flu-like or chickenpox symptoms", "Complete full course if part of H. pylori therapy"], "sideEffects": ["Black/dark stools (harmless)", "Darkened tongue", "Constipation", "Tinnitus (high/prolonged doses - salicylate toxicity)", "Reye's syndrome risk (children with viral illness)"]}, {"topic": "gi", "generic": "Ursodiol (ursodeoxycholic acid)", "pronunciation": "er-soh-DY-ol", "brand": ["Urso", "Actigall"], "class": "Bile acid (hydrophilic)", "moa": "Reduces cholesterol synthesis and secretion into bile and decreases intestinal cholesterol absorption, dissolving cholesterol gallstones and reducing bile toxicity in cholestatic liver disease (e.g., PBC).", "indication": "Dissolution of small radiolucent cholesterol gallstones (surgery-averse patients), primary biliary cholangitis (PBC), prevention of gallstones with rapid weight loss.", "dosage": "13–15 mg/kg/day PO in divided doses for gallstone dissolution/PBC; up to 20 mg/kg/day for cholestatic liver disease", "examPoints": ["Not effective for pigment (calcified) gallstones — only radiolucent cholesterol stones respond", "Treatment for gallstone dissolution can take months and stones may recur after stopping", "First-line therapy for primary biliary cholangitis to slow disease progression and improve liver biochemistry", "Take with food to improve absorption/reduce GI upset"], "counselling": ["May take several months of therapy to dissolve gallstones — adherence is important", "Take with food", "Report worsening abdominal pain, jaundice, or itching to your prescriber", "Follow-up ultrasounds may be used to monitor gallstone response"], "sideEffects": ["Diarrhea", "Nausea", "Abdominal pain", "Headache", "Pruritus (rare)"]}, {"topic": "pain", "generic": "Acetaminophen", "pronunciation": "uh-SEE-tuh-MIN-oh-fen", "brand": ["Tylenol"], "class": "Analgesic/antipyretic (non-opioid)", "moa": "Exact mechanism not fully established; thought to inhibit central COX (and possibly a COX-3 variant) and modulate descending serotonergic pain pathways; minimal peripheral anti-inflammatory activity.", "indication": "Mild-moderate pain, fever; first-line for osteoarthritis pain per many guidelines.", "dosage": "325–1000 mg PO q4–6h PRN; max 4 g/day (3 g/day if hepatic risk factors or chronic use)", "examPoints": ["Max daily dose generally 4 g/day in healthy adults; many guidelines/product labels now recommend ≤3 g/day for chronic use or in those with hepatic risk factors", "Hepatotoxicity is dose-dependent and is the classic overdose exam topic — antidote is N-acetylcysteine (NAC)", "Caution/lower max dose with chronic alcohol use, malnutrition, or existing liver disease", "Found in many combination products (cold/flu, opioid combos like Tylenol #3) — risk of inadvertent overdose from stacking products"], "counselling": ["Check all other OTC/combination products (cold/flu remedies, opioid combos) for hidden acetaminophen to avoid exceeding the daily limit", "Do not exceed the recommended daily maximum dose", "Limit or avoid alcohol, especially with regular use", "Seek immediate medical attention for suspected overdose even if no symptoms yet (delayed hepatotoxicity)"], "sideEffects": ["Generally well tolerated at therapeutic doses", "Nausea (uncommon)", "Hepatotoxicity (overdose/chronic excess)", "Rare skin reactions (SJS/TEN - rare but serious)"]}, {"topic": "pain", "generic": "Ibuprofen", "pronunciation": "eye-byoo-PROH-fen", "brand": ["Advil", "Motrin"], "class": "NSAID (nonselective COX inhibitor), propionic acid derivative", "moa": "Nonselectively inhibits cyclooxygenase (COX-1 and COX-2), reducing prostaglandin synthesis responsible for pain, inflammation, and fever.", "indication": "Mild-moderate pain, inflammation (osteoarthritis, RA adjunct), fever, dysmenorrhea.", "dosage": "200–400 mg PO q4–6h PRN (OTC max 1200 mg/day); prescription max 3200 mg/day divided TID–QID", "examPoints": ["GI bleed/ulcer risk (COX-1 inhibition reduces protective gastric prostaglandins) — increased risk with age >65, prior ulcer, corticosteroid or anticoagulant co-use", "Cardiovascular risk (esp. at high doses/long-term) — boxed warning class effect for NSAIDs, use lowest effective dose shortest duration", "Nephrotoxicity risk — avoid/caution in renal impairment, dehydration, with ACEi/ARB + diuretic ('triple whammy')", "Interferes with low-dose ASA's cardioprotective antiplatelet effect if taken before ASA — advise timing (ASA first, ibuprofen ≥30-60 min after, or ≥8h before)"], "counselling": ["Take with food or milk to reduce stomach upset", "Use the lowest effective dose for the shortest time needed", "Report black/tarry stools, unusual bruising, or swelling/weight gain", "If also taking daily low-dose aspirin for heart protection, ask your pharmacist about timing"], "sideEffects": ["Dyspepsia/GI upset", "GI ulcer/bleeding", "Fluid retention/edema", "Renal impairment", "Increased cardiovascular risk (MI, stroke)"]}, {"topic": "pain", "generic": "Naproxen", "pronunciation": "nuh-PROKS-en", "brand": ["Aleve", "Naprosyn"], "class": "NSAID (nonselective COX inhibitor), propionic acid derivative", "moa": "Nonselectively inhibits COX-1 and COX-2, decreasing prostaglandin-mediated pain and inflammation; longer half-life allows less frequent dosing than ibuprofen.", "indication": "Osteoarthritis, rheumatoid arthritis, gout flare, dysmenorrhea, musculoskeletal pain.", "dosage": "250–500 mg PO BID; max 1000 mg/day (1500 mg/day short-term for acute conditions)", "examPoints": ["Considered to have relatively lower cardiovascular risk among NSAIDs compared to diclofenac/COX-2 selective agents (though still class warning applies)", "Longer half-life (~12-17h) permits BID dosing — convenient but also longer duration of any adverse effect once occurring", "Same GI, renal, and CV precautions as other NSAIDs; same ASA interaction/timing issue", "Used commonly for acute gout flares as an alternative to colchicine/steroids"], "counselling": ["Take with food to reduce GI upset", "Do not exceed recommended dose/duration without medical advice", "Report signs of GI bleeding (black stools, blood in vomit) or unusual swelling", "Avoid combining with other NSAIDs (including OTC) to prevent additive toxicity"], "sideEffects": ["Dyspepsia", "GI ulcer/bleeding", "Edema/fluid retention", "Renal impairment", "Cardiovascular events (long-term/high dose)"]}, {"topic": "pain", "generic": "Celecoxib", "pronunciation": "SEL-eh-KOKS-ib", "brand": ["Celebrex"], "class": "NSAID — selective COX-2 inhibitor", "moa": "Selectively inhibits COX-2, sparing COX-1-mediated gastric mucosal protection, reducing prostaglandin synthesis with theoretically lower GI toxicity than nonselective NSAIDs.", "indication": "Osteoarthritis, rheumatoid arthritis, ankylosing spondylitis, acute pain.", "dosage": "100–200 mg PO once–BID daily; max 400 mg/day (200 mg BID for RA/OA)", "examPoints": ["Lower GI ulcer/bleed risk than nonselective NSAIDs but NOT zero — risk returns toward baseline with concurrent low-dose ASA use", "Same (or possibly higher, per some data) cardiovascular risk as nonselective NSAIDs — boxed warning applies", "Contains a sulfonamide moiety — caution/avoid in sulfa allergy", "No antiplatelet effect (unlike nonselective NSAIDs), so does not interfere with cardioprotective ASA the same way"], "counselling": ["Take with food if GI upset occurs", "Report chest pain, shortness of breath, slurred speech (cardiovascular red flags)", "Tell your pharmacist if you have a sulfa allergy before starting", "Do not combine with other NSAIDs"], "sideEffects": ["Dyspepsia", "Headache", "Edema/hypertension", "Increased cardiovascular risk", "GI ulcer/bleeding (lower risk than nonselective NSAIDs but still possible)"]}, {"topic": "pain", "generic": "Morphine", "pronunciation": "MOR-feen", "brand": ["Statex", "MS Contin", "Kadian"], "class": "Opioid agonist (strong, mu-receptor)", "moa": "Full agonist at mu-opioid receptors in the CNS, altering pain perception and emotional response to pain; also affects respiratory centre and GI motility.", "indication": "Moderate-severe acute and chronic (esp. cancer/palliative) pain.", "dosage": "Immediate-release: 5–15 mg PO q4h PRN, titrated to effect; no ceiling dose in opioid-tolerant patients (titrate for analgesia vs. adverse effects)", "examPoints": ["Reference standard for equianalgesic dosing calculations — oral morphine 1:1 comparisons are the basis for opioid conversion tables (e.g., oral morphine:oral hydromorphone ≈5:1; oral:parenteral morphine ≈3:1)", "Active metabolite morphine-6-glucuronide accumulates in renal impairment — increased sedation/toxicity risk, caution/avoid in significant renal disease (hydromorphone or fentanyl often preferred)", "CDSA (Controlled Drugs and Substances Act) schedule — prescription cannot be refilled without a new Rx; specific pharmacy record-keeping/reporting requirements apply", "Constipation does not develop tolerance (unlike sedation/nausea) — prophylactic laxative (stimulant +/- softener) should be co-prescribed"], "counselling": ["Take exactly as prescribed; do not adjust dose without discussing with your prescriber", "Start a bowel regimen (e.g., senna) proactively — constipation is expected and persistent", "Avoid alcohol and other sedatives (benzodiazepines) — risk of dangerous respiratory depression", "Do not drive until you know how this affects you; store securely away from others, including household members"], "sideEffects": ["Constipation (persistent)", "Nausea/vomiting", "Sedation/drowsiness", "Respiratory depression (serious)", "Tolerance/physical dependence", "Pruritus"]}, {"topic": "pain", "generic": "Hydromorphone", "pronunciation": "hy-droh-MOR-fohn", "brand": ["Dilaudid", "Hydromorph Contin"], "class": "Opioid agonist (strong, mu-receptor)", "moa": "Semi-synthetic full mu-opioid receptor agonist, more potent than morphine per mg, with similar mechanism of central pain modulation.", "indication": "Moderate-severe acute and chronic pain, especially when morphine is not tolerated or renal impairment present.", "dosage": "1–2 mg PO q3–4h PRN (immediate-release), titrated to effect; ~5x more potent than morphine", "examPoints": ["Approximately 5x more potent than oral morphine (oral morphine:oral hydromorphone ≈ 5:1) — critical for equianalgesic conversion questions", "Preferred over morphine in renal impairment as it has fewer clinically significant active metabolites that accumulate", "High potential for dosing errors/dispensing errors due to potency and similar-sounding names to morphine — classic ISMP high-alert medication", "Same CDSA scheduling and refill restrictions as morphine (no refills on original Rx)"], "counselling": ["This medication is much stronger per milligram than morphine — never assume dose equivalence without checking with your pharmacist", "Start a bowel regimen to prevent constipation", "Avoid alcohol and other CNS depressants", "Store securely; do not share with others"], "sideEffects": ["Constipation", "Nausea/vomiting", "Sedation", "Respiratory depression", "Dependence/tolerance"]}, {"topic": "pain", "generic": "Codeine", "pronunciation": "KOH-deen", "brand": ["Codeine Contin", "Tylenol #3 (combo)"], "class": "Opioid agonist (weak, prodrug)", "moa": "Prodrug metabolized by CYP2D6 to morphine (active metabolite) to exert mu-opioid analgesic effect; also has antitussive activity.", "indication": "Mild-moderate pain (often in combination with acetaminophen), cough suppression.", "dosage": "30–60 mg PO q4–6h PRN; max 360 mg/day; avoid in CYP2D6 ultra-rapid metabolizers and breastfeeding", "examPoints": ["CYP2D6 ultrarapid metabolizers convert codeine to morphine faster/more completely — risk of overdose/toxicity; poor metabolizers get little analgesic effect", "Health Canada contraindication: codeine (and tramadol) contraindicated in children <12 and in breastfeeding mothers (risk of infant morphine toxicity via CYP2D6 ultrarapid metabolism)", "Combination products (e.g., Tylenol #3) carry acetaminophen ceiling dose limits — watch for total daily acetaminophen when titrating", "CDSA-scheduled (exempt codeine low-dose combos have OTC status in some provinces with conditions, but higher-dose products are Rx/controlled)"], "counselling": ["Do not exceed the recommended dose — check total acetaminophen content in combination products", "Do not give to children under 12 or use while breastfeeding", "May cause drowsiness — avoid driving until effects are known", "Avoid alcohol"], "sideEffects": ["Constipation", "Nausea", "Drowsiness", "Respiratory depression (esp. ultrarapid metabolizers)", "Dependence with prolonged use"]}, {"topic": "pain", "generic": "Tramadol", "pronunciation": "TRA-muh-dol", "brand": ["Tramacet (combo w/ acetaminophen)", "Zytram"], "class": "Atypical opioid agonist + SNRI activity", "moa": "Weak mu-opioid receptor agonist plus inhibits serotonin and norepinephrine reuptake, giving a dual analgesic mechanism distinct from typical opioids.", "indication": "Moderate pain (acute and chronic).", "dosage": "50–100 mg PO q4–6h PRN; max 400 mg/day (300 mg/day in elderly); lowers seizure threshold", "examPoints": ["Lowers seizure threshold — caution/avoid with history of seizures, and with other drugs that lower seizure threshold (bupropion, TCAs)", "Serotonin syndrome risk when combined with other serotonergic drugs (SSRIs, SNRIs, MAOIs, triptans) due to its SNRI-like activity", "CYP2D6-dependent activation similar to codeine — same ultrarapid metabolizer caution and contraindication in children <12/breastfeeding", "Still a controlled substance (CDSA) despite being 'atypical' — same refill restrictions apply"], "counselling": ["Do not combine with other serotonergic medications without checking with your pharmacist (risk of serotonin syndrome)", "Report seizures, confusion, agitation, or fast heart rate", "May cause drowsiness/dizziness — use caution with driving", "Do not exceed prescribed dose"], "sideEffects": ["Nausea/dizziness", "Constipation", "Somnolence", "Seizures (dose-related, risk factors)", "Serotonin syndrome (with interacting drugs)"]}, {"topic": "pain", "generic": "Fentanyl (transdermal)", "pronunciation": "FEN-tuh-nil", "brand": ["Duragesic", "Fentanyl patch (generic)"], "class": "Opioid agonist (strong, synthetic, mu-receptor)", "moa": "Highly potent synthetic full mu-opioid agonist; transdermal patch provides continuous systemic delivery through the skin depot.", "indication": "Chronic, stable, severe pain in opioid-tolerant patients (NOT for opioid-naive patients or acute/postoperative pain).", "dosage": "12–100 mcg/hr patch changed q72h; only for opioid-tolerant patients, not opioid-naïve", "examPoints": ["Contraindicated in opioid-naive patients — reserved for those already tolerant to a specified minimum daily opioid dose; classic exam trap", "Heat exposure (fever, heating pads, hot tubs, sun) increases drug release from the patch — can cause fatal overdose", "Patch takes 12-24h to reach steady effect and has residual depot effect for 12-24h+ after removal — do not abruptly substitute another opioid immediately at full dose", "Used/unused patches must be disposed of properly (fold sticky sides together) — retained fentanyl remains dangerous, even to children/pets, after 'use'"], "counselling": ["Apply to clean, dry, hairless skin and rotate sites; do not cut the patch", "Avoid heat sources (heating pads, saunas, hot tubs, electric blankets, fever) directly over the patch area", "Dispose of used patches by folding sticky sides together, out of reach of children and pets", "This medication is only appropriate if you are already opioid-tolerant — never start it for new/acute pain"], "sideEffects": ["Constipation", "Nausea", "Sedation", "Application site reaction", "Respiratory depression (serious, esp. with heat exposure or in opioid-naive patients)"]}, {"topic": "pain", "generic": "Gabapentin", "pronunciation": "GA-buh-PEN-tin", "brand": ["Neurontin"], "class": "Gabapentinoid (anticonvulsant/neuropathic analgesic)", "moa": "Binds the alpha-2-delta subunit of voltage-gated calcium channels in the CNS, reducing excitatory neurotransmitter release, which dampens neuropathic pain signaling.", "indication": "Neuropathic pain (e.g., postherpetic neuralgia, diabetic neuropathy), adjunct for seizures, off-label for various pain syndromes.", "dosage": "Neuropathic pain: start 100–300 mg PO at bedtime, titrate to usual 900–3600 mg/day in divided doses (TID)", "examPoints": ["Requires renal dose adjustment (renally eliminated, not hepatically metabolized) — key pharmacokinetics exam point", "Bioavailability decreases as dose increases (saturable absorption) — reason for TID dosing and dose-proportionality nonlinearity", "Growing recognition of gabapentinoid misuse potential, especially combined with opioids — increased respiratory depression risk in combination (Health Canada warning)", "Taper needed on discontinuation to avoid withdrawal (anxiety, insomnia, sweating) despite not being a controlled substance federally in Canada (though monitored in some jurisdictions)"], "counselling": ["May cause dizziness/drowsiness, especially when starting — use caution with driving", "Do not stop abruptly — must be tapered under medical supervision", "Full effect on neuropathic pain may take several weeks of titration", "Avoid alcohol and use caution combining with opioids"], "sideEffects": ["Dizziness", "Somnolence/fatigue", "Peripheral edema", "Weight gain", "Ataxia", "Respiratory depression (esp. with opioids)"]}, {"topic": "pain", "generic": "Pregabalin", "pronunciation": "preh-GAB-uh-lin", "brand": ["Lyrica"], "class": "Gabapentinoid (anticonvulsant/neuropathic analgesic)", "moa": "Binds the alpha-2-delta subunit of voltage-gated calcium channels, reducing calcium influx and excitatory neurotransmitter release; similar mechanism to gabapentin with more predictable linear pharmacokinetics.", "indication": "Neuropathic pain (diabetic neuropathy, postherpetic neuralgia, spinal cord injury pain), fibromyalgia, adjunct for partial seizures, generalized anxiety disorder.", "dosage": "Start 75 mg PO BID (or 50 mg TID), titrate to usual 150–300 mg/day, max 600 mg/day; renal dose adjustment required", "examPoints": ["Pregabalin IS a controlled substance in Canada (Schedule G-like/CDSA scheduling considerations vary; treated with more prescribing control than gabapentin) due to recognized abuse potential — differs from gabapentin's non-controlled status", "Linear, dose-proportional absorption (unlike gabapentin) allows BID dosing and more predictable titration", "Renal dose adjustment required", "Same opioid-combination respiratory depression warning as gabapentin; also risk of misuse/euphoria at higher doses"], "counselling": ["May cause dizziness or drowsiness, particularly when starting therapy", "Do not stop abruptly — taper as directed to avoid withdrawal symptoms", "Avoid alcohol and use caution if combined with opioids or other sedatives", "Report swelling of hands/feet or unusual weight gain"], "sideEffects": ["Dizziness", "Somnolence", "Peripheral edema", "Weight gain", "Blurred vision", "Dry mouth"]}, {"topic": "pain", "generic": "Methotrexate (low-dose, RA)", "pronunciation": "meth-oh-TREKS-ayt", "brand": ["Rheumatrex", "Metoject (SC)"], "class": "DMARD (disease-modifying antirheumatic drug) — antimetabolite/folate antagonist", "moa": "Inhibits dihydrofolate reductase and has additional anti-inflammatory/immunomodulatory effects at low weekly doses used in RA, distinct from high-dose cytotoxic oncology use.", "indication": "Rheumatoid arthritis (first-line DMARD), psoriatic arthritis, psoriasis.", "dosage": "7.5–25 mg PO/SC once weekly (NOT daily); given with folic acid 1–5 mg daily (except day of MTX dose) to reduce toxicity", "examPoints": ["CLASSIC EXAM TRAP: dosed ONCE WEEKLY for RA, not daily — daily dosing errors have caused fatal toxicity; pharmacists must verify weekly dosing on every fill", "Folic acid supplementation (typically 1 mg daily or 5 mg weekly, given on a different day than MTX) reduces GI/hepatic side effects and mucositis without reducing efficacy", "Requires baseline and periodic monitoring: CBC, liver enzymes (AST/ALT), renal function, and pregnancy status (teratogenic — effective contraception required in both partners)", "Contraindicated in pregnancy/breastfeeding, significant liver disease, and with alcohol use (hepatotoxicity risk); avoid live vaccines"], "counselling": ["Take this medication ONLY ONCE PER WEEK on the same day each week — confirm the day with your pharmacist", "Take folic acid as prescribed on a different day from your methotrexate dose", "Avoid alcohol due to increased liver toxicity risk", "Effective contraception is required — this drug can cause serious birth defects", "Report unusual bruising/bleeding, mouth sores, persistent cough, or shortness of breath"], "sideEffects": ["Nausea/GI upset", "Mouth sores/mucositis", "Fatigue", "Hepatotoxicity", "Bone marrow suppression", "Pulmonary toxicity (rare, serious)"]}, {"topic": "pain", "generic": "Colchicine", "pronunciation": "KOL-chih-seen", "brand": ["Colchicine (generic)"], "class": "Anti-inflammatory (microtubule inhibitor)", "moa": "Inhibits microtubule polymerization, reducing neutrophil migration/activation and inflammatory response in acute gout.", "indication": "Acute gout flare treatment; gout flare prophylaxis when starting urate-lowering therapy.", "dosage": "Acute gout: 1.2 mg PO at first sign, then 0.6 mg 1h later (max 1.8 mg/episode); prophylaxis 0.6 mg once–BID daily", "examPoints": ["Narrow therapeutic index — reduce dose in renal/hepatic impairment and with CYP3A4/P-gp inhibitors (e.g., clarithromycin) — can be fatal in combination", "Acute flare dosing is a short, specific regimen (e.g., 1.2 mg then 0.6 mg one hour later) — NOT dosed like a regular scheduled drug", "GI side effects (diarrhea) are often the first sign of toxicity"], "counselling": ["Take exactly as directed for the flare — do not repeat the loading dose within the same flare", "Stop and call your pharmacist/doctor if you get significant diarrhea or vomiting", "Tell your pharmacist about all other medications — several common antibiotics interact seriously"], "sideEffects": ["Diarrhea", "Nausea/vomiting", "Abdominal pain", "Bone marrow suppression (overdose/toxicity)", "Myopathy/rhabdomyolysis (rare, esp. with interacting drugs)"]}, {"topic": "pain", "generic": "Allopurinol", "pronunciation": "al-oh-PYOOR-ih-nol", "brand": ["Zyloprim"], "class": "Xanthine oxidase inhibitor (urate-lowering therapy)", "moa": "Inhibits xanthine oxidase, blocking conversion of hypoxanthine/xanthine to uric acid, lowering serum urate to prevent gout flares and tophi formation.", "indication": "Chronic gout (urate-lowering, prevention), tumor lysis syndrome prevention.", "dosage": "Start 100 mg PO daily (50 mg if CKD), titrate q2–4wk to target uric acid <360 µmol/L; usual maintenance 200–300 mg/day, max 800 mg/day", "examPoints": ["Start LOW and titrate slowly to target serum urate (<360 micromol/L, or <300 for tophaceous disease) — rapid dose escalation can precipitate acute flares", "Never start during an acute gout flare — start after the flare resolves, and continue if already established; co-prescribe flare prophylaxis (colchicine/NSAID) for first 3-6 months when initiating/titrating", "HLA-B*5801 allele (higher prevalence in certain Asian and other populations) linked to severe allopurinol hypersensitivity syndrome (SJS/TEN, DRESS) — consider screening in high-risk populations", "Major interaction: azathioprine/6-mercaptopurine — allopurinol inhibits their metabolism (also via xanthine oxidase), requiring significant dose reduction (~75%) to avoid severe myelosuppression"], "counselling": ["Do not stop taking this during a gout flare — it works long-term to prevent future flares, not to treat an active one", "You may be started on a second medication (colchicine or NSAID) for the first few months to prevent flares while allopurinol takes effect", "Report any rash immediately — stop the drug and seek care, as rash can be a sign of a serious reaction", "Drink plenty of fluids and attend follow-up blood tests to monitor uric acid levels"], "sideEffects": ["Rash (can herald severe hypersensitivity)", "GI upset", "Increased LFTs", "Severe hypersensitivity syndrome (SJS/TEN/DRESS - rare but serious)", "Precipitation of acute gout flare (early in therapy)"]}, {"topic": "pain", "generic": "Cyclobenzaprine", "pronunciation": "sy-kloh-BEN-zuh-preen", "brand": ["Flexeril (historical)", "cyclobenzaprine (generic)"], "class": "Skeletal muscle relaxant (centrally acting)", "moa": "Acts centrally at the brainstem level (structurally related to TCAs) to reduce tonic somatic motor activity, relieving muscle spasm without directly acting on the muscle itself.", "indication": "Short-term relief of muscle spasm associated with acute musculoskeletal conditions.", "dosage": "5–10 mg PO TID PRN for muscle spasm; max 30 mg/day; limit use to ≤2–3 weeks", "examPoints": ["Anticholinergic and sedating (TCA-like structure) — significant additive CNS depression with alcohol/opioids/benzodiazepines, caution in elderly (Beers List drug)", "Recommended for short-term use only (typically ≤2-3 weeks) — evidence doesn't support long-term use for chronic pain", "Contraindicated with MAOIs and within 14 days of MAOI use (risk of serotonin syndrome/hyperpyretic crisis)", "Not an anti-inflammatory or direct analgesic — works via CNS sedation/muscle relaxation, distinguish from NSAIDs mechanistically on exams"], "counselling": ["For short-term use only — reassess if muscle spasm/pain persists beyond a couple of weeks", "May cause significant drowsiness — avoid driving or operating machinery until you know how it affects you", "Avoid alcohol and other sedating medications", "Older adults should use caution due to increased fall/confusion risk"], "sideEffects": ["Drowsiness/sedation", "Dry mouth", "Dizziness", "Blurred vision", "Constipation", "Confusion (esp. elderly)"]}, {"topic": "womens", "generic": "Ethinyl estradiol / Levonorgestrel (combined oral contraceptive)", "pronunciation": "ETH-in-il es-truh-DY-ol / lee-voh-nor-JES-trel", "brand": ["Alesse", "Min-Ovral", "Marvelon"], "class": "Combined hormonal contraceptive (estrogen + progestin)", "moa": "Suppresses the hypothalamic-pituitary-ovarian axis to inhibit ovulation (blocks LH surge); also thickens cervical mucus and thins the endometrium.", "indication": "Contraception; also used for cycle regulation, acne, and dysmenorrhea.", "dosage": "1 tablet PO once daily, same time each day, typically 21 active + 7 placebo (or continuous regimens available)", "examPoints": ["Absolute contraindications (UKMEC 4): migraine with aura, smoker >=35 yo with >=15 cig/day, history of VTE/PE, uncontrolled HTN, active breast cancer, <21 days postpartum", "Missed pill rule: >24h late/missed 1 pill = take ASAP + continue pack; >48h/missed 2+ pills = backup contraception x7 days, consider EC if unprotected sex in prior 5 days", "Increases risk of VTE (highest in first year of use, especially with drospirenone-containing products)", "Enzyme inducers (rifampin, some anticonvulsants, St. John's Wort) reduce efficacy", "Non-contraceptive benefits: reduces ovarian/endometrial cancer risk, improves acne and menstrual regularity"], "counselling": ["Take at the same time every day for best effectiveness", "May cause breakthrough spotting in the first 1-3 cycles - this usually resolves", "Report calf swelling/pain, chest pain, severe headache, or visual changes immediately (VTE/stroke warning signs)", "Does not protect against STIs - condoms still needed", "Antibiotics generally do NOT reduce efficacy except rifampin/rifabutin"], "sideEffects": ["Nausea", "Breast tenderness", "Breakthrough bleeding", "Headache", "Venous thromboembolism (rare but serious)", "Mood changes"]}, {"topic": "womens", "generic": "Norethindrone (progestin-only pill)", "pronunciation": "nor-eth-IN-drohn", "brand": ["Micronor", "Movisse"], "class": "Progestin-only contraceptive (POP / \"mini-pill\")", "moa": "Thickens cervical mucus to block sperm penetration and suppresses ovulation in some cycles; does not reliably suppress the HPO axis like combined pills.", "indication": "Contraception for patients with estrogen contraindications (e.g., breastfeeding, VTE history, migraine with aura).", "dosage": "0.35 mg PO once daily continuously at the same time (±3h window) with no placebo interval", "examPoints": ["Must be taken within the SAME 3-hour window daily - stricter than COC's 12-hour rule (traditional norethindrone POP)", "Newer drospirenone-only POP (Slynd) has a more forgiving 24-hour window - classic exam trap", "Safe in breastfeeding and in most patients with estrogen contraindications", "No pill-free interval - taken continuously, including during withdrawal bleeding", "Missed pill >3h late requires backup contraception for 48h"], "counselling": ["Take at the exact same time every day, even during your period", "If more than 3 hours late, use backup contraception (condoms) for the next 48 hours", "Irregular spotting is common and does not mean it isn't working", "Safe to use while breastfeeding", "No pill-free week - continue taking a pill every single day"], "sideEffects": ["Irregular/unpredictable bleeding", "Headache", "Breast tenderness", "Acne", "Mood changes", "Functional ovarian cysts (uncommon)"]}, {"topic": "womens", "generic": "Levonorgestrel (emergency contraception)", "pronunciation": "lee-voh-nor-JES-trel", "brand": ["Plan B", "Plan B One-Step", "Contingency One-Step"], "class": "Progestin emergency contraceptive", "moa": "Primarily delays or inhibits ovulation by suppressing the LH surge; does not disrupt an established pregnancy.", "indication": "Emergency contraception after unprotected intercourse or contraceptive failure.", "dosage": "1.5 mg PO single dose, as soon as possible within 72h (up to 96h) of unprotected intercourse", "examPoints": ["Most effective within 72 hours (3 days) of unprotected sex, though may have reduced efficacy up to 120 hours", "Efficacy decreases with increasing body weight/BMI (>70 kg or BMI >25); ulipristal or copper IUD preferred if overweight", "Available without a prescription (Schedule II, behind-the-counter) in Canadian pharmacies", "Can be used more than once in a cycle, but is not intended as a regular contraceptive method", "Vomiting within 2-3 hours of the dose requires a repeat dose"], "counselling": ["Take as soon as possible after unprotected sex for best effectiveness", "Take a single dose - no need to wait to see if a period comes first", "Next period may be early, late, or heavier/lighter than usual", "Start or resume regular contraception right away; use backup protection for 7 days after", "Does not protect against STIs and is not effective if pregnancy has already occurred"], "sideEffects": ["Nausea", "Fatigue", "Lower abdominal pain", "Headache", "Menstrual irregularities/delayed next period"]}, {"topic": "womens", "generic": "Ulipristal acetate (emergency contraception)", "pronunciation": "yoo-lih-PRIS-tal AS-eh-tayt", "brand": ["Ella"], "class": "Selective progesterone receptor modulator (SPRM)", "moa": "Blocks progesterone receptors to delay or inhibit ovulation even after the LH surge has begun, giving it a longer effective window than levonorgestrel.", "indication": "Emergency contraception, effective up to 120 hours (5 days) after unprotected intercourse.", "dosage": "30 mg PO single dose within 120h (5 days) of unprotected intercourse; more effective than LNG later in the window", "examPoints": ["Effective up to 120 hours (5 days) post-coitus, vs. 72 hours for levonorgestrel - key comparative exam fact", "Maintains effectiveness better than levonorgestrel in patients with higher BMI/weight", "Requires a prescription in Canada (unlike levonorgestrel EC)", "Do NOT use with hormonal contraception concurrently - progestins can blunt ulipristal's effect; wait 5 days after ulipristal before starting/resuming hormonal contraception", "Avoid in breastfeeding for at least 1 week after the dose (pump and discard)"], "counselling": ["Take a single dose as soon as possible, ideally within 5 days of unprotected sex", "Wait at least 5 days before starting or restarting hormonal birth control after taking this", "Use a barrier method (condoms) until your regular contraception is effective again", "If breastfeeding, pump and discard milk for 1 week after the dose", "If vomiting occurs within 3 hours, contact your pharmacist about a repeat dose"], "sideEffects": ["Headache", "Nausea/abdominal pain", "Fatigue", "Delayed or irregular next menstrual period", "Dizziness"]}, {"topic": "womens", "generic": "Estradiol (HRT estrogen)", "pronunciation": "es-truh-DY-ol", "brand": ["Estrace", "Climara (patch)", "Divigel", "Estrogel"], "class": "Hormone replacement therapy - estrogen component", "moa": "Replaces declining endogenous estrogen to relieve vasomotor and genitourinary menopausal symptoms; transdermal routes avoid first-pass hepatic metabolism.", "indication": "Moderate-to-severe menopausal vasomotor symptoms (hot flashes, night sweats) and genitourinary syndrome of menopause.", "dosage": "Oral 0.5–2 mg daily, transdermal patch 0.025–0.1 mg/day (changed 1–2x/week), or gel/spray; lowest effective dose for shortest duration", "examPoints": ["Must be combined with a progestin if the patient has an intact uterus (unopposed estrogen increases endometrial cancer risk)", "Transdermal (patch/gel) has lower VTE and stroke risk than oral estrogen - preferred in patients with VTE risk factors", "\"Window of opportunity\" - greatest cardiovascular benefit/safety when started <60 yo or within 10 years of menopause onset", "WHI study: increased breast cancer risk with prolonged combined HRT use (>3-5 years)", "Contraindicated in history of estrogen-dependent cancer, active VTE, undiagnosed vaginal bleeding, active liver disease"], "counselling": ["Use the lowest effective dose for the shortest duration needed to control symptoms", "If you still have your uterus, you must also take a progestin to protect the uterine lining", "Report unexpected vaginal bleeding, leg swelling/pain, chest pain, or severe headache", "Rotate patch application sites and apply to clean, dry, hairless skin", "Vaginal (local) estrogen for genitourinary symptoms alone does not require added progestin"], "sideEffects": ["Breast tenderness", "Bloating", "Nausea", "Headache", "Venous thromboembolism", "Increased breast cancer risk with prolonged combined use"]}, {"topic": "womens", "generic": "Medroxyprogesterone acetate", "pronunciation": "meh-DROKS-ee-proh-JES-tuh-rohn AS-eh-tayt", "brand": ["Provera (oral)", "Depo-Provera (injectable)"], "class": "Progestin - HRT component / injectable contraceptive", "moa": "Progestin that opposes estrogen's proliferative effect on the endometrium; as Depo-Provera, suppresses gonadotropins to inhibit ovulation.", "indication": "Endometrial protection in HRT (oral); long-acting injectable contraception (Depo-Provera, IM/SC every 12-13 weeks).", "dosage": "Contraception (Depo-Provera): 150 mg IM (or 104 mg SC) every 12–13 weeks; HRT/endometrial protection 2.5–10 mg PO daily or cyclically", "examPoints": ["Depo-Provera carries a Health Canada boxed warning for bone mineral density loss with long-term use (>2 years) - reassess risk/benefit", "Delayed return to fertility after stopping Depo-Provera - can take up to 9-10 months", "Injection must be repeated every 12-13 weeks; if >2 weeks late, rule out pregnancy and use backup contraception", "Weight gain is a commonly reported side effect leading to discontinuation", "Oral medroxyprogesterone used cyclically or continuously alongside estrogen for endometrial protection in HRT"], "counselling": ["Depo-Provera injections must be given on schedule every 12-13 weeks", "It may take several months to a year for fertility to return after stopping", "Consider calcium/vitamin D intake and weight-bearing exercise for bone health with long-term use", "Irregular bleeding is common initially; many patients become amenorrheic over time", "Not a first-line long-term method if osteoporosis risk factors are present"], "sideEffects": ["Weight gain", "Irregular bleeding/amenorrhea", "Bone mineral density loss", "Headache", "Mood changes", "Delayed fertility return"]}, {"topic": "womens", "generic": "Conjugated estrogens ± medroxyprogesterone", "pronunciation": "KON-juh-gay-ted ES-truh-jenz / meh-DROKS-ee-proh-JES-tuh-rohn", "brand": ["Premarin", "Premplus"], "class": "Hormone replacement therapy (estrogen or combined)", "moa": "Mixture of estrogenic compounds derived from pregnant mare urine that binds estrogen receptors to relieve menopausal symptoms; combined product adds a progestin for endometrial protection.", "indication": "Moderate-to-severe vasomotor menopausal symptoms; vulvovaginal atrophy.", "dosage": "Conjugated estrogens 0.3–0.625 mg PO daily, ± medroxyprogesterone 2.5–5 mg daily or cyclically for endometrial protection if uterus intact", "examPoints": ["WHI trial (conjugated estrogen + MPA arm) showed increased breast cancer, stroke, VTE, and coronary events with long-term combined use", "Estrogen-alone arm (in hysterectomized women) showed no increased breast cancer risk, but increased stroke/VTE risk", "Premplus = continuous combined regimen; avoid unopposed conjugated estrogen if uterus is intact", "Oral route has higher VTE risk than transdermal estradiol", "Reassess need for HRT annually; not recommended for primary prevention of chronic disease"], "counselling": ["Take with or without food at the same time each day", "Report new breast lumps, abnormal vaginal bleeding, or leg swelling promptly", "Combined product protects the uterine lining if you still have a uterus", "Discuss annually with your prescriber whether continued therapy is still needed", "Non-hormonal options exist if you prefer to avoid systemic hormones"], "sideEffects": ["Bloating", "Breast tenderness", "Headache", "Nausea", "Increased breast cancer risk (combined, long-term)", "VTE/stroke risk"]}, {"topic": "womens", "generic": "Copper intrauterine device", "pronunciation": "KOP-er in-truh-YOO-ter-in dih-VYS", "brand": ["Paragard", "Nova-T", "Flexi-T"], "class": "Non-hormonal long-acting reversible contraceptive (LARC)", "moa": "Copper ions create a local inflammatory/spermicidal reaction in the uterine cavity that is toxic to sperm and ova, preventing fertilization.", "indication": "Long-term contraception (up to 10 years depending on device); most effective form of emergency contraception if inserted within 5 days of unprotected sex.", "dosage": "No systemic dosing — device inserted intrauterine, effective for 5–10 years depending on product", "examPoints": ["Most effective emergency contraception method available - <1% failure rate, effective up to 120h (5 days) post-coitus regardless of weight", "Hormone-free - safe in patients with estrogen/progestin contraindications and while breastfeeding", "Typically causes heavier, longer, more crampy periods - counsel proactively", "Increased risk of expulsion and perforation is highest at time of insertion and within the first year", "Not first-line if the patient has heavy menstrual bleeding, dysmenorrhea, or Wilson's disease"], "counselling": ["Expect heavier and crampier periods, especially in the first few months", "Check for the device's strings periodically to confirm it is still in place", "Seek care for severe pelvic pain, fever, or foul-smelling discharge (possible infection/expulsion)", "Provides no protection against STIs", "Can remain effective for up to 10 years depending on the specific device"], "sideEffects": ["Heavier/longer menses", "Dysmenorrhea", "Spotting between periods", "Expulsion", "Perforation (rare, mainly at insertion)", "Pelvic infection risk in first 20 days"]}, {"topic": "womens", "generic": "Levonorgestrel intrauterine system", "pronunciation": "lee-voh-nor-JES-trel in-truh-YOO-ter-in SIS-tem", "brand": ["Mirena", "Kyleena", "Jaydess"], "class": "Hormonal long-acting reversible contraceptive (LARC)", "moa": "Releases levonorgestrel locally into the uterine cavity, thickening cervical mucus and thinning the endometrium; minimal systemic absorption.", "indication": "Long-term contraception; also treats heavy menstrual bleeding (Mirena is Health Canada-approved for this).", "dosage": "No systemic dosing — device releases 6–20 mcg/day levonorgestrel locally, effective 3–8 years depending on product", "examPoints": ["Mirena approved for both contraception (up to 8 years) and heavy menstrual bleeding management", "Different devices have different durations and hormone doses (Mirena > Kyleena > Jaydess in levonorgestrel content)", "Often causes lighter periods or amenorrhea over time, unlike the copper IUD", "Very low systemic hormone levels - minimal effect on lipids, mood, or VTE risk compared to systemic hormonal methods", "Small increased risk of ectopic pregnancy IF pregnancy occurs despite the device (rare overall)"], "counselling": ["Expect irregular spotting for the first 3-6 months before periods lighten or stop", "Check for strings periodically; contact your provider if you can't feel them", "Seek care for severe pelvic pain or fever (possible infection or expulsion)", "Effective immediately if inserted during the first 7 days of your cycle, otherwise use backup for 7 days", "Fertility returns quickly after removal"], "sideEffects": ["Irregular spotting (early)", "Amenorrhea (later, often desired)", "Breast tenderness", "Acne", "Ovarian cysts", "Expulsion/perforation (uncommon)"]}, {"topic": "womens", "generic": "Folic acid (prenatal vitamin)", "pronunciation": "FOH-lik AS-id", "brand": ["Folic Acid", "Materna", "Pregvit"], "class": "B-vitamin supplement / neural tube defect prevention", "moa": "Essential cofactor for DNA synthesis and methylation reactions; adequate periconceptional levels reduce the incidence of neural tube defects during early fetal neural tube closure.", "indication": "Prevention of neural tube defects; routine prenatal supplementation.", "dosage": "0.4–1 mg PO daily preconception and throughout pregnancy; 4–5 mg/day if high risk of neural tube defect", "examPoints": ["Standard dose for average-risk pregnancy: 0.4-1 mg/day, started at least 2-3 months before conception through the first trimester", "High-risk dose (prior NTD-affected pregnancy, on antiepileptic drugs, diabetes, obesity, malabsorption): 4-5 mg/day", "Neural tube closes by ~28 days post-conception - supplementation must start BEFORE pregnancy is confirmed to be effective", "Antiepileptic drugs (valproate, carbamazepine) increase NTD risk and folate requirements", "Continue throughout pregnancy as part of a prenatal multivitamin"], "counselling": ["Start folic acid ideally 2-3 months before trying to conceive", "Continue taking it throughout pregnancy, not just early on", "Higher doses are needed if you've had a prior pregnancy affected by a neural tube defect or take certain seizure medications", "A prenatal multivitamin typically also provides iron, vitamin D, and other key nutrients", "Take with food if it causes nausea"], "sideEffects": ["Generally well tolerated", "Mild nausea", "Can mask vitamin B12 deficiency (rare at low doses)"]}, {"topic": "womens", "generic": "Labetalol", "pronunciation": "luh-BET-uh-lol", "brand": ["Trandate"], "class": "Combined alpha-1 and non-selective beta-blocker (antihypertensive)", "moa": "Blocks beta-1, beta-2, and alpha-1 adrenergic receptors, reducing peripheral vascular resistance and heart rate to lower blood pressure.", "indication": "First-line treatment of chronic hypertension and severe/acute hypertension in pregnancy, including preeclampsia.", "dosage": "100–200 mg PO BID–TID, titrate to max 2400 mg/day; IV 20 mg bolus then 20–80 mg q10min (hypertensive emergency in pregnancy)", "examPoints": ["First-line oral agent for chronic HTN in pregnancy along with methyldopa and nifedipine XL", "Also used IV for acute severe hypertension (BP >=160/110) in preeclampsia/eclampsia", "Treatment threshold in pregnancy: BP >=140/90 mmHg (lower target than general population, per SOGC guidance)", "Generally preferred over other beta-blockers (e.g., atenolol, associated with fetal growth restriction)", "Monitor for neonatal bradycardia/hypoglycemia if used near delivery"], "counselling": ["Take regularly as prescribed to control blood pressure throughout pregnancy", "Report dizziness, especially on standing, or unusually slow heart rate", "Do not stop abruptly - taper if discontinuation is needed", "Attend all prenatal visits for blood pressure and fetal growth monitoring", "Report severe headache, visual changes, or upper abdominal pain (possible preeclampsia signs)"], "sideEffects": ["Fatigue", "Dizziness", "Headache", "Bradycardia", "Scalp tingling (transient)", "Hypotension"]}, {"topic": "womens", "generic": "Methyldopa", "pronunciation": "meth-il-DOH-puh", "brand": ["Aldomet"], "class": "Centrally acting alpha-2 agonist (antihypertensive)", "moa": "Converted to alpha-methylnorepinephrine centrally, stimulating alpha-2 receptors in the brainstem to reduce sympathetic outflow and lower blood pressure.", "indication": "First-line chronic hypertension in pregnancy, favoured for its long-standing safety record.", "dosage": "250 mg PO BID–TID, titrate to usual 500 mg–2 g/day in divided doses; max 3 g/day; first-line for chronic HTN in pregnancy", "examPoints": ["Longest track record of fetal safety among antihypertensives - classic first-line choice in pregnancy", "Slower onset of action than labetalol or nifedipine, not used for acute severe hypertension", "Can cause maternal sedation/depression - may be less preferred if these are concerns", "Positive Coombs test can occur with chronic use (rarely causes hemolytic anemia)", "Often switched postpartum to another agent due to sedation and mood side effects"], "counselling": ["Take as directed, often 2-3 times daily", "May cause drowsiness, especially when starting - use caution with driving", "Report signs of depression or unusual fatigue to your provider", "Do not stop suddenly without medical advice", "Continue routine blood pressure monitoring at home if advised"], "sideEffects": ["Sedation/drowsiness", "Dry mouth", "Orthostatic hypotension", "Depression (uncommon)", "Positive Coombs test/hemolytic anemia (rare)"]}, {"topic": "womens", "generic": "Nifedipine (extended-release)", "pronunciation": "ny-FED-ih-peen", "brand": ["Adalat XL"], "class": "Dihydropyridine calcium channel blocker (antihypertensive)", "moa": "Blocks L-type calcium channels in vascular smooth muscle, causing arterial vasodilation and reducing blood pressure.", "indication": "First-line chronic hypertension in pregnancy; extended-release also used for tocolysis (off-label) and acute BP control.", "dosage": "30–60 mg PO once daily (XR), titrate to max 120 mg/day; used for HTN in pregnancy and tocolysis (immediate-release, off-label)", "examPoints": ["Use the extended-release (XL) formulation for chronic management - immediate-release sublingual/capsule form can cause a precipitous BP drop and reflex tachycardia (avoid)", "One of three standard first-line agents in pregnancy alongside labetalol and methyldopa", "Caution with concurrent magnesium sulfate (used for preeclampsia seizure prophylaxis) - risk of additive hypotension/neuromuscular blockade", "Also used off-label as a tocolytic to delay preterm labour", "Do not crush or chew the extended-release tablet"], "counselling": ["Swallow the extended-release tablet whole - do not crush, chew, or split it", "You may notice the empty tablet shell in your stool - this is normal for this formulation", "Report headache, flushing, or swelling of the ankles", "Take at the same time each day", "Do not use short-acting nifedipine for blood pressure control unless directed"], "sideEffects": ["Peripheral edema", "Headache", "Flushing", "Reflex tachycardia (more with IR form)", "Dizziness"]}, {"topic": "womens", "generic": "Fluconazole", "pronunciation": "floo-KOH-nuh-zohl", "brand": ["Diflucan"], "class": "Triazole antifungal", "moa": "Inhibits fungal cytochrome P450 (lanosterol 14-alpha-demethylase), blocking ergosterol synthesis and disrupting the fungal cell membrane.", "indication": "Uncomplicated vulvovaginal candidiasis (yeast infection).", "dosage": "150 mg PO single dose for vaginal candidiasis (avoid in pregnancy — teratogenic risk with repeated/high doses)", "examPoints": ["Standard uncomplicated regimen: single 150 mg oral dose", "Avoid in pregnancy - associated with increased risk of miscarriage and congenital malformations at higher/repeated doses; topical azoles preferred in pregnancy", "Significant CYP2C9/3A4 inhibitor - interacts with warfarin (increases INR), statins, and other CYP substrates", "Recurrent VVC (>=4 episodes/year) may require an extended induction-maintenance regimen", "Consider alternative diagnosis (BV, trichomoniasis) if symptoms don't resolve after treatment"], "counselling": ["One capsule by mouth is usually sufficient for a typical yeast infection", "Symptom relief may take a few days even after the dose", "Avoid if pregnant - ask your pharmacist about a topical alternative instead", "Tell your pharmacist about all medications - fluconazole interacts with several drugs including blood thinners", "See a doctor if this is your first yeast infection or if symptoms recur frequently"], "sideEffects": ["Headache", "Nausea/GI upset", "Abdominal pain", "Elevated liver enzymes (rare)", "QT prolongation (rare, high doses)"]}, {"topic": "womens", "generic": "Metronidazole", "pronunciation": "meh-troh-NY-duh-zohl", "brand": ["Flagyl", "Metrogel (vaginal)"], "class": "Nitroimidazole antibiotic", "moa": "Reduced within anaerobic organisms to reactive metabolites that damage microbial DNA, causing cell death.", "indication": "Bacterial vaginosis (BV) and trichomoniasis.", "dosage": "500 mg PO BID x7 days (BV/trichomoniasis); or 2 g single dose for trichomoniasis; safe in pregnancy after 1st trimester per guidelines", "examPoints": ["Standard oral BV regimen: 500 mg twice daily x 7 days (or vaginal gel 0.75% once daily x 5 days)", "Avoid alcohol during treatment and for 24-48 hours after (disulfiram-like reaction: flushing, nausea, tachycardia)", "Safe to use in pregnancy (all trimesters) for symptomatic BV per current guidance, despite older caution", "Trichomoniasis requires treating sexual partner(s) simultaneously even if asymptomatic", "Metallic taste and darkened urine are common but harmless"], "counselling": ["Avoid alcohol during treatment and for 1-2 days after finishing - it can cause severe nausea and flushing", "Complete the full course even if symptoms improve early", "A metallic taste in the mouth is common and not concerning", "If treating trichomoniasis, your partner needs treatment too, and you should abstain from sex until both are finished", "Vaginal gel: wash hands before/after application and use at bedtime for best retention"], "sideEffects": ["Metallic taste", "Nausea", "Headache", "Dark urine", "Disulfiram-like reaction with alcohol", "Peripheral neuropathy (rare, prolonged use)"]}, {"topic": "regs", "generic": "Oxycodone", "pronunciation": "oks-ee-KOH-dohn", "brand": ["OxyNEO", "Supeudol", "Percocet (combo)"], "class": "CDSA Schedule I Narcotic", "moa": "Full agonist at mu-opioid receptors in the CNS, producing analgesia by altering pain perception and emotional response to pain.", "indication": "Management of moderate-to-severe acute and chronic pain.", "dosage": "5–15 mg PO q4–6h PRN (immediate-release), titrated to effect; controlled substance (opioid)", "examPoints": ["CDSA Schedule I narcotic - no refills permitted; each fill requires a new prescription (verbal or written)", "Verbal/telephone orders for narcotics ARE permitted from a practitioner, but must be documented and, per provincial regulation, may require written follow-up", "Transfer of a narcotic prescription between pharmacies is generally NOT permitted (unlike most Schedule I NAPRA drugs)", "Faxed prescriptions for narcotics are typically not accepted as the original - original hard copy generally required before dispensing in most jurisdictions", "Loss or theft must be reported to Health Canada's Office of Controlled Substances and local authorities"], "counselling": ["Take exactly as prescribed - do not adjust the dose on your own", "Store securely away from others, especially children and visitors, given diversion/misuse risk", "Do not combine with alcohol or other CNS depressants (benzodiazepines) due to overdose/respiratory depression risk", "Do not drive until you know how this medication affects you", "Dispose of unused tablets through a pharmacy take-back program"], "sideEffects": ["Constipation", "Sedation/drowsiness", "Nausea", "Respiratory depression (serious, dose-dependent)", "Physical dependence/withdrawal on abrupt discontinuation", "Misuse/diversion potential"]}, {"topic": "regs", "generic": "Fentanyl (transdermal)", "pronunciation": "FEN-tuh-nil", "brand": ["Duragesic", "generic fentanyl patch"], "class": "CDSA Schedule I Narcotic", "moa": "Highly potent synthetic mu-opioid receptor agonist; transdermal patch provides continuous systemic absorption over 72 hours.", "indication": "Management of chronic, opioid-tolerant severe pain (NOT for opioid-naive patients or acute/intermittent pain).", "dosage": "12–100 mcg/hr patch q72h, opioid-tolerant patients only; Schedule/Controlled substance with strict diversion controls", "examPoints": ["Contraindicated in opioid-naive patients - reserved for patients already tolerant to a substantial daily opioid dose", "Many provinces mandate patch-for-patch return policy at the pharmacy to reduce diversion of used patches (residual fentanyl remains after use)", "Extreme potency - a major contributor to opioid-related overdose deaths; implicated heavily in the Canadian opioid crisis and illicit fentanyl contamination of the street drug supply", "Heat exposure (fever, hot baths, heating pads) increases absorption and overdose risk", "As a Schedule I narcotic: no refills, loss/theft reporting required, strict record-keeping"], "counselling": ["Apply to clean, dry, non-irritated skin and rotate sites; do not cut the patch", "Avoid heat sources (hot tubs, heating pads, saunas, fever) over the patch site - this increases drug release", "Fold used patches sticky-side together and return them to the pharmacy for safe disposal", "Never give this medication to anyone else - even a small dose can be fatal to someone who is not opioid-tolerant", "Keep naloxone accessible and make sure household members know how to use it"], "sideEffects": ["Respiratory depression (life-threatening)", "Sedation", "Constipation", "Nausea", "Application site reaction", "High overdose/diversion risk"]}, {"topic": "regs", "generic": "Codeine", "pronunciation": "KOH-deen", "brand": ["Tylenol No. 1/2/3", "generic codeine"], "class": "CDSA Schedule I Narcotic (low-dose combination products are Schedule II in some provinces)", "moa": "Prodrug metabolized by CYP2D6 to morphine, providing weak-to-moderate mu-opioid agonist analgesic and antitussive effects.", "indication": "Mild-to-moderate pain (usually in combination products); cough suppression.", "dosage": "30–60 mg PO q4–6h PRN; controlled substance, triplicate/monitored prescribing in most provinces", "examPoints": ["Prescription codeine products are CDSA Schedule I narcotics (no refills, standard narcotic controls)", "Low-dose codeine combination products (e.g., Tylenol No. 1, <=8 mg/dose) may be sold without a prescription as a Schedule II product in some provinces (pharmacist-only, logbook may be required) - varies by province", "CYP2D6 ultra-rapid metabolizers convert codeine to morphine faster, risking toxicity - contraindicated in breastfeeding mothers and children post-tonsillectomy due to case reports of infant/pediatric deaths", "Health Canada contraindicates codeine in children <12 years old", "Poor CYP2D6 metabolizers get little to no analgesic effect"], "counselling": ["Do not exceed the recommended dose - risk of both opioid and acetaminophen toxicity in combination products", "Avoid if breastfeeding without discussing with your pharmacist or physician", "Can cause drowsiness - avoid driving until you know how it affects you", "Avoid alcohol and other sedating medications", "Not recommended for children under 12"], "sideEffects": ["Constipation", "Drowsiness", "Nausea", "Respiratory depression (rare at low doses, but risk in ultra-rapid metabolizers)", "Dependence with prolonged use"]}, {"topic": "regs", "generic": "Tramadol", "pronunciation": "TRA-muh-dol", "brand": ["Ralivia", "Zytram XL", "generic tramadol"], "class": "CDSA Schedule I Narcotic (added October 2022)", "moa": "Weak mu-opioid receptor agonist plus inhibits serotonin and norepinephrine reuptake, giving a dual analgesic mechanism.", "indication": "Moderate pain management.", "dosage": "50–100 mg PO q4–6h PRN, max 400 mg/day; controlled substance in Canada as of 2022", "examPoints": ["Became a CDSA Schedule I controlled substance in Canada in October 2022 - previously unscheduled federally; classic recent-change exam point", "Now subject to full narcotic prescribing controls: no refills, loss/theft reporting, verbal order documentation", "Lowers seizure threshold - caution with other seizure-threshold-lowering drugs or seizure history", "Risk of serotonin syndrome when combined with SSRIs/SNRIs/MAOIs due to serotonergic activity", "CYP2D6 polymorphisms affect conversion to the active metabolite, altering efficacy/toxicity risk"], "counselling": ["Take exactly as prescribed - do not exceed the maximum daily dose", "Tell your pharmacist about all antidepressants you take due to serotonin syndrome risk", "May cause dizziness or drowsiness - use caution with driving", "Report any seizure activity to your prescriber immediately", "Do not stop abruptly after prolonged use - taper as directed"], "sideEffects": ["Nausea", "Dizziness", "Constipation", "Seizures (dose-dependent risk)", "Serotonin syndrome (with serotonergic drugs)", "Dependence/withdrawal"]}, {"topic": "regs", "generic": "Methadone", "pronunciation": "METH-uh-dohn", "brand": ["Metadol", "Metadol-D"], "class": "CDSA Schedule I Narcotic - Opioid Agonist Therapy (OAT)", "moa": "Long-acting full mu-opioid receptor agonist that prevents withdrawal and reduces cravings; also has NMDA receptor antagonist activity.", "indication": "Opioid use disorder (opioid agonist therapy) and chronic pain management (specialized use).", "dosage": "Opioid agonist therapy: individualized induction starting 10–30 mg PO daily, titrated slowly (max increase 5–10 mg q5days) to steady state; requires specially authorized prescriber", "examPoints": ["Requires a special federal exemption/authorization for prescribers (and historically for dispensing pharmacies) under the CDSA, in addition to provincial methadone maintenance program enrollment", "Long, variable half-life (~24-36h) creates significant overdose risk during initial titration - start low, go slow", "Typically dispensed as daily witnessed (observed) ingestion at the pharmacy, especially early in treatment, per provincial OAT program rules", "Carries QT-prolongation risk at higher doses - caution with other QT-prolonging drugs", "Significant CYP3A4 drug interactions (e.g., rifampin can precipitate withdrawal; some antivirals/antifungals can increase levels)"], "counselling": ["Take your dose exactly as directed by the program, typically once daily and witnessed at the pharmacy", "Do not use other opioids or sedatives (benzodiazepines, alcohol) without discussing with your care team - overdose risk", "It can take several days for the full effect of a dose change to be felt due to its long half-life", "Missing multiple consecutive doses can reduce your tolerance - contact your program before restarting", "Report irregular heartbeat, fainting, or palpitations promptly"], "sideEffects": ["Sedation", "Constipation", "Sweating", "QT prolongation", "Respiratory depression (especially during induction)", "Withdrawal if doses missed"]}, {"topic": "regs", "generic": "Buprenorphine / naloxone", "pronunciation": "byoo-preh-NOR-feen / nal-OKS-ohn", "brand": ["Suboxone", "Sublocade (extended-release injection)"], "class": "CDSA Schedule I Narcotic - Opioid Agonist Therapy (OAT)", "moa": "Buprenorphine is a partial mu-opioid agonist with a ceiling effect on respiratory depression; the combined naloxone deters injection misuse (precipitates withdrawal if injected) while having minimal effect sublingually.", "indication": "Opioid use disorder (first-line OAT in many Canadian guidelines due to safety profile).", "dosage": "Induction 2–4 mg SL on day 1 (after mild-moderate withdrawal), titrate to usual maintenance 12–24 mg/day (max 32 mg/day)", "examPoints": ["Often preferred first-line OAT over methadone due to lower overdose risk (ceiling effect) and less restrictive take-home rules once stabilized", "Requires induction after the patient is already in mild-moderate withdrawal to avoid precipitated withdrawal (high receptor affinity displaces other opioids)", "Naloxone component has poor sublingual bioavailability - only activates if the product is injected, deterring misuse", "Sublocade (long-acting SC injection) must be administered by a healthcare professional only - never self-administered, and requires prior stabilization on sublingual buprenorphine", "Prescriber generally needs an exemption/authorization depending on province; dispensing follows provincial OAT witnessed-dosing protocols similar to methadone"], "counselling": ["Allow the sublingual film/tablet to dissolve completely under the tongue - do not swallow it", "Do not take your dose until you're already feeling some withdrawal symptoms if starting fresh, per your prescriber's instructions", "Avoid alcohol and other sedatives", "Injecting this product will trigger withdrawal due to the naloxone component - it is meant to be taken sublingually", "Attend follow-up visits as required by your OAT program"], "sideEffects": ["Headache", "Nausea", "Constipation", "Precipitated withdrawal (if induced too early)", "Sedation (lower risk than full agonists)", "Injection site reactions (Sublocade)"]}, {"topic": "regs", "generic": "Naloxone", "pronunciation": "nal-OKS-ohn", "brand": ["Narcan (nasal spray)", "Naloxone HCl (injectable)"], "class": "NAPRA Schedule II - Opioid antagonist", "moa": "Competitively displaces opioids from mu-opioid receptors, rapidly reversing respiratory depression from opioid overdose.", "indication": "Emergency reversal of suspected opioid overdose.", "dosage": "0.4–2 mg IM/IN/IV, may repeat q2–3min PRN for opioid overdose; nasal spray 4 mg per spray", "examPoints": ["Schedule II - accessible without a prescription through pharmacist consultation (not self-selected off an open shelf)", "Widely available free through take-home naloxone (THN) programs across Canadian provinces", "Duration of action is shorter than most opioids (especially long-acting ones like methadone or fentanyl) - repeated dosing and EMS activation are essential", "No harm if given to someone without opioids in their system - appropriate to give when overdose is merely suspected", "Nasal spray formulation designed for lay bystander use without injection training"], "counselling": ["Call 911 immediately after giving naloxone, even if the person wakes up", "Give another dose after 2-3 minutes if there is no response", "The person needs medical observation afterward since naloxone can wear off before the opioid does, causing symptoms to return", "Keep the kit accessible and know the expiry date", "It's safe to give even if you're not certain the cause is an opioid overdose"], "sideEffects": ["Precipitated opioid withdrawal (agitation, pain, nausea) in opioid-dependent individuals", "No significant effect if opioids are not present"]}, {"topic": "regs", "generic": "Diazepam (benzodiazepines, class representative)", "pronunciation": "dy-AZ-eh-pam", "brand": ["Valium", "generic diazepam"], "class": "CDSA Schedule IV Controlled Substance", "moa": "Positive allosteric modulator at the GABA-A receptor, enhancing chloride influx and neuronal inhibition, producing anxiolytic, sedative, muscle-relaxant, and anticonvulsant effects.", "indication": "Anxiety, acute alcohol withdrawal, muscle spasm, seizure management.", "dosage": "2–10 mg PO BID–QID PRN (anxiety); controlled substance, taper needed after prolonged use to avoid withdrawal", "examPoints": ["CDSA Schedule IV - controlled but with less stringent rules than narcotics (e.g., refills ARE permitted if authorized by the prescriber, unlike Schedule I narcotics)", "Long half-life with active metabolites (desmethyldiazepam) - accumulation risk in elderly/hepatic impairment", "High risk of physical dependence and withdrawal (including seizures) with abrupt discontinuation after prolonged use", "Additive CNS/respiratory depression risk when combined with opioids - major factor in overdose deaths, prompting Health Canada warnings on co-prescribing", "Beers Criteria flags benzodiazepines as potentially inappropriate in older adults due to fall/fracture/cognitive impairment risk"], "counselling": ["Do not stop abruptly after regular use - your dose needs to be tapered gradually", "Avoid alcohol and other sedating medications, especially opioids", "May cause drowsiness or impaired coordination - use caution with driving", "Can be habit-forming - use only as prescribed and for the shortest necessary duration", "Store securely; misuse or sharing carries legal and safety risk"], "sideEffects": ["Sedation/drowsiness", "Cognitive impairment/confusion (especially in elderly)", "Ataxia/fall risk", "Dependence and withdrawal (including seizures)", "Respiratory depression (with opioids/alcohol)"]}, {"topic": "regs", "generic": "Zopiclone", "pronunciation": "ZOH-pih-klohn", "brand": ["Imovane", "generic zopiclone"], "class": "Targeted Substance (Food and Drug Regulations, Part G) - non-benzodiazepine sedative-hypnotic (\"Z-drug\")", "moa": "Binds a distinct site on the GABA-A receptor complex from benzodiazepines but produces similar GABAergic sedative-hypnotic effects.", "indication": "Short-term management of insomnia.", "dosage": "5–7.5 mg PO at bedtime; controlled substance (Schedule IV-like monitoring), short-term use recommended", "examPoints": ["Classified as a Targeted Substance under Part G of the Food and Drug Regulations rather than the CDSA - a common exam trap since it is controlled similarly to benzodiazepines but through a different legal instrument", "Recommended for short-term use only (typically <=7-10 days) due to tolerance and dependence risk", "Associated with a distinct bitter/metallic aftertaste", "Beers Criteria: avoid in older adults due to fall risk, similar to benzodiazepines", "Additive CNS depression with alcohol/opioids; Health Canada has issued warnings about next-day impairment (driving)"], "counselling": ["Take immediately before bed, only when you can get a full night's sleep (7-8 hours)", "Avoid driving or operating machinery the next morning until you know how it affects you", "A bitter or metallic taste afterward is common and expected", "Do not use for more than the short duration recommended by your prescriber", "Avoid alcohol while taking this medication"], "sideEffects": ["Bitter/metallic taste", "Drowsiness", "Dizziness", "Next-day impairment", "Dependence/rebound insomnia with prolonged use", "Complex sleep-related behaviours (rare)"]}, {"topic": "regs", "generic": "Methylphenidate", "pronunciation": "meth-il-FEN-ih-dayt", "brand": ["Ritalin", "Concerta", "Biphentin"], "class": "CDSA Schedule III Controlled Substance - CNS stimulant", "moa": "Blocks dopamine and norepinephrine reuptake transporters, increasing synaptic concentrations of these neurotransmitters to improve attention and reduce impulsivity/hyperactivity.", "indication": "Attention-deficit/hyperactivity disorder (ADHD); narcolepsy.", "dosage": "Start 5 mg PO BID (immediate-release) or 18 mg daily (extended-release), titrate weekly; usual range 20–60 mg/day; controlled substance (stimulant)", "examPoints": ["CDSA Schedule III - controlled substance but subject to somewhat different record-keeping than Schedule I narcotics", "High misuse/diversion potential, especially among students seeking cognitive enhancement - pharmacists should watch for early refill requests or dose escalation patterns", "Extended-release formulations (Concerta OROS, Biphentin) reduce misuse potential and once-daily dosing improves adherence vs. immediate-release", "Can cause growth suppression with long-term pediatric use - monitor height/weight", "Caution in cardiac conditions - can increase heart rate and blood pressure; baseline cardiac history/exam recommended before starting"], "counselling": ["Take in the morning to avoid interfering with sleep", "Extended-release capsules/tablets should generally be swallowed whole, not crushed or chewed", "Report appetite suppression or poor growth in children on long-term therapy", "Store securely - this medication has misuse and diversion potential", "Report heart palpitations, chest pain, or fainting immediately"], "sideEffects": ["Appetite suppression", "Insomnia", "Increased heart rate/blood pressure", "Growth suppression (pediatric, long-term)", "Irritability/mood changes", "Misuse/dependence potential"]}, {"topic": "regs", "generic": "Testosterone", "pronunciation": "tes-TOS-ter-ohn", "brand": ["Androgel", "Delatestryl", "Testim"], "class": "CDSA Schedule IV Controlled Substance - anabolic androgenic steroid", "moa": "Binds androgen receptors to promote male secondary sexual characteristics and anabolic (muscle-building) effects; exogenous administration suppresses endogenous LH/FSH via negative feedback.", "indication": "Testosterone replacement therapy for confirmed hypogonadism; gender-affirming hormone therapy.", "dosage": "IM: 50–100 mg weekly or 100–200 mg q2wk; transdermal gel 25–100 mg/day; controlled substance, monitored for misuse", "examPoints": ["CDSA Schedule IV due to anabolic steroid misuse potential (performance/physique enhancement) - controlled substance despite common therapeutic legitimate use", "Exogenous testosterone suppresses the HPG axis, causing reduced endogenous testosterone production and impaired fertility/testicular atrophy with prolonged non-therapeutic use", "Topical gel/formulations carry a risk of transference to others (children, partners) via skin contact - counsel on covering application site", "Monitor hematocrit (risk of polycythemia) and PSA in appropriate patients during therapy", "Diversion for non-medical bodybuilding/athletic use is a recognized regulatory concern"], "counselling": ["Apply gel to clean, dry skin as directed and allow it to dry fully before dressing to prevent transfer to others", "Avoid skin-to-skin contact with others at the application site for several hours", "Attend regular monitoring visits for blood counts and other labs", "Do not share this medication - it is a controlled substance with misuse potential", "Report unusual mood changes, aggression, or signs of excess red blood cell production"], "sideEffects": ["Acne", "Polycythemia (elevated hematocrit)", "Mood/behavioural changes", "Gynecomastia", "Reduced fertility/testicular atrophy (with suppression)", "Sleep apnea worsening"]}, {"topic": "regs", "generic": "Pseudoephedrine", "pronunciation": "soo-doh-eh-FED-rin", "brand": ["Sudafed", "generic pseudoephedrine"], "class": "NAPRA Schedule II - sympathomimetic decongestant / precursor chemical", "moa": "Indirect sympathomimetic that stimulates alpha-adrenergic receptors in nasal mucosa, causing vasoconstriction and decongestion; also a chemical precursor that can be illicitly converted to methamphetamine.", "indication": "Symptomatic relief of nasal/sinus congestion.", "dosage": "60 mg PO q4–6h PRN, max 240 mg/day; behind-the-counter due to methamphetamine precursor restrictions", "examPoints": ["NAPRA Schedule II - must be kept behind the counter/pharmacist-only area (not self-selected) due to precursor diversion risk for illicit methamphetamine production", "Subject to Health Canada's National Precursor Loss/Theft Reporting requirements and sales quantity/frequency monitoring in many pharmacies", "Contraindicated/used with caution in uncontrolled hypertension, cardiovascular disease, and with MAOIs (hypertensive crisis risk)", "Can cause CNS stimulation - avoid or use cautiously in insomnia-prone or anxious patients, and near bedtime", "Distinguish from phenylephrine (unscheduled, oral bioavailability debated as less effective) - a common exam comparison"], "counselling": ["Take during the day, as it can cause insomnia or jitteriness if taken close to bedtime", "Avoid if you have uncontrolled high blood pressure or heart disease without checking with your pharmacist first", "Photo ID may be required for purchase, and quantity sold may be limited per pharmacy policy", "Do not combine with other stimulant decongestants or MAOIs", "Use only for short-term symptom relief; see a doctor if congestion persists beyond a week"], "sideEffects": ["Insomnia", "Nervousness/jitteriness", "Increased heart rate/blood pressure", "Headache", "Palpitations (with overuse or cardiac sensitivity)"]}, {"topic": "regs", "generic": "Medical cannabis (dried cannabis / cannabis oil)", "pronunciation": "KAN-uh-bis", "brand": ["Various licensed producer products (not a single brand)"], "class": "Regulated under the Cannabis Act (2018) and Cannabis Regulations - not CDSA-scheduled for legal product", "moa": "THC acts as a partial agonist at CB1/CB2 cannabinoid receptors producing psychoactive, analgesic, and appetite-stimulating effects; CBD has minimal CB1 activity with anti-inflammatory/anxiolytic properties via other pathways.", "indication": "Chronic pain, chemotherapy-induced nausea/vomiting, spasticity (MS), appetite stimulation - typically after conventional therapies have failed.", "dosage": "Highly individualized; start low THC/CBD ratio at lowest effective dose, titrate slowly (\"start low, go slow\"); no standard dose — authorized under federal ACMPR/Cannabis Act framework", "examPoints": ["Legal cannabis is regulated federally under the Cannabis Act, separate from the CDSA - a key distinction from other controlled substances in this list", "Medical access requires a medical document (not technically a 'prescription') from an authorized healthcare practitioner, registering with a licensed producer or obtaining from a retail source", "Pharmacists in most provinces do NOT dispense dried cannabis directly through the standard retail/medical stream (distinct distribution model from other Rx drugs) - though this varies and is evolving", "Drug interaction and impairment counselling remains a pharmacist responsibility when patients disclose use, given CYP3A4/2C9 interactions and CNS/psychomotor effects", "Driving under the influence of cannabis is a criminal offence under the Criminal Code, separate from the product's regulatory status"], "counselling": ["Do not drive or operate machinery until you know how cannabis affects you", "Start with a low dose (\"start low, go slow\"), especially with edibles due to delayed onset", "Disclose cannabis use to all your healthcare providers due to potential drug interactions", "Store securely away from children and pets", "Effects and potency can vary significantly between products and THC:CBD ratios"], "sideEffects": ["Sedation", "Dizziness/impaired coordination", "Dry mouth", "Anxiety/paranoia (especially high-THC products)", "Tachycardia", "Dependence with chronic heavy use"]}, {"topic": "regs", "generic": "Natural health products (NHP) - general category", "pronunciation": "NAT-chuh-rul helth PROD-ukts", "brand": ["Products bearing an NPN or DIN-HM (e.g., various vitamins, herbal, homeopathic products)"], "class": "Regulated under the Natural Health Products Regulations (distinct from prescription/OTC drug regulation)", "moa": "Varies by product; regulatory rationale (not pharmacology) is the focus - products must demonstrate safety and provide evidence for claimed uses to receive market authorization.", "indication": "Varies widely - vitamins, minerals, herbal remedies, homeopathic preparations, probiotics, traditional medicines.", "dosage": "Not applicable — regulatory category (NPN-licensed products), not a single dosed drug; dosing varies by individual product label", "examPoints": ["Requires a Natural Product Number (NPN) or Homeopathic Medicine Number (DIN-HM) on the label to be legally sold in Canada, issued by Health Canada's Natural and Non-prescription Health Products Directorate (NNHPD)", "Evidentiary standard for licensing is lower than for prescription drugs - traditional use evidence can be sufficient, unlike drugs which require robust clinical trial data", "Pharmacists should still screen for drug-NHP interactions (e.g., St. John's Wort induces CYP3A4/P-gp, reducing efficacy of oral contraceptives, warfarin, many drugs)", "NHPs can still cause adverse effects and interact with prescription medications despite being widely perceived as \"natural = safe\"", "Adverse events involving NHPs are reportable to Canada Vigilance, similar to conventional drugs"], "counselling": ["Tell your pharmacist about all natural health products you take, not just prescription medications", "\"Natural\" does not always mean safe or free of drug interactions", "Look for the NPN or DIN-HM number on the label as a sign of Health Canada authorization", "Be cautious combining herbal products with prescription drugs (e.g., St. John's Wort with antidepressants or oral contraceptives)", "Report any unusual reactions to your pharmacist or Health Canada"], "sideEffects": ["Highly variable by product", "GI upset (common with many herbals)", "Drug interactions (e.g., St. John's Wort, ginkgo with anticoagulants)", "Allergic reactions", "Contamination/adulteration risk (quality control concerns)"]}, {"topic": "regs", "generic": "Gabapentin", "pronunciation": "GA-buh-PEN-tin", "brand": ["Neurontin", "generic gabapentin"], "class": "Not CDSA-scheduled federally, but a provincially monitored drug in several jurisdictions due to misuse potential", "moa": "Binds the alpha-2-delta subunit of voltage-gated calcium channels, reducing excitatory neurotransmitter release; structurally related to GABA but does not act directly on GABA receptors.", "indication": "Neuropathic pain, adjunct for partial seizures, off-label for anxiety/insomnia.", "dosage": "900–3600 mg/day PO in divided doses (TID); increasingly monitored/scheduled in some provinces due to misuse potential with opioids", "examPoints": ["Not a CDSA controlled substance federally, but several provinces (e.g., Nova Scotia, others) have added it to monitored/triplicate prescription programs due to rising misuse, particularly when combined with opioids", "Combined use with opioids significantly increases risk of respiratory depression - Health Canada has issued warnings on this interaction", "Dose must be adjusted for renal impairment - renally eliminated unchanged", "Increasingly reported as a drug of misuse/diversion, especially among patients with opioid use disorder seeking to potentiate euphoric effects", "Abrupt discontinuation after prolonged use can precipitate withdrawal symptoms and, rarely, seizures"], "counselling": ["Take as prescribed; do not stop abruptly without consulting your prescriber", "Avoid combining with opioids or alcohol without medical guidance - increased sedation/breathing risk", "May cause drowsiness or dizziness - use caution with driving until you know how it affects you", "Your dose may need to be adjusted if you have kidney problems", "Report worsening mood, suicidal thoughts, or unusual behaviour changes"], "sideEffects": ["Drowsiness/sedation", "Dizziness", "Peripheral edema", "Ataxia", "Respiratory depression (with opioids)", "Misuse/dependence potential (emerging concern)"]}, {"topic": "pk", "generic": "Phenytoin", "pronunciation": "FEN-ih-toyn", "brand": ["Dilantin"], "class": "Anticonvulsant (hydantoin)", "moa": "Blocks voltage-gated sodium channels, stabilizing neuronal membranes; exhibits nonlinear (zero-order/Michaelis-Menten) kinetics near therapeutic concentrations as metabolic enzymes saturate.", "indication": "Tonic-clonic and focal seizures; status epilepticus (IV/fosphenytoin).", "dosage": "Loading dose 15–20 mg/kg IV, maintenance 300–400 mg/day PO in divided doses; target level 40–80 µmol/L (10–20 mg/L), monitor free levels if hypoalbuminemic", "examPoints": ["Zero-order kinetics near therapeutic range — small dose increases can cause disproportionately large level rises", "Highly albumin-bound (~90%) — correct total level in hypoalbuminemia/renal failure (Sheiner-Tozer)", "Strong CYP3A4/2C9/2C19 inducer — reduces efficacy of warfarin, oral contraceptives, many drugs", "Therapeutic range ~10-20 mg/L total (free 1-2 mg/L); toxicity = nystagmus→ataxia→confusion continuum", "IV infusion max 50 mg/min (25 mg/min elderly) — propylene glycol vehicle risks hypotension/arrhythmia"], "counselling": ["Take consistently the same way each time; don't skip doses", "Report double vision, unsteadiness, slurred speech, or confusion right away", "Use back-up contraception — reduces birth control pill effectiveness", "Maintain good oral hygiene — gum overgrowth is a known effect", "Don't stop abruptly — seizure risk"], "sideEffects": ["Gingival hyperplasia", "Nystagmus/ataxia (toxicity)", "Hirsutism, coarsened features", "Rash (rare SJS/TEN)", "Drowsiness, cognitive slowing", "Osteoporosis (long-term)"]}, {"topic": "pk", "generic": "Digoxin", "pronunciation": "dih-JOKS-in", "brand": ["Toloxin"], "class": "Cardiac glycoside", "moa": "Inhibits Na+/K+-ATPase, raising intracellular calcium for positive inotropy, and increases vagal tone to slow AV conduction; large volume of distribution and P-glycoprotein substrate, eliminated largely unchanged renally.", "indication": "Heart failure (symptom control); rate control in atrial fibrillation.", "dosage": "0.125–0.25 mg PO daily; target trough (drawn ≥6h post-dose) 0.5–0.9 ng/mL for HF, up to 2.0 ng/mL historically for rate control", "examPoints": ["Therapeutic range 0.5-2.0 ng/mL (HF target lower, ~0.5-0.9 ng/mL)", "P-gp substrate — inhibitors (amiodarone, verapamil, clarithromycin) raise levels → toxicity", "Renally eliminated unchanged — reduce dose in renal impairment; hypokalemia/hypomagnesemia potentiate toxicity", "Large Vd — loading dose needed; draw levels ≥6-8h post-dose (after distribution phase)", "Toxicity: nausea/vomiting, yellow-green visual halos, arrhythmias (bradycardia, PVCs, heart block)"], "counselling": ["Check your pulse before dosing; hold and call if under 60 bpm", "Report nausea, vomiting, or vision changes (halos)", "Don't stop diuretics or other heart failure meds without discussing — electrolytes affect toxicity risk", "Stick with the same brand/formulation — bioavailability can vary"], "sideEffects": ["Nausea, vomiting, anorexia", "Visual disturbances (yellow-green halos)", "Arrhythmias (toxicity)", "Confusion (esp. elderly)", "Gynecomastia (long-term)"]}, {"topic": "pk", "generic": "Lithium", "pronunciation": "LITH-ee-um", "brand": ["Carbolith", "Duralith"], "class": "Mood stabilizer", "moa": "Mechanism not fully defined; modulates neurotransmission and second-messenger signaling. Handled renally like sodium — reabsorbed in the proximal tubule and competes with sodium for reabsorption.", "indication": "Bipolar disorder — acute mania and maintenance.", "dosage": "Start 300 mg PO BID–TID, titrate to trough level (12h post-dose) 0.6–1.2 mmol/L; narrow therapeutic index requires regular monitoring", "examPoints": ["Narrow TI — therapeutic range 0.6-1.2 mmol/L (maintenance); trough drawn 12h post-dose", "Sodium depletion (dehydration, diuretics, low-salt diet) increases reabsorption → toxicity", "NSAIDs, ACEI/ARBs, thiazides raise lithium levels via reduced renal clearance", "Toxicity: coarse tremor, ataxia, confusion, seizures; chronic use → nephrogenic diabetes insipidus, hypothyroidism", "Requires baseline/periodic renal and thyroid monitoring"], "counselling": ["Keep fluid and salt intake consistent — don't start a low-salt diet or lose fluids without adjusting monitoring", "Report worsening tremor, vomiting, diarrhea, confusion, or excess thirst/urination", "Avoid NSAIDs; check with pharmacist before any new OTC medication", "Regular blood level, kidney, and thyroid checks are essential"], "sideEffects": ["Fine tremor (common)", "Polyuria/polydipsia", "Hypothyroidism/goiter", "GI upset, weight gain", "Coarse tremor, ataxia, confusion (toxicity)", "Seizures, arrhythmias (severe toxicity)"]}, {"topic": "pk", "generic": "Vancomycin", "pronunciation": "van-koh-MY-sin", "brand": ["Vancocin"], "class": "Glycopeptide antibiotic", "moa": "Inhibits bacterial cell wall synthesis by binding the D-Ala-D-Ala terminus of peptidoglycan precursors; renally eliminated with efficacy driven by the AUC24/MIC ratio.", "indication": "Serious gram-positive infections (MRSA); oral form for C. difficile colitis.", "dosage": "15–20 mg/kg IV q8–12h; target AUC24/MIC 400–600 (or trough 15–20 mg/L for serious infections)", "examPoints": ["Dosing target is AUC24/MIC ≥400 (current guideline emphasis over trough-only)", "Trough target (if used) typically 15-20 mg/L for serious infections", "Nephrotoxicity risk rises with troughs >20 or concomitant nephrotoxins", "'Red man syndrome' from rapid infusion is histamine-mediated, not a true allergy — slow infusion prevents it", "Oral vancomycin is not systemically absorbed — effective only for C. diff within the GI lumen"], "counselling": ["IV infusion is given slowly to reduce flushing/itching", "Report ringing in the ears or hearing changes", "Complete the full course even if feeling better", "Report decreased urination"], "sideEffects": ["Red man syndrome (infusion reaction)", "Nephrotoxicity", "Ototoxicity (rare)", "Phlebitis at infusion site", "Neutropenia (prolonged use)"]}, {"topic": "pk", "generic": "Gentamicin", "pronunciation": "jen-tuh-MY-sin", "brand": ["Garamycin"], "class": "Aminoglycoside antibiotic", "moa": "Binds the bacterial 30S ribosomal subunit, causing mRNA misreading and inhibiting protein synthesis; bactericidal with concentration-dependent killing and a post-antibiotic effect.", "indication": "Serious gram-negative infections; synergy with beta-lactams for enterococcal/streptococcal endocarditis.", "dosage": "Traditional: 1–2.5 mg/kg IV q8h; extended-interval (once-daily) 5–7 mg/kg IV q24h, dosed by peak/trough or nomogram", "examPoints": ["Concentration-dependent killing supports extended-interval (once-daily) dosing", "Narrow TI — nephrotoxicity and ototoxicity are dose/duration related and can be irreversible", "Peak reflects efficacy; trough reflects toxicity risk (undetectable trough desired with extended-interval dosing)", "Hydrophilic — Vd rises in edema/ascites/sepsis, requiring dose adjustment", "Renally eliminated — adjust for renal function; monitor SCr regularly"], "counselling": ["Report hearing changes, ringing in the ears, dizziness, or vertigo", "Report decreased urine output", "Blood levels and kidney function will be monitored during treatment", "Given by injection/infusion, typically for short hospital courses"], "sideEffects": ["Nephrotoxicity (usually reversible)", "Ototoxicity — auditory and vestibular (can be irreversible)", "Neuromuscular blockade (rare, high doses)", "Rash"]}, {"topic": "pk", "generic": "Theophylline", "pronunciation": "thee-OFF-ih-lin", "brand": ["Uniphyl"], "class": "Methylxanthine bronchodilator", "moa": "Nonselective phosphodiesterase inhibitor raising cAMP to cause bronchodilation, with adenosine receptor antagonism; metabolized by CYP1A2 with high interpatient variability.", "indication": "Asthma/COPD adjunct (less commonly used now).", "dosage": "Start 300–400 mg/day PO in divided doses, titrate to target level 55–110 µmol/L (10–20 mcg/mL); narrow therapeutic index, many drug interactions", "examPoints": ["Narrow TI — therapeutic range 10-20 mcg/mL (some target 5-15 to reduce toxicity)", "CYP1A2 substrate — smoking induces metabolism (lowers levels); cessation raises levels", "Inhibited by ciprofloxacin, cimetidine, clarithromycin → toxicity risk", "Toxicity: nausea, tremor, tachycardia, seizures (can occur without warning)", "Methylxanthine class shares caffeine-like stimulant effects"], "counselling": ["Take consistently with regard to meals as directed", "Report nausea, vomiting, tremor, rapid heartbeat, or palpitations", "Tell your prescriber before starting or stopping smoking — affects dose needs", "Limit caffeine — additive stimulant effects"], "sideEffects": ["Nausea, vomiting, GI upset", "Tremor, insomnia, nervousness", "Tachycardia, palpitations, arrhythmias", "Seizures (can be first sign of toxicity)", "Headache"]}, {"topic": "pk", "generic": "Warfarin", "pronunciation": "WOR-fuh-rin", "brand": ["Coumadin"], "class": "Vitamin K antagonist anticoagulant", "moa": "Inhibits VKORC1, blocking vitamin K regeneration and reducing synthesis of clotting factors II, VII, IX, X; the more potent S-enantiomer is metabolized predominantly by CYP2C9, and the drug is ~99% protein-bound.", "indication": "VTE treatment/prevention; stroke prevention in atrial fibrillation; mechanical heart valves.", "dosage": "Individualized to target INR 2–3 (or 2.5–3.5 for mechanical valves); typical maintenance 1–10 mg/day", "examPoints": ["CYP2C9 poor metabolizers and VKORC1 variants need lower doses — pharmacogenomic algorithms exist", "Highly protein-bound — displacement interactions transiently raise free fraction", "Onset delayed 3-5 days, reflecting half-lives of existing clotting factors (factor II ~60h)", "Narrow TI monitored via INR; target usually 2-3 (2.5-3.5 for mechanical mitral valves)", "Numerous CYP2C9/1A2/3A4 interactions raise or lower INR"], "counselling": ["Keep vitamin K (leafy green) intake consistent, don't drastically change it", "Regular INR monitoring, especially with diet or medication changes", "Report unusual bruising, bleeding gums, or blood in urine/stool", "Tell every prescriber, dentist, and pharmacist you're on warfarin before any new medication", "Avoid excess alcohol"], "sideEffects": ["Bleeding/bruising", "Skin necrosis (rare)", "Purple toe syndrome (rare)", "Alopecia (long-term)"]}, {"topic": "pk", "generic": "Cyclosporine", "pronunciation": "sy-kloh-SPOR-een", "brand": ["Neoral", "Sandimmune"], "class": "Calcineurin inhibitor immunosuppressant", "moa": "Binds cyclophilin, inhibiting calcineurin and blocking IL-2 transcription to suppress T-cell activation; narrow TI with variable oral bioavailability and extensive CYP3A4/P-glycoprotein metabolism/transport.", "indication": "Transplant rejection prophylaxis; severe psoriasis/RA (select cases).", "dosage": "Individualized by indication/trough level (transplant: trough 100–400 ng/mL depending on time post-transplant); typically 2–15 mg/kg/day divided BID", "examPoints": ["Narrow TI — trough (C0) or 2h post-dose (C2) levels monitored per protocol", "Major CYP3A4/P-gp substrate — grapefruit juice raises levels; rifampin/St. John's Wort lower levels", "Neoral and Sandimmune are not interchangeable without monitoring — different bioavailability", "Nephrotoxic — monitor renal function, potassium, magnesium", "Extensive bidirectional drug interaction potential"], "counselling": ["Take at a consistent time relative to meals every day; don't switch brands without telling your prescriber", "Avoid grapefruit and grapefruit juice", "Report decreased urination, swelling, or high blood pressure readings", "Report tremor or gum swelling", "Avoid live vaccines and limit infection exposure"], "sideEffects": ["Nephrotoxicity", "Hypertension", "Tremor", "Gingival hyperplasia", "Hirsutism", "Increased infection/malignancy risk"]}, {"topic": "pk", "generic": "Tacrolimus", "pronunciation": "tak-ROH-lih-mus", "brand": ["Prograf", "Advagraf"], "class": "Calcineurin inhibitor immunosuppressant", "moa": "Binds FKBP-12, inhibiting calcineurin and blocking IL-2 gene transcription to suppress T-cell activation; more potent than cyclosporine, and a CYP3A4/P-gp substrate with a narrow therapeutic index.", "indication": "Solid organ transplant rejection prophylaxis.", "dosage": "Individualized by trough level (transplant: 5–15 ng/mL depending on time post-transplant); typically 0.1–0.2 mg/kg/day divided BID", "examPoints": ["Narrow TI — trough levels monitored (target varies by organ/time post-transplant, e.g. 5-15 ng/mL)", "CYP3A4 substrate — azoles/macrolides raise levels significantly; rifampin lowers levels", "Immediate-release and extended-release (Advagraf) are not interchangeable", "Nephrotoxic and diabetogenic — monitor renal function and glucose", "High inter- and intrapatient variability requires ongoing TDM"], "counselling": ["Take consistently at the same time each day relative to food (empty stomach preferred)", "Avoid grapefruit juice", "Report tremor, headache, or high blood sugar symptoms (thirst, frequent urination)", "Report signs of infection promptly", "Don't switch brands/formulations without prescriber approval"], "sideEffects": ["Nephrotoxicity", "Neurotoxicity (tremor, headache)", "New-onset diabetes after transplant", "Hypertension", "Hyperkalemia", "Increased infection risk"]}, {"topic": "pk", "generic": "Clopidogrel", "pronunciation": "kloh-PID-oh-grel", "brand": ["Plavix"], "class": "Antiplatelet (P2Y12 inhibitor), prodrug", "moa": "A prodrug activated mainly by hepatic CYP2C19 to a metabolite that irreversibly inhibits the platelet P2Y12 ADP receptor, blocking aggregation.", "indication": "Acute coronary syndrome, PCI/stent placement, secondary stroke/MI prevention.", "dosage": "75 mg PO daily; loading 300–600 mg; CYP2C19 poor metabolizers may have reduced efficacy (pharmacogenomic consideration)", "examPoints": ["Prodrug — CYP2C19 poor metabolizers get less active drug, raising stent thrombosis/recurrent event risk", "CYP2C19 inhibitors (omeprazole, esomeprazole) may reduce activation — pantoprazole preferred if a PPI is needed", "Irreversible platelet inhibition — effect lasts the platelet lifespan (~7-10 days); hold before elective surgery", "Genotype testing available for poor metabolizer status in select high-risk patients", "Full antiplatelet effect is delayed without a loading dose"], "counselling": ["Report unusual bleeding or bruising", "Tell all providers, including dentists, before procedures", "Don't stop abruptly without discussing with your cardiologist, especially after a stent", "Take with or without food consistently"], "sideEffects": ["Bleeding/bruising", "GI upset, dyspepsia", "Rash", "Thrombotic thrombocytopenic purpura (rare)"]}, {"topic": "pk", "generic": "Codeine", "pronunciation": "KOH-deen", "brand": ["generic; combination products"], "class": "Opioid analgesic, prodrug", "moa": "A prodrug metabolized by CYP2D6 to morphine, the active metabolite responsible for most analgesia; CYP2D6 activity varies widely by genotype.", "indication": "Mild-moderate pain; antitussive at lower doses.", "dosage": "30–60 mg PO q4–6h PRN; efficacy/toxicity depend on CYP2D6 phenotype (poor metabolizers get no analgesia, ultra-rapid get toxicity)", "examPoints": ["CYP2D6 ultrarapid metabolizers convert more codeine to morphine faster → toxicity risk (contraindicated in breastfeeding — infant deaths reported)", "CYP2D6 poor metabolizers get little analgesic benefit", "Not recommended under age 12 and avoided in breastfeeding due to unpredictable morphine exposure", "CYP2D6 inhibitors (some SSRIs) can blunt analgesic effect", "Adds to overall opioid/CNS depressant burden — respiratory depression risk stacks"], "counselling": ["Don't exceed the prescribed dose — effect varies widely between people", "Avoid alcohol and other sedating medications", "Report excessive drowsiness or slow/shallow breathing", "Not recommended for children or breastfeeding mothers", "Consider a stool softener with regular use — constipation is common"], "sideEffects": ["Constipation", "Nausea, sedation", "Respiratory depression (esp. ultrarapid metabolizers)", "Dependence/tolerance with prolonged use", "Itching"]}, {"topic": "pk", "generic": "Carbamazepine", "pronunciation": "kar-buh-MAZ-eh-peen", "brand": ["Tegretol"], "class": "Anticonvulsant (iminostilbene)", "moa": "Blocks voltage-gated sodium channels to stabilize neuronal membranes, and potently induces its own metabolism (autoinduction) via CYP3A4 over the first weeks of therapy.", "indication": "Focal/generalized seizures; trigeminal neuralgia; bipolar disorder (adjunct).", "dosage": "Start 100–200 mg PO BID, titrate to target level 17–50 µmol/L (4–12 mcg/mL); autoinduces its own metabolism over 3–5 weeks", "examPoints": ["Autoinduction — clearance rises over 2-4 weeks, requiring dose increases/level rechecks early in therapy", "Strong CYP3A4/1A2/2C9 inducer — reduces efficacy of oral contraceptives, warfarin, many drugs", "HLA-B*1502 (Asian ancestry) and HLA-A*3101 linked to SJS/TEN — screening recommended in at-risk populations", "Therapeutic range roughly 4-12 mg/L", "Can cause SIADH/hyponatremia — monitor sodium"], "counselling": ["Report fever, mouth sores, rash, sore throat, or bruising", "Use back-up contraception — reduces oral contraceptive effectiveness", "Levels may need rechecking in the first weeks as dose requirements can rise", "Report severe rash immediately"], "sideEffects": ["Drowsiness, dizziness, diplopia", "Rash (rare SJS/TEN)", "Hyponatremia (SIADH)", "Aplastic anemia/agranulocytosis (rare)", "Nausea"]}, {"topic": "pk", "generic": "Valproic Acid", "pronunciation": "val-PROH-ik AS-id", "brand": ["Depakene", "Epival"], "class": "Anticonvulsant", "moa": "Increases GABA availability and blocks voltage-gated sodium channels; highly protein-bound with saturable binding at higher concentrations, so free fraction rises disproportionately.", "indication": "Generalized seizures; bipolar disorder; migraine prophylaxis.", "dosage": "10–15 mg/kg/day PO divided, titrate to target level 350–700 µmol/L (50–100 mcg/mL)", "examPoints": ["Highly protein-bound (~90%) but binding saturates at higher totals — total level can underestimate free drug/effect", "Therapeutic range roughly 50-100 mg/L (total)", "Hepatotoxicity and pancreatitis risk — baseline/periodic LFTs", "Strongest anticonvulsant teratogen (neural tube defects) — avoid in pregnancy/childbearing potential unless essential", "Inhibits metabolism of other drugs (e.g., lamotrigine) — dose adjustments needed in combination"], "counselling": ["Report yellowing of skin/eyes, abdominal pain, or unusual bleeding/bruising", "Effective contraception is essential if of childbearing potential", "Don't stop abruptly — seizure risk", "Take with food to reduce GI upset"], "sideEffects": ["GI upset, nausea", "Weight gain", "Tremor", "Hepatotoxicity", "Pancreatitis (rare)", "Thrombocytopenia"]}, {"topic": "pk", "generic": "Methotrexate", "pronunciation": "meth-oh-TREKS-ayt", "brand": ["generic"], "class": "Antimetabolite / DMARD", "moa": "Inhibits dihydrofolate reductase, blocking folate-dependent purine/pyrimidine synthesis; primarily renally eliminated and sequesters in third-space fluid (ascites, pleural effusion), prolonging exposure.", "indication": "Rheumatoid arthritis, psoriasis (low-dose weekly); certain cancers/ectopic pregnancy at high dose (different regimen).", "dosage": "Low-dose (RA/psoriasis): 7.5–25 mg PO/SC once weekly. High-dose oncology requires leucovorin rescue and level monitoring to ensure clearance", "examPoints": ["RA dosing is WEEKLY, not daily — fatal errors have occurred from daily dosing mix-ups", "Third-spacing (ascites/effusions) delays elimination and raises toxicity risk", "Renally eliminated — reduced clearance in renal impairment increases toxicity", "Folic acid supplementation reduces GI/hepatic side effects without reducing RA-dose efficacy", "NSAIDs and other renally cleared/protein-bound drugs can raise methotrexate levels/toxicity"], "counselling": ["Confirm this is a WEEKLY dose, not daily — double-check with your pharmacist", "Take folic acid supplement as directed", "Report mouth sores, unusual bruising/bleeding, shortness of breath, or yellowing skin", "Avoid alcohol — increases liver toxicity risk", "Effective contraception is required — teratogenic"], "sideEffects": ["Mucositis/mouth sores", "GI upset, nausea", "Hepatotoxicity", "Myelosuppression", "Pulmonary toxicity (pneumonitis)", "Nephrotoxicity (high-dose)"]}, {"topic": "pk", "generic": "Omeprazole", "pronunciation": "oh-MEP-ruh-zohl", "brand": ["Losec"], "class": "Proton pump inhibitor", "moa": "Irreversibly inhibits the gastric H+/K+-ATPase (proton pump) in parietal cells, suppressing acid secretion; metabolized predominantly by CYP2C19, which shows significant genetic polymorphism affecting exposure.", "indication": "GERD, peptic ulcer disease, H. pylori eradication (combination), NSAID ulcer prevention.", "dosage": "20–40 mg PO once daily; CYP2C19 polymorphisms affect metabolism/efficacy, especially relevant with clopidogrel co-administration", "examPoints": ["CYP2C19 poor metabolizers have higher exposure — may need lower doses; higher H. pylori cure rates", "CYP2C19 ultrarapid metabolizers may have inadequate acid suppression at standard doses", "Omeprazole/esomeprazole inhibit CYP2C19 — can reduce clopidogrel activation; pantoprazole preferred if a PPI is needed with clopidogrel", "Best taken 30-60 min before a meal, when proton pumps are actively secreting", "Long-term use linked to reduced Mg/B12 absorption, fracture risk, and C. difficile risk"], "counselling": ["Take 30-60 minutes before a meal for best effect", "Don't crush or chew delayed-release capsules", "Report muscle cramps/spasms (possible low magnesium with long-term use)", "Use the lowest effective dose for the shortest duration when possible", "Report persistent diarrhea"], "sideEffects": ["Headache", "GI upset (diarrhea, nausea)", "Hypomagnesemia (long-term)", "B12 deficiency (long-term)", "Increased fracture risk (long-term)", "C. difficile infection risk"]}, {"topic": "inter", "generic": "Warfarin", "pronunciation": "WOR-fuh-rin", "brand": ["Coumadin"], "class": "Vitamin K antagonist anticoagulant — interaction hub", "moa": "Metabolized mainly by CYP2C9 (minor CYP1A2/3A4) and highly protein-bound; numerous drugs alter INR by enzyme inhibition/induction, protein-binding displacement, or by adding pharmacodynamic bleeding risk.", "indication": "Anticoagulation for atrial fibrillation, VTE, mechanical heart valves.", "dosage": "Individualized to INR target 2–3; numerous interactions (CYP2C9/VKORC1-mediated) alter dose requirements significantly", "examPoints": ["CYP2C9 inhibitors (amiodarone, fluconazole, metronidazole, TMP-SMX) increase INR/bleeding risk", "CYP inducers (rifampin, carbamazepine, St. John's Wort) decrease INR/efficacy", "Broad-spectrum antibiotics increase INR by killing gut flora that produce vitamin K", "Pharmacodynamic interactions: NSAIDs/ASA/clopidogrel raise bleeding risk without changing INR", "Regular acetaminophen use can also raise INR — not a benign combination"], "counselling": ["Tell every prescriber and pharmacist you take warfarin before any new medication, herbal, or supplement", "Report any unusual bruising or bleeding", "Get INR checked after starting or stopping any new medication", "Avoid NSAIDs for pain; use acetaminophen cautiously and inform your prescriber"], "sideEffects": ["Bleeding (interaction context)", "Bruising", "Elevated INR (supratherapeutic)", "Subtherapeutic INR/clot risk (with inducers)"]}, {"topic": "inter", "generic": "Amiodarone", "pronunciation": "uh-MEE-oh-duh-rohn", "brand": ["Cordarone"], "class": "Class III antiarrhythmic", "moa": "Potent inhibitor of CYP3A4, CYP2C9, CYP2D6, and P-glycoprotein, with a very long half-life (weeks) so interactions can persist long after discontinuation.", "indication": "Ventricular and atrial arrhythmias (AFib rhythm control).", "dosage": "Maintenance 100–400 mg/day PO; potent CYP3A4/2C9/2D6 inhibitor — reduce warfarin/digoxin doses ~30-50% when co-administered", "examPoints": ["Inhibits P-gp — roughly doubles digoxin levels; digoxin dose typically halved when starting amiodarone", "Inhibits CYP2C9 — significantly increases warfarin effect; warfarin dose often reduced ~30-50%", "Inhibits CYP3A4 — raises statin levels (simvastatin capped at 20mg with amiodarone)", "Extremely long half-life (~58 days) — interactions/toxicity can persist long after stopping", "Prolongs QT — additive risk with other QT-prolonging drugs"], "counselling": ["Report new medications to your prescriber — amiodarone affects other drug levels long-term", "Regular thyroid, liver, and lung function monitoring is needed with long-term use", "Use sun protection — photosensitivity is common", "Report shortness of breath, cough, or vision changes"], "sideEffects": ["Photosensitivity/blue-grey skin discoloration", "Thyroid dysfunction", "Pulmonary toxicity/fibrosis", "Hepatotoxicity", "Corneal microdeposits", "QT prolongation"]}, {"topic": "inter", "generic": "Clarithromycin", "pronunciation": "kluh-RITH-roh-MY-sin", "brand": ["Biaxin"], "class": "Macrolide antibiotic", "moa": "Potent CYP3A4 (and P-gp) inhibitor that raises concentrations of many co-administered drugs, and directly prolongs the QT interval.", "indication": "Respiratory tract infections; H. pylori eradication (triple therapy).", "dosage": "250–500 mg PO q12h; strong CYP3A4 inhibitor — avoid with statins metabolized by 3A4 (simvastatin, lovastatin) and many other substrates", "examPoints": ["Strong CYP3A4 inhibitor — contraindicated with simvastatin/lovastatin (rhabdomyolysis risk)", "Raises colchicine levels — fatal toxicity reported in renal impairment; combination contraindicated", "Additive QT prolongation with other QT-prolonging drugs (antipsychotics, other macrolides, antiarrhythmics)", "Raises carbamazepine, cyclosporine, tacrolimus levels via CYP3A4 inhibition", "Azithromycin has minimal CYP3A4 inhibition — often preferred when interaction risk is a concern"], "counselling": ["Tell your pharmacist about all current medications, especially statins", "Report muscle pain or weakness", "Report irregular heartbeat, palpitations, or fainting", "Complete the full course as prescribed"], "sideEffects": ["GI upset (nausea, diarrhea, metallic taste)", "QT prolongation", "Hepatotoxicity (rare)", "Drug interaction-related toxicity (statin, colchicine)"]}, {"topic": "inter", "generic": "Rifampin", "pronunciation": "RIF-am-pin", "brand": ["Rofact"], "class": "Antimycobacterial (rifamycin)", "moa": "Potent inducer of CYP3A4, CYP2C9, CYP2C19, and P-glycoprotein, increasing the metabolism/clearance of many co-administered drugs, typically within 1-2 weeks.", "indication": "Tuberculosis (combination therapy); select prophylaxis (meningococcal contacts).", "dosage": "600 mg PO/IV once daily (TB treatment); potent CYP450 inducer — reduces efficacy of oral contraceptives, warfarin, many other drugs substantially", "examPoints": ["Reduces oral contraceptive efficacy — breakthrough bleeding/failure reported; use backup contraception", "Substantially reduces warfarin effect — INR can drop, requiring dose increases", "Reduces cyclosporine/tacrolimus levels — transplant rejection risk if not adjusted", "Induction takes ~1-2 weeks to develop and ~2 weeks to resolve after stopping", "Causes harmless red-orange discoloration of body fluids — can stain soft contact lenses"], "counselling": ["Urine, sweat, and tears may turn red-orange — this is harmless", "Use additional/backup contraception", "Soft contact lenses may become permanently stained — avoid wearing during therapy", "Tell all prescribers you're taking this — it affects many other drugs", "Take on an empty stomach for best absorption if directed"], "sideEffects": ["Red-orange body fluid discoloration", "GI upset", "Hepatotoxicity", "Flu-like reaction (intermittent dosing)", "Rash"]}, {"topic": "inter", "generic": "St. John's Wort", "pronunciation": "saynt JONZ wert", "brand": ["natural health product"], "class": "Herbal supplement (antidepressant-like)", "moa": "Induces CYP3A4, CYP1A2, CYP2C9, and P-glycoprotein, and has serotonergic activity that adds pharmacodynamic interaction risk.", "indication": "Self-treatment for mild depression (OTC/herbal use).", "dosage": "300 mg PO TID (standardized extract) typical OTC dose; potent CYP3A4/P-gp inducer — reduces levels of OCPs, warfarin, cyclosporine, many drugs", "examPoints": ["Induces CYP3A4/P-gp — reduces cyclosporine, tacrolimus (transplant rejection reported), oral contraceptive, and warfarin levels", "Serotonergic activity — risk of serotonin syndrome with SSRIs/SNRIs/other serotonergic drugs", "Reduces oral contraceptive efficacy — breakthrough bleeding and pregnancy reported", "Patients often don't disclose it as a 'natural' product — ask specifically", "Induction/de-induction timeline similar to other CYP inducers (~1-2 weeks)"], "counselling": ["Tell your pharmacist or doctor if you're taking this — it interacts with many prescription drugs", "Don't combine with prescription antidepressants without medical advice", "Use backup contraception if on oral contraceptives", "Discuss before starting if on transplant or anticoagulant medication"], "sideEffects": ["GI upset", "Photosensitivity", "Serotonin syndrome (in combination)", "Reduced efficacy of interacting medications"]}, {"topic": "inter", "generic": "Grapefruit Juice", "pronunciation": "GRAYP-froot joos", "brand": ["N/A — dietary interaction"], "class": "Food-drug interaction (intestinal CYP3A4 inhibitor)", "moa": "Furanocoumarins irreversibly inhibit intestinal (not hepatic) CYP3A4, reducing first-pass metabolism and raising bioavailability of susceptible oral CYP3A4 substrates; a single glass can affect levels for 24-72 hours.", "indication": "N/A — dietary counselling point.", "dosage": "Not a dosed drug — intestinal CYP3A4 inhibitor; even a single glass can significantly increase levels of many CYP3A4 substrates (e.g., some statins, CCBs)", "examPoints": ["Inhibits intestinal CYP3A4 only, not hepatic — mainly affects drugs with high first-pass metabolism", "A single glass can affect levels for 24-72 hours — timing separation doesn't reliably prevent it", "Classic affected drugs: some statins (simvastatin, atorvastatin, lovastatin), CCBs (felodipine, nifedipine), cyclosporine, some benzodiazepines", "Pravastatin, rosuvastatin, and fluvastatin are NOT significantly affected — safer alternatives", "Effect varies between individuals and products (juice vs whole fruit vs citrus type)"], "counselling": ["Avoid grapefruit and grapefruit juice if taking an affected medication", "Timing doesn't reliably help — the effect can last days after one serving", "Ask your pharmacist if your specific medication is affected before assuming it's safe", "Consider an alternative citrus (e.g., orange juice) if craving juice"], "sideEffects": ["Increased drug levels/toxicity of affected medications (e.g., statin myopathy, CCB hypotension)"]}, {"topic": "inter", "generic": "Phenelzine", "pronunciation": "FEN-el-zeen", "brand": ["Nardil"], "class": "Monoamine oxidase inhibitor (antidepressant)", "moa": "Irreversibly inhibits monoamine oxidase A and B, preventing breakdown of serotonin, norepinephrine, dopamine, and dietary tyramine, risking both serotonin syndrome and hypertensive crisis.", "indication": "Treatment-resistant depression.", "dosage": "Start 15 mg PO TID, titrate to usual 45–90 mg/day; MAOI — requires tyramine-restricted diet and 2-week washout before/after other serotonergic or sympathomimetic drugs", "examPoints": ["Combination with other serotonergic drugs (SSRIs, SNRIs, tramadol, triptans, meperidine) causes life-threatening serotonin syndrome — requires washout periods", "Tyramine-containing foods (aged cheese, cured meats, fermented products, tap beer) trigger hypertensive crisis", "Sympathomimetics (e.g., pseudoephedrine) can precipitate hypertensive crisis", "Irreversible inhibition — interaction risk persists ~2 weeks after stopping until new enzyme is made", "Meperidine + MAOI is a classic, potentially fatal, absolute contraindication"], "counselling": ["Avoid aged cheeses, cured/fermented meats, tap beer, and soy sauce", "Avoid OTC cold/decongestant medications without checking with your pharmacist first", "Tell every prescriber you're on an MAOI — many combinations are dangerous", "Wait the full recommended washout time when switching to/from other antidepressants", "Seek immediate care for severe headache, stiff neck, or palpitations"], "sideEffects": ["Orthostatic hypotension", "Insomnia, agitation", "Weight gain", "Hypertensive crisis (with tyramine/sympathomimetics)", "Serotonin syndrome (with serotonergic drugs)"]}, {"topic": "inter", "generic": "Tramadol", "pronunciation": "TRA-muh-dol", "brand": ["Ralivia", "Zytram", "Tridural"], "class": "Opioid analgesic (atypical) / SNRI-like", "moa": "A weak mu-opioid agonist that also inhibits serotonin and norepinephrine reuptake; a CYP2D6-derived active metabolite (M1) has greater mu-opioid activity, creating both PK (2D6) and PD (serotonergic) interaction concerns.", "indication": "Moderate pain.", "dosage": "50–100 mg PO q4–6h PRN; serotonergic activity — risk of serotonin syndrome combined with SSRIs/SNRIs/MAOIs; lowers seizure threshold", "examPoints": ["Serotonergic activity — combination with SSRIs/SNRIs/MAOIs/other serotonergic drugs risks serotonin syndrome", "CYP2D6 substrate — ultrarapid metabolizers get more active metabolite (toxicity risk); poor metabolizers get less analgesia", "Lowers seizure threshold — caution with other drugs that also lower it (e.g., bupropion)", "CYP2D6 inhibitors (paroxetine, fluoxetine) reduce active metabolite formation, reducing analgesia", "Combination with benzodiazepines/other CNS depressants raises respiratory depression risk"], "counselling": ["Report agitation, rapid heart rate, sweating, or tremor — possible serotonin syndrome", "Avoid alcohol and other sedating medications", "Tell your prescriber about all antidepressants you're taking", "Report seizures or unusual muscle twitching", "Don't drive until you know how this affects you"], "sideEffects": ["Nausea, dizziness", "Constipation", "Sedation", "Seizures (dose/interaction-related)", "Serotonin syndrome (in combination)", "Respiratory depression (with other CNS depressants)"]}, {"topic": "inter", "generic": "Ciprofloxacin", "pronunciation": "SIP-roh-FLOKS-uh-sin", "brand": ["Cipro"], "class": "Fluoroquinolone antibiotic", "moa": "Inhibits bacterial DNA gyrase/topoisomerase IV; forms non-absorbable chelation complexes with polyvalent cations, prolongs the QT interval, and inhibits CYP1A2.", "indication": "Urinary tract, respiratory, and other gram-negative infections.", "dosage": "250–750 mg PO q12h; chelates with polyvalent cations (Ca, Mg, Fe, Al, Zn) — separate antacids/dairy/supplements by 2–6h", "examPoints": ["Chelation with divalent/trivalent cations (antacids, calcium, iron, zinc, dairy) drastically reduces absorption — separate by 2h before/6h after", "Additive QT prolongation risk with other QT-prolonging drugs", "Inhibits CYP1A2 — significantly raises theophylline levels, risking toxicity", "Increases warfarin effect — monitor INR", "Black-box warnings: tendon rupture, peripheral neuropathy, CNS effects"], "counselling": ["Take 2 hours before or 6 hours after antacids, calcium, iron, or dairy products", "Report tendon pain or swelling — stop and seek care immediately", "Report numbness, tingling, or unusual sensations", "Report palpitations or fainting", "Avoid excessive sun exposure"], "sideEffects": ["GI upset, nausea", "Tendinopathy/tendon rupture", "Peripheral neuropathy", "QT prolongation", "CNS effects (dizziness, confusion, rare seizures)", "Photosensitivity"]}, {"topic": "inter", "generic": "Simvastatin", "pronunciation": "SIM-vuh-STAT-in", "brand": ["Zocor"], "class": "HMG-CoA reductase inhibitor (statin)", "moa": "Inhibits HMG-CoA reductase, reducing cholesterol synthesis; extensively metabolized by CYP3A4, making it highly susceptible to interactions that raise exposure and myopathy/rhabdomyolysis risk.", "indication": "Hyperlipidemia; cardiovascular risk reduction.", "dosage": "10–40 mg PO once daily at bedtime (max 20 mg/day if on amlodipine/amiodarone); avoid with strong CYP3A4 inhibitors (myopathy/rhabdomyolysis risk)", "examPoints": ["CYP3A4 substrate — strong inhibitors (clarithromycin, itraconazole, HIV protease inhibitors) are contraindicated", "Dose capped at 20mg with amiodarone, 10mg with verapamil/diltiazem", "Grapefruit juice can significantly raise levels — avoid regular/large intake", "Increased myopathy/rhabdomyolysis risk with fibrates (avoid gemfibrozil combination) and niacin", "Pravastatin/rosuvastatin (not CYP3A4-dependent) are safer alternatives when interacting drugs are needed"], "counselling": ["Report muscle pain, tenderness, or weakness, especially with dark urine", "Avoid large amounts of grapefruit juice", "Tell your prescriber before starting antibiotics like clarithromycin", "Take in the evening — cholesterol synthesis peaks at night"], "sideEffects": ["Myalgia", "Myopathy/rhabdomyolysis (rare but serious)", "Elevated liver enzymes", "GI upset", "Increased blood glucose (class effect)"]}, {"topic": "inter", "generic": "Digoxin", "pronunciation": "dih-JOKS-in", "brand": ["Toloxin"], "class": "Cardiac glycoside — P-gp interaction example", "moa": "A P-glycoprotein substrate for both intestinal absorption/efflux and renal/biliary elimination; P-gp inhibitors raise digoxin levels by reducing efflux at multiple sites, independent of hepatic CYP metabolism.", "indication": "Heart failure; atrial fibrillation rate control.", "dosage": "0.125–0.25 mg PO daily; narrow therapeutic index, interacts with amiodarone, verapamil, clarithromycin (increased levels) and diuretics (hypokalemia increases toxicity)", "examPoints": ["P-gp inhibitors (amiodarone, verapamil, clarithromycin, quinidine) significantly raise digoxin levels — dose reduction (often ~50%) needed", "Interaction is via P-gp transport, not CYP metabolism — distinguishes it from most other interactions", "Hypokalemia/hypomagnesemia (e.g., from loop/thiazide diuretics) potentiate toxicity independent of level", "Narrow TI (0.5-2.0 ng/mL) — modest level increases can cause toxicity", "St. John's Wort (P-gp inducer) can decrease digoxin levels/efficacy"], "counselling": ["Tell your prescriber before starting amiodarone, verapamil, or certain antibiotics — dose may need adjusting", "Report nausea, visual changes (halos), or irregular heartbeat", "Have electrolytes checked periodically, especially if on diuretics", "Don't take St. John's Wort without discussing it first"], "sideEffects": ["Nausea, vomiting, anorexia", "Visual disturbances", "Arrhythmias (toxicity)", "Confusion"]}, {"topic": "inter", "generic": "Fluconazole", "pronunciation": "floo-KOH-nuh-zohl", "brand": ["Diflucan"], "class": "Azole antifungal", "moa": "Inhibits fungal CYP450 (14-alpha-demethylase) to block ergosterol synthesis, and also significantly inhibits human CYP2C9, CYP2C19, and (dose-dependently) CYP3A4, raising levels of many co-administered drugs.", "indication": "Candidiasis (vaginal, oral, systemic); cryptococcal infections.", "dosage": "100–400 mg PO/IV daily depending on indication; CYP2C9/3A4 inhibitor — increases warfarin, phenytoin, and sulfonylurea levels", "examPoints": ["Inhibits CYP2C9 — significantly raises warfarin effect/INR, requires close monitoring", "Inhibits CYP3A4 — raises levels of many statins, benzodiazepines, phenytoin", "Additive QT prolongation risk with other QT-prolonging drugs", "Even single-dose fluconazole (common for vaginal candidiasis) can meaningfully interact due to a long half-life (~30h)", "Dose-dependent inhibition — higher systemic doses cause more significant interactions than low-dose vaginal use"], "counselling": ["Tell your pharmacist if you're on warfarin before taking fluconazole, even a single dose", "Report unusual bruising/bleeding if on blood thinners", "Report muscle pain if on a statin", "Complete the course as directed"], "sideEffects": ["Headache", "GI upset (nausea)", "Hepatotoxicity (rare)", "QT prolongation", "Rash"]}, {"topic": "inter", "generic": "Cimetidine", "pronunciation": "sy-MET-ih-deen", "brand": ["Tagamet"], "class": "H2-receptor antagonist", "moa": "Broadly inhibits multiple hepatic CYP450 isoenzymes (1A2, 2C9, 2D6, 3A4), a classic non-selective enzyme inhibitor causing numerous drug interactions, while also reducing gastric acid via H2 blockade.", "indication": "GERD, peptic ulcer disease (largely superseded by PPIs; retained as a classic teaching example).", "dosage": "300 mg PO QID or 800 mg at bedtime; potent CYP450 inhibitor (broad) — largely replaced by other H2RAs/PPIs clinically due to interaction burden", "examPoints": ["Broad, non-selective CYP450 inhibitor — unlike most inhibitors that target one isoenzyme; classic 'many interactions' exam drug", "Significantly raises warfarin, phenytoin, and theophylline levels via multiple CYP pathways", "Other H2 blockers (famotidine, ranitidine) and PPIs largely lack this broad CYP inhibition — preferred when interaction risk is a concern", "Reduces gastric acid — can decrease absorption of drugs requiring an acidic environment (e.g., ketoconazole)", "Also inhibits renal tubular secretion of some drugs (e.g., procainamide)"], "counselling": ["Tell your pharmacist about all medications — this drug interacts broadly with many others", "Report signs of toxicity from other medications (e.g., confusion with phenytoin, bleeding with warfarin)", "Consider alternative acid reducers if you're on multiple other medications"], "sideEffects": ["Headache", "GI upset", "Gynecomastia (with prolonged use)", "Confusion (elderly, high doses)"]}, {"topic": "inter", "generic": "Doxycycline", "pronunciation": "doks-ee-SY-kleen", "brand": ["Vibramycin", "Doxycin"], "class": "Tetracycline antibiotic", "moa": "Inhibits bacterial 30S ribosomal subunit protein synthesis and forms insoluble chelation complexes with polyvalent cations (Ca, Mg, Al, Fe, Zn), drastically reducing GI absorption.", "indication": "Respiratory/skin/STI infections, malaria prophylaxis, acne.", "dosage": "100 mg PO q12h; chelates with polyvalent cations — separate from antacids/dairy/iron by 2–3h; reduced efficacy with enzyme inducers", "examPoints": ["Chelates with dairy, antacids, calcium/iron/zinc supplements — separate administration by 2-3 hours", "Less affected by food/dairy than older tetracyclines but still significantly reduced by divalent cations", "Reduced oral contraceptive efficacy is a commonly taught, weakly-evidenced interaction for doxycycline (unlike rifampin) — still often counselled conservatively", "Photosensitivity is significant — sunburn risk with normal sun exposure", "Contraindicated in pregnancy and children <8 years — tooth discoloration/bone effects"], "counselling": ["Take with a full glass of water and stay upright for 30 minutes to avoid esophageal irritation", "Separate from antacids, calcium, iron, or dairy by a couple of hours", "Use sun protection — increased sunburn risk", "Not for use in pregnancy or young children"], "sideEffects": ["GI upset, esophageal irritation", "Photosensitivity", "Tooth discoloration (children/fetal exposure)", "Rare intracranial hypertension"]}, {"topic": "inter", "generic": "Linezolid", "pronunciation": "lih-NEZ-oh-lid", "brand": ["Zyvoxam"], "class": "Oxazolidinone antibiotic / weak MAOI", "moa": "Inhibits bacterial protein synthesis at the 50S ribosomal subunit and also acts as a weak, reversible, non-selective monoamine oxidase inhibitor, creating serotonin syndrome and tyramine-interaction risk similar to classic MAOIs.", "indication": "Resistant gram-positive infections (VRE, MRSA).", "dosage": "600 mg PO/IV q12h; weak MAOI activity — risk of serotonin syndrome with serotonergic drugs and hypertensive crisis with tyramine/sympathomimetics", "examPoints": ["Weak MAOI activity — combination with serotonergic drugs (SSRIs, SNRIs, TCAs) risks serotonin syndrome, often requiring avoidance/washout", "Tyramine interaction theoretically possible but less clinically significant than classic MAOIs at short-course doses", "Myelosuppression risk increases with duration of therapy (>2 weeks) — monitor CBC", "Peripheral/optic neuropathy risk with prolonged use (>28 days)", "Reversible MAO inhibition — shorter interaction persistence than irreversible MAOIs like phenelzine"], "counselling": ["Tell your prescriber about all antidepressants you're taking before starting this antibiotic", "Report agitation, rapid heartbeat, sweating, or tremor", "Report unusual bruising, bleeding, or fatigue with longer courses", "Report vision changes or numbness/tingling with prolonged use"], "sideEffects": ["GI upset, diarrhea", "Headache", "Myelosuppression (esp. thrombocytopenia)", "Serotonin syndrome (in combination)", "Peripheral/optic neuropathy (prolonged use)", "Lactic acidosis (rare)"]}, {"topic": "peds", "generic": "Acetaminophen (pediatric)", "pronunciation": "uh-SEE-tuh-MIN-oh-fen", "brand": ["Tylenol", "Tempra"], "class": "Non-opioid analgesic/antipyretic", "moa": "Inhibits central prostaglandin synthesis (COX inhibition in CNS); exact mechanism incompletely understood but lacks peripheral anti-inflammatory effect.", "indication": "Mild-moderate pain and fever in infants and children.", "dosage": "10–15 mg/kg/dose PO q4–6h PRN; max 75 mg/kg/day (not to exceed adult max 4 g/day)", "examPoints": ["Dosed 10-15 mg/kg/dose PO q4-6h, max 5 doses/24h or per product max (~75 mg/kg/day, not exceeding adult max)", "Always dose by weight, not age, on the MCQ — age-based dosing charts are approximations only", "Available in different concentrations (infant drops vs children's suspension) — historical concentration mix-ups caused overdoses, now standardized to 160 mg/5 mL", "No max single OTC duration without physician: fever >3 days or pain >5 days needs follow-up", "Antidote for overdose is N-acetylcysteine; hepatotoxicity is the major toxicity concern"], "counselling": ["Use the dosing device/syringe provided, not a kitchen spoon", "Confirm concentration on the label before calculating dose — products vary", "Do not combine with other acetaminophen-containing products (cough/cold combos)", "Space doses at least 4 hours apart, do not exceed 5 doses in 24 hours", "Seek care if fever persists >3 days or child appears very unwell"], "sideEffects": ["Generally well tolerated", "Rare rash", "Hepatotoxicity with overdose/chronic excess dosing", "Rare severe skin reactions (SJS/TEN) - very rare"]}, {"topic": "peds", "generic": "Ibuprofen (pediatric)", "pronunciation": "eye-byoo-PROH-fen", "brand": ["Advil", "Motrin"], "class": "NSAID", "moa": "Non-selective COX-1/COX-2 inhibition, reducing prostaglandin synthesis for analgesic, antipyretic, and anti-inflammatory effect.", "indication": "Mild-moderate pain, fever, and inflammation in children ≥6 months.", "dosage": "5–10 mg/kg/dose PO q6–8h PRN; max 40 mg/kg/day; avoid in infants <6 months", "examPoints": ["Dosed 5-10 mg/kg/dose PO q6-8h, max 40 mg/kg/day", "Contraindicated <6 months of age and in dehydration/varicella (theoretical Reye-like/skin reaction concerns and renal risk in dehydration)", "Give with food to reduce GI upset; avoid in active GI bleed or significant renal impairment", "Preferred over ASA in children due to Reye syndrome risk with aspirin during viral illness", "Can be alternated/combined with acetaminophen per current pediatric fever guidance, though evidence for alternating is mixed"], "counselling": ["Give with food or milk to minimize stomach upset", "Ensure adequate hydration while using, especially during vomiting/diarrhea illness", "Do not use in infants under 6 months without physician advice", "Watch for and report black stools, persistent vomiting, or reduced urination", "Use exact weight-based dose with provided syringe"], "sideEffects": ["GI upset, nausea", "Rare GI bleeding", "Renal impairment with dehydration", "Rare hypersensitivity/bronchospasm in aspirin-sensitive children"]}, {"topic": "peds", "generic": "Amoxicillin (pediatric suspension)", "pronunciation": "uh-mok-sih-SIL-in", "brand": ["Amoxil"], "class": "Aminopenicillin antibiotic", "moa": "Binds penicillin-binding proteins to inhibit bacterial cell wall synthesis, causing bactericidal cell lysis.", "indication": "Otitis media, streptococcal pharyngitis, sinusitis, and other susceptible pediatric infections.", "dosage": "25–90 mg/kg/day PO divided q8–12h depending on indication/resistance concerns; high-dose (80–90 mg/kg/day) for AOM in resistant areas", "examPoints": ["Standard dose 40-90 mg/kg/day divided BID or TID depending on indication (high-dose 80-90 mg/kg/day for AOM to cover resistant S. pneumoniae)", "Shake suspension well before each use; discard after 14 days (refrigeration recommended, varies by product)", "Cross-reactivity with penicillin allergy — avoid in true penicillin-allergic patients", "First-line for acute otitis media per Canadian pediatric guidelines in appropriate candidates", "Complete full course even if symptoms improve to prevent resistance/relapse"], "counselling": ["Shake bottle well before every dose", "Can give with or without food; giving with food may reduce GI upset", "Finish the entire course as prescribed, don't stop early", "Watch for rash, hives, or breathing difficulty (allergic reaction)", "Refrigerate if directed by pharmacist; discard unused suspension after the labeled expiry"], "sideEffects": ["Diarrhea", "GI upset", "Rash (including non-allergic amoxicillin rash with concurrent viral infection/mono)", "Rare hypersensitivity/anaphylaxis", "Rare C. difficile-associated diarrhea"]}, {"topic": "peds", "generic": "Methylphenidate", "pronunciation": "meth-il-FEN-ih-dayt", "brand": ["Ritalin", "Concerta", "Biphentin"], "class": "CNS stimulant", "moa": "Blocks dopamine and norepinephrine reuptake transporters, increasing synaptic catecholamine levels to improve attention and reduce hyperactivity.", "indication": "ADHD in children ≥6 years.", "dosage": "Start 5 mg PO once–BID (immediate-release), titrate weekly; usual range 0.3–1 mg/kg/day (max ~60 mg/day); age ≥6 years", "examPoints": ["Controlled substance (CDSA Schedule) — requires careful prescription handling and monitoring for diversion", "Extended-release formulations (Concerta OROS, Biphentin) allow once-daily dosing and reduce abuse potential/afternoon rebound", "Monitor growth (height/weight), appetite, blood pressure/heart rate, and sleep at baseline and periodically", "Contraindicated with significant cardiac disease, severe anxiety, or concurrent MAOI use", "'Drug holidays' sometimes used to reassess need and allow catch-up growth"], "counselling": ["Take in the morning to avoid insomnia; extended-release swallowed whole, not crushed/chewed", "Track height, weight, and appetite regularly — may cause appetite suppression", "May cause trouble sleeping — take as early in the day as directed", "Report any chest pain, fainting, or new mood/behavioural changes", "Store securely — controlled substance with abuse/diversion potential"], "sideEffects": ["Appetite suppression/weight loss", "Insomnia", "Headache", "Increased heart rate/blood pressure", "Rare: growth suppression with long-term use, rare psychiatric symptoms"]}, {"topic": "peds", "generic": "Amphetamine/dextroamphetamine salts", "pronunciation": "am-FET-uh-meen / deks-troh-am-FET-uh-meen", "brand": ["Adderall XR"], "class": "CNS stimulant", "moa": "Promotes release of dopamine and norepinephrine from presynaptic terminals and blocks their reuptake, enhancing catecholaminergic neurotransmission.", "indication": "ADHD in children ≥6 years (also narcolepsy).", "dosage": "Start 5 mg PO once–BID, titrate weekly by 5 mg increments; usual range 5–40 mg/day (max varies by formulation)", "examPoints": ["CDSA controlled substance; similar monitoring requirements to methylphenidate (growth, cardiovascular, sleep)", "Higher abuse potential profile than methylphenidate in some contexts — counsel on secure storage", "Avoid with MAOIs (risk of hypertensive crisis) and use caution in cardiac disease/structural heart abnormality", "XR capsules can be opened and sprinkled on food for children who cannot swallow capsules (product-specific)", "Second-line to methylphenidate in many Canadian pediatric ADHD algorithms, but first-line stimulant choice varies by patient response"], "counselling": ["Take first thing in the morning to limit insomnia", "May suppress appetite — encourage nutrient-dense meals/snacks when appetite returns later in day", "Do not stop abruptly if used long-term/high-dose; monitor mood and behaviour", "Keep secure/locked due to misuse and diversion risk", "Report palpitations, chest pain, or fainting immediately"], "sideEffects": ["Decreased appetite", "Insomnia", "Irritability/mood lability", "Tachycardia, elevated BP", "Rare: psychotic symptoms, growth suppression"]}, {"topic": "peds", "generic": "Atomoxetine", "pronunciation": "at-oh-MOKS-eh-teen", "brand": ["Strattera"], "class": "Selective norepinephrine reuptake inhibitor (non-stimulant)", "moa": "Selectively inhibits the presynaptic norepinephrine transporter, increasing noradrenergic (and indirectly prefrontal dopaminergic) signaling without direct stimulant activity.", "indication": "ADHD in children ≥6 years, especially when stimulants are contraindicated, not tolerated, or diversion is a concern.", "dosage": "Start 0.5 mg/kg/day PO, titrate after ≥3 days to target 1.2 mg/kg/day (max 1.4 mg/kg/day or 100 mg/day, whichever less); non-stimulant", "examPoints": ["Not a controlled substance — useful option when stimulant misuse/diversion is a concern or with comorbid anxiety/tics", "Takes several weeks for full effect (unlike immediate-onset stimulants) — set expectations", "Boxed warning for suicidal ideation in children/adolescents — monitor mood closely, especially early in therapy", "Can cause hepatotoxicity (rare) — counsel on jaundice/dark urine; and can increase BP/HR", "CYP2D6 substrate — poor metabolizers have higher exposure; interacts with strong CYP2D6 inhibitors (e.g., paroxetine, fluoxetine)"], "counselling": ["Effect builds over several weeks — do not expect immediate results like stimulants", "Can be taken once or twice daily, with or without food (take with food if GI upset)", "Report any new or worsening suicidal thoughts, mood changes, especially in first months", "Report yellowing of skin/eyes, dark urine, or itching (rare liver effects)", "Do not stop abruptly without checking with prescriber"], "sideEffects": ["GI upset, decreased appetite", "Fatigue/somnolence", "Increased heart rate/BP", "Rare: hepatotoxicity, suicidal ideation (boxed warning)"]}, {"topic": "peds", "generic": "Salbutamol (with spacer/mask)", "pronunciation": "sal-BYOO-tuh-mol", "brand": ["Ventolin", "Airomir"], "class": "Short-acting beta2-agonist (SABA) bronchodilator", "moa": "Stimulates beta2-adrenergic receptors in bronchial smooth muscle causing relaxation and bronchodilation via increased cAMP.", "indication": "Acute asthma symptom relief/rescue therapy and pre-exercise prophylaxis in pediatric asthma.", "dosage": "100 mcg (1 puff) via spacer q30–60sec up to 4–10 puffs for acute exacerbation, or 1–2 puffs q4–6h PRN for maintenance", "examPoints": ["Spacer (+/- mask for young children) dramatically improves lung deposition vs MDI alone and is standard of care in kids", "Technique: shake inhaler, attach to spacer, seal lips/mask, one puff at a time, 5-6 tidal breaths or single deep breath+hold per puff", "Overuse (>1 canister/month or frequent rescue use) signals poor asthma control — needs step-up therapy/referral", "Not for daily maintenance/prevention — reliever only; regular overuse is an exam red flag", "Rinse mouth not required for salbutamol (unlike ICS) but wash spacer per manufacturer instructions periodically"], "counselling": ["Always use with a spacer device, and a mask if the child cannot form a seal on the mouthpiece", "One puff at a time into the spacer, then breathe normally for several breaths", "Carry the reliever at all times for emergencies; use before exercise if exercise-induced symptoms", "Rising use (needing it more than twice a week) means asthma is not controlled — contact your care team", "Clean spacer regularly to reduce static and improve drug delivery"], "sideEffects": ["Tremor", "Tachycardia/palpitations", "Nervousness/hyperactivity", "Headache", "Rare: hypokalemia with high doses"]}, {"topic": "peds", "generic": "Fluticasone (inhaled)", "pronunciation": "floo-TIK-uh-zohn", "brand": ["Flovent"], "class": "Inhaled corticosteroid (ICS)", "moa": "Binds glucocorticoid receptors to reduce airway inflammation, mucus production, and bronchial hyperresponsiveness over time.", "indication": "Maintenance/controller therapy for persistent pediatric asthma.", "dosage": "Pediatric: 50–100 mcg BID depending on age/severity, titrated to lowest effective dose to minimize growth suppression risk", "examPoints": ["Controller medication — must be used daily/regularly, not for acute symptom relief", "Rinse mouth and spit after each use to prevent oral thrush and minimize systemic absorption", "Use with spacer to reduce oropharyngeal deposition and improve lung delivery in children", "Growth velocity should be monitored with long-term ICS use in children (small, usually non-cumulative effect at low-moderate doses)", "Step therapy: use lowest effective dose to control symptoms, per Canadian pediatric asthma guidelines"], "counselling": ["Use every day as scheduled even if feeling well — it prevents attacks, doesn't stop them acutely", "Rinse mouth with water and spit after each dose to prevent thrush", "Use with a spacer for consistent, effective dosing", "Do not use for sudden wheeze/shortness of breath — use the rescue inhaler (salbutamol) instead", "Track growth at regular checkups while on long-term therapy"], "sideEffects": ["Oral thrush (candidiasis)", "Dysphonia (hoarse voice)", "Cough/throat irritation", "Rare: growth velocity reduction, adrenal suppression at high doses"]}, {"topic": "peds", "generic": "Ondansetron (pediatric)", "pronunciation": "on-DAN-seh-tron", "brand": ["Zofran"], "class": "5-HT3 receptor antagonist antiemetic", "moa": "Blocks serotonin (5-HT3) receptors both peripherally (vagal afferents in GI tract) and centrally (chemoreceptor trigger zone) to prevent nausea/vomiting.", "indication": "Acute gastroenteritis-associated vomiting and chemotherapy/postoperative nausea in children.", "dosage": "0.15 mg/kg/dose PO/IV (max 8 mg/dose) for acute gastroenteritis-related vomiting, single dose typically sufficient", "examPoints": ["Single oral dose (weight-based, ODT formulation common) reduces vomiting and need for IV fluids/hospitalization in pediatric gastroenteritis per ED guidelines", "QT prolongation risk — caution with other QT-prolonging drugs, electrolyte abnormalities, or congenital long QT syndrome", "ODT (orally disintegrating tablet) is convenient in vomiting children who cannot swallow whole tablets", "Not first-line for routine self-limited vomiting without dehydration risk — used to facilitate oral rehydration therapy", "Common exam pairing: used adjunctively with oral rehydration solution, not a substitute for fluids"], "counselling": ["Let the orally-dissolving tablet melt on the tongue, don't chew or swallow whole if ODT formulation", "Continue offering small frequent sips of oral rehydration solution after the dose", "One dose is often enough to interrupt the vomiting cycle and allow rehydration", "Seek care if vomiting continues, or if signs of dehydration develop (dry mouth, no tears, reduced urination)", "Report irregular heartbeat or fainting (rare QT-related effects)"], "sideEffects": ["Headache", "Diarrhea", "Fatigue", "Rare: QT prolongation, constipation"]}, {"topic": "peds", "generic": "Hydrocortisone 1% topical", "pronunciation": "hy-droh-KOR-tih-zohn", "brand": ["Cortate", "various OTC"], "class": "Low-potency topical corticosteroid", "moa": "Binds cytoplasmic glucocorticoid receptors to reduce inflammatory mediator release, decreasing local erythema, itching, and inflammation.", "indication": "Mild pediatric eczema/atopic dermatitis flares and other mild inflammatory dermatoses.", "dosage": "Apply thin layer to affected area BID PRN; limit duration of use, especially on face/thin skin in children", "examPoints": ["Low potency — first-line and appropriate for face, skin folds, and young infants where higher potency agents risk more atrophy/absorption", "Apply thin layer to affected areas only, typically once-twice daily during flares, taper as skin improves", "Use fingertip unit (FTU) concept to teach appropriate quantity to caregivers", "Combine with regular emollient/moisturizer use as mainstay of eczema management (steroid for flares, emollient always)", "Prolonged/excessive use risks skin atrophy, striae, and (rarely in infants) systemic absorption/HPA suppression given larger surface-area-to-weight ratio"], "counselling": ["Apply a thin layer only to the affected (red/itchy) patches, not healthy skin", "Use for the shortest effective period during a flare, then step back to moisturizer alone", "Apply emollient/moisturizer liberally every day, even between flares", "Avoid prolonged continuous use on the face or skin folds without medical guidance", "Wash hands after application unless hands are the treated area"], "sideEffects": ["Local burning/stinging on application", "Skin thinning (atrophy) with prolonged use", "Striae with prolonged/high-potency use", "Rare: HPA axis suppression with extensive/prolonged use in infants"]}, {"topic": "peds", "generic": "Iron (ferrous sulfate/fumarate) pediatric", "pronunciation": "EYE-ern (FAIR-us SUL-fayt / FYOO-muh-rayt)", "brand": ["Fer-In-Sol"], "class": "Oral iron supplement", "moa": "Provides elemental iron substrate for hemoglobin synthesis, correcting iron-deficiency erythropoiesis.", "indication": "Iron-deficiency anemia and prevention in at-risk infants (e.g., preterm, exclusively breastfed past 6 months).", "dosage": "3–6 mg/kg/day elemental iron PO divided (treatment); 1–2 mg/kg/day for prophylaxis; give on empty stomach if tolerated", "examPoints": ["Dosed by elemental iron mg/kg/day (typically 3-6 mg/kg/day elemental iron for deficiency treatment)", "Liquid pediatric formulations can stain teeth — administer via dropper toward back of mouth/behind teeth, brush after", "Give on empty stomach for best absorption but may move to with-food if GI upset limits adherence; avoid with milk/calcium/tea which impair absorption", "Vitamin C (e.g., orange juice) enhances absorption when co-administered", "Accidental overdose is a leading cause of pediatric poisoning deaths historically — stress child-proof storage"], "counselling": ["Give with a dropper/syringe placed toward the back of the mouth to reduce tooth staining", "Brush teeth after dosing if staining is a concern", "Avoid giving with milk, tea, or antacids — these reduce absorption; a small amount of vitamin C-rich juice can help absorption", "Stools may turn dark/greenish — this is expected and not harmful", "Keep container out of reach of children — iron overdose is a serious poisoning risk"], "sideEffects": ["Constipation", "GI upset/nausea", "Dark stools (expected)", "Tooth staining (liquid formulations)", "Severe: iron overdose toxicity is a medical emergency (GI bleeding, shock)"]}, {"topic": "peds", "generic": "Diphenhydramine (pediatric use caution)", "pronunciation": "dy-fen-HY-druh-meen", "brand": ["Benadryl"], "class": "First-generation antihistamine", "moa": "Competitively blocks H1 histamine receptors; sedating due to significant CNS penetration and additional anticholinergic activity.", "indication": "Allergic reactions, urticaria; historically used for cough/cold and sleep but now discouraged in young children.", "dosage": "1 mg/kg/dose PO q6h PRN (max 50 mg/dose); use caution — sedation and paradoxical excitation possible in children", "examPoints": ["Not recommended under 6 years for cough/cold indications — Health Canada/product labeling restricts pediatric cough-cold combination products under 6 (many voluntarily withdrawn under 6, caution 6-12)", "Paradoxical excitation/hyperactivity can occur in children instead of sedation", "Anticholinergic effects (dry mouth, urinary retention, constipation) more pronounced and risky in young children", "Not an antiemetic/sleep aid of choice in pediatrics — safer alternatives preferred", "Overdose risk is significant in small children owing to narrow safety margin per kg"], "counselling": ["Do not use OTC cough/cold products containing this in children under 6 without physician direction", "Watch for unusual excitability or agitation rather than expected drowsiness", "Use only the pediatric-specific concentration and weight-based dosing device", "Avoid combining with other sedating or anticholinergic products", "Contact poison control immediately for suspected overdose"], "sideEffects": ["Sedation (or paradoxical hyperactivity in children)", "Dry mouth", "Constipation/urinary retention", "Rare: overdose causing anticholinergic toxicity/seizures"]}, {"topic": "peds", "generic": "Oral rehydration solution (ORS)", "pronunciation": "OR-ul ree-hy-DRAY-shun soh-LOO-shun", "brand": ["Pedialyte", "Gastrolyte"], "class": "Electrolyte/glucose rehydration solution", "moa": "Co-transports sodium and glucose across intestinal epithelium via SGLT1, driving water reabsorption even during secretory diarrhea.", "indication": "Prevention/treatment of mild-moderate dehydration from vomiting/diarrhea in children.", "dosage": "50–100 mL/kg over 4h for mild-moderate dehydration, then ongoing replacement of losses (~10 mL/kg per loose stool)", "examPoints": ["Preferred first-line over IV fluids for mild-moderate dehydration per Canadian Paediatric Society guidance", "Give small frequent volumes (e.g., 5 mL every few minutes) especially if vomiting, increasing as tolerated", "Not the same as sports drinks/juice — those have inappropriate osmolarity/electrolyte ratios for rehydration", "Continue age-appropriate diet/breastfeeding alongside ORS — no need for prolonged fasting or diluted formula", "Refer to ED for signs of significant dehydration: lethargy, no tears, sunken fontanelle, minimal urine output, sunken eyes"], "counselling": ["Offer small sips frequently rather than large volumes at once, especially if the child is vomiting", "Continue breastfeeding or regular diet as tolerated - no need to withhold food", "Do not substitute sports drinks, soda, or plain juice for ORS", "Watch for red flags: dry mouth, no tears, reduced wet diapers/urination, lethargy — seek care promptly", "Refrigerate opened solution and discard after 24-48 hours per product instructions"], "sideEffects": ["Generally very well tolerated", "Vomiting if given too quickly in large volumes", "Rare: electrolyte imbalance if improperly prepared/concentrated (homemade solutions)"]}, {"topic": "peds", "generic": "Amoxicillin-clavulanate (pediatric)", "pronunciation": "uh-mok-sih-SIL-in KLAV-yoo-lan-ayt", "brand": ["Clavulin"], "class": "Beta-lactam/beta-lactamase inhibitor combination", "moa": "Amoxicillin inhibits cell wall synthesis; clavulanate irreversibly inhibits bacterial beta-lactamase enzymes, protecting amoxicillin from degradation and extending coverage to beta-lactamase-producing organisms.", "indication": "Recurrent/persistent otitis media, sinusitis, and other infections with suspected beta-lactamase-producing pathogens.", "dosage": "45–90 mg/kg/day (amoxicillin component) PO divided q12h, based on indication and resistance risk", "examPoints": ["Dosed based on the amoxicillin component (mg/kg/day), with attention to the clavulanate ratio to avoid excess clavulanate-related diarrhea", "Higher rate of GI upset/diarrhea compared to amoxicillin alone due to clavulanate component", "Different formulation ratios (e.g., 7:1 vs 4:1) exist — using the wrong strength product can under- or overdose clavulanate", "Second-line after amoxicillin failure or for recurrent AOM within 30 days", "Give with food to improve tolerability and reduce GI side effects"], "counselling": ["Give with food to reduce stomach upset/diarrhea", "Shake suspension well before each dose", "Complete the full course even if the child feels better", "Report severe or bloody diarrhea (rare C. difficile risk)", "Watch for allergic reaction signs as with any penicillin"], "sideEffects": ["Diarrhea (more than amoxicillin alone)", "GI upset", "Diaper rash (from diarrhea/moisture)", "Rash", "Rare: hypersensitivity, hepatotoxicity"]}, {"topic": "peds", "generic": "Vaccines - routine childhood schedule (general)", "pronunciation": "vak-SEENZ", "brand": ["various (e.g., Infanrix, Prevnar, MMR-II)"], "class": "Active immunization biologics", "moa": "Introduce antigen (inactivated, live-attenuated, subunit, or conjugate) to stimulate adaptive immune memory (B- and T-cell response) without causing full disease.", "indication": "Prevention of vaccine-preventable diseases per provincial routine childhood immunization schedules.", "dosage": "Not applicable — general immunization schedule overview, not a single dosed adult drug; individual vaccine dosing varies by product and age", "examPoints": ["Live vaccines (MMR, varicella) generally contraindicated in significant immunosuppression and pregnancy; can be co-administered same day or spaced ≥4 weeks apart if not simultaneous", "Minor illness without fever is NOT a contraindication to vaccination — common exam trap (true contraindication is severe/anaphylactic reaction to prior dose or component)", "Catch-up schedules exist for children who fall behind — pharmacists should know provincial catch-up tools/NACI guidance", "Common mild reactions (fever, soreness) managed with acetaminophen; prophylactic antipyretic before vaccination is generally NOT recommended (may blunt immune response)", "Vaccine hesitancy counselling: pharmacist role is providing evidence-based information non-judgmentally"], "counselling": ["Mild fever, soreness, or fussiness for 1-2 days after vaccination is expected and normal", "Acetaminophen or ibuprofen can be used after vaccination for discomfort if needed, but not routinely beforehand", "A mild cold without fever does not need to delay vaccination — check with your provider", "Keep the vaccination record up to date and bring it to every appointment", "Seek care for high fever, unusual crying, seizures, or signs of severe allergic reaction after vaccination"], "sideEffects": ["Injection site soreness/redness", "Mild fever", "Fussiness/irritability", "Rare: febrile seizure, severe allergic reaction (anaphylaxis)"]}, {"topic": "geri", "generic": "Lorazepam (elderly use)", "pronunciation": "lor-AZ-eh-pam", "brand": ["Ativan"], "class": "Benzodiazepine", "moa": "Enhances GABA-A receptor-mediated chloride influx, increasing inhibitory neurotransmission causing sedative, anxiolytic, and amnestic effects.", "indication": "Anxiety, insomnia (short-term), procedural sedation; used cautiously in elderly.", "dosage": "Start at lowest dose 0.25–0.5 mg PO once–BID PRN; use lower doses/longer intervals due to reduced clearance and fall risk (Beers Criteria caution)", "examPoints": ["Beers Criteria: avoid benzodiazepines in older adults — increased risk of cognitive impairment, delirium, falls, fractures, and motor vehicle accidents", "Lorazepam undergoes only glucuronidation (no oxidative metabolism), making it comparatively 'safer' pharmacokinetically in hepatic impairment vs diazepam, but still carries the class risk in elderly", "STOPP criteria flags benzodiazepines for ≥4 weeks continuous use in older adults with falls history", "Taper gradually rather than abrupt discontinuation to avoid withdrawal/rebound anxiety or seizures", "Additive CNS depression with opioids, alcohol, other sedatives — major interaction/black-box concern"], "counselling": ["Use only for short-term/as-needed situations if possible, not routine daily long-term use", "Avoid alcohol and other sedating medications while taking this", "Rise slowly from sitting/lying to reduce fall risk", "Do not stop abruptly after regular use — needs a gradual taper with your prescriber", "Report excessive drowsiness, confusion, or unsteadiness"], "sideEffects": ["Sedation/drowsiness", "Confusion, cognitive impairment", "Falls/fractures risk", "Ataxia", "Rare: paradoxical agitation, respiratory depression (esp. with opioids)"]}, {"topic": "geri", "generic": "Oxybutynin", "pronunciation": "oks-ee-BYOO-tih-nin", "brand": ["Ditropan"], "class": "Anticholinergic (antimuscarinic) - urinary antispasmodic", "moa": "Blocks muscarinic (M3) receptors on bladder detrusor smooth muscle, reducing involuntary bladder contractions in overactive bladder.", "indication": "Overactive bladder/urge urinary incontinence.", "dosage": "2.5–5 mg PO BID–TID (immediate-release) or 5–10 mg once daily (extended-release); avoid in elderly with cognitive impairment (anticholinergic burden, Beers list)", "examPoints": ["Beers Criteria: high anticholinergic burden drug — avoid in older adults, especially with dementia/cognitive impairment", "Contributes significantly to cumulative Anticholinergic Cognitive Burden (ACB) scale scores — classic exam culprit drug", "Immediate-release has higher anticholinergic CNS penetration/side effect burden than extended-release or transdermal formulations", "Preferred alternatives in elderly: mirabegron (beta-3 agonist, non-anticholinergic) or behavioral/pelvic floor therapy first-line", "Watch for prescribing cascade: anticholinergic causes constipation/confusion, which may be mistakenly treated with more drugs rather than recognizing the cause"], "counselling": ["May cause dry mouth, constipation, and blurred vision — report if bothersome", "Can cause confusion or memory problems, especially in older adults — report any new confusion promptly", "Stay well hydrated and use sugar-free candy/gum for dry mouth", "Avoid overheating/dehydration — this drug can reduce sweating", "Non-drug options (bladder training, pelvic floor exercises) should be tried alongside or before medication"], "sideEffects": ["Dry mouth", "Constipation", "Blurred vision", "Cognitive impairment/confusion in elderly", "Urinary retention", "Rare: heat stroke from decreased sweating"]}, {"topic": "geri", "generic": "Donepezil", "pronunciation": "doh-NEP-eh-zil", "brand": ["Aricept"], "class": "Cholinesterase inhibitor", "moa": "Inhibits acetylcholinesterase, increasing synaptic acetylcholine to partially compensate for cholinergic deficits in Alzheimer's disease.", "indication": "Mild-to-moderate (and moderate-to-severe) Alzheimer's dementia.", "dosage": "Start 5 mg PO daily at bedtime, increase to 10 mg after 4–6 weeks if tolerated; max 23 mg/day for moderate-severe AD", "examPoints": ["Modest symptomatic benefit only — does not stop disease progression, sets realistic expectations for families", "GI side effects and bradycardia are the main tolerability issues, especially at initiation/titration", "Avoid combining with anticholinergic drugs — they work against each other pharmacologically (a common prescribing-cascade trap)", "Caution in patients with bradycardia, syncope, or conduction abnormalities", "Deprescribing consideration: reassess benefit periodically, especially in advanced dementia or end-of-life care"], "counselling": ["Take at bedtime to minimize daytime GI upset, unless it causes vivid dreams/insomnia (then switch to morning)", "Benefits are gradual and modest — don't expect dramatic improvement", "Report significant nausea, vomiting, or slow heart rate", "Do not combine with other over-the-counter anticholinergic products (e.g., some sleep aids) without checking first", "Continue routine follow-up to reassess whether the medication is still providing benefit"], "sideEffects": ["Nausea/vomiting/diarrhea", "Insomnia or vivid dreams", "Bradycardia", "Muscle cramps", "Loss of appetite/weight loss"]}, {"topic": "geri", "generic": "Memantine", "pronunciation": "MEM-an-teen", "brand": ["Ebixa"], "class": "NMDA receptor antagonist", "moa": "Non-competitively blocks NMDA glutamate receptors, reducing excitotoxic glutamatergic overstimulation implicated in neurodegeneration.", "indication": "Moderate-to-severe Alzheimer's dementia, often combined with a cholinesterase inhibitor.", "dosage": "Start 5 mg PO daily, titrate weekly by 5 mg to target 10 mg BID (or 28 mg once daily XR); reduce dose in severe renal impairment", "examPoints": ["Different mechanism from cholinesterase inhibitors, allowing combination therapy in moderate-severe disease", "Renal dose adjustment required in significant renal impairment (renally eliminated largely unchanged)", "Generally better tolerated than cholinesterase inhibitors, with fewer GI effects", "Titrate slowly (weekly dose increases) to minimize CNS side effects (dizziness, confusion)", "Like donepezil, provides symptomatic benefit only, not disease-modifying"], "counselling": ["Dose is increased gradually over several weeks — follow the titration schedule provided", "May cause dizziness or headache initially, especially during dose increases", "Can be taken with or without food", "Report significant confusion, dizziness, or hallucinations", "Continue regular follow-up to assess ongoing benefit versus burden of therapy"], "sideEffects": ["Dizziness", "Headache", "Confusion", "Constipation", "Rare: hallucinations"]}, {"topic": "geri", "generic": "Morphine (palliative dyspnea/pain)", "pronunciation": "MOR-feen", "brand": ["Statex", "MS Contin", "M-Eslon"], "class": "Opioid agonist", "moa": "Binds mu-opioid receptors centrally and peripherally, reducing pain perception; also reduces the ventilatory drive's sensitivity to hypercapnia/dyspnea perception at low doses.", "indication": "Moderate-severe pain and refractory dyspnea in palliative care.", "dosage": "Start low: 2.5–5 mg PO q4h PRN (or lower in opioid-naïve elderly), titrated to symptom relief; no ceiling in palliative titration", "examPoints": ["Low-dose opioids are standard of care for palliative dyspnea, not just pain — a key exam concept distinguishing palliative from general opioid caution", "Start low, go slow in elderly/opioid-naive patients due to increased sensitivity and reduced clearance; renal impairment requires dose reduction/caution (active metabolite M6G accumulation)", "Always co-prescribe a bowel regimen (stimulant +/- softener) prophylactically — opioid-induced constipation does not resolve with tolerance", "Titrate breakthrough dosing as 10-15% of total daily dose, given q1h PRN (immediate-release) alongside scheduled long-acting dosing", "Naloxone reversal for respiratory depression; monitor sedation score as an earlier warning sign than respiratory rate"], "counselling": ["Take a stool softener/laxative regularly while on this medication — constipation will not go away on its own", "This may be used for breathlessness as well as pain — it is a recognized palliative treatment for both", "Do not drive or operate machinery until you know how this affects you, especially after dose changes", "Take breakthrough doses as directed for pain/breathlessness between regular doses", "Report excessive drowsiness, confusion, or slowed/shallow breathing to caregivers immediately"], "sideEffects": ["Constipation (universal, does not resolve with tolerance)", "Nausea (usually transient)", "Sedation/drowsiness", "Respiratory depression (dose-related)", "Rare: myoclonus, hyperalgesia with high doses, especially in renal impairment"]}, {"topic": "geri", "generic": "Glycopyrrolate", "pronunciation": "gly-koh-PIH-roh-layt", "brand": ["Robinul"], "class": "Anticholinergic (antimuscarinic), quaternary amine", "moa": "Blocks muscarinic receptors on exocrine glands, reducing salivary and bronchial secretions; quaternary structure limits CNS penetration.", "indication": "Management of excessive respiratory secretions ('death rattle') in end-of-life/palliative care.", "dosage": "1–2 mg PO BID–TID, or 0.1–0.2 mg IV/SC/IM q4–6h PRN for secretions (palliative \"death rattle\")", "examPoints": ["Preferred over atropine/scopolamine in some settings because it does NOT cross the blood-brain barrier well, causing less sedation/delirium", "Most effective when started early/proactively at first sign of secretions rather than after secretions are already pooled (cannot clear existing secretions, only prevents new ones)", "Given subcutaneously or via continuous infusion in palliative/hospice settings; also available oral for chronic sialorrhea", "Anticholinergic side effects (dry mouth, urinary retention, tachycardia) still apply despite reduced CNS effect", "Distinguish from scopolamine (crosses BBB, more sedating/delirium-prone) and atropine (also CNS-active, faster onset but shorter duration) on exam comparisons"], "counselling": ["This is used to reduce noisy breathing/secretions at end of life; caregivers should know it may not fully eliminate the sound", "Best started as soon as secretions are noticed rather than waiting", "Report signs of urinary retention or significant dry mouth", "Family/caregiver education focuses on comfort — the 'death rattle' is usually more distressing to family than to the patient", "Administered by nursing/caregiver per the palliative care plan (often subcutaneous)"], "sideEffects": ["Dry mouth", "Urinary retention", "Tachycardia", "Constipation", "Less sedation/confusion than other antimuscarinics (still possible)"]}, {"topic": "geri", "generic": "Haloperidol (delirium)", "pronunciation": "hal-oh-PER-ih-dol", "brand": ["Haldol"], "class": "Typical (first-generation) antipsychotic", "moa": "Blocks central dopamine D2 receptors, reducing dopaminergic hyperactivity thought to underlie agitation/psychotic symptoms of delirium.", "indication": "Severe agitation/distressing psychotic symptoms in delirium when non-pharmacologic measures fail, and palliative nausea (lower doses).", "dosage": "0.25–0.5 mg PO/IM/IV q4–6h PRN, low starting dose in elderly (start low, go slow); max 2–3 mg/day in most frail elderly", "examPoints": ["Non-pharmacologic management (reorientation, sleep-wake cycle, minimize tethers, treat underlying cause) is always first-line for delirium — drugs are for severe/dangerous agitation only", "Low doses used off-label for palliative nausea/vomiting via central D2 blockade at the chemoreceptor trigger zone", "Beers Criteria/geriatric caution: antipsychotics carry boxed warning for increased mortality in dementia-related psychosis — use lowest effective dose, shortest duration", "Risk of extrapyramidal symptoms (EPS) and QT prolongation — ECG monitoring considerations with higher doses/IV use", "Avoid in Parkinson's disease and Lewy body dementia — can severely worsen motor symptoms; quetiapine preferred in these populations"], "counselling": ["Used short-term for severe agitation or distressing symptoms when other measures haven't worked", "Family should know this carries increased risk in older adults with dementia and is used cautiously", "Report stiffness, tremor, or unusual movements (possible extrapyramidal side effects)", "Not for routine/long-term behavioural management — reassess ongoing need frequently", "In palliative nausea use, low doses are typical and different from doses used for agitation"], "sideEffects": ["Extrapyramidal symptoms (rigidity, tremor, akathisia)", "Sedation", "QT prolongation", "Orthostatic hypotension", "Rare: neuroleptic malignant syndrome, increased mortality in dementia-related psychosis (boxed warning)"]}, {"topic": "geri", "generic": "Diphenhydramine (elderly use caution)", "pronunciation": "dy-fen-HY-druh-meen", "brand": ["Benadryl", "Nytol"], "class": "First-generation antihistamine (anticholinergic)", "moa": "Blocks H1 histamine receptors with significant CNS penetration and anticholinergic (antimuscarinic) activity causing sedation.", "indication": "Historically used OTC for allergies/insomnia; generally avoided in elderly.", "dosage": "Generally avoided in elderly (Beers Criteria) due to strong anticholinergic effects — confusion, falls, urinary retention; if used, lowest dose PRN only", "examPoints": ["Beers Criteria: avoid in older adults — highly anticholinergic, causes confusion, dry mouth, constipation, and increased fall/fracture risk", "Commonly hidden in OTC 'PM' combination products and sleep aids — counsel patients to check ingredients, not just brand names", "Contributes heavily to cumulative anticholinergic burden score, associated with long-term dementia risk in observational studies", "Paradoxical CNS stimulation can occur instead of sedation in some elderly patients", "Safer alternatives for sleep/allergy in elderly: non-pharm sleep hygiene, or non-sedating second-generation antihistamines (cetirizine/loratadine) for allergy symptoms"], "counselling": ["Avoid regular use for sleep or allergies if you're an older adult — safer options exist", "Check OTC product labels carefully — many 'nighttime' or 'PM' pain relievers contain this ingredient", "Report confusion, dry mouth, constipation, or difficulty urinating", "Ask your pharmacist about non-anticholinergic alternatives for allergies or insomnia", "Increased fall risk — use caution with nighttime mobility if taken"], "sideEffects": ["Sedation (or paradoxical agitation in elderly)", "Confusion/cognitive impairment", "Dry mouth, constipation, urinary retention", "Falls risk", "Blurred vision"]}, {"topic": "geri", "generic": "Amitriptyline (elderly use caution)", "pronunciation": "am-ee-TRIP-tih-leen", "brand": ["Elavil"], "class": "Tricyclic antidepressant (TCA)", "moa": "Inhibits reuptake of serotonin and norepinephrine; also has strong antihistaminic, anticholinergic, and antiadrenergic activity.", "indication": "Historically for depression/neuropathic pain; largely avoided in elderly due to side effect burden.", "dosage": "Generally avoided in elderly (Beers Criteria); if used at all, start very low (10 mg at bedtime), significant anticholinergic/orthostatic risk", "examPoints": ["Beers Criteria: avoid TCAs (especially tertiary amines like amitriptyline) in older adults — highly anticholinergic, sedating, and orthostatic-hypotension-prone", "Cardiac conduction effects (QT prolongation) are a significant risk, particularly in overdose or with other QT-prolonging drugs", "If a TCA is needed, secondary amines (nortriptyline) are preferred over tertiary amines (amitriptyline) due to lower anticholinergic burden", "Falls risk from combined sedation + orthostatic hypotension is a classic exam pairing for geriatric harm", "Deprescribing candidate — SSRIs/SNRIs or other non-anticholinergic agents preferred for depression/neuropathic pain in elderly"], "counselling": ["Rise slowly from sitting or lying down — this medication can cause dizziness/low blood pressure on standing", "Report confusion, dry mouth, constipation, or urinary difficulty", "This is generally avoided in older adults if alternatives exist — ask about safer options", "Report palpitations or fainting", "Do not stop abruptly if on long-term therapy — needs gradual taper"], "sideEffects": ["Anticholinergic effects (dry mouth, constipation, blurred vision)", "Orthostatic hypotension", "Sedation", "Cardiac conduction abnormalities/QT prolongation", "Falls risk"]}, {"topic": "geri", "generic": "Glyburide (elderly use caution)", "pronunciation": "GLY-byoor-eyed", "brand": ["Diabeta"], "class": "Sulfonylurea (second-generation)", "moa": "Stimulates pancreatic beta cells to increase insulin secretion independent of glucose level, lowering blood glucose.", "indication": "Type 2 diabetes; use in elderly is discouraged.", "dosage": "Generally avoided in elderly (Beers Criteria) due to prolonged hypoglycemia risk; if used, start low (1.25–2.5 mg daily) — shorter-acting sulfonylureas preferred", "examPoints": ["Beers Criteria: avoid glyburide in older adults specifically (vs other sulfonylureas) — long half-life and active metabolites cause prolonged, severe hypoglycemia risk", "Hypoglycemia in elderly is particularly dangerous — mimics/precipitates falls, confusion, and cardiovascular events, and may go unrecognized (hypoglycemia unawareness)", "If a sulfonylurea is needed, shorter-acting agents like gliclazide are preferred in older adults", "Renal impairment (common in elderly) further increases hypoglycemia risk due to reduced clearance", "Deprescribing/switching consideration alongside metformin dose adjustment for renal function in comprehensive geriatric medication reviews"], "counselling": ["Take with meals as directed to reduce hypoglycemia risk — never skip a meal after a dose", "Carry a fast-acting sugar source at all times in case of low blood sugar", "Know the signs of low blood sugar: shakiness, sweating, confusion, dizziness", "This drug is generally avoided in older adults due to higher risk of prolonged low blood sugar — ask about alternatives", "Regular blood glucose monitoring is important, especially with illness or reduced eating"], "sideEffects": ["Hypoglycemia (can be severe/prolonged in elderly)", "Weight gain", "GI upset", "Rare: hepatotoxicity, hemolytic anemia (G6PD deficiency)"]}, {"topic": "geri", "generic": "Zopiclone", "pronunciation": "ZOH-pih-klohn", "brand": ["Imovane"], "class": "Non-benzodiazepine hypnotic (Z-drug)", "moa": "Binds the benzodiazepine site on GABA-A receptors (different binding profile than benzodiazepines) enhancing GABAergic inhibitory transmission to promote sleep.", "indication": "Short-term treatment of insomnia.", "dosage": "Start 3.75 mg PO at bedtime in elderly (reduced from standard 5–7.5 mg); use caution — fall and cognitive impairment risk (Beers Criteria)", "examPoints": ["Beers Criteria: avoid Z-drugs in older adults — despite marketing as 'safer,' they carry similar fall, fracture, and cognitive impairment risk to benzodiazepines in elderly", "Associated with next-day psychomotor impairment and motor vehicle accident risk, especially at higher doses in women/elderly (dose reduction often recommended)", "Metallic taste is a distinctive, commonly tested side effect", "Should be limited to short-term use (days to a few weeks); sleep hygiene and CBT-I are preferred first-line for chronic insomnia in elderly", "Additive CNS depression with alcohol, opioids, and other sedatives"], "counselling": ["Use for the shortest time necessary — not intended for long-term nightly use", "Take right before getting into bed, as it works quickly and can cause immediate drowsiness/impaired coordination", "A metallic or bitter taste afterward is common and expected", "Avoid alcohol while taking this medication", "Rise slowly and use caution with nighttime mobility (bathroom trips) due to fall risk"], "sideEffects": ["Metallic/bitter taste", "Sedation/drowsiness", "Dizziness, impaired coordination", "Falls risk", "Rare: cognitive impairment, complex sleep behaviours (sleepwalking/driving)"]}, {"topic": "geri", "generic": "Senna", "pronunciation": "SEN-uh", "brand": ["Senokot"], "class": "Stimulant laxative", "moa": "Anthraquinone glycoside metabolized by colonic bacteria to active compounds that stimulate colonic myenteric plexus, increasing peristalsis and reducing water/electrolyte reabsorption.", "indication": "Prevention and treatment of opioid-induced constipation; general constipation in elderly/palliative patients.", "dosage": "1 tablet (8.6 mg) PO once–BID, titrated as needed; first-line for opioid-induced/geriatric constipation prophylaxis", "examPoints": ["Standard prophylactic co-prescription with any regular opioid — opioid-induced constipation does not resolve with tolerance, so a stimulant laxative is started proactively, not reactively", "Stimulant laxatives (senna, bisacodyl) are preferred over bulk-forming agents (psyllium) for opioid-induced constipation — bulk formers can worsen obstruction risk in low-mobility/low-fluid-intake patients", "Onset typically 6-12 hours — dose timing (e.g., evening dose for morning effect) can be counselled", "Often combined with a stool softener (docusate) though evidence for docusate's added benefit is weak; senna alone is frequently sufficient", "Assess for red flags (no bowel movement several days, abdominal distension/pain) suggesting impaction or obstruction requiring escalation beyond routine laxative"], "counselling": ["Take regularly as scheduled while on opioid therapy, not just when constipated — prevention is the goal", "May cause abdominal cramping, especially at higher doses", "Adequate fluid intake helps stimulant laxatives work more comfortably", "Report no bowel movement for several days despite regular use, or significant abdominal pain/bloating", "Effect is usually seen within 6-12 hours of a dose"], "sideEffects": ["Abdominal cramping", "Diarrhea (if overdosed)", "Electrolyte disturbance with chronic excessive use", "Discoloration of urine (harmless)", "Rare: melanosis coli with prolonged daily use"]}, {"topic": "geri", "generic": "Metoclopramide (geriatric caution)", "pronunciation": "met-oh-KLOH-pruh-myd", "brand": ["Maxeran"], "class": "Dopamine D2-receptor antagonist / prokinetic", "moa": "Blocks central D2 receptors (antiemetic, chemoreceptor trigger zone) and enhances gastric motility/emptying via peripheral cholinergic sensitization.", "indication": "Nausea/vomiting, gastroparesis, sometimes used in palliative nausea; caution in elderly with Parkinsonian features.", "dosage": "5 mg PO/IV TID-QID (lower end of range); avoid/use cautiously in elderly due to extrapyramidal symptoms and tardive dyskinesia risk", "examPoints": ["Beers Criteria caution: extrapyramidal effects, particularly tardive dyskinesia risk with prolonged use — Health Canada/FDA limit duration to ≤12 weeks when possible", "Avoid or use very cautiously in Parkinson's disease — can worsen motor symptoms by blocking central dopamine receptors", "Common in palliative care for nausea related to gastroparesis/delayed gastric emptying (opioid-induced) specifically because of prokinetic action", "Renal dose adjustment needed in renal impairment", "Distinguish from haloperidol/domperidone in exam scenario — domperidone doesn't cross BBB well, so lower EPS risk, sometimes preferred in Parkinson's patients"], "counselling": ["Use for the shortest duration needed due to risk of movement side effects with long-term use", "Report any new tremor, stiffness, or unusual movements immediately", "Take before meals if prescribed for delayed stomach emptying/nausea related to eating", "Avoid if you have Parkinson's disease unless specifically directed by your specialist", "Report persistent restlessness or muscle spasms"], "sideEffects": ["Extrapyramidal symptoms (dystonia, akathisia)", "Drowsiness/fatigue", "Diarrhea", "Tardive dyskinesia (with prolonged use)", "Rare: neuroleptic malignant syndrome"]}, {"topic": "geri", "generic": "Dexamethasone (palliative use)", "pronunciation": "deks-uh-METH-uh-zohn", "brand": ["Decadron"], "class": "Corticosteroid (glucocorticoid)", "moa": "Binds glucocorticoid receptors to suppress inflammatory cytokine production; reduces peritumoral/vasogenic edema and has appetite-stimulating and mood-elevating effects.", "indication": "Palliative symptom control: appetite stimulation, reducing edema/pain from tumor mass effect, anti-inflammatory, sometimes antiemetic adjunct.", "dosage": "2–8 mg PO/SC once daily (morning dosing to reduce insomnia) for palliative symptom control (appetite, nausea, pain from mass effect)", "examPoints": ["High potency, minimal mineralocorticoid activity, long biological half-life — allows once-daily dosing, useful in palliative regimens", "Used for multiple overlapping palliative indications: appetite, energy, pain from nerve/organ compression, nausea adjunct, spinal cord compression emergencies", "Give in the morning/early afternoon to reduce insomnia risk (unlike immediate need for symptom control which may override timing)", "Long-term use risks: hyperglycemia, immunosuppression, myopathy, mood changes, GI ulceration — but risk/benefit reframed in palliative/end-of-life context (comfort over long-term risk)", "Do not stop abruptly after more than a few days' use — risk of adrenal insufficiency; taper per care plan"], "counselling": ["Take earlier in the day when possible to reduce trouble sleeping", "May increase appetite and energy — this is often a desired effect in palliative care", "Monitor blood sugar if diabetic, as this can raise glucose levels", "Do not stop suddenly without guidance — needs to be tapered if used for more than a few days", "Report mood changes, significant swelling, or signs of infection promptly"], "sideEffects": ["Hyperglycemia", "Insomnia/mood changes (euphoria or irritability)", "Increased appetite/fluid retention", "GI upset/ulcer risk", "Rare: adrenal suppression on withdrawal, myopathy with prolonged use"]}, {"topic": "geri", "generic": "Digoxin (elderly caution)", "pronunciation": "dih-JOKS-in", "brand": ["Toloxin"], "class": "Cardiac glycoside", "moa": "Inhibits the Na+/K+-ATPase pump in cardiac myocytes, increasing intracellular calcium and enhancing myocardial contractility (positive inotrope); also increases vagal tone slowing AV conduction.", "indication": "Rate control in atrial fibrillation and heart failure with reduced ejection fraction (adjunct), particularly when other agents insufficient.", "dosage": "0.0625–0.125 mg PO daily; reduced dosing required due to decreased renal clearance and increased sensitivity in elderly (narrow therapeutic index)", "examPoints": ["Beers Criteria caution: avoid doses >0.125 mg/day in most older adults due to narrow therapeutic index and reduced renal clearance with age", "Renally eliminated — dose must be adjusted for renal function; toxicity risk rises sharply with impaired renal clearance (common in elderly)", "Hypokalemia significantly increases digoxin toxicity risk — watch diuretic co-therapy closely (classic interaction pairing)", "Toxicity signs: nausea/vomiting, visual disturbances (yellow-green halos), arrhythmias (can be life-threatening) — classic exam symptom cluster", "Narrow therapeutic range requires periodic level monitoring, especially with renal function changes or new interacting drugs"], "counselling": ["Take exactly as prescribed - do not double up on a missed dose without checking first", "Report nausea, vomiting, visual changes (seeing yellow/green halos), or irregular heartbeat immediately", "Regular blood tests are needed to monitor drug levels and kidney function", "Tell your pharmacist about all new medications, including OTC, due to interaction risk", "Report symptoms of low potassium (weakness, cramps) especially if also taking a diuretic"], "sideEffects": ["Nausea/vomiting, anorexia", "Visual disturbances (yellow-green halos, blurred vision)", "Arrhythmias (bradycardia, various dysrhythmias)", "Confusion", "Toxicity risk increased by hypokalemia and renal impairment"]}, {"topic": "onc", "generic": "Methotrexate (high-dose oncology)", "pronunciation": "meth-oh-TREKS-ayt", "brand": ["Trexall", "generic IV/oral"], "class": "Antimetabolite (folate antagonist) / antineoplastic", "moa": "Inhibits dihydrofolate reductase, blocking conversion of dihydrofolate to tetrahydrofolate, which halts purine/pyrimidine synthesis and DNA replication in rapidly dividing cells.", "indication": "Hematologic malignancies (ALL, lymphoma), osteosarcoma, choriocarcinoma at high oncologic doses; contrast with low-dose weekly use in RA/psoriasis.", "dosage": "Highly individualized, up to several g/m² IV per protocol with leucovorin rescue and level monitoring (distinct from low-dose weekly RA dosing)", "examPoints": ["High-dose MTX requires leucovorin (folinic acid) rescue to prevent lethal toxicity — timing is critical, started ~24h after MTX infusion", "Requires aggressive IV hydration and urine alkalinization (target urine pH >=7) to prevent precipitation in renal tubules", "Monitor serum MTX levels on a nomogram to guide leucovorin dosing and duration", "NSAIDs, penicillins, and PPIs can reduce MTX renal clearance and increase toxicity — avoid around high-dose administration", "Fatal errors occur when weekly oral low-dose MTX (RA) is mistakenly given daily — a classic exam/practice safety trap distinct from oncology dosing"], "counselling": ["You will receive IV fluids and a rescue medication (leucovorin) on a strict schedule to protect your body from this drug's side effects", "Report mouth sores, unusual bruising/bleeding, fever, or reduced urination immediately", "Avoid alcohol and NSAIDs unless your oncology team approves them", "Blood work will be checked frequently to monitor kidney function and drug levels"], "sideEffects": ["Mucositis/mouth sores", "Myelosuppression", "Nausea/vomiting", "Nephrotoxicity", "Hepatotoxicity", "Pulmonary fibrosis (rare, chronic use)"]}, {"topic": "onc", "generic": "Doxorubicin", "pronunciation": "DOKS-oh-ROO-bih-sin", "brand": ["Adriamycin", "Caelyx (liposomal)"], "class": "Anthracycline antineoplastic", "moa": "Intercalates into DNA and inhibits topoisomerase II, causing DNA strand breaks; also generates free radicals contributing to both antitumor effect and cardiotoxicity.", "indication": "Breast cancer, lymphomas, leukemias, sarcomas — broad-spectrum solid tumor and hematologic use.", "dosage": "Individualized by protocol/BSA, typically 60–75 mg/m² IV per cycle q3wk; cumulative lifetime dose limit ~450–550 mg/m² (cardiotoxicity risk)", "examPoints": ["Cumulative lifetime dose limit (~450-550 mg/m2) due to irreversible dose-dependent cardiomyopathy risk", "Vesicant — severe tissue necrosis if extravasated; classic 'red devil' with red-tinged urine (harmless, distinct from hematuria)", "Baseline and periodic LVEF/ECHO or MUGA scan monitoring required", "Liposomal formulation (Caelyx) reduces cardiotoxicity but increases risk of hand-foot syndrome", "Dexrazoxane may be used as a cardioprotectant once nearing cumulative dose limits"], "counselling": ["Your urine may turn red/orange for a day or two after infusion — this is expected and not blood", "Report any new shortness of breath, swelling, or palpitations, as this drug can affect heart function over time", "Tell the nurse immediately if you feel burning or stinging at the IV site during infusion", "Hair loss is expected and usually reversible after treatment ends"], "sideEffects": ["Myelosuppression", "Nausea/vomiting", "Alopecia", "Red/orange urine", "Cardiotoxicity/cardiomyopathy (cumulative dose)", "Extravasation tissue necrosis"]}, {"topic": "onc", "generic": "Cisplatin", "pronunciation": "SIS-pluh-tin", "brand": ["Platinol", "generic"], "class": "Platinum-based alkylating-like antineoplastic", "moa": "Forms platinum-DNA crosslinks (intra- and inter-strand) that disrupt DNA structure and function, triggering apoptosis in rapidly dividing cells.", "indication": "Testicular, ovarian, bladder, lung, and head/neck cancers.", "dosage": "Individualized by protocol/BSA, typically 50–100 mg/m² IV per cycle q3–4wk, with aggressive pre/post-hydration to reduce nephrotoxicity", "examPoints": ["Highly emetogenic (high emetic risk tier) — requires triple/quadruple antiemetic prophylaxis (5-HT3 antagonist + NK1 antagonist + dexamethasone +/- olanzapine)", "Significant nephrotoxicity — requires aggressive pre/post-hydration with saline to protect kidneys", "Ototoxicity and peripheral neuropathy are dose-limiting and often irreversible", "Causes electrolyte wasting, especially magnesium and potassium — monitor and replace", "Distinguish from carboplatin, which is dosed by Calvert formula (AUC) and has less nephro/oto/neurotoxicity but more myelosuppression"], "counselling": ["You'll receive IV fluids before and after treatment to protect your kidneys", "Report any ringing in the ears, hearing changes, or tingling/numbness in hands and feet", "Anti-nausea medication will be given proactively since this drug commonly causes vomiting", "Blood tests will monitor your kidney function and electrolytes closely"], "sideEffects": ["Nephrotoxicity", "Ototoxicity", "Peripheral neuropathy", "Severe nausea/vomiting (highly emetogenic)", "Electrolyte wasting (Mg, K)", "Myelosuppression"]}, {"topic": "onc", "generic": "Tamoxifen", "pronunciation": "tuh-MOKS-ih-fen", "brand": ["Nolvadex", "generic"], "class": "Selective estrogen receptor modulator (SERM)", "moa": "Competitively binds estrogen receptors in breast tissue, acting as an antagonist to block estrogen-driven proliferation of hormone receptor-positive breast cancer cells; has partial agonist activity in endometrium and bone.", "indication": "Hormone receptor-positive (ER+) breast cancer treatment and prevention in high-risk patients; used in premenopausal women (aromatase inhibitors preferred post-menopause).", "dosage": "20 mg PO once daily for 5–10 years for hormone receptor-positive breast cancer (adjuvant or risk reduction)", "examPoints": ["Increases risk of endometrial cancer and VTE due to partial estrogen agonist activity in the uterus — counsel on abnormal vaginal bleeding", "CYP2D6 interaction is high-yield: strong CYP2D6 inhibitors (paroxetine, fluoxetine, bupropion) reduce conversion to active metabolite endoxifen — avoid concurrent use", "Standard duration is 5-10 years of therapy", "Increases bone density in postmenopausal women but can cause hot flashes/menopausal symptoms in all patients", "Contraindicated with concurrent warfarin due to increased bleeding risk and drug interaction"], "counselling": ["Report any unusual vaginal bleeding, leg swelling/pain, or shortness of breath right away", "Avoid certain antidepressants like paroxetine and fluoxetine unless your oncologist approves — they can make tamoxifen less effective", "Hot flashes and mood changes are common; discuss non-hormonal options if bothersome", "This medication is typically taken once daily for 5 to 10 years"], "sideEffects": ["Hot flashes", "Vaginal discharge/bleeding", "Increased VTE risk", "Endometrial hyperplasia/cancer (rare)", "Mood changes"]}, {"topic": "onc", "generic": "Pembrolizumab", "pronunciation": "pem-broh-LIZ-oo-mab", "brand": ["Keytruda"], "class": "Immune checkpoint inhibitor (anti-PD-1 monoclonal antibody)", "moa": "Blocks PD-1 receptor on T cells, preventing tumor cells from evading immune destruction via the PD-1/PD-L1 pathway, thereby restoring T-cell mediated antitumor immune response.", "indication": "Melanoma, non-small cell lung cancer, and numerous other PD-L1-expressing solid tumors.", "dosage": "200 mg IV q3wk, or 400 mg IV q6wk, per approved protocol/indication", "examPoints": ["Hallmark toxicity is immune-related adverse events (irAEs) — colitis, pneumonitis, hepatitis, endocrinopathies (thyroiditis, hypophysitis, adrenal insufficiency) — from immune overactivation, not classic cytotoxic chemo effects", "irAEs are managed with corticosteroids; severe cases require holding/discontinuing therapy", "Does NOT cause classic myelosuppression/alopecia like cytotoxic chemo — different counselling focus", "Patients must be counselled to report ANY new symptom (diarrhea, rash, cough, fatigue) as potentially immune-related, since onset can be delayed weeks to months", "Given as IV infusion on a fixed-dose schedule (e.g., every 3 or 6 weeks)"], "counselling": ["This medication works by boosting your immune system to attack cancer cells, not by directly killing cells like traditional chemo", "Report any new diarrhea, rash, cough, extreme fatigue, or unusual symptoms right away, even weeks after your infusion — the immune system can overreact and affect other organs", "You may need regular blood tests to check thyroid and other organ function", "Unlike traditional chemotherapy, hair loss and severe nausea are not typical with this drug"], "sideEffects": ["Fatigue", "Rash/pruritus", "Diarrhea/colitis (immune-mediated)", "Pneumonitis (immune-mediated)", "Endocrinopathies (thyroid, adrenal, pituitary)", "Hepatitis (immune-mediated)"]}, {"topic": "onc", "generic": "Ondansetron", "pronunciation": "on-DAN-seh-tron", "brand": ["Zofran"], "class": "5-HT3 receptor antagonist (antiemetic)", "moa": "Blocks serotonin (5-HT3) receptors both centrally in the chemoreceptor trigger zone and peripherally on vagal afferents in the GI tract, preventing chemotherapy-induced nausea/vomiting signaling.", "indication": "Prevention of chemotherapy-induced and postoperative nausea and vomiting (CINV/PONV).", "dosage": "8–16 mg PO/IV before chemotherapy, may repeat q8h PRN; max single dose 16 mg PO (QT risk)", "examPoints": ["First-line for moderate-to-highly emetogenic chemo, typically combined with dexamethasone +/- NK1 antagonist (aprepitant) for high-risk regimens", "Causes dose-dependent QT prolongation — caution with other QT-prolonging drugs, electrolyte abnormalities, or cardiac history", "Common and classic side effect is constipation and headache", "Available PO, IV, ODT (orally disintegrating tablet) — useful when patient has active vomiting", "Better for acute (first 24h) CINV; less effective alone for delayed CINV, where NK1 antagonists/olanzapine add benefit"], "counselling": ["Take this medication before your chemotherapy as directed to prevent nausea rather than treat it once it starts", "Headache and constipation are the most common side effects — a stool softener may help", "Tell your pharmacist about any heart rhythm problems or other medications that affect heart rhythm", "The dissolving tablet doesn't need water and works well if you're already feeling nauseated"], "sideEffects": ["Headache", "Constipation", "QT prolongation", "Dizziness", "Fatigue"]}, {"topic": "onc", "generic": "Filgrastim (G-CSF)", "pronunciation": "fil-GRA-stim", "brand": ["Neupogen", "Grastofil (biosimilar)"], "class": "Granulocyte colony-stimulating factor (recombinant)", "moa": "Stimulates proliferation, differentiation, and maturation of neutrophil precursors in bone marrow, and enhances function of mature neutrophils, accelerating neutrophil recovery after myelosuppressive chemotherapy.", "indication": "Prevention/treatment of chemotherapy-induced neutropenia and febrile neutropenia risk reduction; stem cell mobilization prior to transplant.", "dosage": "5 mcg/kg/day SC starting 24h after chemotherapy, continued until ANC recovery", "examPoints": ["Should NOT be given within 24 hours before or after cytotoxic chemotherapy — timing error is a classic exam trap since it can worsen effects on rapidly dividing marrow cells during chemo administration", "Bone pain is the most common and characteristic side effect, managed with antihistamines/analgesics (not NSAIDs preferred first-line by some, but acetaminophen commonly used)", "Pegfilgrastim (Neulasta) is the long-acting form given once per cycle, ~24h after chemo, vs daily filgrastim", "Monitor CBC/ANC; used per febrile neutropenia risk-based guidelines (e.g., >20% risk regimens warrant primary prophylaxis)", "Rare but serious: splenic rupture — counsel on left upper quadrant/shoulder pain"], "counselling": ["This injection helps your body make white blood cells to fight infection after chemotherapy", "Bone pain, especially in the back, hips, and long bones, is common — an over-the-counter pain reliever like acetaminophen can help", "This is typically given the day after chemotherapy, not on the same day", "Seek urgent care for sudden left-sided abdominal or shoulder pain"], "sideEffects": ["Bone pain", "Injection site reaction", "Fever", "Splenic rupture (rare)", "Leukocytosis"]}, {"topic": "onc", "generic": "Dalteparin", "pronunciation": "dal-TEP-uh-rin", "brand": ["Fragmin"], "class": "Low molecular weight heparin (LMWH)", "moa": "Binds antithrombin III, potentiating its inhibition of Factor Xa (predominantly) and, to a lesser extent, thrombin (Factor IIa), preventing clot propagation.", "indication": "Treatment and secondary prevention of cancer-associated venous thromboembolism (CAT); historically preferred over warfarin in active cancer.", "dosage": "200 units/kg SC once daily (max 18,000 units) for cancer-associated VTE treatment, per protocol duration", "examPoints": ["LMWH (dalteparin) was long the guideline-preferred anticoagulant for cancer-associated thrombosis due to superior efficacy over warfarin in this population", "Renally cleared — requires dose adjustment/caution in renal impairment (CrCl <30), unlike some DOACs' labeling nuances", "No routine monitoring needed (unlike UFH); anti-Xa levels may be used in renal impairment, obesity, or pregnancy", "Subcutaneous injection — rotate sites, do not aspirate, do not rub after injection", "Risk of heparin-induced thrombocytopenia (HIT) is lower than UFH but still possible — monitor platelets"], "counselling": ["This is a self-injected blood thinner given once daily under the skin, usually in the abdomen", "Rotate injection sites and do not rub the area afterward to reduce bruising", "Report unusual bruising, bleeding gums, blood in urine/stool, or severe headache", "Do not stop this medication without discussing with your oncology team, as cancer increases clot risk"], "sideEffects": ["Injection site bruising/hematoma", "Bleeding", "Thrombocytopenia (including HIT, rare)", "Elevated liver enzymes (transient)"]}, {"topic": "onc", "generic": "Apixaban", "pronunciation": "uh-PIKS-uh-ban", "brand": ["Eliquis"], "class": "Direct oral anticoagulant (DOAC) — Factor Xa inhibitor", "moa": "Directly and selectively inhibits Factor Xa, both free and clot-bound, interrupting the coagulation cascade and preventing thrombin generation and clot formation.", "indication": "Cancer-associated venous thromboembolism (increasingly preferred alternative to LMWH in guidelines for patients without GI/GU malignancy or high bleeding risk); also AF stroke prevention, VTE treatment/prophylaxis.", "dosage": "5 mg PO BID for cancer-associated VTE (alternative to LMWH per current guidelines); reduce per standard criteria", "examPoints": ["Guidelines now support DOACs (apixaban, rivaroxaban) as alternatives to LMWH for cancer-associated thrombosis, EXCEPT in GI/GU luminal cancers where LMWH is preferred due to higher bleeding risk with DOACs", "No routine coagulation monitoring required; no reliable reversal agent widely available compared to warfarin (andexanet alfa exists but limited access)", "Significant interactions with strong CYP3A4/P-gp inhibitors (azole antifungals, some chemo agents) and inducers — check for drug interactions with the cancer regimen", "Renal/hepatic dosing considerations; use caution in severe impairment", "Oral convenience is a key advantage over LMWH injections, improving quality of life/adherence in cancer patients"], "counselling": ["Take this tablet twice daily, with or without food, at consistent times", "Report any unusual bleeding, black/tarry stools, blood in urine, or severe bruising", "Tell every healthcare provider and dentist that you're on this blood thinner before any procedure", "Do not stop this medication abruptly without speaking to your cancer care team"], "sideEffects": ["Bleeding (GI, GU)", "Bruising", "Anemia", "Nausea (less common)"]}, {"topic": "onc", "generic": "Ferrous sulfate / Iron supplements", "pronunciation": "FAIR-us SUL-fayt", "brand": ["Feramax (polysaccharide iron complex)", "generic ferrous sulfate/gluconate/fumarate"], "class": "Oral iron supplement", "moa": "Provides elemental iron substrate for hemoglobin synthesis, correcting iron-deficiency anemia which is common in cancer patients from chronic disease, GI blood loss, or chemotherapy-related nutritional deficits.", "indication": "Iron-deficiency anemia, often adjunct in cancer-related anemia workup before/with erythropoiesis-stimulating agents.", "dosage": "300 mg (60 mg elemental iron) PO once–TID daily for iron-deficiency anemia, often chemo-related; take on empty stomach if tolerated", "examPoints": ["Should be taken on an empty stomach for best absorption, but often taken with food to reduce GI upset — counsel on the trade-off", "Vitamin C (ascorbic acid) enhances absorption; avoid concurrent calcium, antacids, PPIs, tetracyclines, and levothyroxine (space by 2-4 hours) as they impair absorption", "Classic side effects: constipation, dark/black stools (distinguish benign iron-related black stool from true melena)", "Elemental iron content varies by salt: ferrous sulfate ~20%, ferrous gluconate ~12%, ferrous fumarate ~33% — relevant for dosing calculations", "In cancer patients, distinguish iron-deficiency anemia from anemia of chronic disease/chemo-induced anemia — iron studies (ferritin, TSAT) guide need for IV vs oral iron"], "counselling": ["Take on an empty stomach if tolerated for best absorption; taking with a small amount of food is fine if it upsets your stomach", "Your stools may turn dark or black — this is expected and not necessarily a concern, but report if stools become tarry or you have new abdominal pain", "Avoid taking at the same time as antacids, calcium supplements, or thyroid medication — space these by a few hours", "Taking with orange juice or vitamin C can improve absorption"], "sideEffects": ["Constipation", "Dark/black stools", "Nausea/GI upset", "Metallic taste", "Teeth staining (liquid formulations)"]}, {"topic": "onc", "generic": "Epoetin alfa", "pronunciation": "eh-POH-eh-tin AL-fuh", "brand": ["Eprex"], "class": "Erythropoiesis-stimulating agent (ESA, recombinant human erythropoietin)", "moa": "Mimics endogenous erythropoietin, binding erythropoietin receptors on erythroid progenitor cells in bone marrow to stimulate red blood cell production.", "indication": "Chemotherapy-induced anemia (non-curative intent settings) to reduce transfusion needs.", "dosage": "Start 150 units/kg SC 3x/week (or 40,000 units weekly) for chemotherapy-induced anemia, titrated to Hgb target, avoiding over-correction", "examPoints": ["Boxed warning: increases risk of thrombosis/VTE and may shorten survival or increase tumor progression in some cancers — used cautiously, only in palliative/non-curative chemo settings, at lowest dose to avoid transfusion", "Should NOT be used when the goal of chemotherapy is cure, per most guidelines/product warnings", "Iron stores must be adequate (check ferritin/TSAT) before and during therapy — supplement iron if deficient, as ESAs are ineffective without adequate iron", "Target hemoglobin should not exceed ~120 g/L due to cardiovascular/thrombotic risk with over-correction", "Distinguish from filgrastim (G-CSF, for neutrophils) — epoetin acts on the erythroid line for red cells"], "counselling": ["This medication stimulates your body to make more red blood cells to reduce fatigue from chemotherapy-related anemia and reduce the need for transfusions", "Report leg swelling, chest pain, or shortness of breath, as this drug can increase clotting risk", "You may need iron supplementation alongside this medication for it to work properly", "Regular blood tests will monitor your hemoglobin to keep it in a safe target range"], "sideEffects": ["Hypertension", "Thrombosis/VTE risk", "Headache", "Injection site reaction", "Possible tumor progression risk (boxed warning)"]}, {"topic": "onc", "generic": "Vincristine", "pronunciation": "vin-KRIS-teen", "brand": ["Oncovin", "generic"], "class": "Vinca alkaloid antineoplastic (mitotic inhibitor)", "moa": "Binds tubulin and inhibits microtubule assembly, arresting cell division at metaphase, leading to apoptosis of dividing cancer cells.", "indication": "Leukemias, lymphomas (e.g., part of CHOP/R-CHOP regimen), pediatric solid tumors.", "dosage": "Individualized by protocol/BSA, typically 1.4 mg/m² IV per cycle (capped at 2 mg total dose); vesicant — IV administration only, never intrathecal", "examPoints": ["FATAL if given intrathecally (must be administered IV ONLY) — a classic, high-stakes exam/practice safety point; vials should be clearly labeled and dispensed separately from intrathecal medications", "Dose-limiting toxicity is peripheral neuropathy (unlike most chemo where myelosuppression is dose-limiting) — has minimal myelosuppression relative to other agents", "Potent vesicant — extravasation causes severe tissue damage", "Causes constipation/paralytic ileus from autonomic neuropathy — prophylactic bowel regimen often recommended", "'Vincristine ceiling dose' concept — often capped (e.g., 2 mg) regardless of BSA-based calculation to limit neurotoxicity"], "counselling": ["Report numbness, tingling, or weakness in your hands or feet, as nerve side effects are common with this drug", "This drug commonly causes constipation — a bowel regimen (stool softener/laxative) may be started proactively", "Tell the nurse immediately if you feel pain or burning at the IV injection site", "This medication is only ever given into a vein, never into the spinal fluid"], "sideEffects": ["Peripheral neuropathy", "Constipation/ileus", "Alopecia", "Jaw pain", "Extravasation tissue necrosis", "Mild myelosuppression"]}, {"topic": "onc", "generic": "Rituximab", "pronunciation": "ri-TUK-sih-mab", "brand": ["Rituxan", "Truxima (biosimilar)"], "class": "Anti-CD20 monoclonal antibody", "moa": "Binds the CD20 antigen on B-lymphocytes, triggering antibody-dependent and complement-mediated cytotoxicity as well as apoptosis, depleting both malignant and normal B cells.", "indication": "Non-Hodgkin lymphoma (e.g., component of R-CHOP), chronic lymphocytic leukemia, and some autoimmune conditions.", "dosage": "375 mg/m² IV once weekly x4 doses (or per combination protocol schedule), premedicate to reduce infusion reactions", "examPoints": ["Requires premedication with acetaminophen, antihistamine +/- corticosteroid to reduce infusion-related reactions, which are most common with the FIRST infusion", "Screen for hepatitis B before starting — risk of HBV reactivation due to B-cell depletion/immunosuppression", "Causes prolonged B-cell depletion, increasing infection risk; live vaccines should be avoided during and after treatment until B-cell recovery", "Infusion rate is typically slow and gradually escalated to reduce reaction risk", "'R' in R-CHOP regimen for lymphoma — high-yield regimen recognition"], "counselling": ["You'll receive premedications like acetaminophen and an antihistamine before your infusion to reduce reaction risk", "Tell the nurse immediately about any fever, chills, itching, or breathing difficulty during the infusion", "This medication increases infection risk by lowering certain white blood cells — report any signs of infection promptly", "Live vaccines should be avoided while on this treatment — check with your care team before any vaccination"], "sideEffects": ["Infusion-related reactions (fever, chills, rash)", "Increased infection risk", "Hepatitis B reactivation risk", "Myelosuppression", "Progressive multifocal leukoencephalopathy (rare, serious)"]}, {"topic": "onc", "generic": "Imatinib", "pronunciation": "ih-MAT-ih-nib", "brand": ["Gleevec"], "class": "Tyrosine kinase inhibitor (BCR-ABL inhibitor)", "moa": "Selectively inhibits the BCR-ABL tyrosine kinase produced by the Philadelphia chromosome translocation, blocking the abnormal signaling that drives uncontrolled proliferation of leukemic cells.", "indication": "Chronic myeloid leukemia (CML, Philadelphia chromosome-positive), certain GISTs.", "dosage": "400 mg PO once daily (CML chronic phase); up to 600–800 mg/day for advanced disease/GIST, taken with food and large glass of water", "examPoints": ["Targeted oral therapy — transformed CML from a fatal disease to a chronic, manageable one; classic exam link between Philadelphia chromosome (BCR-ABL) and imatinib", "Take with food and a large glass of water to minimize GI upset", "Significant CYP3A4 drug interactions — many interactions with azole antifungals, grapefruit juice, and other CYP3A4 substrates/inhibitors/inducers", "Fluid retention/edema (including periorbital edema) is a characteristic and common side effect", "Requires ongoing molecular monitoring (BCR-ABL transcript levels via PCR) rather than just CBC, to assess treatment response"], "counselling": ["Take this medication with food and a full glass of water to reduce stomach upset", "Puffiness around the eyes or swelling in the legs is a common but usually manageable side effect — report if severe", "Avoid grapefruit juice, as it can interact with this medication", "You'll need regular blood tests, including specialized tests, to track how well the treatment is working at the molecular level"], "sideEffects": ["Fluid retention/edema (periorbital, peripheral)", "Nausea", "Muscle cramps", "Myelosuppression", "Hepatotoxicity", "Rash"]}, {"topic": "onc", "generic": "Leucovorin (folinic acid)", "pronunciation": "loo-koh-VOR-in", "brand": ["generic"], "class": "Folate analog / chemoprotective agent", "moa": "Reduced folate that bypasses dihydrofolate reductase, replenishing the intracellular folate pool needed for DNA synthesis in normal cells, thereby 'rescuing' healthy cells from methotrexate toxicity.", "indication": "Rescue therapy after high-dose methotrexate; also used to potentiate 5-fluorouracil efficacy in colorectal cancer regimens (e.g., FOLFOX, FOLFIRI).", "dosage": "Rescue dosing individualized to methotrexate level/timing post high-dose MTX (typically 10–15 mg/m² IV/PO q6h until MTX level safe)", "examPoints": ["Must NOT be confused with leuprolide (GnRH agonist) — a classic look-alike/sound-alike (LASA) medication error pair on exams", "Timing relative to methotrexate is critical — started per protocol (commonly ~24h post-MTX) and continued until MTX levels fall below toxic threshold", "In FOLFOX/FOLFIRI regimens, leucovorin enhances 5-FU's inhibition of thymidylate synthase — a different purpose than MTX rescue", "Levoleucovorin is the active stereoisomer form, dosed at half the leucovorin dose", "Delayed or inadequate leucovorin rescue after high-dose MTX can be fatal — pharmacists play a key verification role"], "counselling": ["This medication protects your healthy cells from the effects of the chemotherapy drug methotrexate — it's important to take/receive it exactly on schedule", "Do not skip or delay doses of this rescue medication, even if you feel fine", "Confirm with your pharmacist which drug you're receiving, as its name sounds similar to another unrelated hormone medication (leuprolide)", "Report mouth sores, unusual bruising, or reduced urination, which may signal inadequate rescue"], "sideEffects": ["Generally well tolerated", "Allergic reaction (rare)", "Nausea (mild)"]}, {"topic": "immun", "generic": "Influenza vaccine (inactivated, IIV)", "pronunciation": "in-floo-EN-zuh", "brand": ["Fluzone", "Flulaval", "Fluad (high-dose adjuvanted, 65+)"], "class": "Inactivated (split-virus/subunit) vaccine", "moa": "Contains inactivated influenza virus antigens (typically quadrivalent, covering 2 A strains and 2 B strains) that stimulate antibody production against hemagglutinin, providing season-specific protection.", "indication": "Annual prevention of seasonal influenza, recommended for essentially all persons 6 months and older, especially high-risk groups.", "dosage": "0.5 mL IM, single dose annually (adults); high-dose formulation available for age ≥65", "examPoints": ["Reformulated annually based on WHO strain predictions — needs yearly re-vaccination, unlike many childhood vaccines", "Egg-allergic patients can still receive standard-dose flu vaccine (no special precautions needed per current NACI guidance, even with severe egg allergy) — classic updated exam point", "High-dose/adjuvanted formulations (e.g., Fluad, Fluzone High-Dose) preferred in adults 65+ for improved immunogenicity", "Inactivated vaccine — safe in pregnancy and immunocompromised patients (unlike live attenuated nasal spray FluMist)", "Best given in fall (Oct-Nov) before flu season peaks; can be co-administered with other vaccines"], "counselling": ["You need this vaccine every year because the flu virus changes and protection wanes over time", "Egg allergy is no longer considered a contraindication to the standard flu shot", "Soreness at the injection site and mild fatigue for a day or two are common and expected", "This vaccine cannot give you the flu, since it does not contain live virus"], "sideEffects": ["Injection site soreness", "Low-grade fever", "Myalgia", "Fatigue", "Rarely, Guillain-Barre syndrome (very rare)"]}, {"topic": "immun", "generic": "Pneumococcal vaccines (PCV15/PCV20 conjugate, PPSV23 polysaccharide)", "pronunciation": "noo-moh-KOK-ul", "brand": ["Prevnar 13/20 (PCV13/20)", "Pneumovax 23 (PPSV23)"], "class": "Conjugate and polysaccharide bacterial vaccines", "moa": "PCV vaccines conjugate pneumococcal capsular polysaccharide to a carrier protein, inducing T-cell dependent immune response with immunologic memory; PPSV23 is a pure polysaccharide inducing a T-cell independent response without strong memory/boosting in young children.", "indication": "Prevention of invasive pneumococcal disease (pneumonia, meningitis, bacteremia) — routine infant series, and adults 65+ or high-risk (immunocompromised, chronic disease, asplenia).", "dosage": "0.5 mL IM/SC single dose per product; sequencing/timing of PCV then PPSV23 depends on age and risk factors per current guidelines", "examPoints": ["Conjugate vaccines (PCV) generate immunologic memory and are effective in infants <2 years, unlike pure polysaccharide (PPSV23) which is poorly immunogenic in that age group", "Sequencing matters when both are indicated: give PCV before PPSV23 (conjugate primes the immune system better first)", "High-risk adults (asplenia, immunocompromise, CSF leak, cochlear implant) may need both vaccine types with specific minimum intervals (often 8 weeks PCV-to-PPSV23, 1 year PPSV23-to-PCV in some protocols)", "PPSV23 covers more serotypes (23) but PCV offers better immune memory/herd effect for its covered serotypes", "Newer PCV20 may eliminate need for follow-up PPSV23 in some adult schedules — evolving NACI guidance is testable"], "counselling": ["This vaccine protects against serious pneumococcal infections like pneumonia and meningitis", "If you need both types of pneumococcal vaccine, they must be spaced apart in a specific order and timing — your pharmacist will confirm the schedule", "Sore arm and mild fatigue are the most common side effects", "People with certain chronic conditions or those 65 and older are specifically recommended to receive this vaccine"], "sideEffects": ["Injection site pain/redness", "Fatigue", "Myalgia", "Fever (more common in children)", "Headache"]}, {"topic": "immun", "generic": "Zoster vaccine (recombinant)", "pronunciation": "ZOS-ter", "brand": ["Shingrix"], "class": "Recombinant subunit vaccine (non-live)", "moa": "Contains a glycoprotein E antigen with an adjuvant system to boost varicella-zoster-specific immunity, reducing shingles/post-herpetic neuralgia risk.", "indication": "Shingles (herpes zoster) prevention in adults 50 years and older, including immunocompromised patients.", "dosage": "0.5 mL IM, 2-dose series given 2–6 months apart, recommended for adults ≥50 years", "examPoints": ["Non-live (recombinant) vaccine — safe in immunocompromised patients, unlike the older live zoster vaccine", "Given as a 2-dose series, 2-6 months apart", "Recommended even in patients with a prior shingles episode or prior live zoster vaccine", "Higher local reactogenicity (sore arm, myalgia, fatigue) than most other adult vaccines — counsel patients to expect this"], "counselling": ["You'll need two doses spaced 2-6 months apart for full protection", "Expect a sore arm and possibly fatigue/muscle aches for a day or two after each dose — this is normal", "Recommended even if you've had shingles before or had the older shingles vaccine"], "sideEffects": ["Injection site pain/redness/swelling", "Myalgia", "Fatigue", "Headache", "Fever (less common)"]}, {"topic": "immun", "generic": "Tdap (tetanus, diphtheria, acellular pertussis)", "pronunciation": "TEE-dap", "brand": ["Adacel", "Boostrix"], "class": "Inactivated toxoid/acellular bacterial vaccine", "moa": "Contains tetanus and diphtheria toxoids plus acellular pertussis antigens, stimulating antitoxin/antibody production against the respective toxins and bacterial components.", "indication": "Booster immunization against tetanus, diphtheria, pertussis; routine adult booster every 10 years, and specifically recommended each pregnancy.", "dosage": "0.5 mL IM single dose, then Td booster every 10 years; 1 dose Tdap in each pregnancy regardless of prior history", "examPoints": ["Recommended in EVERY pregnancy, ideally between 27-32 weeks gestation, to passively transfer pertussis antibodies to the newborn before their own vaccination series starts", "Routine adult booster interval is every 10 years (Td or Tdap); at least one adult dose should be Tdap rather than Td to maintain pertussis immunity", "Wound management: tetanus-prone wounds may require earlier booster if >5 years since last dose (vs 10-year routine interval)", "Inactivated — safe in pregnancy and immunocompromised patients", "Can be co-administered with other vaccines (e.g., flu, COVID) at different injection sites"], "counselling": ["If you're pregnant, this vaccine is recommended during every pregnancy, ideally in the third trimester, to protect your newborn from whooping cough", "Routine booster is needed every 10 years for adults", "For a dirty or deep wound, you may need this sooner than the usual 10-year mark if it's been more than 5 years since your last dose", "Local soreness at the injection site is common and temporary"], "sideEffects": ["Injection site pain/swelling", "Fever", "Fatigue", "Headache", "Arthus-type reaction (rare, with frequent dosing)"]}, {"topic": "immun", "generic": "MMR (measles, mumps, rubella)", "pronunciation": "em-em-AR", "brand": ["Priorix", "M-M-R II"], "class": "Live attenuated viral vaccine", "moa": "Contains live attenuated measles, mumps, and rubella viruses that replicate minimally in the host, stimulating robust humoral and cell-mediated immunity without causing clinical disease.", "indication": "Routine childhood immunization and catch-up/susceptible adult immunization against measles, mumps, rubella.", "dosage": "0.5 mL SC, 2-dose series (routine childhood) or catch-up in susceptible adults ≥4 weeks apart; contraindicated in pregnancy/immunosuppression", "examPoints": ["LIVE vaccine — contraindicated in pregnancy and significant immunocompromise; pregnancy must be avoided for at least 1 month after vaccination", "Routine schedule: first dose at 12 months, second dose at 18 months (or per provincial schedule, sometimes 4-6 years)", "Live vaccines given on the same day are fine, but if not same day, must be spaced at least 4 weeks apart from other live vaccines", "Contraindicated with current severe egg allergy is NOT accurate for MMR — MMR is grown in chick fibroblast cells and is generally safe even in egg-allergic patients (unlike old yellow fever/flu myths) — a common exam distractor", "Antibody-containing blood products (e.g., immunoglobulin) can interfere with MMR immune response — spacing required (weeks to months depending on product/dose)"], "counselling": ["This is a live vaccine, so you should avoid becoming pregnant for at least one month after receiving it", "Two doses are needed for full protection, typically in early childhood", "Mild fever and rash 1-2 weeks after vaccination can occur as the vaccine virus replicates — this is expected, not an infection", "If you've recently received antibody products like immunoglobulin, timing of this vaccine may need to be adjusted"], "sideEffects": ["Fever", "Mild rash", "Injection site reaction", "Transient joint pain (rubella component, more common in adult women)", "Thrombocytopenia (rare)"]}, {"topic": "immun", "generic": "HPV vaccine (9-valent)", "pronunciation": "aych-pee-VEE", "brand": ["Gardasil 9"], "class": "Recombinant virus-like particle (VLP) vaccine (non-live)", "moa": "Contains recombinant L1 capsid proteins from 9 HPV types that self-assemble into virus-like particles, inducing neutralizing antibodies without infectious viral DNA — cannot cause HPV infection.", "indication": "Prevention of HPV-related cancers (cervical, anal, oropharyngeal) and genital warts; recommended for all genders starting around age 9-12.", "dosage": "0.5 mL IM; 2-dose series (0, 6–12 months) if started before age 15, 3-dose series (0, 2, 6 months) if started at 15+ or immunocompromised", "examPoints": ["Non-live vaccine despite common misconception — cannot cause HPV infection", "Dosing schedule depends on age at first dose: 2 doses (6 months apart) if started before age 15; 3 doses if started at 15+ or immunocompromised", "Most effective when given before sexual debut/HPV exposure, but still recommended for older individuals with some benefit", "Recommended for all genders (not just females) to reduce transmission and prevent anal/oropharyngeal cancers and genital warts in males too", "Syncope (fainting) is a notable post-injection risk in adolescents — observe for 15 minutes after administration"], "counselling": ["The number of doses you need depends on your age when you start the series — 2 doses if under 15, 3 doses if 15 or older", "This vaccine works best when given before any exposure to HPV, which is why it's recommended in early adolescence", "You'll be asked to sit for about 15 minutes after the injection since fainting can occur, especially in teens", "This vaccine protects against several HPV-related cancers, not just cervical cancer, and is recommended for all genders"], "sideEffects": ["Injection site pain/swelling", "Headache", "Fever", "Syncope (especially adolescents)", "Dizziness"]}, {"topic": "immun", "generic": "Hepatitis A vaccine", "pronunciation": "hep-uh-TY-tis AY", "brand": ["Havrix", "Avaxim", "Twinrix (combined with Hep B)"], "class": "Inactivated viral vaccine", "moa": "Contains inactivated hepatitis A virus that stimulates protective antibody production against the virus, which is transmitted via fecal-oral route.", "indication": "Travel to endemic areas, occupational exposure, chronic liver disease, MSM, and other at-risk groups.", "dosage": "1 mL (adult) IM, 2-dose series at 0 and 6–12 months", "examPoints": ["Standard 2-dose series, 6-12 months apart, for long-lasting immunity (~20+ years, possibly lifelong)", "A single dose provides good short-term protection, useful for last-minute travelers, but the series should be completed for durable immunity", "Twinrix (combined Hep A/B) has a different schedule (0, 1, 6 months, or accelerated 0/7/21 days + 12-month booster for last-minute travel)", "Ideally given at least 2 weeks before travel to endemic regions for optimal antibody response, though even last-minute dosing offers some protection", "Inactivated — safe in pregnancy and immunocompromised individuals"], "counselling": ["Two doses spaced several months apart give long-lasting protection, but even one dose offers good short-term protection if you're travelling soon", "Ideally get this vaccine at least 2 weeks before you travel to allow your body to build immunity", "This vaccine is recommended for travel to areas with unclean food/water risk, as hepatitis A spreads through contaminated food and water", "There's a combination vaccine that also covers hepatitis B if you need protection against both"], "sideEffects": ["Injection site soreness", "Headache", "Fatigue", "Low-grade fever", "Loss of appetite (children)"]}, {"topic": "immun", "generic": "Hepatitis B vaccine", "pronunciation": "hep-uh-TY-tis BEE", "brand": ["Engerix-B", "Recombivax HB", "Twinrix (combined with Hep A)"], "class": "Recombinant subunit viral vaccine", "moa": "Contains recombinant hepatitis B surface antigen (HBsAg) produced in yeast, stimulating antibody (anti-HBs) production against the viral surface antigen without risk of infection.", "indication": "Universal infant immunization; catch-up for unvaccinated adults; high-risk groups (healthcare workers, travelers to endemic areas, dialysis patients, sexual/household contacts of infected persons).", "dosage": "1 mL (adult) IM, 3-dose series at 0, 1, and 6 months (accelerated schedules available for travel)", "examPoints": ["Standard schedule is 3 doses (0, 1, 6 months); accelerated schedules exist for imminent travel/exposure", "Post-vaccination anti-HBs titer testing recommended for healthcare workers and dialysis patients to confirm seroconversion", "Non-responders may need a repeat series or higher-dose formulation", "Part of routine infant immunization schedule in Canada, often as part of combination vaccines", "Safe in pregnancy (inactivated/recombinant, no live virus)"], "counselling": ["The standard series is three doses over six months for long-term protection", "Healthcare workers often need a blood test after the series to confirm the vaccine worked", "This vaccine protects against a virus that can cause chronic liver disease and liver cancer", "It is safe to receive during pregnancy since it does not contain live virus"], "sideEffects": ["Injection site soreness", "Fatigue", "Headache", "Low-grade fever", "Rare anaphylaxis"]}, {"topic": "immun", "generic": "Meningococcal vaccines (MenC, MenACWY, MenB)", "pronunciation": "meh-NIN-jih-KOK-ul", "brand": ["Menactra/Nimenrix (MenACWY)", "Bexsero (MenB)"], "class": "Conjugate and recombinant protein bacterial vaccines", "moa": "MenACWY conjugate vaccines link capsular polysaccharide from serogroups A, C, W, Y to a carrier protein for T-cell dependent immunity; MenB (Bexsero) uses recombinant surface protein antigens since serogroup B's capsule is poorly immunogenic.", "indication": "Routine adolescent immunization, travelers to meningitis belt (sub-Saharan Africa) or Hajj pilgrims (mandatory MenACWY), asplenia/complement deficiency, first-year university students in residence.", "dosage": "0.5 mL IM; dosing schedule (1–3 doses) depends on specific product, age, and risk category", "examPoints": ["MenACWY is REQUIRED (not just recommended) for Hajj/Umrah pilgrimage travelers to Saudi Arabia — a specific mandatory travel vaccine exam point", "'Meningitis belt' of sub-Saharan Africa is a key travel indication, especially during dry season (Dec-June)", "MenB (Bexsero) covers serogroup B, NOT covered by conjugate ACWY vaccines — needed separately, particularly for outbreak situations or high-risk conditions", "First-year students in residence and military recruits are specific high-risk groups due to close-contact living", "Asplenia/complement deficiency patients need both MenACWY and MenB, often with booster doses due to sustained high risk"], "counselling": ["If you're travelling to Saudi Arabia for Hajj or Umrah, this vaccine is a mandatory entry requirement, not just a recommendation", "There are different vaccines for different meningococcal strains — your pharmacist will determine which one(s) you need based on your risk factors", "First-year students living in residence are at higher risk due to close living quarters and are specifically recommended to get vaccinated", "Sore arm and mild fever are the most common side effects"], "sideEffects": ["Injection site pain", "Fever", "Headache", "Fatigue", "Myalgia"]}, {"topic": "immun", "generic": "RSV vaccine/monoclonal antibody", "pronunciation": "ar-es-VEE", "brand": ["Arexvy/Abrysvo (older adult vaccines)", "Synagis (palivizumab, infant mAb prophylaxis)", "Beyfortus (nirsevimab, infant mAb)"], "class": "Protein subunit vaccine (older adults) / monoclonal antibody prophylaxis (infants)", "moa": "Adult vaccines (Arexvy/Abrysvo) contain stabilized RSV fusion (F) glycoprotein to induce active neutralizing antibody production; infant products (palivizumab/nirsevimab) are monoclonal antibodies providing passive, immediate protection without stimulating the infant's own immune system.", "indication": "Older adults (60+) for RSV lower respiratory tract disease prevention; infants/young children at high risk for RSV-related severe illness (premature, cardiac/lung disease, or now broader nirsevimab programs for all infants).", "dosage": "Vaccine: 0.5 mL IM single dose for adults ≥60 (or per current age/risk guidance); nirsevimab (monoclonal) dosed by weight for infants", "examPoints": ["Distinguish active vaccination (older adults, builds own immunity, needed seasonally/periodically) from passive monoclonal antibody prophylaxis (infants, immediate but temporary protection, no immune memory built)", "Abrysvo is also approved for maternal immunization (pregnancy) to passively protect the newborn via transplacental antibody transfer, similar concept to Tdap in pregnancy", "Nirsevimab (Beyfortus) is increasingly used as broad infant RSV prophylaxis regardless of prematurity status, given as a single seasonal dose before/during RSV season", "RSV season in Canada typically runs fall through spring — timing of administration matters", "Palivizumab (older product) requires monthly dosing throughout RSV season, whereas nirsevimab's longer half-life allows single-dose seasonal protection — key differentiator"], "counselling": ["For older adults, this vaccine helps your immune system build its own protection against severe RSV lung infection", "For infants, the antibody injection gives immediate, ready-made protection rather than training the baby's immune system, so it may need repeating each RSV season", "If you're pregnant, this vaccine can be given late in pregnancy to pass protection to your newborn before birth", "RSV protection is timed around the fall/winter RSV season for maximum benefit"], "sideEffects": ["Injection site pain", "Fatigue", "Headache", "Myalgia", "Guillain-Barre syndrome (rare signal noted with adult RSV vaccines)"]}, {"topic": "immun", "generic": "Rabies vaccine (pre- and post-exposure)", "pronunciation": "RAY-beez", "brand": ["Imovax Rabies", "RabAvert"], "class": "Inactivated viral vaccine", "moa": "Contains inactivated rabies virus that stimulates neutralizing antibody production; post-exposure regimens combine active vaccination with rabies immunoglobulin for immediate passive protection while active immunity develops.", "indication": "Pre-exposure prophylaxis for travelers to high-risk endemic areas or occupational exposure; post-exposure prophylaxis after animal bite/exposure in endemic areas.", "dosage": "Pre-exposure: 1 mL IM on days 0, 7, 21 or 28. Post-exposure: 1 mL IM on days 0, 3, 7, 14 (± day 28) plus rabies immune globulin on day 0", "examPoints": ["Post-exposure prophylaxis (PEP) requires BOTH rabies immunoglobulin (RIG, infiltrated around the wound) AND vaccine series if NOT previously vaccinated — RIG provides immediate passive protection while active immunity develops", "If previously vaccinated (pre-exposure series completed), PEP only requires 2 vaccine doses and NO immunoglobulin — key distinction tested on exams", "Pre-exposure series is typically 2-3 doses depending on schedule/product; reduces but does not eliminate need for post-exposure boosting", "Rabies is essentially 100% fatal once symptomatic — PEP is a true medical urgency, not something to delay", "Wound care (immediate thorough washing with soap and water) is a critical first step regardless of vaccine access"], "counselling": ["If you're bitten or scratched by an animal in a rabies-risk area, wash the wound thoroughly with soap and water immediately and seek medical care right away — do not wait", "If you've never been vaccinated before, you'll need both an immunoglobulin injection near the wound and a full vaccine series", "If you already completed pre-travel rabies vaccination, you'll only need two follow-up doses and no immunoglobulin after an exposure", "Pre-travel vaccination is worth considering if you'll have significant animal contact or be far from medical care in a high-risk region"], "sideEffects": ["Injection site pain/swelling", "Headache", "Dizziness", "Myalgia", "Rare hypersensitivity reactions"]}, {"topic": "immun", "generic": "Yellow fever vaccine", "pronunciation": "YEL-oh FEE-ver", "brand": ["YF-Vax", "Stamaril"], "class": "Live attenuated viral vaccine", "moa": "Contains a live attenuated strain of yellow fever virus that replicates minimally, producing robust and long-lasting (often lifelong) neutralizing antibody immunity.", "indication": "Travel to endemic regions of sub-Saharan Africa and tropical South America; required by International Health Regulations for entry to/from certain countries.", "dosage": "0.5 mL SC single dose, provides long-term/lifetime protection for most travelers; required for entry to certain countries (ICVP certificate)", "examPoints": ["Must be administered at a designated/certified Yellow Fever Vaccination Centre — cannot be given at just any pharmacy in Canada, a key logistical exam point", "A single dose provides long-lasting, likely lifelong, protection per current WHO/NACI guidance (booster no longer routinely required for most travelers)", "Requires an International Certificate of Vaccination (ICVP, 'yellow card') that becomes valid 10 days after vaccination — relevant for border entry requirements", "LIVE vaccine — contraindicated in pregnancy (unless unavoidable travel), infants <6 months, and significant immunocompromise/thymus disorders", "Rare but serious risk of yellow fever vaccine-associated viscerotropic/neurotropic disease, especially in adults >60 and those with thymus disorders — risk-benefit discussion needed"], "counselling": ["This vaccine can only be given at a designated Yellow Fever Vaccination Centre, not at a regular pharmacy", "Your proof of vaccination (yellow card) becomes valid for travel 10 days after your injection, so plan ahead", "One dose now provides long-lasting protection for most people — a booster usually isn't needed", "This is a live vaccine, so it isn't recommended during pregnancy or for those with weakened immune systems unless travel is unavoidable"], "sideEffects": ["Injection site soreness", "Headache", "Myalgia", "Low-grade fever", "Rare viscerotropic/neurotropic disease (serious, more common in older adults)"]}, {"topic": "immun", "generic": "Typhoid vaccine", "pronunciation": "TY-foyd", "brand": ["Typhim Vi (injectable polysaccharide)", "Vivotif (oral live attenuated)"], "class": "Polysaccharide (injectable) or live attenuated (oral) bacterial vaccine", "moa": "Typhim Vi contains purified Vi capsular polysaccharide from Salmonella Typhi stimulating antibody response; Vivotif contains a live attenuated oral strain (Ty21a) that induces mucosal and systemic immunity mimicking natural infection.", "indication": "Travel to endemic regions with poor food/water sanitation (South Asia, parts of Africa, Central/South America) for typhoid fever prevention.", "dosage": "Injectable (Vi polysaccharide): 0.5 mL IM single dose, booster q2–3yr if ongoing risk. Oral live-attenuated: 1 capsule PO qod x4 doses", "examPoints": ["Two formulations differ importantly: injectable Vi polysaccharide (single dose, IM) vs oral live attenuated (4 capsules, taken every other day, must be refrigerated and taken with cool liquid, not hot)", "Oral live vaccine is contraindicated in immunocompromised patients and requires avoiding antibiotics around the dosing window (antibiotics can kill the live vaccine strain)", "Oral live vaccine interacts with antimalarial mefloquine timing/proguanil and should not be co-administered with certain antibiotics", "Neither formulation provides complete protection — safe food/water precautions remain essential counselling regardless of vaccination", "Injectable vaccine needs re-dosing every 2-3 years for ongoing risk; oral needs repeating every 5 years (varies by product/jurisdiction)"], "counselling": ["There are two types available: a single injection or oral capsules taken every other day — your pharmacist will help decide which suits you", "If taking the oral capsules, keep them refrigerated and take each with a cool drink, not a hot beverage, and avoid taking them with antibiotics", "This vaccine reduces but doesn't eliminate your risk, so you should still be careful about food and water hygiene while travelling", "Protection isn't permanent — you'll need repeat doses if you continue to travel to risk areas"], "sideEffects": ["Injection site soreness (Vi)", "Abdominal discomfort/nausea (oral)", "Headache", "Fever", "Rash (rare)"]}, {"topic": "immun", "generic": "Japanese encephalitis vaccine", "pronunciation": "jap-uh-NEEZ en-sef-uh-LY-tis", "brand": ["Ixiaro"], "class": "Inactivated viral vaccine", "moa": "Contains inactivated Japanese encephalitis virus that stimulates neutralizing antibody production against this mosquito-borne flavivirus.", "indication": "Travelers to endemic rural areas of Asia (particularly with prolonged stays, rural travel, or during transmission season) at risk of Japanese encephalitis.", "dosage": "0.5 mL IM, 2-dose series 28 days apart (accelerated 7-day schedule available for some products), for travel to endemic areas", "examPoints": ["Only recommended for specific higher-risk travel: extended stays (>1 month), rural areas, outdoor/agricultural activities, or during peak transmission (rainy season) — not for typical short urban trips", "Standard schedule is 2 doses, 28 days apart, completed at least 1 week before travel for adequate immune response", "Inactivated vaccine, so theoretically compatible with immunocompromised travelers, though efficacy data in this population is limited", "Mosquito bite avoidance remains essential regardless of vaccination, as with all mosquito-borne travel illnesses (malaria, dengue, JE)", "Distinguish from yellow fever — JE vaccine centres are less restrictive (not required to be at designated YF centres) and it is not an IHR-regulated travel requirement"], "counselling": ["This vaccine is only recommended if you're travelling to rural areas of Asia for an extended period or during high mosquito-transmission season", "You'll need two doses, four weeks apart, completed at least a week before you travel", "Preventing mosquito bites with repellent, long sleeves, and bed nets is still essential even after vaccination", "This is different from typical short city trips, where the risk is generally too low to warrant vaccination"], "sideEffects": ["Injection site pain/redness", "Headache", "Myalgia", "Fatigue", "Rare hypersensitivity reaction"]}, {"topic": "immun", "generic": "Cholera vaccine (oral, live attenuated/inactivated)", "pronunciation": "KOL-er-uh", "brand": ["Dukoral"], "class": "Oral vaccine (inactivated whole-cell + recombinant B subunit)", "moa": "Contains inactivated Vibrio cholerae whole cells plus recombinant cholera toxin B subunit, stimulating local intestinal (mucosal IgA) and systemic antibody responses that also provide partial cross-protection against enterotoxigenic E. coli (ETEC) traveler's diarrhea.", "indication": "Travelers to cholera-endemic areas with limited access to medical care, healthcare/relief workers, and for partial protection against ETEC traveler's diarrhea.", "dosage": "Oral suspension, 2-dose series ≥1 week apart (adults), completed at least 1 week before travel", "examPoints": ["Not routinely recommended for typical tourists — reserved for high-risk travel (humanitarian work, remote areas with poor sanitation access to care)", "Oral suspension mixed with buffer solution — taken on an empty stomach, no food/drink 1 hour before or after each dose", "2-dose series (adults), spaced 1-6 weeks apart, completed at least 1 week before travel; children need a 3-dose series", "Provides partial (~50-60%) cross-protection against ETEC traveler's diarrhea, a notable bonus benefit distinct from cholera prevention itself", "Protection wanes — booster considerations if ongoing risk beyond 2 years (adults) or 6 months (young children)"], "counselling": ["This is an oral vaccine, not an injection — you'll mix the powder with the provided buffer solution and drink it", "Avoid eating or drinking for one hour before and after taking each dose", "This vaccine is only recommended for specific high-risk travel situations, not routine tourism", "It also offers some protection against a common cause of traveler's diarrhea, as a secondary benefit"], "sideEffects": ["GI upset (mild)", "Abdominal cramping", "Nausea", "Headache (uncommon)"]}, {"topic": "derm", "generic": "Hydrocortisone / Betamethasone valerate / Clobetasol propionate (potency ladder example)", "pronunciation": "hy-droh-KOR-tih-zohn / bay-tuh-METH-uh-zohn VAL-er-ayt / kloh-BEH-tuh-sol PROH-pee-oh-nayt", "brand": ["Cortate", "Betaderm", "Dermovate"], "class": "Topical corticosteroid", "moa": "Binds intracellular glucocorticoid receptors, inducing anti-inflammatory, antiproliferative, immunosuppressive, and vasoconstrictive effects in the skin by suppressing cytokine release and phospholipase A2 activity.", "indication": "Inflammatory dermatoses — eczema, psoriasis, contact dermatitis, atopic dermatitis; potency chosen by site and severity.", "dosage": "Apply thin layer to affected area 1–2x daily; low potency (hydrocortisone) for face/skin folds, mid potency (betamethasone valerate) for trunk/limbs, high potency (clobetasol) for thick plaques — limit high-potency use to ≤2–4 weeks", "examPoints": ["Canada uses a 7-group potency classification (I=super-high potency e.g. clobetasol to VII=low e.g. hydrocortisone 0.5-1%)", "Face, groin, axillae, and skin folds require low-potency agents due to thinner skin and higher absorption", "Occlusion (e.g. under diaper or dressing) increases potency and systemic absorption risk", "Fingertip unit (FTU) is used to estimate correct application amount — 1 FTU covers about 2 hand-sized areas", "Prolonged high-potency use can cause skin atrophy, telangiectasia, striae, and HPA-axis suppression"], "counselling": ["Apply a thin layer only to affected skin, usually once or twice daily as directed", "Do not use on the face or in skin folds unless specifically prescribed for that site", "Wash hands after application unless hands are the treated area", "Do not use for longer than the recommended duration without follow-up — risk of skin thinning increases with prolonged use", "If using with an emollient, apply the corticosteroid first (or as directed), then moisturizer after a short gap"], "sideEffects": ["Skin thinning/atrophy", "Telangiectasia (visible blood vessels)", "Striae (stretch marks)", "Perioral dermatitis/acne with facial use", "Hypopigmentation", "HPA-axis suppression with extensive high-potency use"]}, {"topic": "derm", "generic": "Tretinoin / Adapalene", "pronunciation": "TRET-ih-noyn / uh-DAP-uh-leen", "brand": ["Retin-A", "Stieva-A", "Differin"], "class": "Topical retinoid", "moa": "Binds retinoic acid receptors, normalizing follicular keratinocyte desquamation to prevent comedone formation and exerting anti-inflammatory effects; adapalene is more photostable and less irritating than tretinoin.", "indication": "Acne vulgaris (comedonal and inflammatory) — first-line topical agent, also used for photoaging.", "dosage": "Apply pea-sized amount to clean, dry skin once daily at bedtime; start every other night to build tolerance, avoid sun exposure", "examPoints": ["Causes initial \"purging\"/irritation in first 2-4 weeks — counsel patients not to stop, full effect takes 8-12 weeks", "Tretinoin is degraded by UV light and oxidized by benzoyl peroxide if applied simultaneously (apply at different times) — adapalene is photostable and BPO-compatible", "Increases photosensitivity — sunscreen is mandatory", "Contraindicated in pregnancy (Category C/X depending on product) — teratogenic risk with topical use is debated but generally avoided", "Start low frequency (every other night) to build tolerance and reduce irritation"], "counselling": ["Apply a pea-sized amount to clean, dry skin at night, avoiding eyes, lips, and mucous membranes", "Start every other night for 1-2 weeks then increase to nightly as tolerated", "Use a broad-spectrum sunscreen daily — skin will be more sun-sensitive", "Expect redness, peeling, and dryness initially; this usually improves after several weeks", "Do not use with other harsh exfoliants or products at the same time to reduce irritation"], "sideEffects": ["Erythema", "Dryness/peeling", "Photosensitivity", "Initial acne flare (purging)", "Contact irritation/burning"]}, {"topic": "derm", "generic": "Benzoyl peroxide", "pronunciation": "BEN-zoh-il per-OK-side", "brand": ["Clearasil", "PanOxyl", "Benzac"], "class": "Topical antibacterial/keratolytic", "moa": "Releases free-radical oxygen species that oxidize bacterial proteins in Cutibacterium acnes, reducing bacterial counts; also has mild comedolytic and keratolytic activity.", "indication": "Mild to moderate acne vulgaris; often combined with topical antibiotics or retinoids.", "dosage": "Apply 2.5–10% preparation once–BID daily to affected area; start lower concentration/frequency to reduce irritation", "examPoints": ["No bacterial resistance develops to benzoyl peroxide — used to reduce resistance when combined with topical/oral antibiotics", "Bleaches hair, clothing, and towels — an important practical counselling point", "Available OTC in 2.5-10% concentrations; higher concentration is not necessarily more effective and increases irritation", "Oxidizes and inactivates tretinoin if applied together — separate application times or use adapalene instead", "Wash off formulations may be preferred for sensitive skin to reduce contact time and irritation"], "counselling": ["Apply to clean, dry skin once or twice daily as tolerated, starting with lower concentration/frequency", "Use white or dark-colored towels and pillowcases as it can bleach fabric", "Expect dryness and mild peeling initially — use a non-comedogenic moisturizer if needed", "Apply sunscreen during the day as skin may be more sun-sensitive", "If irritation is severe, reduce frequency rather than stopping completely"], "sideEffects": ["Dryness/peeling", "Erythema", "Contact irritation", "Bleaching of hair/fabric", "Rare allergic contact dermatitis"]}, {"topic": "derm", "generic": "Terbinafine (topical) / Terbinafine (oral) / Clotrimazole", "pronunciation": "ter-BIN-uh-feen / kloh-TRY-muh-zohl", "brand": ["Lamisil", "Canesten"], "class": "Antifungal (allylamine topical/oral; azole topical)", "moa": "Terbinafine inhibits fungal squalene epoxidase, causing squalene accumulation and ergosterol deficiency, which is fungicidal against dermatophytes; clotrimazole inhibits fungal cytochrome P450-dependent ergosterol synthesis (fungistatic/fungicidal azole).", "indication": "Dermatophyte infections — tinea pedis, tinea cruris, tinea corporis (topical); onychomycosis and extensive/refractory tinea (oral terbinafine).", "dosage": "Topical: apply once–BID daily x1–4 weeks. Oral terbinafine: 250 mg PO once daily x6 weeks (fingernails) to 12 weeks (toenails)", "examPoints": ["Oral terbinafine requires baseline and periodic LFT monitoring due to rare but serious hepatotoxicity", "Oral terbinafine course for onychomycosis: typically 6 weeks (fingernails) to 12 weeks (toenails)", "Terbinafine is a strong CYP2D6 inhibitor — interacts with drugs like tricyclic antidepressants, some beta-blockers, and SSRIs", "Topical antifungals should be continued 1-2 weeks after visible clearing to prevent relapse", "Clotrimazole/azoles cover both dermatophytes and yeast (Candida), useful when diagnosis is uncertain"], "counselling": ["Apply topical cream to affected area and surrounding skin as directed, usually once or twice daily", "Continue treatment for the full course even after symptoms improve to prevent recurrence", "Keep the area clean and dry; wear breathable footwear/clothing to reduce fungal recurrence", "For oral therapy, report any unusual fatigue, yellowing of skin/eyes, or dark urine (signs of liver problems)", "Avoid sharing towels, socks, or footwear to reduce spread"], "sideEffects": ["Local irritation/burning (topical)", "Rash", "Headache, GI upset (oral)", "Taste disturbance (oral terbinafine)", "Rare hepatotoxicity (oral terbinafine)"]}, {"topic": "derm", "generic": "Permethrin 5% / 1%", "pronunciation": "per-METH-rin", "brand": ["Kwellada-P", "Nix"], "class": "Pediculicide/scabicide (pyrethroid)", "moa": "Disrupts sodium channel function in arthropod nerve cell membranes, causing paralysis and death of mites (scabies) or lice.", "indication": "Scabies (5% cream) and head lice (1% cream rinse/lotion).", "dosage": "5% cream: apply head-to-toe (scabies), leave 8–14h, may repeat in 1 week. 1% lotion: apply to hair/scalp (lice), leave 10 min, rinse", "examPoints": ["Scabies: apply 5% cream neck-to-toe (include scalp/face in infants and elderly), leave on 8-14 hours (overnight), then wash off", "All household/close contacts should be treated simultaneously even if asymptomatic — scabies incubation can be weeks", "Wash bedding/clothing in hot water or seal in plastic bag for 72 hours to kill mites/lice off the host", "Itching may persist for 2-4 weeks after successful scabies treatment (dead mite antigen reaction) — does not mean treatment failure", "Lice: a second application is typically recommended 7-9 days later to kill newly hatched nits"], "counselling": ["Apply to clean, dry skin covering the entire body from neck to soles of feet, leave on for the recommended time then wash off", "Treat all close contacts/household members at the same time", "Wash all bedding, clothing, and towels used in the last few days in hot water and dry on high heat", "Persistent itching after treatment is common and does not necessarily mean the treatment failed", "For lice, use a fine-tooth comb to remove nits and repeat treatment after 7-9 days"], "sideEffects": ["Local burning/stinging/itching", "Erythema", "Rare allergic reaction (contains chrysanthemum-derived compounds — caution with ragweed allergy)"]}, {"topic": "derm", "generic": "Latanoprost", "pronunciation": "luh-TAN-oh-prost", "brand": ["Xalatan"], "class": "Prostaglandin F2-alpha analogue (ophthalmic)", "moa": "Increases uveoscleral outflow of aqueous humour, lowering intraocular pressure.", "indication": "Open-angle glaucoma and ocular hypertension — first-line IOP-lowering agent.", "dosage": "1 drop in affected eye(s) once daily in the evening; avoid exceeding once-daily dosing (paradoxically reduces efficacy)", "examPoints": ["Dosed once daily, typically at bedtime — more frequent dosing can paradoxically reduce effectiveness", "Can cause permanent iris/eyelash pigmentation changes — important counselling point, especially in patients with mixed-colour eyes", "If using multiple eye drops, space at least 5 minutes apart and use this one last if combined with other IOP-lowering drops per typical sequencing"], "counselling": ["Use one drop in the affected eye(s) at bedtime", "Apply gentle pressure to the inner corner of the eye (punctal occlusion) after instilling to reduce systemic absorption", "You may notice gradual darkening of the iris or longer/darker eyelashes over time — this is a known, often permanent effect", "Remove contact lenses before instilling, wait 15 minutes before reinserting"], "sideEffects": ["Eye redness/irritation", "Iris pigmentation darkening (often permanent)", "Eyelash growth/darkening", "Blurred vision transiently after application"]}, {"topic": "derm", "generic": "Tobramycin / Moxifloxacin (ophthalmic)", "pronunciation": "toh-bruh-MY-sin / moks-ih-FLOKS-uh-sin", "brand": ["Tobrex", "Vigamox"], "class": "Ophthalmic antibiotic (aminoglycoside / fluoroquinolone)", "moa": "Tobramycin binds the bacterial 30S ribosomal subunit inhibiting protein synthesis (bactericidal); moxifloxacin inhibits bacterial DNA gyrase/topoisomerase IV, blocking DNA replication.", "indication": "Bacterial conjunctivitis and other susceptible external ocular infections.", "dosage": "1–2 drops in affected eye(s) q2–4h while awake (tobramycin) or TID (moxifloxacin) x7 days for bacterial conjunctivitis", "examPoints": ["Bacterial conjunctivitis typically presents with purulent discharge and eyelids stuck shut in the morning, unlike watery viral conjunctivitis", "Most bacterial conjunctivitis is self-limiting; antibiotics shorten duration and reduce transmission but are not always necessary", "Discontinue contact lens use during active infection and until fully resolved plus a few days", "Do not touch the dropper tip to the eye or any surface to avoid contamination and reinfection", "Fluoroquinolone drops have broader gram-negative coverage; reserve broader-spectrum agents per local antibiogram/guideline stewardship"], "counselling": ["Wash hands before and after applying drops", "Instill the prescribed number of drops into the affected eye(s) at the prescribed frequency, usually every few hours initially tapering", "Avoid touching the tip of the applicator to your eye or eyelid to prevent contamination", "Do not share towels or pillowcases; discard eye makeup used before/during infection", "Complete the full course even if symptoms improve early to prevent recurrence/resistance"], "sideEffects": ["Transient stinging/burning on instillation", "Ocular irritation", "Blurred vision immediately after use", "Rare hypersensitivity reaction"]}, {"topic": "derm", "generic": "Polyvinyl alcohol / Carboxymethylcellulose artificial tears", "pronunciation": "pol-ee-VY-nil AL-koh-hol / kar-BOKS-ee-meth-il-SEL-yoo-lohs", "brand": ["Tears Naturale", "Refresh", "Systane"], "class": "Ocular lubricant", "moa": "Forms a viscous, hydrophilic film over the corneal surface that mimics natural tear film, reducing friction and evaporation to relieve dryness.", "indication": "Dry eye syndrome, ocular irritation, contact lens discomfort.", "dosage": "1–2 drops in eye(s) PRN as needed for dryness; no maximum, preservative-free preferred for frequent use (>4x/day)", "examPoints": ["Preservative-free single-use vials are preferred for frequent use (>4x/day) or in patients with sensitive eyes to avoid preservative-induced toxicity (e.g., benzalkonium chloride)", "Considered safe for essentially unlimited use as needed — no meaningful systemic absorption", "Should be used at least 15 minutes apart from other eye medications if administered together, and typically applied last if used with a gel/ointment for lubrication", "Gel/ointment formulations provide longer-lasting relief but cause more blurring — often reserved for nighttime use"], "counselling": ["Instill 1-2 drops into the affected eye(s) as often as needed for comfort", "If using single-use vials, discard after one use — do not reuse or reseal", "Wait several minutes between artificial tears and any other eye drop or ointment", "Ointment/gel forms are best used at bedtime since they can blur vision temporarily"], "sideEffects": ["Transient blurred vision (especially gel/ointment)", "Mild stinging on instillation", "Rare irritation from preservatives with frequent use of preserved formulations"]}, {"topic": "derm", "generic": "Ciprofloxacin/dexamethasone otic", "pronunciation": "SIP-roh-FLOKS-uh-sin / deks-uh-METH-uh-zohn", "brand": ["Ciprodex"], "class": "Otic antibiotic-corticosteroid combination", "moa": "Ciprofloxacin inhibits bacterial DNA gyrase (bactericidal); dexamethasone reduces inflammation, edema, and pain in the ear canal.", "indication": "Acute otitis externa (swimmer's ear) and otitis media with tympanostomy tubes.", "dosage": "4 drops in affected ear BID x7 days (adults); warm to body temperature before instilling", "examPoints": ["Confirm an intact tympanic membrane is NOT required for this combination (approved for use with perforated eardrum/tubes) — differs from some other otic products (e.g., avoid aminoglycosides like neomycin if perforation suspected due to ototoxicity risk)", "Warm the bottle in hands before use — cold drops instilled in the ear can cause dizziness/vertigo", "Lie with affected ear up for several minutes after instillation, or use ear wick if canal is very swollen", "Typical course is 7 days for otitis externa", "Avoid water exposure/swimming during treatment"], "counselling": ["Warm the bottle by rolling it between your hands before use to reduce dizziness", "Lie down with the affected ear facing up, instill the prescribed drops, and stay in that position for 1-2 minutes", "Gently pull the outer ear (up and back in adults) to help the drops reach the ear canal", "Keep the ear dry — avoid swimming and try to keep water out while showering during treatment", "Complete the full course even if pain resolves early"], "sideEffects": ["Local itching/irritation", "Taste disturbance (if drainage reaches throat via tube)", "Rare hypersensitivity", "Ear discomfort on instillation"]}, {"topic": "derm", "generic": "Fluticasone propionate nasal spray", "pronunciation": "floo-TIK-uh-zohn PROH-pee-oh-nayt", "brand": ["Flonase"], "class": "Intranasal corticosteroid", "moa": "Binds nasal mucosal glucocorticoid receptors to reduce local inflammatory mediator release, decreasing nasal mucosal edema, congestion, and secretions.", "indication": "Allergic rhinitis (seasonal/perennial) — first-line for moderate-severe or persistent symptoms, especially congestion.", "dosage": "2 sprays per nostril once daily (or 1 spray BID); allergic rhinitis, onset may take several days for full effect", "examPoints": ["Full effect may take several days to 2 weeks of regular use — not a rescue/PRN medication like decongestant sprays", "Correct technique (angle away from septum) reduces risk of epistaxis and septal perforation", "No rebound congestion risk (unlike OTC decongestant sprays such as oxymetazoline)", "Most effective single agent for allergic rhinitis symptom control including congestion, per guidelines", "Can be used alongside oral antihistamines for combined symptom control"], "counselling": ["Shake gently and prime the pump before first use or if not used recently", "Blow your nose gently before use to clear nasal passages", "Tilt your head slightly forward, aim the spray tip toward the outer wall of the nostril (away from the septum), and avoid sniffing hard immediately after spraying", "Use regularly as directed, even before symptoms are severe, for best effect — takes several days for full benefit", "If nosebleeds occur, reduce frequency and point spray away from the septum; contact prescriber if persistent"], "sideEffects": ["Nasal dryness/irritation", "Epistaxis (nosebleed)", "Headache", "Sore throat", "Rare septal perforation with long-term improper technique"]}, {"topic": "derm", "generic": "Hydroquinone 2-4%", "pronunciation": "hy-droh-KWIH-nohn", "brand": ["Glyquin", "Ultraquin"], "class": "Topical depigmenting agent", "moa": "Inhibits tyrosinase enzyme, reducing melanin synthesis in melanocytes to lighten hyperpigmented skin.", "indication": "Melasma, post-inflammatory hyperpigmentation, solar lentigines.", "dosage": "Apply thin layer to hyperpigmented area BID daily; limit continuous use to ≤3–6 months due to risk of ochronosis", "examPoints": ["Sun exposure worsens hyperpigmentation and reduces efficacy — strict daily sunscreen use is essential and non-negotiable", "Prolonged continuous use (often beyond several months) can rarely cause exogenous ochronosis (paradoxical blue-black darkening)", "Typically limited to a defined treatment course (e.g., a few months) then a break, per product/prescriber guidance", "Often combined with a retinoid and/or mild corticosteroid (triple combination) for enhanced effect"], "counselling": ["Apply a thin layer to the affected area only, as directed, avoiding normal surrounding skin", "Use broad-spectrum sunscreen daily and reapply — sun exposure will counteract treatment and worsen pigmentation", "Improvement is gradual and may take several weeks to months", "Avoid applying near eyes or on broken/irritated skin", "Do not exceed the recommended duration of use without checking with your pharmacist/physician"], "sideEffects": ["Local irritation/erythema", "Dryness", "Rare contact dermatitis", "Rare exogenous ochronosis with prolonged misuse"]}, {"topic": "derm", "generic": "Selenium sulfide / Ketoconazole shampoo", "pronunciation": "seh-LEE-nee-um SUL-fyd / kee-toh-KOH-nuh-zohl", "brand": ["Selsun Blue", "Nizoral"], "class": "Antifungal/antiseborrheic shampoo", "moa": "Reduces Malassezia yeast overgrowth on the scalp (implicated in seborrheic dermatitis/dandruff) and has cytostatic effects on epidermal cell turnover.", "indication": "Dandruff, seborrheic dermatitis of the scalp, tinea versicolor (selenium sulfide).", "dosage": "Apply to scalp, lather, leave 5 min, rinse; use 2x/week for seborrheic dermatitis/dandruff, or per product for tinea", "examPoints": ["Contact time on the scalp matters — leave lather on for the directed time (often 2-5 minutes) before rinsing for efficacy", "Can discolor light/gray or chemically treated hair with selenium sulfide — practical counselling point", "Ketoconazole shampoo available OTC at lower strength (1%) and Rx at higher strength (2%) in Canada", "Maintenance/intermittent use (e.g., 1-2x/week) often needed for chronic seborrheic dermatitis control"], "counselling": ["Wet hair, apply shampoo, massage into scalp, and leave on for the directed contact time before rinsing thoroughly", "Use as directed frequency (often 2-3 times weekly initially, then less often for maintenance)", "Rinse well to avoid residue and reduce irritation", "If hair discoloration occurs (selenium sulfide), rinse thoroughly and consider alternate-day dosing"], "sideEffects": ["Scalp irritation/dryness", "Oiliness or dryness of hair", "Hair discoloration (selenium sulfide)", "Rare contact dermatitis"]}, {"topic": "derm", "generic": "Calamine lotion / Colloidal oatmeal", "pronunciation": "KAL-uh-myn / kuh-LOY-dul OHT-meel", "brand": ["Caladryl", "Aveeno"], "class": "Topical antipruritic/protectant", "moa": "Provides a mild astringent, cooling, and protective barrier effect on irritated skin; colloidal oatmeal has anti-inflammatory and skin-barrier-restoring properties.", "indication": "Symptomatic relief of itching from insect bites, poison ivy, chickenpox, mild eczema, sunburn.", "dosage": "Apply topically to affected area PRN for itch relief (calamine); oatmeal as bath soak or topical paste PRN", "examPoints": ["Purely symptomatic — does not treat underlying cause, appropriate self-care recommendation with counselling on red flags (spreading infection, fever, widespread rash)", "Safe in pregnancy, children, and most populations — low-risk OTC recommendation", "Calamine with added antihistamine (e.g., diphenhydramine, Caladryl) carries a small risk of contact sensitization/systemic absorption with extensive use, especially in children"], "counselling": ["Apply to the affected area as needed for itch relief; shake lotion well before use", "Colloidal oatmeal can be added to a lukewarm bath and soaked for 10-15 minutes for widespread itching", "Avoid applying to broken skin or open wounds", "See a pharmacist or physician if the rash spreads, is associated with fever, or does not improve within a few days"], "sideEffects": ["Skin drying if used excessively", "Rare contact irritation/allergic reaction", "Temporary skin discoloration (calamine is pink-tinted)"]}, {"topic": "derm", "generic": "Salicylic acid (topical, e.g. for warts/acne/psoriasis)", "pronunciation": "sal-ih-SIL-ik AS-id", "brand": ["Compound W", "Duofilm", "Stieprox"], "class": "Keratolytic", "moa": "Softens and dissolves intercellular keratin, promoting desquamation of the outer skin layer; also has mild comedolytic and antifungal effects at higher concentrations.", "indication": "Common/plantar warts (17-40%), acne (0.5-2%), and adjunct in psoriasis/dandruff (lower concentrations).", "dosage": "Apply 0.5–17-40% preparation (concentration depends on product/indication) once–BID daily to affected area", "examPoints": ["Wart treatment requires soaking the area and filing down dead skin before each application for best penetration and effect", "Avoid use on the face, mucous membranes, moles, birthmarks, or genital warts without medical guidance", "Diabetics and patients with peripheral neuropathy/poor circulation should avoid self-treating foot warts due to injury/infection risk", "Systemic salicylate toxicity is a rare but real risk with extensive application over large body surface area, especially in children"], "counselling": ["Soak the wart in warm water for 5-10 minutes, then gently file away dead skin before applying", "Apply directly to the wart only, protecting surrounding healthy skin (e.g., with petroleum jelly)", "Reapply daily as directed; treatment may take several weeks for full wart resolution", "Do not use on facial skin, moles, or genital lesions without consulting a healthcare provider", "Diabetic patients or those with poor circulation should see a healthcare provider rather than self-treating foot warts"], "sideEffects": ["Local irritation/burning", "Skin peeling", "Rare salicylate toxicity with extensive use", "Contact dermatitis"]}, {"topic": "derm", "generic": "Olopatadine (ophthalmic)", "pronunciation": "oh-loh-PAT-uh-deen", "brand": ["Patanol", "Pataday"], "class": "Ophthalmic antihistamine/mast cell stabilizer", "moa": "Selectively blocks H1 histamine receptors and inhibits mast cell degranulation, reducing release of histamine and other inflammatory mediators in the conjunctiva.", "indication": "Allergic conjunctivitis — itching and redness relief.", "dosage": "1 drop in affected eye(s) once–BID daily depending on formulation, for allergic conjunctivitis", "examPoints": ["Dual mechanism (antihistamine + mast cell stabilizer) gives both rapid symptom relief and preventive benefit with regular use", "Once-daily formulations (Pataday) available for convenience versus twice-daily older formulation (Patanol)", "Distinguish allergic conjunctivitis (itching prominent, bilateral, associated with other allergy symptoms) from bacterial (purulent discharge) or viral (watery, often unilateral then bilateral) conjunctivitis — antihistamine drops are not appropriate for infectious conjunctivitis", "Remove contact lenses before instillation; most formulations advise waiting at least 10 minutes before reinsertion"], "counselling": ["Instill one drop into the affected eye(s) as directed (once or twice daily depending on product)", "Remove contact lenses before use and wait at least 10 minutes before reinserting", "Wash hands before use and avoid touching the dropper tip to the eye", "For best results with allergy prevention, use regularly during allergy season rather than only when symptomatic"], "sideEffects": ["Mild eye irritation/stinging", "Headache", "Dry eye", "Rare blurred vision"]}, {"topic": "otc", "generic": "Fish oil (omega-3 fatty acids, EPA/DHA)", "pronunciation": "FISH oyl (oh-MAY-guh three)", "brand": ["Webber Naturals Omega-3", "Jamieson Fish Oil"], "class": "Natural health product — essential fatty acid supplement", "moa": "EPA and DHA are incorporated into cell membranes and eicosanoid pathways, reducing triglyceride synthesis in the liver and modestly reducing inflammatory mediator production.", "indication": "Hypertriglyceridemia (adjunct), cardiovascular health support, joint/anti-inflammatory support (evidence variable).", "dosage": "1–4 g/day PO (combined EPA+DHA) for general use; up to 2–4 g/day of prescription-strength product for hypertriglyceridemia", "examPoints": ["Doses greater than 3 g/day EPA+DHA can have an antiplatelet effect — caution with concurrent anticoagulants/antiplatelets (warfarin, ASA, clopidogrel, DOACs) and before surgery", "Can cause fishy aftertaste/burping — enteric-coated or frozen products may reduce this", "High doses used for triglyceride lowering (prescription-strength, e.g., icosapent ethyl or 4g/day) differ from typical OTC supplement doses", "May slightly raise LDL cholesterol in some patients depending on formulation/dose"], "counselling": ["Take with food to reduce GI upset and fishy burps", "If you are on blood thinners or have an upcoming surgery, tell your pharmacist or doctor before starting high-dose fish oil", "Store in a cool place or refrigerate to reduce rancidity and fishy aftertaste", "Look for products certified for purity to minimize mercury/contaminant exposure"], "sideEffects": ["Fishy burps/aftertaste", "GI upset (nausea, loose stools)", "Increased bleeding risk at high doses", "Rare mild LDL increase"]}, {"topic": "otc", "generic": "Melatonin", "pronunciation": "mel-uh-TOH-nin", "brand": ["Natrol Melatonin", "Jamieson Melatonin"], "class": "Natural health product — hormone/sleep aid", "moa": "Binds MT1/MT2 melatonin receptors in the suprachiasmatic nucleus, helping regulate the circadian sleep-wake cycle and signal onset of sleep.", "indication": "Short-term insomnia (sleep onset), jet lag, shift-work sleep disruption, circadian rhythm disorders.", "dosage": "0.5–5 mg PO 30–60 min before bedtime; lower doses often as effective as higher for sleep onset", "examPoints": ["Low doses (0.5-3 mg) taken 30-60 minutes before bedtime are often as or more effective than higher doses for sleep onset — higher doses are not necessarily better", "Timing matters more than dose for jet lag/circadian re-entrainment", "Can cause next-day drowsiness/grogginess, especially at higher doses", "Health Canada regulates melatonin as an NHP with standardized dosing/labelling requirements (unlike the less-regulated US market)", "Use in children should be guided by a healthcare provider — increasingly used for pediatric sleep/ADHD-related insomnia but data are still evolving"], "counselling": ["Take about 30-60 minutes before your intended bedtime", "Start with the lowest effective dose", "Avoid alcohol around the time of dosing as it can reduce effectiveness and increase sedation", "Limit screen/bright light exposure before bed to support melatonin's natural sleep-promoting effect", "Use for short-term sleep difficulty; discuss with a pharmacist if insomnia persists beyond a couple of weeks"], "sideEffects": ["Next-day drowsiness", "Headache", "Dizziness", "Vivid dreams", "Rare mood changes"]}, {"topic": "otc", "generic": "St. John's Wort (Hypericum perforatum)", "pronunciation": "saynt JONZ wert (hy-PER-ih-kum per-for-AY-tum)", "brand": ["A.Vogel Hyperiforce", "Jamieson St. John's Wort"], "class": "Natural health product — botanical for mood support", "moa": "Thought to inhibit reuptake of serotonin, norepinephrine, and dopamine and mildly inhibit MAO; hyperforin content also strongly induces CYP3A4 and P-glycoprotein.", "indication": "Mild to moderate depression (self-limited use) — evidence supports benefit similar to some antidepressants for mild-moderate depression, but NOT for severe depression.", "dosage": "300 mg PO TID (standardized 0.3% hypericin extract) for mild-moderate depression; significant CYP3A4/P-gp induction — many interactions", "examPoints": ["CLASSIC EXAM TRAP: potent CYP3A4/P-gp inducer — reduces efficacy of oral contraceptives, warfarin, cyclosporine, many antidepressants, and other CYP3A4 substrates", "Risk of serotonin syndrome if combined with SSRIs, SNRIs, triptans, or other serotonergic drugs — must screen before recommending", "Can cause photosensitivity — counsel on sun protection", "Should not be used for severe depression or combined/switched without physician involvement due to interaction complexity and withdrawal/interaction issues", "Onset of benefit takes several weeks, similar to conventional antidepressants"], "counselling": ["Tell your pharmacist about all other medications you take before starting — this product interacts with many drugs including birth control pills and blood thinners", "Do not combine with prescription antidepressants unless directed by your doctor, due to serotonin syndrome risk", "Use extra sun protection as this product can increase sun sensitivity", "Effects build gradually over several weeks — do not expect immediate results", "Do not stop hormonal contraception reliance on this product alone — effectiveness of the pill can be reduced"], "sideEffects": ["GI upset", "Photosensitivity", "Dizziness", "Dry mouth", "Serotonin syndrome risk with interacting drugs", "Reduced efficacy of many co-administered medications"]}, {"topic": "otc", "generic": "Ginkgo biloba", "pronunciation": "GING-koh by-LOH-buh", "brand": ["Jamieson Ginkgo Biloba", "A.Vogel Ginkgo"], "class": "Natural health product — botanical", "moa": "Proposed antioxidant and mild platelet-activating factor (PAF) antagonist effects, with possible mild vasodilatory and neuroprotective properties; evidence for cognitive benefit is mixed/weak.", "indication": "Marketed for memory/cognitive support and peripheral circulation (e.g., claudication) — evidence is limited/inconsistent.", "dosage": "120–240 mg/day PO in divided doses (standardized extract) for claimed cognitive/circulatory benefits; evidence limited, mild antiplatelet effect", "examPoints": ["CLASSIC EXAM TRAP: increases bleeding risk — caution/avoid with anticoagulants (warfarin, DOACs), antiplatelets (ASA, clopidogrel), and NSAIDs; stop before surgery", "Case reports of spontaneous bleeding (including intracranial) when combined with anticoagulants", "Evidence for meaningful benefit in dementia/cognitive decline is weak and inconsistent across trials", "Should be discontinued at least 1-2 weeks before elective surgery due to bleeding risk"], "counselling": ["Tell your pharmacist if you take blood thinners, aspirin, or NSAIDs before starting this product", "Stop taking this product at least 1-2 weeks before any planned surgery", "Report any unusual bruising or bleeding to your healthcare provider", "Evidence for memory benefit is limited — set realistic expectations"], "sideEffects": ["GI upset", "Headache", "Increased bleeding risk", "Dizziness", "Rare allergic skin reaction"]}, {"topic": "otc", "generic": "Glucosamine sulfate (± chondroitin)", "pronunciation": "gloo-KOH-suh-meen SUL-fayt (kon-DROY-tin)", "brand": ["Jamieson Glucosamine", "Osteo Bi-Flex"], "class": "Natural health product — joint health supplement", "moa": "Proposed substrate for glycosaminoglycan and proteoglycan synthesis in cartilage, potentially supporting cartilage repair and reducing inflammatory mediators; clinical evidence for symptom benefit is modest/mixed.", "indication": "Osteoarthritis symptom management (joint pain/stiffness), particularly knee OA.", "dosage": "1500 mg/day PO (often with chondroitin 1200 mg/day) in divided or single dose for osteoarthritis symptom relief", "examPoints": ["CLASSIC EXAM TRAP: glucosamine is often derived from shellfish (crustacean exoskeletons) — caution/avoid in patients with shellfish allergy (though evidence on cross-reactivity is debated, standard practice is to ask/avoid)", "May cause a mild increase in blood glucose — theoretical caution in diabetics, though clinical significance is debated", "Full effect may take 4-8 weeks of consistent use to assess benefit", "Not recommended for acute pain relief — this is a slow-onset, maintenance-type supplement, not an analgesic"], "counselling": ["Take consistently as directed; it can take 4-8 weeks before you notice a difference in joint symptoms", "If you have a shellfish allergy, check with your pharmacist as many products are derived from shellfish", "This is not a fast-acting pain reliever — continue your usual analgesic as needed while assessing benefit", "Diabetic patients should monitor blood glucose closely when starting, though effect on glucose is usually minor"], "sideEffects": ["GI upset (nausea, heartburn)", "Headache", "Rare allergic reaction (shellfish-derived products)", "Possible mild blood glucose elevation"]}, {"topic": "otc", "generic": "Nicotine replacement therapy (patch, gum, lozenge, inhaler)", "pronunciation": "NIK-oh-teen ree-PLAYS-ment THAIR-uh-pee", "brand": ["Nicoderm", "Nicorette"], "class": "Smoking cessation aid", "moa": "Provides controlled nicotine delivery to partially occupy nicotinic acetylcholine receptors, reducing withdrawal symptoms and cravings while removing exposure to combustion toxins.", "indication": "Smoking cessation adjunct to behavioural support.", "dosage": "Patch 21 mg/24h taper over 6–12 weeks; gum/lozenge 2–4 mg q1–2h PRN based on cigarettes/day; inhaler 6–16 cartridges/day PRN", "examPoints": ["Patch provides steady-state background nicotine (16-hr or 24-hr options); gum/lozenge/inhaler provide rapid, as-needed relief for breakthrough cravings — often combination therapy (patch + fast-acting) is more effective than either alone", "Dose selection based on cigarettes/day (e.g., >=10-20 cigs/day typically starts on higher-strength patch/gum)", "Gum must be chewed with the \"chew and park\" technique — chewing too fast/continuously causes excess salivation and reduced buccal absorption plus jaw pain/hiccups", "Acidic beverages (coffee, juice, soda) reduce buccal absorption of nicotine from gum/lozenge — avoid eating/drinking for 15 minutes before and during use", "Insomnia/vivid dreams can occur with 24-hr patches — switching to 16-hr patch (removed at bedtime) can help"], "counselling": ["Apply the patch to a clean, dry, hairless area of skin each morning and rotate application sites to reduce irritation", "For gum: chew slowly until you taste a peppery/minty flavour, then \"park\" it between your cheek and gum; repeat this cycle for about 30 minutes", "Avoid coffee, juice, and soda for 15 minutes before and while using gum or lozenges as they reduce absorption", "If you have vivid dreams or trouble sleeping with the patch, try removing it before bed (16-hour patch) instead of the 24-hour version", "Combining a patch with as-needed gum/lozenge for breakthrough cravings is often more effective than either alone"], "sideEffects": ["Skin irritation at patch site", "Sleep disturbance/vivid dreams (patch)", "Mouth/throat irritation, hiccups, jaw discomfort (gum)", "Nausea", "Palpitations at high doses"]}, {"topic": "otc", "generic": "Ranitidine alternative: Famotidine / Calcium carbonate", "pronunciation": "ruh-NIT-ih-deen / fuh-MOH-tih-deen / KAL-see-um KAR-boh-nayt", "brand": ["Pepcid AC", "Tums"], "class": "OTC antacid / H2-receptor antagonist", "moa": "Famotidine competitively blocks histamine H2 receptors on gastric parietal cells, reducing acid secretion; calcium carbonate directly neutralizes existing stomach acid on contact.", "indication": "Heartburn, acid indigestion, GERD symptom relief (self-care, short-term).", "dosage": "Famotidine 10–20 mg PO PRN/BID (OTC); Calcium carbonate 500–1000 mg PO PRN for heartburn, max per label", "examPoints": ["Famotidine has a slower onset (~1 hour) but longer duration (~10-12 hours) than antacids — better for prevention taken before a trigger meal; antacids act within minutes but only last 20-60 minutes", "Antacids can chelate/reduce absorption of many drugs (tetracyclines, fluoroquinolones, iron, levothyroxine) — separate dosing by at least 2 hours", "Famotidine dose adjustment needed in renal impairment", "Self-care red flags requiring referral: symptoms >2 weeks despite OTC treatment, dysphagia, weight loss, GI bleeding (melena/hematemesis), age >55 with new-onset symptoms", "Ranitidine was withdrawn from the Canadian market due to NDMA contamination concerns — famotidine is the standard OTC H2RA alternative now"], "counselling": ["Famotidine can be taken before a meal expected to cause heartburn, or as needed for symptoms, up to twice daily", "Antacids like calcium carbonate work quickly for occasional heartburn but wear off faster", "If taking other medications, separate them from antacids by at least 2 hours to avoid absorption interference", "See a doctor if heartburn persists more than 2 weeks, or if you have difficulty swallowing, unintended weight loss, or black/bloody stools"], "sideEffects": ["Headache (famotidine)", "Constipation (calcium carbonate)", "Rare confusion in elderly/renal impairment (famotidine)", "Belching/gas (calcium carbonate)"]}, {"topic": "otc", "generic": "Polyethylene glycol 3350", "pronunciation": "pol-ee-ETH-ih-leen GLY-kol", "brand": ["RestoraLAX", "PegLyte", "Lax-A-Day"], "class": "Osmotic laxative", "moa": "Non-absorbable polymer that osmotically retains water in the colon, softening stool and increasing stool frequency without significant electrolyte shifts.", "indication": "Occasional or chronic constipation — first-line laxative for most patients including long-term use.", "dosage": "17 g PO dissolved in liquid once daily PRN for constipation; onset 1–3 days", "examPoints": ["Onset of action is typically 1-3 days — counsel patients not to expect immediate relief like a stimulant laxative", "Considered safe for long-term daily use, including in elderly and pediatric patients, unlike stimulant laxatives", "Minimal electrolyte disturbance compared to other osmotic agents (e.g., magnesium- or phosphate-based)", "Self-care red flags: rectal bleeding, unexplained weight loss, severe abdominal pain, vomiting, or constipation alternating with diarrhea warrant referral (possible bowel obstruction or other pathology)", "No significant taste when dissolved in liquid — improves adherence versus other osmotic agents"], "counselling": ["Dissolve the powder completely in 250 mL (1 cup) of water, juice, or another beverage and drink once daily", "Effects are usually seen within 1-3 days — this is not a fast-acting product", "Maintain adequate fluid intake while using this product", "Can be used for both short-term and longer-term management of constipation under guidance", "Seek medical attention if you notice rectal bleeding, severe abdominal pain, or if constipation is accompanied by vomiting"], "sideEffects": ["Bloating/gas", "Abdominal cramping", "Nausea", "Diarrhea if overdosed"]}, {"topic": "otc", "generic": "Cetirizine / Loratadine", "pronunciation": "seh-TEER-ih-zeen / lor-AT-uh-deen", "brand": ["Reactine", "Claritin"], "class": "OTC second-generation (non-sedating) antihistamine", "moa": "Selectively antagonizes peripheral H1 histamine receptors, reducing allergic symptoms (itching, sneezing, rhinorrhea, urticaria) with minimal CNS penetration compared to first-generation agents.", "indication": "Allergic rhinitis, urticaria, other histamine-mediated allergic symptoms.", "dosage": "Cetirizine 10 mg PO once daily; Loratadine 10 mg PO once daily; both non-sedating, renal/hepatic dose adjustment for cetirizine", "examPoints": ["Second-generation agents (cetirizine, loratadine, fexofenadine, desloratadine) cause significantly less sedation than first-generation (diphenhydramine) due to poor blood-brain barrier penetration (P-gp substrate)", "Cetirizine is somewhat more sedating than loratadine/fexofenadine within the second-generation class — worth noting for patients sensitive to drowsiness", "Once-daily dosing improves adherence versus older agents", "Dose adjustment needed in renal impairment (especially cetirizine, renally cleared)", "Fexofenadine absorption is reduced by fruit juices (grapefruit, orange, apple) — take with water"], "counselling": ["Take once daily, with or without food", "While less sedating than older antihistamines, use caution when first starting until you know how it affects you", "If one non-sedating antihistamine doesn't work well, switching to a different one in the class sometimes helps (individual response varies)", "Renal impairment may require a lower dose — check with your pharmacist", "For fexofenadine specifically, take with water rather than fruit juice to ensure full absorption"], "sideEffects": ["Mild drowsiness (more with cetirizine than loratadine/fexofenadine)", "Dry mouth", "Headache", "Rare paradoxical stimulation in children"]}, {"topic": "otc", "generic": "Vitamin D3 (cholecalciferol)", "pronunciation": "koh-luh-kal-SIF-er-ol", "brand": ["Jamieson Vitamin D", "D-Vi-Sol"], "class": "Vitamin supplement (fat-soluble)", "moa": "Converted in the liver and kidney to active calcitriol, which increases intestinal calcium and phosphate absorption and supports bone mineralization and immune function.", "indication": "Vitamin D deficiency prevention/treatment, bone health support, supplementation in limited sun exposure (common in Canadian climate) or breastfed infants.", "dosage": "400–2000 IU PO once daily for general maintenance; higher repletion doses (e.g., 50,000 IU weekly x8wk) for documented deficiency", "examPoints": ["Health Canada recommends routine supplementation for exclusively/partially breastfed infants (400 IU/day) since breast milk is low in vitamin D", "Common general adult maintenance dose is 400-1000 IU/day; higher therapeutic doses (e.g., 1000-2000+ IU/day or higher, or prescription 10,000 IU) used for diagnosed deficiency under monitoring", "Being fat-soluble, toxicity (hypercalcemia) is possible with excessive chronic high-dose intake — unlike water-soluble vitamins", "Take with a meal containing fat for optimal absorption", "Canadians are at higher risk of deficiency due to limited UVB sun exposure especially in winter months and northern latitudes"], "counselling": ["Take with a meal that contains some fat to improve absorption", "Follow the recommended dose for your age group — infants, adults, and older adults have different recommended intakes", "More is not necessarily better — very high doses over time can cause harmful calcium buildup", "If you have limited sun exposure, especially in winter, supplementation is generally recommended in Canada"], "sideEffects": ["Generally well tolerated at recommended doses", "GI upset at high doses", "Hypercalcemia with chronic excessive intake", "Nausea, weakness with toxicity"]}, {"topic": "otc", "generic": "Ferrous sulfate / Ferrous gluconate / Ferrous fumarate", "pronunciation": "FAIR-us SUL-fayt / FAIR-us GLOO-koh-nayt / FAIR-us FYOO-muh-rayt", "brand": ["Feosol", "Palafer"], "class": "Oral iron supplement", "moa": "Provides elemental iron for incorporation into hemoglobin, supporting red blood cell production in iron-deficiency states.", "indication": "Iron deficiency anemia, prevention of deficiency in pregnancy or heavy menstrual blood loss.", "dosage": "60–120 mg elemental iron PO once daily–TID for iron-deficiency anemia; take on empty stomach if tolerated, separate from antacids/calcium", "examPoints": ["Elemental iron content differs by salt: ferrous fumarate (~33%) > ferrous sulfate (~20%) > ferrous gluconate (~12%) — relevant for dosing comparisons", "Best absorbed on an empty stomach with vitamin C/orange juice (enhances absorption); food, especially calcium, dairy, tea/coffee (tannins), and antacids reduce absorption significantly", "Causes dark/black stools — a benign but important counselling point to distinguish from GI bleeding (melena)", "Constipation is common — counsel on fluid/fibre or consider stool softener", "Take iron and calcium supplements/antacids/levothyroxine at least 2 hours apart due to absorption interference", "Accidental pediatric iron overdose is a leading cause of fatal poisoning in young children — emphasize child-proof storage"], "counselling": ["Take on an empty stomach with water or juice (vitamin C helps absorption) if tolerated; take with a small amount of food if it causes stomach upset", "Avoid taking with milk, tea, coffee, or calcium/antacid products — take these at least 2 hours apart", "Expect stools to turn dark green or black — this is normal and not harmful", "Increase fluid and fibre intake to help prevent constipation, a common side effect", "Store safely out of reach of children — iron overdose can be fatal in young children"], "sideEffects": ["Constipation", "Nausea/GI upset", "Dark stools", "Metallic taste", "Rare GI irritation/ulceration with high doses"]}, {"topic": "otc", "generic": "Dextromethorphan / Guaifenesin", "pronunciation": "deks-troh-meh-THOR-fan / gwy-FEN-eh-sin", "brand": ["Robitussin", "Buckley's", "Benylin"], "class": "OTC cough/cold — antitussive / expectorant", "moa": "Dextromethorphan suppresses the cough reflex centrally at the medullary cough centre (NMDA/sigma receptor activity); guaifenesin thins and loosens mucus secretions to make cough more productive.", "indication": "Symptomatic relief of dry/nonproductive cough (dextromethorphan) or productive cough with thick mucus (guaifenesin).", "dosage": "Dextromethorphan 10–20 mg PO q4h or 30 mg q6–8h PRN (max 120 mg/day); Guaifenesin 200–400 mg PO q4h PRN (max 2400 mg/day)", "examPoints": ["CLASSIC EXAM TRAP: dextromethorphan carries serotonin syndrome risk when combined with MAOIs (contraindicated, including within 14 days of stopping an MAOI) and caution with SSRIs/SNRIs", "Combining an antitussive (suppresses cough) with an expectorant (loosens mucus to be coughed up) is somewhat contradictory pharmacologically for a productive cough — match agent to cough type", "Not generally recommended for children under 6 years (health authority guidance in Canada) due to limited efficacy evidence and safety concerns; caution/avoid under 12 in many current guidelines for cough/cold combination products", "Dextromethorphan has abuse/misuse potential at high doses (dissociative effects) — watch for repeated purchase patterns", "Cough lasting more than 1-2 weeks, or with fever, chest pain, or blood, warrants referral rather than continued self-treatment"], "counselling": ["Use dextromethorphan for a dry, irritating cough that isn't producing mucus", "Use guaifenesin for a chesty cough with thick mucus, and drink plenty of fluids to help it work", "Do not use dextromethorphan if you take or have recently stopped an MAOI antidepressant", "These products are generally not recommended for young children — check age restrictions on the label or ask your pharmacist", "See a healthcare provider if cough lasts more than 1-2 weeks or is accompanied by fever, chest pain, or blood"], "sideEffects": ["Drowsiness or dizziness (dextromethorphan)", "GI upset (guaifenesin)", "Nausea", "Rare serotonin syndrome with drug interactions (dextromethorphan)"]}, {"topic": "otc", "generic": "Diphenhydramine / Doxylamine", "pronunciation": "dy-fen-HY-druh-meen / doks-ILL-uh-meen", "brand": ["Unisom", "Nytol", "Benadryl"], "class": "OTC sleep aid — first-generation antihistamine", "moa": "Antagonizes central H1 histamine receptors, producing sedation as a side effect that is repurposed for short-term insomnia relief; also has anticholinergic activity.", "indication": "Short-term (occasional) insomnia relief; diphenhydramine also used for allergy symptoms.", "dosage": "Diphenhydramine 25–50 mg PO PRN (sleep/allergy); Doxylamine 25 mg PO at bedtime PRN for sleep; avoid in elderly (anticholinergic)", "examPoints": ["CLASSIC EXAM TRAP: strong anticholinergic effects — caution/avoid in elderly (Beers Criteria — associated with increased dementia risk with chronic use, falls, confusion), BPH/urinary retention, and narrow-angle glaucoma", "Next-day residual sedation (\"hangover effect\") is common, especially in elderly — can impair driving performance the next morning", "Tolerance to sedative effect develops within days, making it inappropriate for long-term nightly use — intended for short-term/occasional use only", "Doxylamine is also the antihistamine component in Diclectin (doxylamine/pyridoxine) for nausea in pregnancy — different use context worth distinguishing", "Not recommended for routine use in older adults due to anticholinergic burden and fall risk"], "counselling": ["Use only for occasional, short-term sleep difficulty — not intended for nightly long-term use", "Take about 30 minutes before bedtime and allow a full night (7-8 hours) for sleep before needing to drive or operate machinery", "Older adults should generally avoid this product due to increased risk of confusion, dizziness, and falls — ask your pharmacist about alternatives", "Avoid alcohol while using this product as it increases sedation", "If you have glaucoma, an enlarged prostate, or urinary retention issues, check with your pharmacist before use"], "sideEffects": ["Drowsiness/next-day grogginess", "Dry mouth", "Urinary retention", "Constipation", "Confusion (especially in elderly)", "Blurred vision"]}, {"topic": "otc", "generic": "Sennosides (Senna)", "pronunciation": "SEN-oh-syds", "brand": ["Senokot"], "class": "Stimulant laxative", "moa": "Metabolized by colonic bacteria to active compounds that directly stimulate colonic myenteric nerves, increasing peristalsis and reducing water/electrolyte absorption from the colon.", "indication": "Short-term relief of occasional constipation; second-line to bulk-forming/osmotic agents for chronic use.", "dosage": "1–2 tablets (8.6 mg sennosides) PO once–BID PRN, max 4 tablets BID", "examPoints": ["Onset of action is typically 6-12 hours — often taken at bedtime for a morning bowel movement", "Not recommended for chronic daily long-term use due to theoretical concern for laxative dependence/tolerance (\"cathartic colon\") — though modern evidence for this is debated, it remains a common teaching point", "Can cause abdominal cramping more than osmotic agents due to direct peristaltic stimulation", "Avoid in suspected bowel obstruction (red flag symptoms: severe pain, vomiting, no flatus)", "Often paired with a stool softener (docusate) in combination products for straining prevention"], "counselling": ["Take at bedtime for a bowel movement the next morning, as onset is typically 6-12 hours", "Use for short-term/occasional constipation relief rather than continuous daily use", "Drink plenty of water while taking this medication", "Stop and seek medical attention if you develop severe abdominal pain, vomiting, or if you don't pass gas or stool (possible obstruction)"], "sideEffects": ["Abdominal cramping", "Diarrhea", "Electrolyte imbalance with overuse", "Discoloration of urine (harmless)", "Nausea"]}, {"topic": "otc", "generic": "Loperamide", "pronunciation": "loh-PER-uh-myd", "brand": ["Imodium"], "class": "OTC antidiarrheal", "moa": "Acts on mu-opioid receptors in the intestinal wall to slow peristalsis and increase intestinal transit time, allowing greater water/electrolyte reabsorption, without significant CNS opioid effects at normal doses due to poor blood-brain barrier penetration.", "indication": "Symptomatic relief of acute nonspecific diarrhea and traveler's diarrhea.", "dosage": "4 mg PO after first loose stool, then 2 mg after each subsequent stool; OTC max 8 mg/day", "examPoints": ["EXAM TRAP: contraindicated/avoid in acute bloody diarrhea, high fever, or suspected invasive bacterial infection (e.g., C. difficile, Shigella) — can worsen toxic megacolon risk by slowing clearance of toxins", "Not for use in children under a certain age (typically avoid under 2 years, use caution/guidance under 12) due to risk of CNS/respiratory depression and paralytic ileus in young children", "Self-care red flags: diarrhea >48-72 hours despite treatment, signs of dehydration, blood/mucus in stool, high fever — refer rather than continue self-treatment", "Oral rehydration therapy is an essential adjunct/alternative, especially in children and elderly, not a substitute replaced solely by loperamide", "High-dose misuse (recreational) has been associated with cardiac arrhythmias (QT prolongation) — an emerging safety concern"], "counselling": ["Take as directed after each loose stool, not exceeding the maximum daily dose on the label", "Maintain hydration with water or oral rehydration solution while using this product", "Do not use if you have bloody diarrhea, high fever, or if diarrhea persists beyond 48 hours — see a healthcare provider", "Not recommended for young children without medical guidance", "Stop use and seek care if symptoms worsen or new symptoms (fever, blood in stool) develop"], "sideEffects": ["Constipation", "Abdominal cramping/bloating", "Dizziness", "Nausea", "Rare cardiac arrhythmia with high-dose misuse"]}, {"topic": "ethics", "generic": "Four principles of biomedical ethics (autonomy, beneficence, non-maleficence, justice)", "pronunciation": "by-oh-MED-ih-kul ETH-iks", "brand": [], "class": "Foundational ethics framework", "moa": "The Beauchamp & Childress framework: autonomy = respect a capable patient's right to self-determination; beneficence = act in the patient's best interest; non-maleficence = avoid causing harm ('first, do no harm'); justice = fair, equitable distribution of resources/care regardless of personal characteristics.", "indication": "Underlies virtually every ethical dilemma in pharmacy practice — used as the analytic lens when principles conflict (e.g., autonomy vs beneficence in refusing treatment).", "dosage": "Not applicable — conceptual/ethics framework, not a dosed drug", "examPoints": ["Exam stems often pit two principles against each other — identify which principle 'wins' given context (competent adult autonomy usually trumps paternalistic beneficence)", "Non-maleficence includes duty to prevent harm from errors, interactions, and diversion", "Justice includes equitable access — not refusing service based on race, ability to pay, or personal judgment of the patient", "No single principle is absolute; PEBC favors principlism balanced with professional judgment, not rigid rule-following", "Autonomy requires capacity — an incapable patient's 'autonomous' refusal may need SDM involvement"], "counselling": ["Frame patient conversations around respecting their choice while ensuring they have full information (informed autonomy)", "Document the ethical reasoning when principles conflict, not just the final action taken", "When declining a request on non-maleficence grounds, explain the specific risk in plain language", "Apply justice principle by treating walk-in and difficult patients with the same standard of care as any other"], "sideEffects": ["Treating beneficence as license for paternalism (overriding a capable patient's wishes)", "Forgetting justice when triaging time for 'difficult' patients", "Assuming one principle always trumps another regardless of context", "Ignoring non-maleficence duty to follow up on a potential interaction because the patient seems 'fine'"]}, {"topic": "ethics", "generic": "Informed consent", "pronunciation": "in-FORMD kon-SENT", "brand": [], "class": "Professional ethics / legal duty", "moa": "Consent must be voluntary, informed (nature of treatment, risks, benefits, alternatives, consequences of refusal disclosed), and given by a capable person (or their SDM). Consent can be implied (rolling up sleeve for a vaccine) or express (written for a service like injections).", "indication": "Required before initiating any pharmacy service: dispensing with counselling, administering injections/vaccines, therapeutic substitutions, adapting a prescription, or enrolling in monitoring programs.", "dosage": "Not applicable — legal/ethical concept, not a dosed drug", "examPoints": ["Four elements: capacity, voluntariness, disclosure of material information, and comprehension", "Consent is an ongoing process, not a one-time signature — patient can withdraw at any time", "Material risk = one a reasonable patient would want to know, even if statistically rare", "Emergency exception: implied consent when patient is incapable and no SDM immediately available and delay would cause harm", "Consent for a minor follows capacity assessment, not a fixed age, in most Canadian provinces (mature minor doctrine)"], "counselling": ["Explain in plain language: what the medication/service is, why, common and serious risks, alternatives (including no treatment), and expected outcome", "Confirm understanding with teach-back ('can you tell me what we just discussed?')", "Document consent discussion, especially for injections or off-label/non-standard use", "Offer opportunity for questions before proceeding, and reassure them they can decline without judgment"], "sideEffects": ["Assuming consent because the patient didn't object (silence is not consent)", "Skipping disclosure of rare-but-serious risks to save time", "Not re-confirming consent when the treatment plan changes materially", "Treating consent as a signature-only formality rather than a comprehension check", "Failing to assess capacity before accepting a refusal at face value"]}, {"topic": "ethics", "generic": "Confidentiality and its exceptions", "pronunciation": "kon-fih-DEN-shee-AL-ih-tee", "brand": [], "class": "Professional ethics / privacy law (PHIPA and provincial equivalents)", "moa": "Patient health information is confidential and may only be collected, used, or disclosed with consent, except where legislation permits/requires disclosure without consent (e.g., risk of serious harm to self/others, mandatory reporting, court order, public health reporting of certain diseases).", "indication": "Applies to every patient interaction, record, and communication (verbal, written, electronic) including discussions with family members, other health professionals, and employers.", "dosage": "Not applicable — legal/ethical concept, not a dosed drug", "examPoints": ["Key exceptions: imminent risk of serious harm to self or identifiable others (duty to warn), mandatory reporting (e.g., certain communicable diseases, impaired drivers in some provinces), court subpoena, statutory college inspection", "Family members are NOT automatically entitled to information, even spouses, without patient consent (unless SDM for an incapable patient)", "Circle of care allows sharing with other treating providers without explicit consent for that specific disclosure, but patient can expressly withdraw (lock-box)", "De-identified/aggregate data use for quality improvement is generally permitted", "Minimum necessary disclosure principle — only share what's needed for the purpose"], "counselling": ["Ask who is on the phone/at the counter before discussing any medication details for another adult", "Explain to patients how their information may be shared within the circle of care", "When disclosing without consent (e.g., harm-to-self concern), document the reasoning and who was notified", "Use private counselling areas for sensitive topics (STIs, mental health, substance use)"], "sideEffects": ["Discussing a patient's medications with a family member without confirming consent or SDM status", "Leaving printouts, screens, or voicemail messages with identifiable health info exposed", "Assuming 'spouse' automatically equals authorized recipient", "Failing to invoke the duty-to-warn exception when there's a credible risk of serious harm", "Over-disclosing more information than necessary even when an exception applies"]}, {"topic": "ethics", "generic": "Conscientious objection and duty to refer", "pronunciation": "kon-shee-EN-shus ob-JEK-shun", "brand": [], "class": "Professional ethics — scope of personal belief vs professional duty", "moa": "A pharmacist may decline to provide a legal service (e.g., Plan B, MAiD-related medications, gender-affirming hormone therapy) due to personal moral/religious belief, but must not abandon the patient — duty requires timely, non-judgmental referral to another provider/pharmacy who will provide the service without imposing personal delay or barriers.", "indication": "Arises with emergency contraception, medical assistance in dying (MAiD) medication supply, opioid agonist therapy, harm reduction supplies, and other morally contentious but legal services.", "dosage": "Not applicable — professional/ethical concept, not a dosed drug", "examPoints": ["Objection is permitted; abandonment is NOT — must ensure continuity of care", "Referral must be timely and effective (not a same-city pharmacy that's closed, not a vague 'try somewhere else')", "Pharmacist cannot impose personal judgment on the patient ('are you sure you want this?') or lecture them", "In an emergency where no timely referral is possible, most provincial colleges require the pharmacist to provide the service anyway", "This is distinct from refusing due to clinical/safety concerns (e.g., drug interaction) — that is a clinical judgment, not conscientious objection"], "counselling": ["State objection neutrally and immediately, before the patient invests time waiting: 'I'm not able to provide this personally, but let me connect you with a colleague/pharmacy who can'", "Provide the actual name, address, phone number, or transfer the prescription directly", "Avoid any facial expression, tone, or comment that shames the patient", "Document that a referral was made and to whom"], "sideEffects": ["Silently stalling or being deliberately unhelpful instead of clearly stating objection", "Lecturing or moralizing to the patient about their choice", "Referring to a pharmacy that is closed, too far, or doesn't actually offer the service", "Refusing in an emergency situation with no alternative available", "Confusing conscientious objection with clinical contraindication and using it as cover for judgment"]}, {"topic": "ethics", "generic": "Error disclosure duty", "pronunciation": "ER-er dis-KLOH-zher DOO-tee", "brand": [], "class": "Professional ethics / patient safety obligation", "moa": "When a dispensing or clinical error occurs, the pharmacist has a duty to disclose it to the affected patient promptly, honestly, and completely — including what happened, the clinical impact, and steps being taken — regardless of whether the error caused harm, separate from any internal incident reporting/QA process.", "indication": "Any medication error: wrong drug, wrong dose, wrong patient, wrong instructions, omission, or clinically significant near-miss reaching the patient.", "dosage": "Not applicable — professional/ethical concept, not a dosed drug", "examPoints": ["Disclosure to the patient is an ethical/professional duty distinct from internal continuous quality improvement (CQI) reporting — both must happen", "Disclose even if no harm occurred and even if the patient hasn't noticed", "Apologize for the error itself without necessarily admitting legal liability language (most provinces have apology legislation protecting sincere apologies from being used as legal admission)", "Explain corrective action being taken to prevent recurrence", "Delay or non-disclosure is itself a separate ethical breach, worse than the original error in many cases"], "counselling": ["Contact the patient as soon as the error is discovered — don't wait for them to notice", "Use plain, non-defensive language: 'I want to let you know we made an error with your prescription...'", "Explain concretely what to monitor for or what corrective steps to take (e.g., return incorrect med, take corrected dose)", "Offer a direct contact for follow-up questions and document the disclosure conversation"], "sideEffects": ["Hoping the patient won't notice and staying silent", "Disclosing only after the patient discovers it themselves", "Being defensive or blaming other staff during disclosure", "Fixing the error internally (CQI) but skipping patient notification entirely", "Over-apologizing in a way that creates confusing legal exposure vs a sincere, clear apology"]}, {"topic": "ethics", "generic": "Capacity assessment and substitute decision-makers", "pronunciation": "kuh-PAS-ih-tee uh-SESS-ment", "brand": [], "class": "Professional ethics / health law", "moa": "Capacity is decision-specific and time-specific: a patient is capable if they can understand the relevant information and appreciate the reasonably foreseeable consequences of a decision (or lack of one). Capacity is presumed unless demonstrated otherwise. If incapable, decisions fall to a hierarchy of substitute decision-makers (SDM) as defined by provincial law.", "indication": "Needed whenever consent or refusal is in question — cognitive impairment, intoxication, acute psychiatric crisis, pediatric patients, or any situation where the patient's ability to understand is in doubt.", "dosage": "Not applicable — legal/ethical concept, not a dosed drug", "examPoints": ["Capacity is decision-specific — a patient may be capable of deciding about a cough syrup but not a complex chemo regimen", "Capacity is NOT the same as agreeing with the pharmacist's recommendation — disagreement alone is not incapacity", "SDM hierarchy typically: court-appointed guardian > attorney for personal care > spouse/partner > child > parent > sibling > other relative (order varies by province)", "SDM must make decisions per prior expressed wishes if known, otherwise in the patient's best interest", "A fluctuating capacity (e.g., delirium, intoxication) may require reassessment at a later, more lucid time rather than an immediate SDM override for non-urgent decisions"], "counselling": ["Assess capacity through a conversation, not a checklist — can they explain the decision and its consequences in their own words?", "When capacity is uncertain and the decision is non-urgent, offer to revisit when the patient is more alert/sober rather than immediately escalating to SDM", "When engaging an SDM, confirm their legal standing and document the basis (relationship, any documentation)", "Explain the decision and rationale to both the patient (to the extent possible) and the SDM"], "sideEffects": ["Equating disagreement with the pharmacist's advice as automatic incapacity", "Applying a global capacity label instead of assessing per-decision", "Skipping the SDM hierarchy and asking whichever family member is present", "Failing to reassess capacity when a temporary condition (intoxication, acute illness) resolves"]}, {"topic": "ethics", "generic": "Scope-of-practice boundaries", "pronunciation": "skohp uv PRAK-tis BOWN-duh-reez", "brand": [], "class": "Professional ethics / regulatory competence", "moa": "Pharmacists must practice only within the scope authorized by their provincial college and their individual competence/certification (e.g., prescribing authority, injection certification), and must refer or collaborate when a patient's needs exceed that scope.", "indication": "Applies to prescribing adaptations, therapeutic substitutions, minor ailment prescribing, injections, and any expanded scope activity that varies significantly by province.", "dosage": "Not applicable — regulatory/professional concept, not a dosed drug", "examPoints": ["Scope of practice is set provincially — what's authorized in Alberta/Ontario may differ from other provinces; PEBC exam uses generalized Canadian scope concepts", "Practicing beyond authorized scope is a regulatory violation even if the pharmacist believes they are clinically competent", "Practicing below scope (failing to use full authorized scope when needed, e.g., not adapting an expired prescription when authorized) can also be a professionalism/access issue", "Competence requires ongoing education — certification alone doesn't guarantee current competence for infrequently-used skills", "Refer to physician/NP/specialist when the clinical complexity exceeds pharmacist scope (e.g., new complex diagnosis, unstable condition)"], "counselling": ["Be transparent with patients about what you can and cannot do under your authorized scope", "When referring, explain why (this is outside my scope / requires physician assessment), not just 'go see a doctor'", "Document scope-based clinical decisions (e.g., minor ailment assessment and prescribing rationale)", "Seek additional training/certification proactively before expanding personal practice into a new authorized activity"], "sideEffects": ["Prescribing or adapting beyond what the province authorizes", "Diagnosing conditions outside the minor ailments list without appropriate referral", "Assuming a skill learned once (e.g., injections) remains competent without practice/renewal", "Being overly conservative and refusing to use legitimate scope, delaying patient access unnecessarily"]}, {"topic": "ethics", "generic": "Conflict of interest", "pronunciation": "KON-flikt uv IN-trest", "brand": [], "class": "Professional ethics — integrity of professional judgment", "moa": "A conflict of interest arises when a pharmacist's personal, financial, or other interests could improperly influence (or appear to influence) their professional judgment or the patient's care — must be disclosed and managed to prioritize patient welfare over personal/business gain.", "indication": "Common scenarios: incentives tied to selling specific products, dispensing quotas, referral fees, employer pressure to push a particular brand/OTC product, personal relationships with patients, or investing in a company whose drugs are recommended.", "dosage": "Not applicable — professional/ethical concept, not a dosed drug", "examPoints": ["Disclosure is necessary but not always sufficient — some conflicts require complete avoidance (e.g., dispensing to self or immediate family in certain jurisdictions/situations)", "Recommending a therapeutically equivalent but higher-margin product without disclosing a financial incentive is a breach", "Employer/corporate pressure (sales targets, promotional pushes) does not override the duty to recommend based on patient need", "Accepting gifts from pharmaceutical reps that could influence prescribing/recommending behavior is a classic conflict scenario", "Perceived conflicts (appearance of impropriety) matter even without provable actual influence"], "counselling": ["Disclose any relevant financial or personal interest to the patient when recommending a product/service", "Base recommendations strictly on clinical appropriateness and patient preference/cost, not commission structures", "Decline gifts or incentives that could reasonably be seen as influencing clinical judgment", "When a family member/friend is the patient, consider involving another pharmacist for objectivity on complex therapy decisions"], "sideEffects": ["Pushing higher-margin OTC products or add-on sales without clinical justification", "Ignoring employer dispensing-quota pressure conflicts and prioritizing volume over appropriateness", "Failing to disclose being a shareholder/rep-affiliated when recommending a specific product", "Assuming disclosure alone resolves every conflict when avoidance is actually required"]}, {"topic": "ethics", "generic": "Managing suspected diversion and drug-seeking behaviour non-judgmentally", "pronunciation": "dy-VER-zhun", "brand": [], "class": "Professional ethics — harm reduction and professional judgment", "moa": "Balances non-maleficence/public safety (preventing diversion, misuse) with beneficence, autonomy, and anti-stigma principles — pharmacists must use objective, consistent, documented criteria (PMP/prescription monitoring checks, dosing patterns, early refill history) rather than assumptions based on appearance, history, or stereotype, and engage the patient respectfully.", "indication": "Early refill requests, patients seen at multiple prescribers/pharmacies, high-dose opioid/benzodiazepine combinations, pattern suggestive of misuse or diversion, or a patient with a documented substance use disorder seeking legitimate treatment.", "dosage": "Not applicable — professional practice concept, not a dosed drug", "examPoints": ["Use objective tools consistently for ALL patients (e.g., prescription monitoring program checks) rather than selectively based on appearance or assumption — inconsistent application is discriminatory", "A patient with substance use disorder still has the right to non-judgmental, dignified care and pain/symptom management", "Verify with prescriber and document reasoning before refusing to fill, rather than an outright unilateral refusal", "Distinguish between refusing to fill (a clinical/professional judgment call, requires documentation and alternative arrangement) vs reporting suspected diversion (may trigger regulatory/legal duty)", "Stigmatizing language or visibly treating a patient differently in front of others is itself a professionalism breach"], "counselling": ["Speak to the patient privately and respectfully about any discrepancy noticed, rather than accusing publicly", "Explain any verification steps being taken (e.g., 'I need to confirm this with your prescriber before I can fill it')", "Offer harm-reduction resources (naloxone, safer use info) regardless of suspected diversion status", "Document objective findings (PMP results, refill dates, prescriber contact) rather than subjective impressions"], "sideEffects": ["Profiling patients based on appearance, age, or history rather than objective data", "Publicly confronting or shaming a patient at the counter", "Refusing to fill without contacting the prescriber or documenting rationale", "Applying extra scrutiny inconsistently across different patient populations", "Withholding harm reduction supplies/naloxone as a punitive measure"]}, {"topic": "ethics", "generic": "Professional boundaries", "pronunciation": "proh-FESH-uh-nul BOWN-duh-reez", "brand": [], "class": "Professional ethics — therapeutic relationship integrity", "moa": "Pharmacists must maintain a clear professional relationship with patients, avoiding dual relationships (romantic, business, overly personal) that could impair objectivity or be exploitative given the inherent power imbalance between provider and patient.", "indication": "Applies broadly, but especially relevant with vulnerable patients (mental health, substance use, elderly, minors), long-term care relationships, and small/rural communities where dual relationships are harder to avoid.", "dosage": "Not applicable — professional/ethical concept, not a dosed drug", "examPoints": ["Power imbalance exists even when not overtly exploited — patients may feel unable to refuse a boundary-crossing request", "Romantic/sexual relationships with current patients are a boundary violation regardless of apparent mutual consent", "Accepting significant gifts, lending/borrowing money, or entering business deals with patients blurs the professional relationship", "In small/rural practice where the pharmacist may also be a neighbour/friend, extra deliberate effort is needed to maintain professional objectivity in clinical decisions", "Boundary violations are assessed even after the professional relationship formally ends, within a defined cooling-off consideration in most colleges' standards"], "counselling": ["Keep interactions focused on the clinical/professional purpose, redirecting personal topics gently", "Decline significant gifts or invitations that could be seen as compromising objectivity, while remaining courteous", "If a dual relationship is unavoidable (small town), disclose it and consider involving a colleague for objectivity on sensitive matters", "Seek supervision/consultation with the regulatory college if uncertain whether a situation crosses a boundary"], "sideEffects": ["Rationalizing a romantic relationship with a patient as 'mutual and consensual'", "Accepting large gifts or financial entanglements with patients", "Sharing excessive personal information that shifts the relationship dynamic", "Failing to recognize how power imbalance affects a patient's ability to say no"]}, {"topic": "ethics", "generic": "Cultural competence and health literacy", "pronunciation": "KUL-chur-ul KOM-peh-tens", "brand": [], "class": "Professional ethics — equitable, patient-centred communication", "moa": "Requires adapting communication and care to the patient's cultural context, language proficiency, and health literacy level without stereotyping — using plain language, teach-back, and professional interpreters (not family members, especially minors) to ensure genuine understanding and respect for cultural health beliefs.", "indication": "Every patient encounter, but especially critical with limited-English-proficiency patients, newcomers, Indigenous patients, and patients with low health literacy or differing cultural beliefs about medicine (e.g., traditional/complementary practices).", "dosage": "Not applicable — professional practice concept, not a dosed drug", "examPoints": ["Avoid assumptions based on ethnicity, religion, or accent about a patient's beliefs or literacy — ask, don't assume", "Use professional interpreter services rather than family members (especially children) for medical interpretation, to preserve accuracy and confidentiality/dignity", "Health literacy is distinct from language — even English-fluent patients may not understand medical terminology; use plain language for everyone", "Respecting cultural/traditional health practices means discussing them openly (interactions, safety) rather than dismissing them outright", "Teach-back method is a validated way to confirm comprehension across literacy/language levels"], "counselling": ["Ask patients their preferred language and arrange interpretation services proactively", "Use plain, jargon-free language and visual aids (pictograms, dosing charts) for all patients", "Ask open, non-judgmental questions about traditional or complementary therapies the patient may be using", "Confirm understanding with teach-back rather than assuming comprehension from a nod"], "sideEffects": ["Using a patient's child as an interpreter for sensitive medical information", "Assuming literacy or fluency based on appearance or accent", "Dismissing traditional remedies instead of assessing them for interactions/safety", "Using medical jargon without checking understanding", "Stereotyping care approach based on a patient's perceived cultural background"]}, {"topic": "ethics", "generic": "Duty to report (mandatory and permissive reporting)", "pronunciation": "DOO-tee too ree-PORT", "brand": [], "class": "Professional ethics / legal obligation", "moa": "Certain circumstances create a legal duty to report to authorities even without patient consent — overriding confidentiality — including child abuse/neglect, certain communicable diseases, impaired ability to drive in some provinces, and colleague impairment/incompetence/misconduct that poses risk to patients.", "indication": "Suspected child abuse, notifiable communicable diseases (public health reporting), a colleague practicing while impaired or grossly incompetent, and (in some provinces) medical conditions impairing ability to safely drive.", "dosage": "Not applicable — legal/regulatory concept, not a dosed drug", "examPoints": ["Duty to report suspected child abuse/neglect is mandatory in all Canadian provinces regardless of profession or usual confidentiality rules", "Duty to report an impaired or incompetent colleague to the regulatory college is a professional obligation, not optional collegiality — protecting patients takes priority over workplace loyalty", "Reporting thresholds are 'reasonable suspicion,' not proof — the reporter is not required to investigate or confirm", "Reporters acting in good faith are generally protected from liability under the relevant reporting legislation", "Distinguish mandatory reporting (legally required) from permissive reporting (legally allowed but discretionary, e.g., some driving-fitness concerns)"], "counselling": ["Report based on reasonable suspicion promptly through the correct channel (child protection agency, public health, regulatory college) rather than delaying to gather more proof", "Document the observations that led to the report factually and objectively", "When reporting a colleague, follow the college's process and, where safe, be transparent that a report is being made per professional obligation", "Explain to a patient (where appropriate and safe) that a report is legally required, to maintain trust and transparency"], "sideEffects": ["Staying silent about a colleague's impairment out of workplace loyalty or fear of conflict", "Waiting for 'proof' before reporting suspected child abuse instead of acting on reasonable suspicion", "Confusing mandatory vs permissive reporting obligations and either over- or under-reporting", "Failing to document the factual basis for a report"]}, {"topic": "ethics", "generic": "Truth-telling and non-deception in patient communication", "pronunciation": "trooth-TEL-ing", "brand": [], "class": "Professional ethics — veracity", "moa": "Pharmacists owe patients honest, accurate information, including uncertainty (e.g., 'we don't have strong evidence for X') and bad news (e.g., therapeutic failure, need for escalation) — therapeutic privilege (withholding info to 'protect' a patient) is rarely justified and never a substitute for informed consent.", "indication": "Applies when discussing prognosis, treatment failure, placebo use, off-label therapy, uncertain evidence for a product, or when a patient asks a direct question the pharmacist would rather avoid.", "dosage": "Not applicable — ethical concept, not a dosed drug", "examPoints": ["Therapeutic privilege (withholding information because the truth may upset the patient) is an outdated and rarely acceptable justification today", "Recommending a placebo without disclosure is a deception issue, not just a clinical one", "Honesty includes admitting uncertainty or lack of evidence rather than overstating confidence in a product's efficacy", "Bad news should be delivered with empathy but without euphemism that obscures the actual message", "Even 'white lies' intended to reassure (e.g., overstating expected benefit) undermine informed consent and trust"], "counselling": ["State uncertainty plainly: 'the evidence for this product is limited, but some patients find it helpful'", "Deliver difficult information (treatment not working, need to see prescriber urgently) directly but compassionately", "Avoid vague reassurance that isn't clinically accurate just to end an uncomfortable conversation quickly", "Pair honest disclosure with support — explain next steps so honesty doesn't feel like abandonment"], "sideEffects": ["Overstating an OTC product's evidence to make a sale or satisfy the patient", "Withholding a concerning finding to avoid an uncomfortable conversation", "Using vague language that lets the patient believe something inaccurate", "Dispensing/recommending placebo-equivalent products without any disclosure"]}, {"topic": "ethics", "generic": "Resource allocation and justice in practice (e.g., drug shortages)", "pronunciation": "REE-sors al-oh-KAY-shun", "brand": [], "class": "Professional ethics — distributive justice", "moa": "When resources are limited (drug shortages, high-demand vaccines, limited appointment slots), allocation must follow transparent, consistent, clinically-justified criteria applied equally to all patients rather than favoritism, first-come chaos, or personal judgment about 'deserving' patients.", "indication": "Drug shortage triage (deciding who gets remaining stock), vaccine prioritization during supply constraints, limited compounding capacity, or clinic appointment scarcity.", "dosage": "Not applicable — ethical/systems concept, not a dosed drug", "examPoints": ["Criteria should be clinical (severity, urgency, lack of alternatives) and applied consistently, documented, and ideally aligned with public health/college guidance during shortages", "First-come-first-served can be ethically defensible for low-stakes scarcity but not when clinical urgency clearly differs among patients", "Favoring regular/loyal customers over walk-ins for scarce supply is a justice violation", "Transparency: informing all affected patients of the shortage and the allocation approach preserves trust", "Should escalate/collaborate with prescribers and other pharmacies to find alternative supply rather than unilaterally deciding who 'deserves' the drug"], "counselling": ["Communicate shortage status proactively and explain the fair criteria being used", "Offer to help locate alternative supply or therapeutic alternatives rather than just saying 'we're out'", "Avoid making value judgments about which patients are more 'deserving' of scarce medication", "Document allocation decisions and rationale, especially in shortage situations"], "sideEffects": ["Reserving scarce stock informally for preferred or regular customers", "Failing to communicate transparently about a shortage, leaving patients in the dark", "Applying inconsistent, ad hoc criteria from patient to patient", "Not exploring therapeutic alternatives or inter-pharmacy transfer before turning a patient away"]}, {"topic": "ethics", "generic": "Whistleblowing and reporting systemic/workplace issues", "pronunciation": "WHISS-ul-bloh-ing", "brand": [], "class": "Professional ethics — accountability beyond the individual encounter", "moa": "Pharmacists have an ethical obligation to raise concerns about systemic issues (inadequate staffing compromising safety, employer pressure to cut corners, unsafe workflow) through appropriate internal and, if unresolved, external/regulatory channels, even at personal or employment risk.", "indication": "Chronic understaffing leading to error risk, employer policies conflicting with professional standards (e.g., pressuring rapid dispensing without proper verification), or observing a pattern of near-misses tied to a systemic cause.", "dosage": "Not applicable — professional/ethical concept, not a dosed drug", "examPoints": ["Professional obligation to patient safety can supersede employment loyalty or fear of retaliation", "Escalation pathway: raise internally first (management/pharmacy manager) → document concerns → escalate to regulatory college if unresolved and patient safety is at risk", "Whistleblower protections exist in most provinces/employment contexts for good-faith safety reports", "Distinguish a single isolated error (individual disclosure/CQI) from a systemic pattern (requires broader reporting)", "The regulatory college's role is protecting the public, not just adjudicating individual complaints — systemic issues are within its mandate"], "counselling": ["Document specific, factual instances (dates, near-misses, workload data) rather than vague complaints when raising concerns", "Raise concerns through proper channels first, escalating only if unaddressed", "Frame the concern around patient safety impact, not personal grievance, to keep the focus appropriately professional", "Know and use the anonymous/protected reporting mechanisms available through the regulatory college if needed"], "sideEffects": ["Staying silent about unsafe staffing/workflow out of fear of employer retaliation", "Escalating externally without first attempting reasonable internal resolution (when safe/appropriate to do so)", "Failing to document specific evidence, weakening the case for systemic change", "Treating a systemic pattern as a series of unrelated individual errors"]}, {"topic": "calc", "generic": "Cockcroft-Gault creatinine clearance (CrCl)", "pronunciation": "KOK-kroft-GAWLT kree-AT-ih-neen", "brand": [], "class": "Renal function / dosing calculation", "moa": "CrCl (mL/min) = [(140 - age) x weight(kg)] / (72 x SCr(mg/dL)); multiply result by 0.85 if female. Uses actual body weight unless obese, then adjusted body weight (ABW) is typically used; underweight patients often use actual weight.", "indication": "Used to dose renally-cleared drugs (e.g., DOACs, aminoglycosides, vancomycin, many antibiotics) and to determine contraindications based on renal function thresholds.", "dosage": "Not applicable — calculation method, not a dosed drug", "examPoints": ["Worked example: 68-yo female, 60 kg, SCr 1.1 mg/dL → [(140-68) x 60] / (72 x 1.1) x 0.85 = (72x60)/(79.2) x0.85 = 4320/79.2=54.5 x0.85 ≈ 46.4 mL/min", "SCr must be in mg/dL for this formula; convert from micromol/L by dividing by 88.4", "Use adjusted body weight if actual weight >30% over ideal body weight: ABW = IBW + 0.4 x (actual - IBW)", "Cockcroft-Gault is the formula most drug monographs/renal dosing tables reference — not MDRD or CKD-EPI (those estimate GFR, used differently)", "Always apply the x0.85 female correction factor — a very common omission on exams"], "counselling": ["Explain to a patient why a dose is being reduced: 'your kidney function calculation means we adjust this dose to keep it safe'", "Document the CrCl value, weight used, and formula version in the patient's profile when adjusting a dose", "Recheck CrCl periodically for patients on renally-cleared drugs with changing renal function (elderly, acute illness)", "Flag to the prescriber when CrCl falls below a drug's labeled threshold for use/contraindication"], "sideEffects": ["Forgetting the female correction factor (x0.85)", "Using SCr in micromol/L without converting to mg/dL first", "Using actual body weight in a significantly obese patient without adjusting", "Confusing Cockcroft-Gault (CrCl, used for drug dosing) with eGFR formulas (MDRD/CKD-EPI, used for CKD staging)", "Using outdated SCr values in an acutely changing renal function patient"]}, {"topic": "calc", "generic": "IV flow rate (mL/hr and gtt/min)", "pronunciation": "EYE-VEE floh rayt", "brand": [], "class": "Dosing/administration calculation", "moa": "mL/hr = Total volume (mL) / Total time (hr). gtt/min = [Volume(mL) x Drop factor(gtt/mL)] / Time(min). Drop factor depends on tubing: macrodrip 10, 15, or 20 gtt/mL; microdrip 60 gtt/mL (used for pediatrics/precise small volumes).", "indication": "Manual (gravity) IV administration without a pump, or to verify/cross-check a programmed infusion pump rate.", "dosage": "Not applicable — calculation method, not a dosed drug", "examPoints": ["Example: 1000 mL over 8 hr with a 15 gtt/mL set → (1000x15)/(8x60 min) = 15000/480 = 31.25 ≈ 31 gtt/min", "mL/hr example: 1000 mL over 8 hr = 125 mL/hr (simple division, no drop factor needed for pump-programmed rates)", "Always convert hours to minutes before computing gtt/min", "Microdrip (60 gtt/mL) numerically equals mL/hr when time is in minutes — a useful shortcut/check", "Round gtt/min to the nearest whole drop since partial drops can't be counted"], "counselling": ["When teaching a caregiver a gravity infusion, have them count drops for a full 60 seconds to verify the rate", "Document the calculated rate, drop factor, and tubing type used in the patient's chart", "Double check units at every step; verify pump-programmed rate against your manual calculation as a safety check"], "sideEffects": ["Forgetting to convert hours to minutes", "Using the wrong drop factor for the tubing type in use", "Rounding too early in a multi-step calculation, compounding the error", "Confusing total volume with flow rate", "Mixing up mL/hr and gtt/min units in the final answer"]}, {"topic": "calc", "generic": "Alligation (mixing two concentrations)", "pronunciation": "al-ih-GAY-shun", "brand": [], "class": "Compounding calculation — concentration/dilution", "moa": "Alligation method: place desired % in the middle, higher stock % top-left, lower stock % (or 0 for diluent) bottom-left. Parts of higher = |desired - lower|; parts of lower = |higher - desired|. Ratio of parts gives the mixing ratio.", "indication": "Compounding a custom-strength product from two different-strength stock preparations (or a stock and a diluent) when no single stock matches the prescribed strength.", "dosage": "Not applicable — calculation method, not a dosed drug", "examPoints": ["Example: need 500 mL of 2.5% cream from 5% stock and 0% (plain) base → parts of 5%=2.5-0=2.5; parts of 0%=5-2.5=2.5 → equal parts (1:1) → 250 mL of 5% + 250 mL of plain base", "Example: need 1% from 10% and 0.5% stocks → parts of 10% = 1-0.5=0.5; parts of 0.5%=10-1=9 → ratio 0.5:9 → scale to total volume needed", "Total parts = sum of both parts; each stock's volume = (its parts/total parts) x total desired volume", "Desired concentration must fall between the two stock concentrations — if not, alligation cannot solve it (need a third stock or different approach)", "Double-check by verifying: (vol1 x conc1 + vol2 x conc2) / total volume = desired conc"], "counselling": ["Label the compounded product with actual final concentration, not just 'diluted X'", "Document the alligation calculation and stock lot numbers used in the compounding record", "Verify the final total volume matches what was prescribed before dispensing"], "sideEffects": ["Placing the desired concentration in the wrong position of the alligation grid", "Forgetting to convert the final parts ratio into actual volumes for the required total quantity", "Attempting alligation when desired concentration is outside the range of the two stocks", "Not verifying the final mass-balance check after computing volumes"]}, {"topic": "calc", "generic": "BSA-based dosing (Mosteller formula)", "pronunciation": "BEE-ess-AY, MOS-tel-er", "brand": [], "class": "Dosing calculation — body surface area", "moa": "BSA (m^2) = sqrt[(height(cm) x weight(kg)) / 3600] (Mosteller formula). Dose = BSA (m^2) x dose per m^2 (as specified by the drug protocol, common in chemotherapy and some pediatric dosing).", "indication": "Chemotherapy dosing and select drugs with a narrow therapeutic index where BSA more accurately reflects metabolic/clearance capacity than weight alone.", "dosage": "Not applicable — calculation method, not a dosed drug", "examPoints": ["Example: height 170 cm, weight 70 kg → sqrt[(170x70)/3600] = sqrt(11900/3600)=sqrt(3.31)=1.82 m^2", "Dose example: if protocol calls for 100 mg/m^2 and BSA=1.82 m^2 → dose = 182 mg", "Always use height in cm and weight in kg for the Mosteller formula (not inches/lb)", "Other BSA formulas exist (DuBois, Haycock) but Mosteller is simplest/most commonly tested for PEBC purposes", "BSA doses are often capped at a maximum BSA (e.g., 2.0 m^2) per protocol to avoid overdosing very large patients"], "counselling": ["Document height, weight, calculated BSA, and resulting dose clearly in the chemotherapy order verification", "Independent double-check of BSA calculation by a second pharmacist is standard practice for chemo due to narrow therapeutic index", "Recalculate BSA if weight changes significantly between cycles"], "sideEffects": ["Using height/weight in the wrong units (inches/lb instead of cm/kg)", "Arithmetic error inside the square root (dividing before multiplying, or vice versa incorrectly)", "Forgetting to apply a protocol-specified BSA cap for oversized patients", "Using outdated weight/height for a recalculation after significant patient status change"]}, {"topic": "calc", "generic": "Pediatric weight-based dosing (mg/kg/day and mg/kg/dose)", "pronunciation": "pee-dee-AT-rik wayt-bayst DOH-sing", "brand": [], "class": "Dosing calculation — pediatrics", "moa": "Total daily dose = mg/kg/day x weight(kg); per-dose amount = total daily dose / number of doses per day (or given directly as mg/kg/dose x weight). Always check against adult max dose ceiling when applicable.", "indication": "Nearly all pediatric prescription and OTC dosing (antibiotics, antipyretics/analgesics, etc.) where dose scales to body weight rather than a fixed adult dose.", "dosage": "Not applicable — calculation method, not a dosed drug", "examPoints": ["Example: amoxicillin 40 mg/kg/day divided BID for a 15 kg child → 40x15=600 mg/day ÷ 2 = 300 mg per dose", "Always compare calculated dose to the drug's adult maximum — pediatric mg/kg dosing should never exceed the adult ceiling dose", "Confirm whether the rate is mg/kg/day (needs dividing by frequency) or mg/kg/dose (already per-administration) — mixing these up is a major source of error", "Use most recent accurate weight in kg (not lb) — convert lb to kg by dividing by 2.2", "Round to a practically measurable/available dose/concentration when finalizing (e.g., to nearest 0.5 mL for oral suspension)"], "counselling": ["Show caregivers the exact dose using the provided oral syringe (mL), not just 'mg', to prevent measurement error", "Confirm caregiver understands frequency and duration, and warn against using household spoons", "Recalculate dose at each visit as the child's weight changes — pediatric doses are not 'set and forget'", "Document weight, mg/kg/day or /dose used, and final calculated dose in the record"], "sideEffects": ["Confusing mg/kg/day with mg/kg/dose and dosing the daily total at each administration", "Not converting weight from lb to kg", "Exceeding the adult maximum dose ceiling in a larger child/adolescent", "Using an outdated weight for a growing child", "Rounding the final volume to an unmeasurable amount on the available oral syringe"]}, {"topic": "calc", "generic": "Days-supply calculation", "pronunciation": "DAYZ suh-PLY kal-kyoo-LAY-shun", "brand": [], "class": "Dispensing/logistics calculation", "moa": "Days supply = Total quantity dispensed / Quantity used per day. For variable/taper regimens, sum the quantity used across each phase, then divide total quantity by total days, or calculate phase-by-phase and sum days.", "indication": "Determining insurance day-supply limits, refill-too-soon checks, and taper/step-down regimen scheduling (e.g., prednisone tapers, insulin sliding scale supply estimates).", "dosage": "Not applicable — calculation method, not a dosed drug", "examPoints": ["Simple example: 90 tablets, 1 tablet twice daily = 2/day → 90/2 = 45 days supply", "Taper example: prednisone 60mg x3d, 40mg x3d, 20mg x3d using 10mg tabs: day1-3 uses 6 tabs/day x3=18; day4-6 uses 4 tabs/day x3=12; day7-9 uses 2 tabs/day x3=6; total=36 tablets over 9 days", "PRN medications: days supply is often estimated using max daily dose (worst-case) unless directed otherwise by policy", "Insulin/inhaler days supply requires knowing total units/actuations per device and daily usage rate, not just 'per vial/inhaler = X days' flatly", "Always double check that 'quantity dispensed' and 'daily usage rate' use the same unit (tablets, mL, units, actuations)"], "counselling": ["Explain to the patient exactly when they'll run out and when to request a refill, especially for tapers", "For inhalers/insulin, show the patient how to track remaining doses (counter or calendar) so they don't run out unexpectedly", "Document days-supply logic used for complex tapers or PRN estimates in the record for consistency at refill"], "sideEffects": ["Miscalculating a taper by using the starting dose's daily rate for the whole supply", "Mismatched units between quantity dispensed and daily usage (e.g., mL vs mg)", "Using an inaccurate PRN 'as needed' assumption for days supply, triggering false refill-too-soon rejections", "Forgetting that combination inhalers may have a different actuation count for 'primer' doses affecting total available doses"]}, {"topic": "calc", "generic": "mEq/mmol conversion for electrolytes", "pronunciation": "mil-ee-EE-kyoo / MIL-ee-mol", "brand": [], "class": "Electrolyte/dosing calculation", "moa": "mEq = (mg x valence) / atomic or molecular weight(mg/mmol). mmol = mg / molecular weight. mEq = mmol x valence (charge). Common valences: Na+ K+ =1, Ca2+ Mg2+=2.", "indication": "Ordering/compounding electrolyte replacement (KCl, NaCl, CaCl2/gluconate, MgSO4, phosphate) in parenteral nutrition, IV fluids, and oral electrolyte supplements where dosing is often specified in mEq or mmol rather than mg.", "dosage": "Not applicable — calculation method, not a dosed drug", "examPoints": ["KCl example: MW of K=39.1, valence=1, so 1 mmol K = 39.1 mg = 1 mEq → to give 40 mEq K, need 40 x 39.1 mg = 1564 mg KCl salt (adjust for salt form MW, e.g., KCl MW=74.5, so mass of KCl salt = 40 x 74.5=2980mg if calculating from the salt, but ion-mass calc uses elemental K mass)", "Calcium example: Ca2+ has valence 2, so 1 mmol Ca2+ = 2 mEq — dividing/multiplying by the wrong valence is a very common trap", "For monovalent ions (Na+, K+), mEq = mmol numerically (valence=1) so conversions are 1:1", "For divalent ions (Ca2+, Mg2+), mEq = 2 x mmol — always double check valence before converting", "SI unit mmol/L is standard in Canadian labs for electrolytes; US-trained candidates should be comfortable converting mg/dL or mEq/L values to SI mmol/L"], "counselling": ["When compounding electrolyte additives for TPN, document both mmol and mEq calculations and have a second check for high-alert electrolytes", "Explain to patients on oral electrolyte supplements what the mEq/mmol number on the label represents relative to their prescribed dose", "Cross-check the salt form's molecular weight matches the one used in the calculation (e.g., KCl vs K-phosphate have different MW)"], "sideEffects": ["Using valence=1 for divalent ions like calcium or magnesium", "Mixing up molecular weight of the elemental ion vs the full salt form", "Confusing mEq and mmol as interchangeable for divalent electrolytes", "Errors in high-alert electrolyte compounding (KCl, CaCl2) that are especially dangerous if IV push is inadvertently used"]}, {"topic": "calc", "generic": "Aliquot method for compounding small quantities", "pronunciation": "AL-ih-kwot", "brand": [], "class": "Compounding calculation — measurement accuracy", "moa": "When the amount of active drug needed is below the minimum accurately weighable/measurable quantity for the balance (typically 120mg for a Class A torsion balance, or minimum measurable volume for a graduate), dilute a larger, accurately-weighable amount with inert diluent, then take a proportional aliquot of that mixture that contains the needed amount of drug.", "indication": "Compounding a capsule/cream/solution requiring a very small quantity of potent active ingredient (e.g., a few mg) that falls below the minimum accurate weighing quantity of standard pharmacy balances.", "dosage": "Not applicable — calculation method, not a dosed drug", "examPoints": ["Minimum weighable quantity (MWQ) for a Class A balance with ±5mg sensitivity and 5% acceptable error = 5mg/0.05 = 100mg (commonly rounded/quoted as 120mg with a sensitivity requirement of 6mg)", "Worked example: need 10mg of drug but MWQ is 120mg. Weigh 120mg of drug, dilute with diluent to a convenient total (e.g., 1200mg total, a 1:10 dilution), then take an aliquot of 100mg of that mixture to obtain 10mg of drug (since 100/1200 x120=10mg)", "Liquid aliquot method follows the same logic using minimum measurable volume of a graduate instead of balance sensitivity", "Always verify the final aliquot quantity is itself measurable/weighable — if not, a second dilution/aliquot step is needed", "Choose a dilution ratio (e.g., 1:10, 1:100) that yields convenient, accurately measurable numbers, not just any random total"], "counselling": ["Document the full aliquot calculation, diluent used, and dilution ratio in the compounding record for reproducibility and verification", "Have a second pharmacist independently verify potent/high-alert aliquot calculations before compounding", "Label intermediate dilutions clearly during preparation to avoid mix-ups mid-process"], "sideEffects": ["Attempting to weigh an amount below the balance's minimum weighable quantity directly, causing large percentage error", "Choosing an inconvenient dilution ratio that produces an aliquot volume/weight that still can't be accurately measured", "Arithmetic error in the proportion step, over- or under-diluting the potent ingredient", "Forgetting to account for the diluent's own contribution to final total weight/volume when relevant"]}, {"topic": "calc", "generic": "Beyond-use dating (BUD) — non-sterile and sterile compounds", "pronunciation": "bee-YOND-yooz DAY-ting", "brand": [], "class": "Compounding calculation — stability/expiry", "moa": "Non-sterile BUD (USP <795>/NAPRA equivalents) is generally the shorter of: manufacturer expiry-based limits, water-containing formulations 14 days refrigerated (absent stability data), non-aqueous/solid oral 25% of remaining manufacturer expiry or 6 months (whichever is less), or per validated stability data. Sterile BUD (USP <797>/NAPRA) depends on risk level (immediate, low, medium, high) and storage condition (room temp, refrigerated, frozen), generally far shorter than non-sterile.", "indication": "Assigning an appropriate beyond-use date to any compounded non-sterile (creams, suspensions, capsules) or sterile (IV admixtures, eye drops) preparation when no manufacturer expiry applies.", "dosage": "Not applicable — regulatory/compounding concept, not a dosed drug", "examPoints": ["Classic non-sterile default: water-containing oral/topical formulation without stability data = 14 days refrigerated (some references say 14 days regardless of storage unless otherwise supported)", "Non-aqueous non-sterile formulation (e.g., capsules, ointments without water) = lesser of 25% of time remaining until earliest component expiry, or 6 months", "Sterile compounding BUD depends on risk level: immediate-use very short (within hours), low-risk longer than medium/high-risk categories, and always shorter at room temperature vs refrigerated vs frozen", "BUD is calculated from the date of compounding, not the date of dispensing", "When in doubt or absent specific stability data, always choose the more conservative (shorter) BUD to protect patient safety"], "counselling": ["Label every compounded product with the BUD (not a generic 'expiry') and appropriate storage conditions", "Explain to the patient the shorter BUD compared to commercial products and why (no preservative/stability testing)", "Document the BUD rationale and reference source (USP chapter, stability reference) in the compounding record"], "sideEffects": ["Applying a commercial product's shelf-life logic to a compounded preparation", "Using the longer/less conservative BUD option when data doesn't support it", "Forgetting to shorten BUD when a component ingredient's own expiry is sooner than the calculated BUD", "Miscategorizing sterile compounding risk level, leading to an inappropriately long BUD"]}, {"topic": "calc", "generic": "Osmolarity and tonicity calculations for compounds", "pronunciation": "oz-moh-LAIR-ih-tee, toh-NIS-ih-tee", "brand": [], "class": "Compounding calculation — parenteral/ophthalmic safety", "moa": "Osmolarity (mOsm/L) = (mmol/L of solute) x number of particles the solute dissociates into. Tonicity relative to body fluids (~285-310 mOsm/L) determines whether a solution is hypotonic, isotonic, or hypertonic; sodium chloride equivalent (E-value) method is commonly used to adjust ophthalmic/parenteral solutions to isotonicity.", "indication": "Preparing IV admixtures (especially peripheral vs central line appropriateness) and ophthalmic/nasal/injectable solutions where tonicity affects patient comfort and safety (e.g., hemolysis risk, ocular irritation).", "dosage": "Not applicable — calculation method, not a dosed drug", "examPoints": ["Example: 0.9% NaCl — MW NaCl=58.5, dissociates into 2 particles (Na+ and Cl-) → (9000mg/L / 58.5mg/mmol) x2 = 153.8 x2 ≈ 308 mOsm/L, confirming isotonicity", "Peripheral IV lines generally tolerate up to ~600-900 mOsm/L osmolarity; higher concentrations require central line administration to avoid phlebitis/vein damage", "Sodium chloride equivalent (E-value) method: amount of NaCl equivalent in osmotic effect to a given weight of drug, used to calculate how much additional NaCl or water is needed to reach isotonicity for ophthalmic prep", "Dextrose 5% in water (D5W) is approximately isotonic (~252 mOsm/L) despite being 'free water' once metabolized — a classic exam distinction (initially isotonic, physiologically acts as hypotonic after dextrose metabolism)", "Always count dissociation particles correctly (e.g., CaCl2 dissociates into 3 particles) — a common calculation trap"], "counselling": ["Document osmolarity/tonicity calculations for any custom parenteral nutrition or high-concentration electrolyte admixture, and flag to the team if peripheral line is inappropriate", "For ophthalmic compounds, note if a preparation was adjusted to isotonicity and with what agent (e.g., NaCl, boric acid)", "Communicate to nursing/prescribers when an admixture's osmolarity requires central line access"], "sideEffects": ["Forgetting to multiply by the number of dissociated particles for a given solute", "Assuming D5W remains hypotonic in the bag before administration (it's isotonic in the bag; the hypotonic effect is physiological post-metabolism)", "Underestimating osmolarity of a TPN admixture and routing a hypertonic solution through a peripheral line", "Using the wrong molecular weight or E-value reference for a less common compounding ingredient"]}, {"topic": "calc", "generic": "Percentage strength and weight/volume, weight/weight, volume/volume conversions", "pronunciation": "per-SEN-tij strength", "brand": [], "class": "Compounding/dispensing calculation — concentration expression", "moa": "% w/v = grams of solute per 100 mL of solution. % w/w = grams of solute per 100 g of total preparation. % v/v = mL of liquid solute per 100 mL of total solution. To convert to mg/mL: %w/v x 10 = mg/mL.", "indication": "Compounding creams/ointments/solutions where the prescribed strength must be translated into an actual weighable/measurable quantity of active ingredient for a given total preparation size.", "dosage": "Not applicable — calculation method, not a dosed drug", "examPoints": ["Example: 2% w/v solution, need 250 mL → 2g/100mL x 250mL = 5 g of active ingredient", "Example: 1% w/w cream, need 30 g total → 1g/100g x 30g = 0.3 g (300 mg) of active ingredient in 30g total cream base", "Quick conversion: %w/v x 10 = concentration in mg/mL (e.g., 5% w/v = 50 mg/mL)", "For semisolids (creams/ointments), always assume w/w unless otherwise specified, since density of the base may not be 1 g/mL", "v/v is used only for liquid-in-liquid mixtures (e.g., alcohol %, essential oil dilutions)"], "counselling": ["Label compounded products with both the percentage strength and the equivalent mg/mL or mg/g for clarity", "Document which type (w/v, w/w, v/v) was used in the calculation, since the base assumption significantly changes the actual drug quantity for creams/ointments", "Double-check final compounded quantity against the prescribed total amount before dispensing"], "sideEffects": ["Assuming w/v for a semisolid (cream/ointment) when w/w is the correct convention, causing a mass/volume density error", "Forgetting to convert grams to mg or vice versa in a multi-step calculation", "Using the wrong total preparation weight/volume as the base of the percentage calculation", "Confusing % w/v with mg/mL without applying the x10 conversion correctly"]}, {"topic": "calc", "generic": "Loading dose and maintenance dose calculations", "pronunciation": "LOH-ding dohs", "brand": [], "class": "Pharmacokinetic dosing calculation", "moa": "Loading dose = (Target Cp x Vd) / bioavailability(F). Maintenance dose rate = (Target Cp x Clearance) / F. Where Cp=target plasma concentration, Vd=volume of distribution (often in L/kg x weight), F=bioavailability fraction (1 for IV).", "indication": "Initiating drugs with a long half-life or narrow therapeutic index where waiting ~5 half-lives to reach steady state is clinically unacceptable (e.g., digoxin, phenytoin, vancomycin, amiodarone).", "dosage": "Not applicable — calculation method, not a dosed drug", "examPoints": ["Example: target Cp=20mg/L, Vd=0.7L/kg for a 70kg patient (=49L), IV (F=1) → Loading dose = 20 x49 = 980mg", "Maintenance dose rate example: target Cp=20mg/L, Clearance=3L/hr → rate=20x3=60mg/hr", "Loading dose is independent of clearance/half-life; maintenance dose/rate depends on clearance, not Vd", "For oral loading doses, divide by bioavailability (F) since less than 100% of an oral dose may reach systemic circulation", "In renal/hepatic impairment, maintenance dose is typically reduced (clearance is lower) while loading dose is generally unchanged (Vd usually unaffected) — a frequently tested distinction"], "counselling": ["Explain to a patient why an initial 'extra' dose is given (loading dose) followed by smaller regular doses", "Document target concentration, calculated Vd/clearance assumptions, and resulting doses in pharmacokinetic dosing notes", "Monitor levels after loading dose administration per protocol (e.g., digoxin level timing) to confirm target achieved"], "sideEffects": ["Reducing the loading dose in renal impairment when only maintenance dose should typically be adjusted", "Forgetting to divide by bioavailability (F) for oral loading dose calculations", "Using total body weight instead of the appropriate weight descriptor (e.g., ideal or adjusted) for Vd in obese patients", "Confusing which parameter (Vd vs Clearance) governs loading vs maintenance dose"]}, {"topic": "calc", "generic": "Unit conversions and dimensional analysis pitfalls", "pronunciation": "YOO-nit kun-VER-zhunz", "brand": [], "class": "Fundamental calculation skill", "moa": "Dimensional analysis: multiply the given quantity by a chain of conversion factors (each equal to 1, e.g., 1000mg/1g) arranged so unwanted units cancel, leaving the desired unit. Systematic method reduces multi-step calculation errors versus ad hoc arithmetic.", "indication": "Any calculation crossing between metric prefixes (mcg/mg/g/kg), weight/volume, or apothecary-to-metric conversions (grains, ounces) still occasionally seen on exams.", "dosage": "Not applicable — calculation method, not a dosed drug", "examPoints": ["Standard chain example: convert 0.25 mg to mcg → 0.25mg x (1000mcg/1mg) = 250mcg", "Weight-based dose in lb patient: always convert lb to kg first (divide by 2.2) before applying mg/kg dosing", "Apothecary conversions still tested occasionally: 1 grain ≈ 60-65mg (commonly 65mg for exam purposes, e.g., ASA 5-grain tablet ≈ 325mg); 1 oz ≈ 30mL; 1 tsp=5mL; 1 tbsp=15mL", "Always write out units at each step of a chain calculation and confirm unwanted units cancel diagonally — this catches most inversion errors", "For concentration-based dosing (mg/mL), set up as: ordered dose(mg) x [1mL/Xmg] = volume to give(mL), keeping units explicit"], "counselling": ["When teaching a caregiver a liquid dose, always convert to the measuring device's actual units (mL) never approximate household spoons", "Show your dimensional analysis work when verifying a colleague's calculation to catch inversion or unit errors", "Round only at the final step of a multi-step conversion, not at each intermediate step"], "sideEffects": ["Inverting a conversion factor (e.g., multiplying by 1g/1000mg instead of 1000mg/1g)", "Rounding intermediate steps too early, compounding small errors into a clinically significant final error", "Forgetting to convert lb to kg before weight-based dosing", "Mixing metric and apothecary units without conversion in a single calculation", "Misremembering apothecary equivalents (e.g., grain-to-mg) and not flagging that as an approximation"]}, {"topic": "calc", "generic": "Ratio strength conversions (e.g., 1:1000, 1:10000)", "pronunciation": "RAY-shee-oh strength", "brand": [], "class": "Compounding/dosing calculation — concentration expression", "moa": "Ratio strength expresses concentration as 1 part solute to X parts total preparation, equivalent to 1g/X mL (w/v) or 1g/Xg (w/w). To convert to %: % = (1/X) x 100. To convert to mg/mL: 1000mg / X mL.", "indication": "Epinephrine (1:1000, 1:10000, 1:100000), and other drugs traditionally labeled/ordered in ratio strength (e.g., some antiseptics, historic dilutions) where clinicians must rapidly convert to mg or mL for administration.", "dosage": "Not applicable — calculation method, not a dosed drug", "examPoints": ["Epinephrine 1:1000 = 1g/1000mL = 1mg/mL; 1:10000 = 1g/10000mL = 0.1mg/mL — mixing these up in a code/anaphylaxis scenario is a classic high-stakes exam trap", "Convert ratio to %: 1:1000 → (1/1000)x100 = 0.1%", "Convert ratio to mg/mL: 1:1000 → 1000mg/1000mL = 1mg/mL", "IM anaphylaxis dose uses 1:1000 (1mg/mL); IV cardiac arrest dose uses 1:10000 (0.1mg/mL) — concentration determines route/clinical use, not interchangeable", "Always express the final answer in mg/mL or mg/dose to reduce ambiguity before administration"], "counselling": ["When verifying an epinephrine order, state back both the ratio strength and its mg/mL equivalent to catch transcription errors", "Document which concentration (1:1000 vs 1:10000) was dispensed/administered, since the two are not interchangeable and have caused fatal errors", "For any ratio-strength product, provide the mg/mL equivalent on the label or verbally to the administering clinician"], "sideEffects": ["Confusing 1:1000 and 1:10000 epinephrine concentrations — a well-documented cause of serious dosing errors", "Forgetting that a larger ratio denominator means a MORE dilute (weaker) preparation, not stronger", "Incorrectly converting ratio strength to % by not multiplying by 100", "Assuming ratio-strength products are interchangeable across routes/indications"]}, {"topic": "calc", "generic": "Parenteral nutrition caloric calculations", "pronunciation": "puh-REN-ter-ul noo-TRISH-un", "brand": [], "class": "Compounding/dosing calculation — total parenteral nutrition (TPN)", "moa": "Caloric yield: dextrose (hydrous) = 3.4 kcal/g; lipid emulsion = ~2 kcal/mL for a 20% emulsion (~10 kcal/g fat, adjusted for glycerol/emulsifier content); protein/amino acids = 4 kcal/g (though protein calories are typically excluded from 'non-protein calorie' counts used for energy goals).", "indication": "Formulating and verifying total parenteral nutrition orders to ensure caloric goals are met without over- or under-feeding, and to calculate the dextrose/lipid/protein calorie distribution.", "dosage": "Not applicable — calculation method, not a dosed drug", "examPoints": ["Example: D50W 500mL provides 250g dextrose x3.4kcal/g = 850 kcal", "Example: 20% lipid emulsion 250mL at ~2kcal/mL = 500 kcal", "Amino acids provide 4kcal/g but are usually excluded from 'non-protein calorie:nitrogen ratio' calculations used to assess adequacy of nonprotein energy relative to protein for anabolism", "Nitrogen content: grams of protein / 6.25 = grams of nitrogen (used for nitrogen balance calculations)", "Always confirm concentration (%) before applying kcal/g or kcal/mL conversion factors, since %w/v directly gives g/100mL"], "counselling": ["Document the caloric breakdown (dextrose, lipid, protein) and total kcal/day in the TPN compounding record", "Communicate total caloric intake and macronutrient distribution to the nutrition support team for goal-tracking", "Flag discrepancies between ordered and calculated total calories before compounding proceeds"], "sideEffects": ["Using the wrong kcal/g factor for dextrose (3.4) vs a generic carbohydrate assumption (4 kcal/g), causing calorie miscalculation", "Forgetting that lipid emulsion kcal/mL varies by concentration (10% vs 20% vs 30%)", "Including protein calories inappropriately in non-protein calorie:nitrogen ratio calculations", "Misreading %w/v concentration and misapplying the g/100mL conversion"]}];
